\begin{example}\label{sec:SNFG:exp:1}

  Consider the multivariate function
  $g(x_{1},\ldots,x_{5}) \defeq f_{1}(x_{1},x_{2},x_{3}) \cdot f_{2}(x_{1},x_{4})
  \cdot f_{3}(x_{2},x_{5})\cdot f_{4}(x_{3},x_{4},x_{5})$, where $g$, the
  so-called global function, is defined to be the product of the so-called
  local functions $f_{1}$, $f_{2}$, $f_{3}$ and $f_{4}$. The factorization of $g$ is visualized by the S-NFG $\graphN$ in
  Fig.~\ref{sec:SNFG:fig:1}, which consists of four function nodes
  $f_1, \ldots, f_4$ corresponding to local functions $f_1, \ldots, f_4$ 
  and five (full) edges $ 1,\ldots,5 $ corresponding to variables
  $x_1, \ldots, x_5$.
  \eexample
\end{example}

%***************************************************************************

%***************************************************************************

An edge that connects to two function nodes is called a full edge, whereas an edge
that is connected to only one function node is called a half edge. The half edges are useful for many practical applications (see, \eg,~\cite{Loeliger2004}). For the
purposes of this paper, it is sufficient to consider S-NFGs with only full
edges, as those with half edges can be converted into this form by attaching a dummy $1$-valued function node to the other end of every half edge without changing any marginals or the partition function, 
and also without changing the cycle structure of the S-NFG. 

%***************************************************************************

\begin{definition}
  \label{def: def of snfg}
  An S-NFG $\graphN(\setF, \setEfull, \set{X})$ consists of the following
  objects.
  \begin{enumerate}

    \item The graph $(\setF,\setEfull)$ with vertex set $\setF$ and edge set
      $\setEfull$, where $\setF$ is also known as function node set. (As
      mentioned above, every edge $e \in \setEfull$ will be assumed to be a full
      edge connecting two function nodes.)

    \item The alphabet $\set{X} \defeq \prod_{e \in \setEfull} \setxe$, where
      $\setxe$ is the finite alphabet of the variable $\xe$ associated with the edge
      $e \in \setEfull$. In this paper, without loss of generality, we assume that $ 0 \in \setxe$ for all $ e \in \setEfull $.

  \end{enumerate} 
  For an arbitrary S-NFG $\graphN(\setF,\setEfull,\set{X})$, we assume that $ \set{F} = \{ f_{1},\ldots,f_{|\set{F}|} \} $, \ie, 
  the function node set $ \set{F} $ consists of the elements
  $ f_{1},\ldots,f_{|\set{F}|}. $ 
  Based on this, we introduce the following definitions.
  %------------------------------------------------------------------------
  % \begin{align*}
  %   \set{F} = \{ f_{1},\ldots,f_{|\set{F}|} \}.
  %   % \qquad
  %   % \setEfull = \bigl[ |\setEfull| \bigr] = \{0,1,\ldots,|\setEfull|-1\} .
  % \end{align*}
  %------------------------------------------------------------------------

  \begin{enumerate}
     \setcounter{enumi}{2}

    \item For every function node $f \in \setF$, the set $\setpf$ is defined to be the set of edges incident on $f$.

    \item For every edge $e = (f_{i}, f_{j}) \in \setEfull$, we assume that $ i < j $. (Note that we assign a uniform direction to each edge $(f_{i}, f_{j})$, \ie, we adopt the convention that $ i < j $ for notational convenience. Nevertheless, the results presented in this paper are invariant under the choice of direction.)

    \item An assignment $\vx \defeq (\xe)_{e \in \setEfull} \in \set{X}$ is called a
      configuration of the S-NFG $ \sfN $. 

    % For each $f \in \setF$, a configuration
    % $\vx \in \set{X}$ induces the vector $\xf \defeq (x_{e})_{e \in \setpf} \in \prod_{e \in \setpf}\setxe$.

   \item For any finite set $ \set{I} \subseteq \setEfull $, we define
   %-----------------------------------------------------------------------
   \begin{align*}
         \setx_{ \set{I} } \defeq 
         \prod_{ e \in \set{I} } \setxe, \qquad 
         \vx_{\set{I}} \defeq (\xe)_{e \in \set{I}}
         \in \setx_{ \set{I} }.
   \end{align*}
   %-----------------------------------------------------------------------

  \item For every function node $f \in \setF$, the local function associated with $f$ is,
    with some slight abuse of notation, also called $f$. Here, the local
    function $f$ is an arbitrary mapping from $\setxf$ to
    $\sRp$.

  \item The global function $g$ is defined to be the mapping
    $g:\set{X}\to \sRp, \ \vx\mapsto \prod_{f \in \setF} f(\xf)$.

  \item A configuration $\vx \in \set{X}$ satisfying $g(\vx) \neq 0$ is called a
    valid configuration.

  \item The partition function\footnote{In this paper, the
      partition function $Z(\graphN)$ of $\graphN$ is a scalar, \ie, it
      is not really a function. If $\graphN$ depends on some parameter
      (say, some pressure parameter), then $Z(\graphN)$ is a function of
      that parameter.} is defined to be
    $Z(\graphN) \defeq \sum_{\vx \in \set{X}}g(\vx)$. Clearly, the partition function satisfies
    $Z(\graphN) \in \sRp$.

  \end{enumerate}
  \edefinition
\end{definition}

%***************************************************************************

In the following, we will only consider S-NFGs $\graphN$ for which
$Z(\graphN) \in \sRpp$.

%***************************************************************************

If there is no ambiguity when we consider S-NFG, we use the short-hands
$\sum_{\vx}$, $\sum_{\xe}$, $\sum_e$, $\sum_{f}$, 
$\prod_{\vx}$, $\prod_{\xe}$, $\prod_e$, $\prod_{f}$,
$ (\cdot)_{\xe} $,
and
$ (\cdot)_{e} $ for
$\sum_{\vx \in \set{X}}$, 
$\sum_{\xe \in \setxe}$, $\sum_{e \in \setEfull}$, $\sum_{f \in \setF}$,
$\prod_{\vx \in \set{X}}$, 
$\prod_{\xe \in \setxe}$, $\prod_{e \in \setEfull}$, $\prod_{f \in \setF}$, 
$ (\cdot)_{\xe \in \setxe} $,
and 
$ (\cdot)_{e\in \setEfull} $,
respectively. 
For any set $ \set{I} \subseteq \setEfull $, we use the short-hands 
$\sum_{\vx_{\set{I}}}$,
$\prod_{\vx_{\set{I}}}$, 
and $ (\cdot)_{\vx_{\set{I}}} $
for 
$\sum_{ \vx_{\set{I}} \in \setx_{\set{I}} }$,
$\prod_{ \vx_{\set{I}} \in \setx_{\set{I}} }$, 
and $ (\cdot)_{ \vx_{\set{I}} \in \setx_{\set{I}} } $, respectively.
Moreover, $\setpf \setminus e$ will be the short-hand notation for
$\setpf \setminus \{ e \}$.


%***************************************************************************

In the following we only give the technical details of the SPA on an S-NFG; for a general discussion with respect to  the motivations behind the SPA, see, \eg,~\cite{Kschischang2001,Loeliger2004}.

\begin{definition}\label{sec:SNFG:def:4}
\label{def:belief at SPA fixed point for S-NFG}

Consider some S-NFG $\graphN$. The SPA is an iterative algorithm that
sends messages along edges, where messages are functions over the alphabet
associated with an edge. (Note that for every iteration and every edge, two
messages are sent along that edge, one in both directions.) More precisely,
the SPA consists of the following steps.
\begin{enumerate}

\item (Initialization) For every $f \in \setF$ and $ e \in \setpf $, the
  message $\mu_{\etof}^{(0)}: \setxe \to \sR_{> 0} $, is defined to be some
  arbitrary non-zero function such that 
  $ \sum_{\xe \in \setxe} \mu_{\etof}^{(0)}(\xe) = 1 $. 
  (Typically, $\mu_{\etof}^{(0)}(\xe) \defeq 1 / |\setxe|$
  for all $\xe \in \setxe$.)

\item (Iteration) For $t = 1, 2, 3, \ldots$, do the following calculations
  until some termination criterion is met.\footnote{The termination
    criterion is typically a combination of numerical convergence and an
    upper bound on the number of iterations.}
  \begin{enumerate}
      \item\label{SPA: update message} For every $e \in \setEfull$, 
      we define the messages from edge $ e = (f_{i}, f_{j}) $ to the function nodes 
      $ f_{j} $ and $ f_{i} $ to be the mappings
      \begin{alignat}{3}
        \mu_{\efj}^{(t)}:\, \set{X}_{e} &\to \sR_{\geq 0}, \quad
        x_{e} &\mapsto&
        \bigl( \kappa_{\efj}^{(t)} \bigr)^{\! -1}
        \cdot
        \sum_{\vx_{ \setpfi \setminus e }}
          f_{i}(\xfi)
          \cdot
          \prod_{e' \in \setpfi \setminus e}
            \mu_{\epfi}^{(t-1)}(x_{e'}), \nonumber
            % \label{sec:SNFG:eqn:8}
        \\
        \mu_{\efi}^{(t)}:\, \set{X}_{e} &\to \sR_{\geq 0}, \quad
        x_{e} &\mapsto&
        \bigl( \kappa_{\efi}^{(t)} \bigr)^{\! -1}
        \cdot
        \sum_{ \vx_{ \setpfj \setminus e } }
          f_{j}(\xfj)
          \cdot
          \prod_{e' \in \setpfj \setminus e}
            \mu_{\epfj}^{(t-1)}(x_{e'}), \nonumber
            % \label{sec:SNFG:eqn:7}
      \end{alignat}
      where the scaling factors $ \kappa_{\efj}^{(t)} $ and $ \kappa_{\efi}^{(t)} $ are defined to be
      %--------------------------------------------------------------------
      \begin{align*}
          \kappa_{\efj}^{(t)}
          &\defeq
          \sum_{\xfi}
          f_{i}(\xfi)
          \cdot
          \prod_{e' \in \setpfi \setminus e}
          \mu_{\epfi}^{(t-1)}(x_{e'}),
          \nonumber\\
          \kappa_{\efi}^{(t)} &\defeq
          \sum_{\xfj}
          f_{j}(\xfj)
          \cdot
          \prod_{e' \in \setpfj \setminus e}
          \mu_{\epfj}^{(t-1)}(x_{e'}).
      \end{align*}
      %--------------------------------------------------------------------
      The associated vectors are defined to be 
      $ \vmu_{\efj}^{(t)} \defeq \bigl( \mu_{\efj}^{(t)}(\xe) \bigr)_{ \!  \xe } $
      and $ \vmu_{\efi}^{(t)} \defeq \bigl( \mu_{\efi}^{(t)}(\xe) \bigr)_{ \!  \xe } $.

      \item\label{SPA: update belief edges} For every $e = (f_{i},f_{j}) \in \setEfull$, we define the belief function at edge $e$ to be the mapping
      \begin{align}
        \beli_e^{(t)}: \setxe \to \sR_{\geq 0}, \quad
        \xe
        &\mapsto
        \bigl( \kappa_e^{(t)} \bigr)^{-1}
        \cdot
        \mu_{\efi}^{(t)}(\xe) \cdot
        \mu_{\efj}^{(t)}(\xe),
        \label{sec:SNFG:eqn:2}
      \end{align}
      where the scaling factor $ \kappa_e^{(t)} $ is defined to be
      %------------------------------------------------------------------------
      \begin{align*}
          \kappa_e^{(t)} \defeq \sum_{\xe} 
          \mu_{\efi}^{(t)}(\xe) \cdot \mu_{\efj}^{(t)}(\xe).
      \end{align*}
      %------------------------------------------------------------------------
      The associated vector is defined to be 
      $ \vbeli_{e}^{(t)} \defeq \bigl( \beli_e^{(t)}(\xe) \bigr)_{ \!  \xe } $.



      \item\label{SPA: update belief functions} For every $f \in \setF$, we define the belief function at function node $f$ to be the mapping
      \begin{align}
        \beli_f^{(t)}: \setxf \to \sR_{\geq 0}, \quad
          \xf
          &\mapsto 
            \bigl( \kappa_f^{(t)} \bigr)^{\! -1}
              \cdot
              f(\xf)
              \cdot
              \prod_{e \in \setpf}
                \mu_{\etof}^{(t)}(\xe),
                    \label{sec:SNFG:eqn:1}
      \end{align}
      where the scaling factor $ \kappa_f^{(t)} $ is defined to be
      %------------------------------------------------------------------------
      \begin{align*}
        \kappa_f^{(t)} \defeq 
            \sum_{ \xf }
            f(\xf) \cdot \prod_{e \in \setpf} \mu_{\etof}^{(t)}(\xe).
      \end{align*}
      %------------------------------------------------------------------------
      % If $ \kappa_f^{(t)} \neq 0 $, then we define the belief function at function node $f$ to be the mapping
      %   \begin{align}
      %     \beli_f^{(t)}: \setxf \to \sR_{\geq 0}, \quad
      %       \xf
      %       &\mapsto 
      %         \bigl( \kappa_f^{(t)} \bigr)^{\! -1}
      %           \cdot
      %           f(\xf)
      %           \cdot
      %           \prod_{e \in \setpf}
      %             \mu_{\etof}^{(t)}(\xe).
      %                 \label{sec:SNFG:eqn:1}
      %   \end{align}
      The associated vector is defined to be
      $ \vbeli_{f}^{(t)} \defeq \bigl( \beli_f^{(t)}(\xf) \bigr)_{ \! \xf } $.

      \item 
        If an edge $ e = (f_{i},f_{j}) \in \setEfull $ satisfies
        $ \kappa_{\efi}^{(t)} \cdot \kappa_{\efj}^{(t)} \cdot \kappa_e^{(t)} \cdot 
        \kappa_{f_{i}}^{(t)} \cdot \kappa_{f_{j}}^{(t)}
        = 0 $, 
        then we skip the update procedures of Steps~\ref{SPA: update message},~\ref{SPA: update belief edges},
        and~\ref{SPA: update belief functions}
        for the vectors in $ \{ \vmu_{e_{1},f_{i}}^{(t)}, \vmu_{e_{2},f_{j}}^{(t)} 
        \}_{e_{1} \in \setpfi, e_{2} \in \setpfj} $, the vector $\vbeli_{e}^{(t)}$,
        and the vectors in $\{\vbeli_{f_{i}}^{(t)},\vbeli_{f_{j}}^{(t)}\}$, respectively.
        Instead, for each $ e_{1} \in \setpfi $ and each $ e_{2} \in \setpfj $,
        we randomly generate the vectors 
        $ \vmu_{e_{1},f_{i}}^{(t)}$ and $ \vmu_{e_{2},f_{j}}^{(t)}$ uniformly from 
        $ \set{P}_{\set{X}_{e_1}} $  and 
        $ \set{P}_{\set{X}_{e_2}} $, respectively.
        Similarly, 
        we randomly generate $\vbeli_{e}^{(t)}$, $\vbeli_{f_{i}}^{(t)}$, and $\vbeli_{f_{j}}^{(t)}$  
        uniformly from 
        $ \set{P}_{\set{X}_{e}} $,
        $ \set{P}_{\set{X}_{\setpfi}} $,
        and $ \set{P}_{\set{X}_{\setpfj}} $,
        respectively.
      \end{enumerate}

      \item At iteration $t \in \sZpp$, the SPA messages can be collected as the SPA message vector
      %--------------------------------------------------------------------
      \begin{align*}
        \vmu^{(t)} \defeq 
        \bigl( \vmu_{\etof}^{(t)} \bigr)_{ \! e \in \setpf,\, f \in \setF}.
      \end{align*}
      %--------------------------------------------------------------------
      With this, the SPA message update rules can be written as
      %--------------------------------------------------------------------
      \begin{align*}
        \vmu^{(t)} = \fSPAN\bigl( \vmu^{(t-1)} \bigr),
      \end{align*}
      %--------------------------------------------------------------------
      where $\fSPAN$ is some suitably defined function. 

      \item An SPA message vector
      %--------------------------------------------------------------------
      \begin{align}
        \vmu \defeq ( \vmu_{\etof} )_{e \in \setpf,\, f \in \setF},
        \label{sec:SNFG:eqn:10}
      \end{align}
      %--------------------------------------------------------------------
      where 
      $ \vmu_{\etof} \defeq \bigl( \mu_{\etof}(\xe) \bigr)_{ \! \xe} $
      is called an SPA fixed-point message vector if it satisfies
      %--------------------------------------------------------------------
      \begin{align}
        \vmu = \fSPAN(\vmu). \label{sec:SNFG:eqn:11}
      \end{align}
      The definitions of the belief functions $ \beli_e $ and $ \beli_f $
      derived from the SPA fixed-point message vector $ \vmu $ 
      are defined similarly as the definitions in~\eqref{sec:SNFG:eqn:2} 
      and~\eqref{sec:SNFG:eqn:1}, respectively, with 
      $ \vmu_{\etof}^{(t)} $ replaced by $ \vmu_{\etof} $ for all
      $ e \in \setpf $ and $ f \in \setF $.
      %-------------------------------------------------------------------- 
  % where $ \mu_{\etof} : \setxe \to \sR $ is an arbitrary mapping and $ \vmu_{\etof} = ( \mu_{\etof}(\xe) )_{\xe} $.

  % \item The beliefs evaluated at an SPA message vector $ \vmu $ are given by 
  % %-----------------------------------------------------------------------
  % \begin{align}
  %     \beli_{f,\vmu}(\xf)
  %     &\defeq \kappa_f
  %       \cdot
  %       f(\xf)
  %       \cdot
  %       \prod_{e \in \setpf}
  %         \mu_{\etof}(\xe),
  %           \quad \xf \in \setxf,\, \kappa_f \in \sR_{>0}, 
  %     \label{sec:DENFG:eqn:12} \\
  %     \beli_{e,\vmu}(\xe)
  %     &\defeq \kappa_e
  %     \cdot
  %     \mu_{\efi}(\xe)
  %     \cdot
  %     \mu_{\efj}(\xe),
  %     \quad \xe \in \setxe,\, \kappa_e \in \sR_{>0}, 
  %     \label{sec:DENFG:eqn:13}.
  % \end{align}
  % %-----------------------------------------------------------------------

\end{enumerate}
\edefinition
\end{definition}

