\begin{remark}
\label{asmp: assume messages are nonnegative}

  We make some remarks on the SPA as defined in 
  Definition~\ref{def:belief at SPA fixed point for S-NFG}.
  \begin{itemize}
    \item If desired or necessary, other normalization procedures for messages and
    beliefs can be specified. 
    % Note that other normalization procedures for beliefs do not change the results in this paper.

    \item In the context of S-NFGs, if not mentioned otherwise, we will only consider the SPA
    messages and beliefs such that 
    $ \vmu_{\etof}^{(t)}, \vbeli_{e}^{(t)} \in \pmf{\setxe}$
    and $ \vbeli_f^{(t)} \in \pmf{\setxf} $ 
    for all $e \in \setpf$,
    $f \in \setF$, and $ t \in \sZp $.
  \end{itemize}

\eassumption
\end{remark}
%***************************************************************************

Yedidia~\etal~\cite[Section V]{Yedidia2005} showed that the SPA fixed-point message vectors can be 
characterized by the stationary points of the Bethe free energy function. 
The following definitions related to the Bethe free energy function are
adapted from~\cite[Section V]{Yedidia2005} to S-NFGs.

\begin{definition}\!\!\cite[Section V]{Yedidia2005}\label{sec:SNFG:def:3}
Let $\graphN$ be some S-NFG. The collection of beliefs is defined to be
%-----------------------------------------------------------------------
\begin{align*}
   \vbeli \defeq \Bigl( ( \vbeli_f )_{f \in \setF}, \,
  ( \vbeli_e )_{e \in \setE} \Bigr),
\end{align*}
%-----------------------------------------------------------------------
where $ \vbeli_f \defeq \bigl( \beli_f(\vxf) \bigr)_{\! \vxf \in \setxf } $ 
for all $ f \in \setF $
and $ \vbeli_e \defeq \bigl( \beli_e(\xe) \bigr)_{\! \xe \in \setxe } $ 
for all $ e \in \setEfull $.
The local marginal polytope $\LMP(\graphN)$
associated with $\graphN$ is defined to be
\begin{align*}
  \LMP(\graphN)
    &\defeq \left\{ 
      \vbeli
    \ \middle| \ 
      \begin{array}{c}
        \vbeli_f \in \pmf{\setxf} \ \text{for all} \ f \in \setF \\
        \vbeli_e \in \pmf{\setxe} \ \text{for all} \ e \in \setE \\[0.10cm]
        \sum\limits_{\vx_{\setpf \setminus e}}
          \beli_f(\xf)
            = \beli_e(\xe),
                \ \forall
                e \in \setpf, f \in \setF, \xe \in \setxe
      \end{array}
    \right\}. 
    % \label{sec:SNFG:eqn:12}
\end{align*}
\edefinition
\end{definition}


