\begin{definition}\label{sec:DENFG:def:2}

    The SPA for a DE-NFG $\sfN$ is a natural extension of the SPA for an S-NFG, with its steps specified below.
    \begin{enumerate}

        \item (Initialization) 
        For every $f \in \setF$ and $ e \in \setpf $, the
        messages $\mu_{\ef}^{(0)}: \tset{X}_{e} \to \sC \setminus \{0\}$, are initialized as some
        arbitrary non-zero-valued function such that $ \sum_{\txe} \mu_{\ef}^{(0)}(\txe) = 1 $. 
        (A typical choice is 
        $\mu_{\ef}^{(0)}(\txe) \defeq |\tset{X}_{e}|^{-1} $ for
        all $\tx_e \in \tset{X}_{e}$.) 

        \item\label{details of SPA in DE-NFG} (Iteration) For $t = 1, 2, 3, \ldots$, the following calculations are performed until a termination criterion is met.\footnote{The termination
          criterion is typically a combination of numerical convergence and an
          upper bound on the number of iterations.}
        \begin{enumerate}

        \item
        \label{SPA: update message: DE-NFG}

        For each $ e = (f_{i},f_{j}) \in \setEfull $, we define the messages 
        from edge $ e $ to function nodes $ f_{j} $ and $ f_{i} $ to be the mappings
        % \footnote{If desired or necessary, other normalization procedures is allowed.}
        \begin{align*}
          \mu_{\efj}^{(t)}: \tset{X}_{e} \to \sC, \qquad
            \txe
              &\mapsto
                 \bigl( \kappa_{\efj}^{(t)} \bigr)^{\!-1}
                 \cdot
                 \sum_{\tvx_{\setpfi \setminus e}}
                  f_{i}\bigl( \tvx_{\setpfi} \bigr)
                   \cdot \prod_{e'\in \setpfi \setminus e}
                    \mu_{\epfi}^{(t-1)}(\tx_{e'}),
              % \label{sec:DENFG:eqn:10} 
              \\
              \mu_{\efi}^{(t)}: \tset{X}_{e} \to \sC, \qquad
              \txe
              &\mapsto
             \bigl( \kappa_{\efi}^{(t)} \bigr)^{\!-1}
             \cdot
             \sum_{\tvx_{\setpfj \setminus e}}
              f_{j}\bigl( \tvx_{\setpfj} \bigr)
              \cdot
              \prod_{e'\in \setpfj \setminus e}
              \mu_{\epfj}^{(t-1)}(\tx_{e'}), \nonumber
              % \label{sec:DENFG:eqn:11}
        \end{align*}
        where the scaling factors $\kappa_{\efj}^{(t)} $ and $\kappa_{\efi}^{(t)} $ are defined to be
        %------------------------------------------------------------------------
        \begin{align*}
            \kappa_{\efj}^{(t)} &\defeq 
            \sum_{\tvx_{\setpfi}}
            f_{i}\bigl( \tvx_{\setpfi} \bigr) 
            \cdot \prod_{e' \in \setpfi \setminus e}
            \mu_{\epfi}^{(t-1)}(\tx_{e'}), \nonumber\\
            \kappa_{\efi}^{(t)} &\defeq 
            \sum_{\tvx_{\setpfj}}
            f_{j}\bigl( \tvx_{\setpfj} \bigr) 
            \cdot \prod_{e' \in \setpfj \setminus e}
            \mu_{\epfj}^{(t-1)}(\tx_{e'}).
        \end{align*}
        %------------------------------------------------------------------------
        The associated vectors are defined to be 
        $ \vmu_{\efj}^{(t)} \defeq \bigl( \mu_{\efj}^{(t)}(\txe) \bigr)_{ \!  \txe } $
        and $ \vmu_{\efi}^{(t)} \defeq \bigl( \mu_{\efi}^{(t)}(\txe) \bigr)_{ \!  \txe } $.
        % If 
        % $ 
        %     \kappa_{\efi}^{(t)} \cdot \kappa_{\efj}^{(t)} = 0 
        % $,
        % we randomly generate each element in 
        % \begin{align*}
        %   \bigl( \mu_{\etof}^{(t-1)}(\txe) \bigr)_{ \! \xe \in \setxe,\, 
        %   e \in \{ \setpfi \cup \setpfj \} \setminus \{e\} } 
        % \end{align*}
        % following a uniform distribution in $ [0,1] $. 

        % \item If there exists an edge $ e = (f_{i}, f_{j}) \in \setEfull $ such that 
        % $ 
        %     \kappa_{\efi}^{(t)} \cdot \kappa_{\efj}^{(t)} = 0 
        % $,
        % we randomly generate each element in 
        % \begin{align*}
        %   \bigl( \mu_{\etof}^{(t-1)}(\txe) \bigr)_{ \! \xe \in \setxe,\, 
        %   e \in \{ \setpfi \cup \setpfj \} \setminus \{e\} } 
        % \end{align*}
        % following a uniform distribution in $ [0,1] $. 

        % \item If $ \prod_{f} \prod_{e \in \setpf} \kappa_{\ef}^{(t)} \neq 0 $, then for each $ e = (f_{i},f_{j}) \in \setEfull $, we define the messages 
        % from edge $ e $ to function node $ f_{j} $ to be the mapping:\footnote{If desired or necessary, other generalization procedures is allowed.}
        % \begin{align}
        % 	\mu_{\efj}^{(t)}: \tset{X}_{e} \to \sC, \qquad
        %     \txe
        %       &\mapsto
        %          \bigl( \kappa_{\efj}^{(t)} \bigr)^{\!-1}
        %          \cdot
        %          \sum_{\tvx_{\setpfi \setminus e}}
        %           f_{i}\bigl( \tvx_{\setpfi} \bigr)
        %            \cdot \prod_{e'\in \setpfi \setminus e}
        %             \mu_{\epfi}^{(t-1)}(\tx_{e'}),
        %       \label{sec:DENFG:eqn:10} \\
        %       \mu_{\efi}^{(t)}: \tset{X}_{e} \to \sC, \qquad
        %       \txe
        %       &\mapsto
        %      \bigl( \kappa_{\efi}^{(t)} \bigr)^{\!-1}
        %      \cdot
        %      \sum_{\tvx_{\setpfj \setminus e}}
        %       f_{j}\bigl( \tvx_{\setpfj} \bigr)
        %        \cdot
