        %       % \label{sec:DENFG:eqn:11}
        % \end{align}
        % % One can obtain the definition of $ \mu_{\efi}^{(t)} $ by switching $ f_{i}  $ with $ f_{j} $ in the above definition. 

        \item 
        \label{SPA: update belief edges: DE-NFG} 
        For every $e = (f_{i}, f_{j}) \in \setEfull$, 
        we define the belief function at edge $e$ to be the mapping
        \begin{align}
          \beli_{e}^{(t)}: \tset{X}_{e} \to \sC, \qquad
          \txe
            &\mapsto 
              \bigl( \kappa_e^{(t)} \bigr)^{\!-1}
              \cdot
              \mu_{\efi}^{(t)}(\txe)
              \cdot \mu_{\efj}^{(t)}(\txe),
              \label{sec:DENFG:eqn:2}
        \end{align}
        where the scaling factor is defined to be
        %------------------------------------------------------------------------
        \begin{align*}
            \kappa_e^{(t)} \defeq
            \sum_{\txe}
            \mu_{\efi}^{(t)}(\txe)
            \cdot \mu_{\efj}^{(t)}(\txe).
        \end{align*}
        The associated vector is defined to be 
        $ \vbeli_{e}^{(t)} \defeq \bigl( \beli_e^{(t)}(\txe) \bigr)_{ \!  \txe } $.


        \item\label{SPA: update belief functions: DE-NFG} 
