\begin{lemma}
  \label{sec:DENFG:lem:1}
  Consider running the SPA defined in Definition~\ref{sec:DENFG:def:2} on a DE-NFG $\graphN$. The following properties with respect to the messages and belief functions hold.
  %---------------------------------------------------------------------------
  \begin{enumerate}

    \item\label{sec:DENFG:lem:1:item:1} For all $t \in \sZpp $, we have 
    $ \matr{C}_{\mu_{\ef}^{(t)}},\matr{C}_{\beli_{e}^{(t)}} \in \setPSD{\set{X}_{e}} $ for all $ e \in \setpf $ and $ f \in \setF $ and
    $\matr{C}_{\beli_f^{(t)}} \in \setPSD{\tset{X}_{\setpf}}$ for all $f \in \setF$.

    \item\label{sec:DENFG:lem:1: PSD of SPA fixed point message} For any SPA fixed-point message vector $ \vmu $, it holds that $ \matr{C}_{\mu_{\ef}} \in \setPSD{\set{X}_{e}} $ for all $ e \in \setpf $ and $ f \in \setF $

    \item\label{sec:DENFG:lem:1:item:2} The beliefs induced by an SPA fixed-point message 
    vector $\vmu$ satisfy the local consistency constraints
    %-----------------------------------------------------------------------
    \begin{align*}
         \sum_{ \tvx_{\setpf \setminus e} } 
         \beli_f(\tvx_{\setpf}) 
         = \beli_{e}(\tx_{e}), \qquad 
         \txe \in \tset{X}_{e}, \, e \in \setpf,\, f \in \setF.
    \end{align*}
    %-----------------------------------------------------------------------
    % for some constant $c_{f,e}$. (In contrast to S-NFGs, the constant $c_{f,e}$ may not be equal to one 
    % because of the type of normalization in~\eqref{sec:DENFG:eqn:1} and~\eqref{sec:DENFG:eqn:2} in Definition~\ref{sec:DENFG:def:2}.) 
    % If we consider the following normalization procedure
    % %------------------------------------------------------------------------
    % \begin{align*}
    %     \sum_{\tvx_{\setpf}} \beli_f^{(t)}\bigl( \tvx_{\setpf} \bigr) &= 1, \qquad 
    %     f \in \setF,\qquad
    %     \sum_{\tx_{e}} \beli_{e}^{(t)}(\tx_{e}) = 1, \qquad 
    %     e \in \setEfull,
    % \end{align*}
    % %------------------------------------------------------------------------
    % then we have $ c_{f,e} = 1 $ for all $ e \in \setpf $ and $ f \in \setF $.
  \end{enumerate}
  %---------------------------------------------------------------------------
\end{lemma}

%***************************************************************************

\begin{proof}
  The statement in Item~\ref{sec:DENFG:lem:1:item:1} is a consequence of Remark~\ref{asmp: assume messages are PSD} and a variant of Schur's product theorem, which states that the entry-wise
  product of two PSD matrices is again a PSD
  matrix.\footnote{Schur's product theorem states that the entry-wise product
    of two positive definite matrices is a positive definite matrix. Note that
    the entry-wise product of two matrices is also known as the Hadamard
    product.} The statement in Item~\ref{sec:DENFG:lem:1: PSD of SPA fixed point message} is a straightforward result of Item~\ref{sec:DENFG:lem:1:item:1}.
   The statement in Item~\ref{sec:DENFG:lem:1:item:2} is a consequence of the SPA message update rules.
\end{proof}

