\begin{lemma}\label{lem: nonnegative of ZBSPA for DE-NFG}
  Consider a DE-NFG $\graphN$ and an SPA fixed-point message vector $ \vmu $. It holds that 
  %------------------------------------------------------------------------
    \begin{align*}
        Z_f(\vmu) &\in  \sR_{\geq 0}, \qquad f \in \setF, \\
        Z_{e}(\vmu)
        & \in \sRp,
        \qquad e \in \setEfull.
        % \label{sec:DENFG:eqn:14}
    \end{align*}
    %------------------------------------------------------------------------
  % which implies that $\ZBSPA(\graphN,\vmu) \in \sRp$ if $ \prod_{e} Z_{e}(\vmu) > 0 $.
\end{lemma}

%***************************************************************************

\begin{proof}
    By Lemma~\ref{sec:DENFG:lem:1}, we know that $ \vmu_{\ef} \in \setPSD{\set{X}_{e}} $ for all $ e \in \setpf $ and $ f \in \setF $. Then we
    can use Schur's product theorem to show that 
    the matrix
    \begin{align*}
      \Biggl( 
        f\bigl( \tvx_{\setpf} \bigr)
        \cdot
        \prod_{e \in \setpf}
        \mu_{\ef}(\txe)
      \Biggr)_{ \!\!\! \vx_{\setpf}, \vx_{\setpf}' \in \set{X}_{\setpf} }
    \end{align*}
    with row indices $ \vx_{\setpf} $ and column indices $ \vx_{\setpf}' $ is a PSD matrix.
    Therefore, we obtain
    \begin{align*}
      Z_f(\vmu) 
      = 
      \sum_{\tvx_{\setpf}} 
      f\bigl( \tvx_{\setpf} \bigr)
      \cdot
      \prod_{e \in \setpf}
      \mu_{\ef}(\txe) \in \sR_{\geq 0}.
    \end{align*}

    The proof of the property that $ Z_{e}(\vmu) \in \sR_{\geq 0} $ for all $ e \in \setEfull $ is similar and thus it is omitted here.
    % For $Z_f(\vmu)$, we have
    % %------------------------------------------------------------------------
    % \begin{align*}
