    %       \cdot \matr{C}_{f}
    %       \cdot 
    %       \Biggl( 
    %         \bigotimes_{e \in \setpf} 
    %         \overline{ \vmu_{\ef} }
    %       \Biggr) 
    %     \overset{(b)}{\in}   \sR_{\geq 0},
    %             \qquad 
    %             f \in \setF, 
    % \end{align*}
    % %------------------------------------------------------------------------
    % where step $(a)$ follows from the property of SPA fixed-point messages in Lemma~\ref{sec:DENFG:lem:2}, \ie, $ \vmu_{\upef} = \overline{ \vmu_{\ef} } $ for all $ e \in \setpf $ and $ f \in \setF $, and where step $(b)$ follows from Assumption~\ref{sec:DENFG:asum:2}, \ie, $ \matr{C}_{f} \in \setPSD{\tset{X}f} $. 

    % Similarly, we obtain the expression of $ Z_{e} $ in~\eqref{sec:DENFG:eqn:14} following the property of SPA fixed-point messages in Lemma~\ref{sec:DENFG:lem:2}.
\end{proof}


