\section{Finite Graph Covers}
\label{sec:GraCov}

This section reviews finite graph covers, a key combinatorial tool for analyzing NFGs, based on the foundational work in~\cite{Stark:Terras:96:1, Koetter2007,Vontobel2013}.

%***************************************************************************

\begin{definition}
  A graph $\hat{\mathsf{G}} = (\hat{\set{V}}, \hat{\set{E}})$ with vertex set
  $\hat{\set{V}}$ and edge set $\hat{\set{E}}$ is the cover of a graph
  $\mathsf{G} = (\set{V}, \set{E})$ if there exists a graph homomorphism
  $\pi: \hat{\set{V}} \to \set{V}$ such that for each $v \in \set{V}$ and
  $\hat{v} \in \pi^{-1}(v)$, where $\pi^{-1}$ is the pre-image of $v$ under
  the mapping $\pi$, the neighborhood of $\hat{v}$, \ie, 
  the set of all vertices in $ \hat{\set{V}} $ adjacent to $ \hat{v} $, is
  mapped bijectively onto the neighborhood of $v$, \ie, the set of all vertices in $ \set{V} $ adjacent to $ v $. Given a cover
  $\hat{\mathsf{G}} = (\hat{\set{V}}, \hat{\set{E}})$, if there is a positive
  integer $M$ such that $|\pi^{-1}(v)| = M$ for all $v\in \set{V}$, then
  $\hat{\mathsf{G}}$ is called an $M$-cover.
  \edefinition
\end{definition}

%***************************************************************************


Without loss of generality, we can denote the vertex set of an $M$-cover by
$\hat{\set{V}} \defeq \set{V} \times [M]$ and define the mapping
$\pi: \hat{\set{V}} \to \set{V}$ to be such that $\pi\bigl( (v,m) \bigr) = v$ for all
$m \in [M]$. Consider an edge in the original graph that connects nodes $v$ and $v'$ and the corresponding edge in the $M$-cover that connects nodes $(v,m)$ and $(v',m')$. It holds that
\begin{align*}
  \Bigl( \pi \bigl( (v,m) \bigr), \pi \bigl( (v',m') \bigr) \Bigr) = (v,v').
\end{align*}
For every edge $e =(v,v')$ in the original graph, there exists a permutation $\sigma_e \in \set{S}_{[M]}$ such that for each $ m \in [M] $, 
the edge $ \bigl( (v,m), (v',m') \bigr) $ in the $M$-cover satisfies $ m' = \sigma_{e}(m) $. Therefore,
for every edge $e =(v,v')$ in the original graph, the corresponding edges in the $M$-cover
can be represented by the set
\begin{align*}
  \left\{ 
    \Bigl( (v,m),\bigl(v',\sigma_{e}(m)\bigr) \Bigr) 
    \ \middle| \ 
    m \in [M] 
  \right\}.
\end{align*}

% such that the set of the corresponding edges can be represented by the set
% \begin{align*}
%   \left\{ 
%     \Bigl( (v,m),\bigl(v',\sigma_{e}(m)\bigr) \Bigr) 
%     \ \middle| \ 
%     m \in [M] 
%   \right\}.
% \end{align*}
% This observation motivates the following definition.
%***************************************************************************

\begin{definition}
% (\textbf{Degree-$M$ finite graph covers of NFGs})
  \label{sec:GraCov:def:1}
  Let $\graphN = (\set{F}, \set{E}, \set{X})$ be an S-NFG or a DE-NFG, and let $M \in \sZpp$. A degree-$M$ cover of $\graphN$, denoted by $\hgraphN$, is an NFG specified by a vector of permutations $\vsigma \defeq (\sigma_e)_{e \in \set{E}} \in \set{S}_M^{|\set{E}|}$. The components of $\hgraphN = (\hat{\set{F}}, \hat{\set{E}}, \hat{\set{X}})$ are defined as follows:
  \begin{enumerate}
      \item Function Nodes: The set of function nodes is $\hat{\set{F}} \defeq \set{F} \times [M]$. Each node $(f,m) \in \hat{\set{F}}$ inherits the local function of its corresponding node $f \in \set{F}$.
      \item Edges: For each edge $e = (f_i, f_j) \in \set{E}$, the cover contains $M$ corresponding edges given by the set
      \begin{align*}
          \hat{\set{E}}_e \defeq \left\{ \Bigl( (f_i, m), \bigl(f_j, \sigma_e(m) \bigr) \Bigr) 
          \ \middle| \ m \in [M] \right\}.
      \end{align*}
      The full edge set of the cover is $\hat{\set{E}} \defeq \bigcup_{e \in \set{E}} \hat{\set{E}}_e$.
      \item Alphabets: Each edge $\hat{e} \in \hat{\set{E}}_e$ inherits the alphabet of its corresponding edge $e \in \set{E}$. For an S-NFG, the alphabet is $\set{X}_{\hat{e}} \defeq \set{X}_e$; for a DE-NFG, it is $\tset{X}_{\hat{e}} \defeq \tset{X}_e$.
  \end{enumerate}
  The set of all possible degree-$M$ covers of $\graphN$ is denoted by $\setcovN{M}$.
  \edefinition
\end{definition}



%***************************************************************************

For a given NFG $\mathsf{N}$, we consider all graphs in $\hat{\set{N}}_{M}$ to be
distinct graphs, despite that some graphs in the set $\hat{\set{N}}_{M}$
might be isomorphic to each other. (See also the comments on labeled graph
covers after~\cite[Definition~19]{Vontobel2013}.) More importantly, for the finite graph covers of a DE-NFG, the double edges are permuted together.\footnote{ A graph-cover definition based on splitting the two edges comprising a double edge could be considered. However, the resulting graph covers would not be immediately relevant for analyzing the SPA in the way that it is formulated.}

