% \subsection{Characterization of the Bethe Approximation}

%***************************************************************************


\begin{definition}\label{sec:GraCov:def:2}

  Let $\graphN$ be an S-NFG or a DE-NFG. For any $M \in \sZpp$, we
  define the degree-$M$ Bethe partition function of $\graphN$ to be
  \begin{align*}
    \ZBM(\graphN) 
      \defeq \sqrt[M]{
           \Bigl\langle
             Z\bigl( \hgraphN \bigr)
           \Bigr\rangle_{ \! \! \hgraphN \in \hat{\set{N}}_{M}}
         } \ ,
  \end{align*}
  where
  $\bigl\langle Z\bigl( \hgraphN \bigr) \bigr\rangle_{\! \hgraphN \in \hat{\set{N}}_{M}}$
  represents the arithmetic mean of
  $Z\bigl( \hgraphN \bigr)$ over all $\hgraphN \in \hat{\set{N}}_{M}$, \ie,
  \begin{align*}
    \Bigl\langle
       Z\bigl( \hgraphN \bigr)
    \Bigr\rangle_{\! \hgraphN \in \hat{\set{N}}_{M}}
    \defeq \frac{1}{|\hat{\set{N}}_{M}|} 
    \cdot \sum_{ \hgraphN \in \hat{\set{N}}_{M} } Z\bigl( \hgraphN \bigr),
  \end{align*}
  where
  $\hat{\set{N}}_{M}$ is the set of all $M$-covers of $\graphN$ (see
  Definition~\ref{sec:GraCov:def:1}).
  \edefinition
\end{definition}

%***************************************************************************

% The following characterization of S-NFGs' Bethe partition functions in
% terms of finite graph covers was given in~\cite{Vontobel2013}.

%***************************************************************************

\begin{theorem}\!\!\cite{Vontobel2013}
  \label{sec:GraCov:thm:1}
  Consider an arbitrary S-NFG $\graphN$. It holds that
  \begin{align*}
    \limsup_{M\to \infty}
      \ZBM(\graphN)
      &= \ZB(\graphN).
      \nonumber
  \end{align*}
  \etheorem
\end{theorem}

%***************************************************************************

Given that DE-NFGs are in many ways a natural generalization of
S-NFGs, one wonders if there is a characterization of the Bethe partition
function of a DE-NFG in terms of its graph covers,
analogous to Theorem~\ref{sec:GraCov:thm:1}.


%***************************************************************************

\begin{conjecture}
  \label{sec:GraCov:conj:1}

  Consider an arbitrary DE-NFG $\graphN$. It holds that
  \begin{align}
      \limsup_{M\to \infty}
      \ZBM(\graphN)
      &= \ZBSPA^{*}(\graphN). \label{eqn: graph cover theorem}
  \end{align}
  \econjecture
\end{conjecture}
The left-hand side of~\eqref{eqn: graph cover theorem}
features a limit superior $ \limsup_{M\to \infty} \ZBM(\graphN) $. For each DE-NFG $ \sfN $, we have $ Z(\graphN) \in \sRpp $, as assumed in Assumption~\ref{sec:DENFG:asum:2}. Because each $M$-cover is again a DE-NFG, we further have $ \ZBM(\graphN) \in \sRp $ and thus $ \limsup_{M\to \infty} \ZBM(\graphN) \in \sRp $. 
The right-hand side of~\eqref{eqn: graph cover theorem}
features $\ZBSPA^{*}(\graphN)$, not $\ZB(\graphN)$, because only the
former is defined for DE-NFGs. 
%***************************************************************************

As already mentioned in the introduction, the proof of
Theorem~\ref{sec:GraCov:thm:1} heavily relies on
the method of types and the primal formulation of the Bethe partition function. However, the method of types does not seem to be useful
for proving Conjecture~\ref{sec:GraCov:conj:1}, and it is unclear how to generalize the primal formulation of the Bethe partition function, \ie, Definition~\ref{sec:SNFG:def:1}, to the case of DE-NFGs. Therefore, novel techniques have to be developed in order to prove Conjecture~\ref{sec:GraCov:conj:1}. Section~\ref{sec:LCT} introduces the LCT, a key technical innovation of this work, which reparameterizes the partition function of a DE-NFG into a form that is suitable for analysis.
Based on the LCT, in Theorem~\ref{sec:CheckCon:thm:1}, we prove that
the limit~\eqref{eqn: graph cover theorem} holds for the DE-NFGs
satisfying an easily checkable condition. We conjecture that the limit~\eqref{eqn: graph cover theorem} holds for more general DE-NFGs. In the rest of this section, we provide promising numerical results supporting
Conjecture~\ref{sec:GraCov:conj:1}.

\input{figures/graph_cov_thm/numerical_result_main}

