\begin{proposition}
  \label{sec:LCT:prop:1}

  Consider an S-NFG $\graphN$. Let
  $\vmu $ be an SPA
  fixed-point message vector for $\graphN$ such that $ Z_e(\vmu) >0 $ for all $ e \in \setEfull $ and $ \ZBSPA(\graphN,\vmu) > 0 $. Then the loop-calculus transformed NFG $\LCT{\graphN}$ is well defined, as specified in
  Definition~\ref{sec:LCT:def:1}.
  The main properties of $\LCT{\graphN}$ are as follows.
  \begin{enumerate}

  \item\label{sec:LCT:prop:1:item:1} The partition function remains the same, \ie,
    \begin{align*}
      Z(\graphN)
        &= Z\bigl( \LCT{\graphN} \bigr).
    \end{align*}

  \item\label{sec:LCT:prop:1:item:2} The SPA-based Bethe partition function of the original S-NFG is equal to the global function value of the all-zero configuration of
    $\LCT{\graphN}$, \ie,
    \begin{align*}
      \ZBSPA(\graphN,\vmu)
        &= \LCT{g}(\vect{0}).
    \end{align*}

  \item\label{sec:LCT:prop:1:item:3} For any $f \in \setF$ and any $\LCTvxf \in \LCTsetxf$ with
    exactly one non-zero component, \ie, $ \wh( \LCTvxf ) = 1 $ with 
    $ \wh( \LCTvxf ) \defeq \sum_{e \in \setpf} 
    [\LCT{x}_{e} \!\neq\! 0] $,
    it holds that
    \begin{align*}
      \LCT{f}(\LCTvxf)
        &= 0,
    \end{align*}
    where $ \wh( \cdot ) $ is the Hamming weight, \ie, the number of non-zero elements, of the argument.

  \item\label{sec:LCT:prop:1:item:4} A configuration $\LCTv{x}$ is called a generalized loop if the subgraph
     $\bigl( \setF,\setE'(\LCTv{x}) \bigr)$ with vertex set $\setF$ and edge set \\
    $\setE'(\LCTv{x}) \defeq \{ e \in \setE \ | \ \LCT{x}_{e} \neq 0 \}$ does not contain any leaves 
    \ie, vertices of degree one. (Note that the all-zero
    configuration $\LCTv{x} = \vect{0}$ is also considered as a generalized loop.)
    It holds that all valid configurations of $\LCT{\graphN}$ are generalized
    loops, and if $\LCTv{x}$ is not a generalized loop, then
    $\LCT{g}(\LCTv{x}) = 0$. 
    If $\graphN$ is cycle-free and with that
    also $\LCT{\graphN}$ is cycle-free, then the only generalized loop is the
    all-zero configuration.

  \item\label{sec:LCT:prop:1:item:5} It holds that
    \begin{align*}
      Z(\LCT{\graphN})
        &= \ZBSPA(\graphN,\vmu)
           \cdot
           \left(
             1
             +
             \sum_{\LCTv{x}:\, \setE'(\LCTv{x}) \neq \emptyset }
               \frac{\LCT{g}(\LCTv{x})}
                    {\LCT{g}(\vect{0})}
           \right), 
    \end{align*}
    where the summation is over all $ \LCTv{x} \in \prod_{e} \LCTsetxe $ such that $ \setE'(\LCTv{x}) $ induces a non-zero generalized loop of
    $\LCT{\graphN}$. The terms in the set
    %-----------------------------------------------------------------------
    $
      \bigl\{ \LCT{g}(\LCTv{x})/\LCT{g}(\vect{0})
      \bigr\}_{\! \LCTv{x}:\, \setE'(\LCTv{x}) \neq \emptyset}
    $
    %-----------------------------------------------------------------------
    are viewed as ``correction terms'' for the SPA-based Bethe approximation. Note
    that if $\graphN$ is cycle-free, then there is no correction term,
    implying the well-known result that
    $Z(\graphN) = \ZBSPA(\graphN,\vmu)$.

  \item\label{sec:LCT:prop:1:item:6} The SPA fixed-point message vector
    $\vmu $ for
    $\graphN$ induces an SPA fixed-point message vector
    $\LCTv{\mu} \defeq ( \LCTv{\mu}_{\ef} )_{e \in \setpf, f \in \setF}$ for
    $\LCT{\graphN}$ with
    \begin{align*}
       	\LCT{\mu}_{e,f}(\LCT{x}_{e})
        &= \bigl[ \LCT{x}_{e} \! = \! 0 \bigr],
        \qquad
        \LCT{x}_{e} \in \LCTset{X}_{e}, \,
        e \in \setpf, \, f \in \setF.
    \end{align*}

  \item\label{sec:LCT:prop:1:item:7} While the above properties are shared by all variants of the LCT, the
    LCT in Definition~\ref{sec:LCT:def:1} has the following additional
    properties (that are not necessarily shared by the other LCT variants).
    \begin{enumerate}

    \item For every $e = (f_{i},f_{j}) \in \setE$, the functions $M_{\efi}$ and
      $M_{\efj}$ are formally symmetric in the sense that swapping $f_{i}$ and
      $f_{j}$ in the definition of $M_{\efi}$ leads to the definition of
      $M_{\efj}$, and vice-versa.

    \item\label{sec:LCT:prop:1:item:7:b} Assume that $M_{\efi}$ and $M_{\efj}$ are defined based on the
      choices $\zeta_{\efi} = \zeta_{\efj} \defeq Z_e^{-1/2}$,
      $\chi_{\efi} = \chi_{\efj} \defeq 1$,
      $\delta_{\efi} = \delta_{\efj} \defeq Z_e^{1/2}$. Let
      $e = (f_{i},f_{j}) \in \setE$ be an edge such that
      $\mu_{\efi}(\xe) = \mu_{\efj}(\xe) \in \sR$ for all $x_e \in \set{X}_e$. Then
      the matrices $\matr{M}_{\efi}$
      and $\matr{M}_{\efj}$ are equal
      and orthogonal.

    \end{enumerate}

  \end{enumerate}
\end{proposition}

