\begin{proposition}
  \label{prop:DENFG:LCT:1}



  Consider a DE-NFG $\graphN$. Let
  $\vmu $ be an SPA
  fixed-point message vector for $\graphN$ such that $ Z_e(\vmu) >0 $ for all $ e \in \setEfull $.
  (Recall that in Lemma~\ref{lem: nonnegative of ZBSPA for DE-NFG}, we prove that $Z_e(\vmu) \in \sRp$ for all $ e \in \setEfull $.) 
  Then the loop-calculus transformed NFG $\LCT{\graphN}$ is well defined, as specified in
  Definition~\ref{def:DENFG:LCT:1}.
  The main properties of $\LCT{\graphN}$ are listed as follows.
  \begin{enumerate}

  \item\label{prop:DENFG:LCT:1:item:1} Natural extension of Property~\ref{sec:LCT:prop:1:item:1} in Proposition~\ref{sec:LCT:prop:1}:
  $
      Z(\graphN)
        = Z\bigl( \LCT{\graphN} \bigr).
  $
  % (modulo the notational changes mentioned in Definition~\ref{def:DENFG:LCT:1})
  \item\label{prop:DENFG:LCT:1:item:4} Natural extension of Property~\ref{sec:LCT:prop:1:item:2} in Proposition~\ref{sec:LCT:prop:1}:
    $
         \ZBSPA(\graphN,\vmu)
        = \LCT{g}(\tv{0}),
    $
    where $ \tv{0} \defeq ( \tzero,\ldots,\tzero ) $.

  \item\label{sec:LCT:prop:1:item:8} Natural extension of Property~\ref{sec:LCT:prop:1:item:3} in Proposition~\ref{sec:LCT:prop:1}: for any $f \in \setF$ and any $\LCTv{x}_{\setpf} \in \LCTsetx_{\setpf}$ with exactly one non-zero component, 
  \ie, $ \wh( \LCTv{x}_{\setpf} ) = 1 $ with $ \wh( \LCTv{x}_{\setpf} ) \defeq 
  \sum_{ e \in \setpf } \bigl[ \LCTt{x}_{e} \!\neq\! \tzero \bigr] $,
    it holds that
    \begin{align*}
      \LCT{f}(\LCTtv{x}_{\setpf})
        &= 0.
