	\section{Properties of \texorpdfstring{$Z(\graphN)$}{} for DE-NFGs}
	\label{apx:property of ZN}

   We first consider the case where $\graphN$ is a strict-sense DE-NFG,
   afterwards the case where $\graphN$ is a weak-sense DE-NFG.

   %***************************************************************************
   Let $\graphN$ be a strict-sense DE-NFG. Fix some $f \in \setF$. Because
   $\matr{C}_f$ is a PSD matrix, the eigenvalue decomposition of $ \matr{C}_f  $ in~\eqref{sec:DENFG:eqn:9} implies that $ \lambda_{f}(\ell_f) \in \sR_{\geq 0} $ for all $\ell_f \in \set{L}_f$ and $ f \in \setF $.
   By the decomposition of $ f $ in~\eqref{sec:DENFG:eqn:5}, we get
   \begin{align*}
     Z(\graphN) 
       &= \sum_{\tvx} 
            \prod_{f \in \setF}
              f(\tvx_{f}) \\
       &= \sum_{\tvx}
            \prod_{f \in \setF}
              \left( 
               \sum_{\ell_f \in \set{L}_f} 
                 \lambda_{f}(\ell_f) \cdot
                u_{f}(\vx_{\setpf},\ell_f) 
                \cdot
                \overline{ u_{f}(\vx_{\setpf}',\ell_f) }
              \right) \\
       &=  \sum_{\ell_{f_1} \in \set{L}_{f_1}} 
           \cdots
           \sum_{\ell_{f_{|\setF|} \in \set{L}_{|\setF|}}}
           \Biggl( \prod_{f \in \setF} \lambda_{f}(\ell_f) \Biggr)
           \cdot 
           \Biggl( 
               \sum_{ \vx_{\setEfull} \in \setx_{\setEfull} }
               \prod_{f \in \setF} u_{f}(\vx_{\setpf},\ell_f) 
           \Biggr)
           \cdot 
           \Biggl( 
               \sum_{ \vx_{\setEfull}' \in \setx_{\setEfull} }
               \prod_{f \in \setF} 
               \overline{u_{f}(\vx_{\setpf}',\ell_f)}
           \Biggr)
           \\
       &=  \sum_{\ell_{f_1} \in \set{L}_{f_1}} 
           \cdots
           \sum_{\ell_{f_{|\setF|} \in \set{L}_{|\setF|}}}
           \Biggl( 
           \underbrace{
           \prod_{f \in \setF} 
               \lambda_{f}(\ell_f)
           }_{\geq 0} \Biggr)
           \cdot 
           \underbrace{
           \Biggl| 
               \sum_{ \vx_{\setEfull} \in \setx_{\setEfull} }
               \prod_{f \in \setF} u_{f}(\vx_{\setpf},\ell_f) 
           \Biggr|^{2}
           }_{\geq 0}
           \nonumber\\
           &\geq 0.
   \end{align*}
   % which shows that $Z(\graphN) \in \sRp$.

   Let $\graphN$ be a weak-sense DE-NFG. Fix some $f \in \setF$. Because
   $\matr{C}_f$ is a Hermitian matrix, the eigenvalue decomposition of $ \matr{C}_f  $ in~\eqref{sec:DENFG:eqn:9} implies that $ \lambda_{f}(\ell_f) \in \sR $ for all $ \ell_f \in \set{L}_f $ and $ f \in \set{F} $.
   Similar calculations as above lead to
   \begin{align*}
     Z(\graphN) 
       &= \sum_{\ell_{f_1} \in \set{L}_{f_1}} 
           \cdots
           \sum_{\ell_{f_{|\setF|} \in \set{L}_{|\setF|}}}
           \Biggl( 
           \underbrace{
           \prod_{f \in \setF} 
               \lambda_{f}(\ell_f)
           }_{\in \sR}
           \Biggr)
           \cdot 
           \underbrace{
           \Biggl| 
               \sum_{ \vx_{\setEfull} \in \setx_{\setEfull} }
               \prod_{f \in \setF} u_{f}(\vx_{\setpf},\ell_f) 
           \Biggr|^{2}
           }_{\geq 0}
           \in \sR.
   \end{align*}


