	\section{Proof of Proposition~\ref{prop: sufficient condition for pd messages}}
	\label{apx: sufficient condition for pd messages}
	The proof can be viewed as a generalization of the main idea in the proof~\cite[Proposition 4]{Yedidia2005}. In this appendix, we suppose that $ \vmu $ is an SPA fixed-point message vector.

   %----------------------------------------------------------------------------
   \begin{lemma}
     \label{lem: property of mu}
     The SPA fixed-point message vector $ \vmu $
     has the following properties.
     %----------------------------------------------------------------------------
     \begin{enumerate}
       \item For each $ e \in \setpf $ and $ f \in \setF $,
       it holds that $ \matr{C}_{\mu_{e,f}} \in \setPSD{\setxe} $.
       % In particular, the right-eigenvectors of $ \matr{C}_{\mu_{\etof}} $ satisfy
       % \begin{align*}
       %   \bigl( \matr{u}_{ \mu_{\etof} }( \ell_{e,f}' ) \bigr)^{\!\Herm}
       %   \cdot 
       %   \matr{u}_{ \mu_{\etof} }( \ell_{e,f} )
       %   = \bigl[ \ell_{e,f}' \! = \! \ell_{e,f} \bigr], \qquad 
       %   \ell_{e,f},\ell_{e,f}' \in \set{L}_{e,f}.
       % \end{align*}

       \item For each $ e \in \setpf $ and $ f \in \setF $, the matrix $\mathbf{C}_{\mu_{e,f}}$ has at least one positive eigenvalue.

       \item For each $ e = (f_{i}, f_{j}) \in \setEfull $, 
       the following normalization constants are positive valued:
       \begin{align*}
         \kappa_{e,f_{i}}
         &\defeq
         \sum_{\tvx_{\setpfj}}
         f_{j}\bigl( \tvx_{\setpfj} \bigr) 
         \cdot \prod_{e' \in \setpfj \setminus e}
         \mu_{\epfj}(\tx_{e'}), \nonumber\\
         \kappa_{e,f_{j}}
         &\defeq
         \sum_{\tvx_{\setpfi}}
         f_{i}\bigl( \tvx_{\setpfi} \bigr) 
         \cdot \prod_{e' \in \setpfi \setminus e}
         \mu_{\epfi}(\tx_{e'}).
       \end{align*}
       These definitions are obtained by replacing
         $ \vmu_{\etof}^{(t)} $ with $ \vmu_{\etof} $ for all
         $ e \in \setpf $ and $ f \in \setF $ in the definition of the normalization constants 
       $ \kappa_{e,f_{i}}^{(t)} $ and $ \kappa_{e,f_{j}}^{(t)} $
       in Definition~\ref{sec:DENFG:def:2}.
       % It holds that
       % \begin{align*}
       %   \mu_{e,f_{i}}(\tze)
       %   = \kappa_{e,f_{i}}^{-1} \cdot 
       %   \sum_{\tvx_{\setpfj}: \txe = \tze }
       %   f_{j}\bigl( \tvx_{\setpfj} \bigr) 
       %   \cdot \prod_{e' \in \setpfj \setminus e}
       %   \mu_{\epfj}(\tx_{e'}), \qquad \tze \in \tset{X}_{e}.
       % \end{align*}
       % where
       % \begin{align*}

       % \end{align*}
       % 
     \end{enumerate}
     %----------------------------------------------------------------------------
     % Similar properties also hold for $ \vmu_{e,f_{j}} $.
   \end{lemma}
   %----------------------------------------------------------------------------
   %----------------------------------------------------------------------------
   \begin{proof}
     The proofs of each property are listed as follows.
     %----------------------------------------------------------------------------
     \begin{enumerate}
       \item This follows straightforwardly from Lemma~\ref{sec:DENFG:lem:1}.

       \item By the SPA update rules in Definition~\ref{sec:DENFG:def:2},
       we know that 
       \begin{align*}
         1 = \sum_{ \txe } \mu_{\etof}(\txe) 
         = \bm{1}^{\tran} \cdot \matr{C}_{\mu_{e,f}} \cdot \bm{1},
         % \label{eqn: property of choi matrix wrt normalization}
       \end{align*}
       where $ \bm{1} $ is the all-one column vector of size $ |\setxe| $.
       Then we know that $ \matr{C}_{\mu_{\etof}} $ has at least one positive eigenvalue.

       \item Assumption~\ref{sec:DENFG:asum:2} implies $ \matr{C}_{f} \in \setPSD{\setxf} $.
       Then by Schur's product theorem, we know that 
       the normalization constants $ \kappa_{\efi},\kappa_{\efj} $ are non-negative.
       Based on the SPA update rules in Definition~\ref{sec:DENFG:def:2},
       we know that the constants $ \kappa_{e,f_{i}}^{(t)} $
       $ \kappa_{e,f_{j}}^{(t)} $ are non-zero-valued for each SPA iteration index $ t \in \sZpp $.
       Thus for the SPA fixed-point message vector $ \vmu $, the constants
       $ \kappa_{\efi},\kappa_{\efj} $ are also non-zero-valued, which implies that
       $ \kappa_{\efi},\kappa_{\efj} $ are positive valued.
     \end{enumerate}
     %----------------------------------------------------------------------------
   \end{proof}
   %----------------------------------------------------------------------------

   %----------------------------------------------------------------------------
   \begin{definition}
     \label{def: def of eig of mu ef}
       For each $ e \in \setpf $ and $ f \in \setF $, we make the following definitions based on the SPA fixed-point message vector $ \vmu_{\etof} $.
       %----------------------------------------------------------------------------
       \begin{enumerate}
         \item The mappings $\matr{u}_{ \mu_{\etof} }: \mathcal{L}_f \to \sC^{|\setxe|}$ 
         and $\lambda_f: \mathcal{L}_f \to \mathbb{R}_{\geq 0}$ are defined such that 
         \begin{align}
           \matr{C}_{\mu_{\etof}}
           = \sum_{ \ell_{e,f} \in \set{L}_{e,f} } 
           \matr{u}_{ \mu_{\etof} }( :, \ell_{e,f} ) 
           \cdot \lambda_{ \mu_{\etof} }(\ell_{e,f} )
           \cdot \bigl( \matr{u}_{ \mu_{\etof} }(:, \ell_{e,f} ) \bigr)^{\!\Herm},
           \label{eqn: decomposition of the Choi matrix for SPA message}
         \end{align}
         where $ \set{L}_{e,f} $ is a finite set with $ |\set{L}_{e,f}| = |\setxe| $,
         and where for each $ \ell_{e,f} \in \set{L}_{e,f} $, the column vector
         \begin{align*}
           \matr{u}_{ \mu_{\etof} }( :, \ell_{e,f} )
           \defeq \bigl( u_{ \mu_{\etof} }( \xe, \ell_{e,f} ) 
           \bigr)_{ \! \xe \in \setxe } \in \sC^{|\setxe|}
         \end{align*}
         is the right-eigenvector associated with the eigenvalue  
         $ \lambda_{ \mu_{\etof} }( \ell_{e,f} ) \in \sR_{\geq 0} $.

         \item The set $ \set{L}_{e,f,\mathrm{p}} $ is defined to be
         \begin{align}
           \set{L}_{e,f,\mathrm{p}}
           \defeq \bigl\{ \ell_{e,f} \ \bigl| \ 
           \ell_{e,f} \in \set{L}_{e,f},\,
           \lambda_{ \mu_{\etof} }( \ell_{e,f} )
           \in \sR_{>0} \bigr\}.  \label{eqn: property of ell e p}
         \end{align}
         A generic element of $ \set{L}_{e,f,\mathrm{p}} $ is denoted by $ \ell_{e,f,\mathrm{p}} $.
       \end{enumerate}
       %----------------------------------------------------------------------------
       \edefinition
   \end{definition}
   %----------------------------------------------------------------------------


   %----------------------------------------------------------------------------
   \begin{lemma}
     \label{lem: positive of message}
     If for all $ f \in \setF $, the Choi matrix 
     $ \matr{C}_{f} $ is a positive definite matrix,
     then for each $ e \in \setpf $ and $ f \in \setF $, the Choi-matrix representation 
     $\matr{C}_{\mu_{\etof}}$ is also a positive definite matrix.
   \end{lemma}
   %----------------------------------------------------------------------------
   %----------------------------------------------------------------------------
   \begin{proof}
     Without loss of generality, we consider the following setup for simplicity.
     %----------------------------------------------------------------------------
     \begin{itemize}
       \item The edge $ 1 \in \setEfull $ connects function nodes $ f_{1} $ and $ f_{2} $.

       \item The set $ \setpf_{1} $ is given by 
       $ \setpf_{1} = \{1,2,\ldots,|\setpf_{1}|\} $, which implies
       $ \vx_{\setpf_{1}} = ( x_{1}, x_{2},\ldots,x_{|\setpf_{1}|} ) $.

     \end{itemize}
     %----------------------------------------------------------------------------
     For simplicity, 
     we use 
     $ \sum_{ 
       \ell_{2},\ldots,\ell_{|\setpf_{1}|}
     } $,
     $ \prod_{e \setminus \{1\}} $, and $ \mathop{\bigotimes}_{e \setminus \{1\}}$ 
     instead of
     $ \sum_{ 
       \ell_{2} \in \set{L}_{2},
       \ldots,\ell_{|\setpf_{1}|} \in \set{L}_{f_{1}}
     } $,
     $ \prod_{e \in \{2,\ldots,|\setpf_{1}|\}} $,
     and
     $ \bigotimes_{ e \in \{2,\ldots,|\setpf_{1}|\} } $, respectively.
     In the following, we establish the positive definiteness of the matrix $ \matr{C}_{\mu_{\onetoftwo}} $ using a proof by contradiction.

     Suppose that for the matrix $ \matr{C}_{\mu_{\onetoftwo}} $, 
     there exists a variable $ \ell_{1,f_{1},0} \in \set{L}_{1} $
     such that $ \lambda_{ \mu_{\onetoftwo} }( \ell_{1,f_{1},0} ) = 0 $.
     Then we obtain a contradiction
     \begin{align}
       0
       &=
       \lambda_{ \mu_{\onetoftwo} }( \ell_{1,f_{1},0} )
       \nonumber\\
       &\overset{(a)}{=}
       \kappa_{\onetoftwo}
       \cdot
       \bigl( \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) \bigr)^{\!\Herm} 
       \cdot \matr{C}_{\mu_{\onetoftwo}}
       \cdot 
       \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} )
       \nonumber\\
       &=
       \sum_{\tx_{1}}
       \overline{u_{ \mu_{\onetoftwo} }( x_{1}, \ell_{1,f_{1},0} )}
       \cdot u_{ \mu_{\onetoftwo} }( x_{1}', \ell_{1,f_{1},0} )
       \cdot \bigl( \kappa_{1,f_{2}} \cdot \mu_{1,f_{2}}(\tx_{1}) \bigr)
       \nonumber\\
       % &=
       % \sum_{\tze}
       % \overline{u_{ \mu_{\onetoftwo} }( z_{1}, \ell_{1,f_{1},0} )}
       % \cdot u_{ \mu_{\onetoftwo} }( z_{1}, \ell_{1,f_{1},0} )
       % \cdot
       % \sum_{ \tvx_{\setpf_{1}} :\, \txe = \tze }
       % f_{1}\bigl( \tvx_{\setpf_{1}} \bigr)
       % \cdot \prod_{e \setminus \{1\}}
       % \mu_{e,f_{1}}(\tx_{e})
       % \nonumber\\
       &\overset{(b)}{=}
       \sum_{\tvx_{\setpf_{1}}}
       \overline{u_{ \mu_{\onetoftwo} }( x_{1}, \ell_{1,f_{1},0} )}
       \cdot
       u_{ \mu_{\onetoftwo} }( x_{1}', \ell_{1,f_{1},0} )
       \cdot 
       f_{1}\bigl( \tvx_{\setpf_{1}} \bigr)
       \cdot \prod_{e \setminus \{1\}}
       \mu_{e,f_{1}}(\tx_{e})
       \nonumber\\
       &\overset{(c)}{=}
       \sum_{ 
         \ell_{2},\ldots,\ell_{|\setpf_{1}|}
       }
       \Biggl( 
         \prod_{ e \setminus 1 }
         \underbrace{ \lambda_{\mu_{\etofone}}( \ell_{e,f} ) }_{\overset{(d)}{\geq 0} }
       \Biggr)
       % \nonumber\\
       % &\qquad 
       \cdot 
       \underbrace{
         \Bigr(
           \bigl( \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) \bigr)^{\!\Herm} 
           \mathop{\bigotimes}_{ e \setminus \{1\} }
           \bigl( \matr{u}_{\etofone}( :, \ell_{e,f} ) \bigr)^{\tran} 
         \Bigl)
         \cdot
         \matr{C}_{f_{1}}
         \cdot
         \Bigr(
           \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) 
           \mathop{\bigotimes}_{ e \setminus \{1\} }
           \overline{ \matr{u}_{\etofone}( :, \ell_{e,f} ) }
         \Bigl)
       }_{\overset{(e)}{>0}}
       \nonumber\\
       &\overset{(f)}{\geq}
       \prod_{ e \setminus 1 }
       \underbrace{ \lambda_{\mu_{\etofone}}( \ell_{e,f_{1},p} ) }_{\overset{(g)}{>0}}
       \cdot 
       \underbrace{
         \Bigr(
           \bigl( \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) \bigr)^{\!\Herm} 
           \mathop{\bigotimes}_{ e \setminus \{1\} }
           \bigl( \matr{u}_{\etofone}( :, \ell_{e,f_{1},p} ) \bigr)^{\tran} 
         \Bigl)
         \cdot
         \matr{C}_{f_{1}}
         \cdot
         \Bigr(
           \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) 
           \mathop{\bigotimes}_{ e \setminus \{1\} }
           \overline{ \matr{u}_{\etofone}( :, \ell_{e,f_{1},p} ) }
         \Bigl)
       }_{>0}
       \nonumber\\
       &>0, \label{eqn: positive of messages}
     \end{align}
     %----------------------------------------------------------------------------
     \begin{itemize}

       \item where step $(a)$ follows from the property that $ \kappa_{\onetoftwo} \in \sR_{>0} $, as proven in Lemma~\ref{lem: property of mu}, and the fact that $ \lambda_{ \mu_{\onetoftwo} }( \ell_{1,f_{1},0} ) = 0 $ is the eigenvalue of $ \matr{C}_{\mu_{\onetoftwo}} $ associated with right-eigenvector $ \matr{u}_{ \mu_{\onetoftwo} }( :, \ell_{1,f_{1},0} ) $, as defined in~\eqref{eqn: decomposition of the Choi matrix for SPA message},

       \item where step $(b)$ follows from the definition of SPA fixed-point messages in~\eqref{sec:DENFG:eqn:15},

       \item where step $(c)$ follows from 
       Choi matrix representation $ \matr{C}_{f_{1}} $ (equation~\eqref{sec:DENFG:eqn:9})
       and the decomposition for each SPA fixed-point message vector in the collection $ ( \vmu_{e,f_{1}} )_{e \in \setpf_{1} \setminus \{1\}} $ (equation~\eqref{eqn: decomposition of the Choi matrix for SPA message}),

       \item where step $(d)$ follows from the property $ \matr{C}_{\mu_{\etof}} \in \setPSD{\setxe} $, as proven in Lemma~\ref{lem: property of mu}, and the fact that 
       $ \lambda_{\mu_{\etofone}}( \ell_{e,f} ) $ is the eigenvalue of 
       the Choi matrix $ \matr{C}_{\mu_{\etof}} $, 
       as defined in~\eqref{eqn: decomposition of the Choi matrix for SPA message},

       \item where step $(e)$ follows from the condition that the Choi matrix 
       $ \matr{C}_{f} $ is a positive definite matrix, as stated in the lemma statement,

       \item where step $(f)$ follows from the fact that $ \ell_{e,f_{1}, \mathrm{p}} \in \set{L}_{e,f_{1}} $ for all $ e \in \setpf_{1} $, as defined in Definition~\ref{def: def of eig of mu ef}, and the property that $ \set{L}_{e,f_{1},\mathrm{p}} \neq \emptyset $ for all $ e \in \setpf_{1} $, as proven in Lemma~\ref{lem: property of mu},

       \item where step $(g)$ follows from the definition of 
       $ \ell_{e,f_{1}, \mathrm{p}} $ in~\eqref{eqn: property of ell e p}.
     \end{itemize}
     %----------------------------------------------------------------------------

     The proof for 
     other vectors in the collection 
     $ \vmu =  (\vmu_{e,f})_{e \in \setpf, f \in \setF} $ is similar and thus it is omitted here. 
   \end{proof}
   %----------------------------------------------------------------------------

   Now we are ready to prove the proposition statement. 
   %----------------------------------------------------------------------------
   \begin{enumerate}
     \item For each $ f \in \setF $, we have
     \begin{align*}
       Z_f(\vmu)
       &=
       \sum_{ 
         (\ell_{e,f})_{e \in \setpf} \in \prod_{e \in \setpf} \set{L}_{e,f}
       }
       \Biggl( 
         \prod_{ e \in \setpf }
         \lambda_{\mu_{\etof}}( \ell_{e,f} )
       \Biggr)
       % \nonumber\\
       % &\qquad 
       \cdot 
       \Biggr(
         \mathop{\bigotimes}_{ e \in \setpf }
         \bigl( \matr{u}_{\etof}(:, \ell_{e,f} ) \bigr)^{\tran} 
       \Biggl)
       \cdot
       \matr{C}_{f}
       \cdot
       \Biggr(
         \mathop{\bigotimes}_{ e \in \setpf }
         \overline{ \matr{u}_{\etof}(:, \ell_{e,f} ) }
       \Biggl) >0, 
     \end{align*}
     where the last inequality follows from similar ideas as in the proof of the strict inequality in~\eqref{eqn: positive of messages}.

     \item  For each $ e = (f_{i},f_{j}) \in \setEfull $, we have
     \begin{align*}
       Z_e(\vmu)
       = \Tr( \matr{C}_{\mu_{e,f_{i}}} \cdot \matr{C}_{\mu_{e,f_{j}}}^{\tran} )
       = \Tr( \sqrt{ \matr{C}_{\mu_{e,f_{j}}}^{\tran} } \cdot 
       \matr{C}_{\mu_{\etof}} \cdot \sqrt{ \matr{C}_{\mu_{e,f_{j}}}^{\tran} } )
       >0,
     \end{align*}
      where the last inequality follows from Lemma~\ref{lem: positive of message}.
   \end{enumerate}
   %----------------------------------------------------------------------------
   Therefore, by the definition of $ \ZBSPA $ in~\eqref{sec:DENFG:eqn:3}, we have
   \begin{align*}
     \ZBSPA(\graphN,\vmu)
     = \frac{\prod\limits_f Z_f(\vmu)}
           {\prod\limits_{e} Z_{e}(\vmu)}
     >0.
   \end{align*}
