	\section{Details of the LCT for S-NFG}
	\label{apx:LCT SNFGs} 
	Given $ |\set{X}_e| \in \sZpp $, without loss of generality, we suppose that
$\set{X}_e = \LCTset{X}_e = \{ 0, 1, \ldots, |\set{X}_e| \! - \! 1 \}$.  We have
to verify that the functions $M_{\efi}$ and $M_{\efj}$
satisfy~\eqref{sec:LCT:exp:1}, \textit{i.e.},
\begin{align*}
  \sum_{\LCT{x}_e}
    M_{\efi}(x_{\efi}, \LCT{x}_e)
    \cdot
    M_{\efj}(x_{\efj}, \LCT{x}_e) 
    &= [x_{\efi} \! = \!  x_{\efj}],
         \qquad x_{\efi}, x_{\efj} \in \set{X}_e.
\end{align*}
We consider the following four cases.
\begin{enumerate}

\item For $x_{\efi} = 0$, $x_{\efj} = 0$, we obtain the constraint
  \begin{align*}
    \zeta_{\efi} 
      \cdot
      \mu_{\efi}(0)
    \cdot
    \zeta_{\efj}
      \cdot
      \mu_{\efj}(0)
    +
    \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
      \zeta_{\efi}
        \cdot
        \chi_{\efi} 
        \cdot
        \bigl( - \mu_{\efj}(\LCT{x}_e) \bigr)
      \cdot
      \zeta_{\efj}
        \cdot
        \chi_{\efj}
        \cdot
        \bigl( - \mu_{\efi}(\LCT{x}_e) \bigr)
       &= 1.
  \end{align*}
  Using~\eqref{sec:LCT:exp:5}
  and~\eqref{sec:LCT:exp:6}, and multiplying both size by
  $Z_e$, we obtain the equivalent constraint
  \begin{align*}
    \mu_{\efi}(0)
    \cdot
    \mu_{\efj}(0)
    +
    \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
      \mu_{\efj}(\LCT{x}_e)
      \cdot
      \mu_{\efi}(\LCT{x}_e)
       &= Z_e.
  \end{align*}
  % \textit{i.e.},
  % \begin{align*}
  %   \sum_{\LCT{x}_e}
  %     \mu_{\efi}(\LCT{x}_e)
  %     \cdot
  %     \mu_{\efj}(\LCT{x}_e)
  %      &= Z_e.
  % \end{align*}
  Clearly, this constraint is satisfied since the left-hand side is just the
  definition of $Z_e$.

\item For $x_{\efi} = 0$, $x_{\efj} \in \set{X}_e \setminus \{ 0 \}$, we obtain
  the constraint
  \begin{align*}
    &
    \zeta_{\efi} 
      \cdot
      \mu_{\efi}(0)
    \cdot
    \zeta_{\efj}
      \cdot
      \mu_{\efj}(x_{\efj}) \\
    &
    \quad
    +
    \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
      \zeta_{\efi}
        \cdot
        \chi_{\efi} 
        \cdot
        \bigl( - \mu_{\efj}(\LCT{x}_e) \bigr)
      \cdot
      \Bigl(
        \zeta_{\efj}
          \cdot
          \chi_{\efj}
          \cdot
          \bigl(
            \delta_{\efj} 
                      \cdot
                      [x_{\efj} \!=\! \LCT{x}_e] 
                    +
                    \epsilon_{\efj}
                      \cdot
                      \mu_{\efj}(x_{\efj}) 
                      \cdot 
                      \mu_{\efi}(\LCT{x}_e)
          \bigr)     
      \Bigr)
        = 0.
  \end{align*}
  Using~\eqref{sec:LCT:exp:5}
  and~\eqref{sec:LCT:exp:6}, we obtain the equivalent
  constraint
  \begin{align*}
    \mu_{\efi}(0)
    \cdot
    \mu_{\efj}(x_{\efj})
    -
    \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
      \mu_{\efj}(\LCT{x}_e)
      \cdot
      \Bigl(
        \delta_{\efj} 
          \cdot
          [x_{\efj} \!=\! \LCT{x}_e] 
        +
        \epsilon_{\efj}
          \cdot
          \mu_{\efj}(x_{\efj}) 
          \cdot 
          \mu_{\efi}(\LCT{x}_e)
      \Bigr)
        &= 0.
  \end{align*}
  Simplifying the sum in the above expression, this constraint is equivalent
  to the constraint
  \begin{align*}
    \mu_{\efi}(0)
    \cdot
    \mu_{\efj}(x_{\efj})
    -
    \mu_{\efj}(x_{\efj})
      \cdot
      \delta_{\efj}
    -
    \epsilon_{\efj}
      \cdot
      \mu_{\efj}(x_{\efj}) 
      \cdot
      \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
        \mu_{\efj}(\LCT{x}_e)
          \cdot
          \mu_{\efi}(\LCT{x}_e)      
        &= 0.
  \end{align*}
  The sum appearing in the above expression equals
  $Z_e \cdot \bigl( 1 - \beli_e(0) \bigr)$. Therefore, this constraint can be
  rewritten as
  \begin{align*}
    \mu_{\efj}(x_{\efj})
      \cdot
      \Bigl(
        \mu_{\efi}(0)
        -
        \delta_{\efj}
        -
        \epsilon_{\efj}
          \cdot
          Z_e
          \cdot
          \bigl( 1 - \beli_e(0) \bigr)
      \Bigr)
      &= 0.
  \end{align*}
  The expression in the parentheses equals zero because
  of~\eqref{sec:LCT:exp:9}, and so this constraint is
  satisfied.

\item For $x_{\efi} \in \set{X}_e \setminus \{ 0 \}$, $x_{\efj} = 0$, we obtain
  similar expressions as for the second case, simply with the roles of $f_{i}$ and
  $f_{j}$ exchanged.

\item For $x_{\efi}, x_{\efj} \in \set{X}_e \setminus \{ 0 \}$, we obtain the
  constraint (we have already used~\eqref{sec:LCT:exp:5}
  and~\eqref{sec:LCT:exp:6} to simplify the expression)
  \begin{align*}
    \mu_{\efi}(x_{\efi})
      \cdot
      \mu_{\efj}(x_{\efj})
    +
    \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
      &
      \Bigl(
        \delta_{\efi} 
          \cdot
          [x_{\efi} \!=\! \LCT{x}_e] 
        +
        \epsilon_{\efi}
          \cdot
          \mu_{\efi}(x_{\efi}) 
          \cdot 
          \mu_{\efj}(\LCT{x}_e)
      \Bigr) \\
      &
      \cdot
      \Bigl(
        \delta_{\efj} 
          \cdot
          [x_{\efj} \!=\! \LCT{x}_e] 
        +
        \epsilon_{\efj}
          \cdot
          \mu_{\efj}(x_{\efj}) 
          \cdot 
          \mu_{\efi}(\LCT{x}_e)
      \Bigr)
        = Z_e 
            \cdot
            [x_{\efi} \!=\! x_{\efj}].
  \end{align*}
  This constraint is equivalent to the constraint
  \begin{align*}
    \hspace{0.25cm}&\hspace{-0.25cm}
    \mu_{\efi}(x_{\efi})
      \cdot
      \mu_{\efj}(x_{\efj})
    +
    \delta_{\efi}
      \cdot
      \delta_{\efj} 
      \cdot
      [x_{\efi} \!=\! x_{\efj}] \\
    &
    +
    \delta_{\efi} 
      \cdot
      \epsilon_{\efj}
      \cdot
      \mu_{\efj}(x_{\efj}) 
      \cdot
      \mu_{\efi}(x_{\efi})
    +
    \delta_{\efj} 
      \cdot
      \epsilon_{\efi}
      \cdot
      \mu_{\efi}(x_{\efi}) 
      \cdot 
      \mu_{\efj}(x_{\efj}) \\
    &
    +
    \epsilon_{\efi}
      \cdot
      \epsilon_{\efj}
      \cdot
      \mu_{\efi}(x_{\efi})
      \cdot
      \mu_{\efj}(x_{\efj})
      \cdot
      \sum_{\LCT{x}_e: \, \LCT{x}_e \neq 0}
        \mu_{\efj}(\LCT{x}_e)
        \cdot
        \mu_{\efi}(\LCT{x}_e)
      = Z_e
          \cdot
          [x_{\efi} \!=\! x_{\efj}].
  \end{align*}
  The sum appearing in the above expression equals
  $Z_e \cdot \bigl( 1 - \beli_e(0) \bigr)$. Therefore, after rewriting this
  constraint, we get the constraint
  \begin{align*}
    &
    [x_{\efi} \!=\! x_{\efj}]
      \cdot
      \bigl(
        \delta_{\efi}
          \cdot
          \delta_{\efj} 
        -
        Z_e
      \bigr) \\
    &
    \quad
    +
    \mu_{\efi}(x_{\efi})
      \cdot
      \mu_{\efj}(x_{\efj})
      \cdot
      \Bigl(
        1
        +
        \delta_{\efi} 
          \cdot
          \epsilon_{\efj}
        +
        \delta_{\efj} 
          \cdot
          \epsilon_{\efi}
        +
        \epsilon_{\efi}
          \cdot
          \epsilon_{\efj}
          \cdot
          Z_e
          \cdot 
          \bigl( 1 - \beli_e(0) \bigr)
      \Bigr)
      = 0.
  \end{align*}
  We claim that this constraint is satisfied. 
  This follows from the above two parenthetical
   expressions being equal to zero. For the first parenthetical
  expression, this observation follows
  from~\eqref{sec:LCT:exp:7}. For the second parenthetical
  expression, this observation follows from the following
  considerations. 
  If $ \beli_e(0) = 1$, the second parenthetical
  expression equals
  \begin{align*}
    1
    +
    \delta_{\efi} 
      \cdot
      \epsilon_{\efj}
    +
    \delta_{\efj} 
      \cdot
      \epsilon_{\efi}
    = 0,
  \end{align*}
  which follows from~\eqref{extra constraint on epsilon for beli = [x = 0]}.
  Now we consider $ \beli_e(0) \neq 1$.
  Because the product of the left-hand sides
  of~\eqref{sec:LCT:exp:8}
  and~\eqref{sec:LCT:exp:9} must equal the product of the
  right-hand sides of~\eqref{sec:LCT:exp:8}
  and~\eqref{sec:LCT:exp:9}, we get
  \begin{align*}
    \hspace{0.25cm}&\hspace{-0.25cm}
    \delta_{\efi}
      \cdot
      \delta_{\efj}
    +
    \delta_{\efi}
      \cdot
      Z_e
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)
      \cdot
      \epsilon_{\efj}
    +
    \delta_{\efj} 
      \cdot
      Z_e
        \cdot 
        \bigl( 1 - \beli_e(0) \bigr)
        \cdot
        \epsilon_{\efi}
    +
    (Z_e)^2
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)^2
      \cdot
      \epsilon_{\efi}
      \cdot
      \epsilon_{\efj} \\
        &
          = \mu_{\efi}(0)
             \cdot
             \mu_{\efj}(0).
  \end{align*}
  Using~\eqref{sec:LCT:exp:7} and
  $\mu_{\efi}(0) \cdot \mu_{\efj}(0) = Z_e \cdot \beli_e(0)$, we obtain
  \begin{align*}
    \hspace{0.25cm}&\hspace{-0.25cm}Z_e
    +
    \delta_{\efi}
      \cdot
      Z_e
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)
      \cdot
      \epsilon_{\efj}
    +
    \delta_{\efj} 
      \cdot
      Z_e
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)
      \cdot
      \epsilon_{\efi}
    +
    (Z_e)^2
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)^2
      \cdot
      \epsilon_{\efi}
      \cdot
      \epsilon_{\efj} \nonumber \\
      &= Z_e \cdot \beli_e(0).
  \end{align*}
  Subtracting $Z_e \cdot \beli_e(0)$ and then dividing $ Z_e \cdot \bigl( 1 - \beli_e(0) \bigr) $ from both sides, results in
  \begin{align*}
    1
    +
    \delta_{\efi}
      \cdot
      \epsilon_{\efj}
    +
    \delta_{\efj} 
      \cdot
      \epsilon_{\efi}
    +
      \epsilon_{\efi}
      \cdot
      \epsilon_{\efj}
      \cdot Z_e
      \cdot 
      \bigl( 1 - \beli_e(0) \bigr)
    &= 0.
  \end{align*}
  This is the promised result.

\end{enumerate}


