	where step $(a)$ follows from Lemma~\ref{sec:sst:lem:1}, where step $(b)$ follows from
	the definition of $ \hgraphPsig $ in Definition~\ref{sec:sst:def:1}, \ie, 
	the partition function of $ \hgraphPsig $ is given by
	%------------------------------------------------------------------------
	\begin{align*}
		Z(\hgraphPsig) =  \sum_{\vx_{[M]}}
		\Biggl( \prod_{m \in [M]} \prod_f f(\vx_{\setpff,m}) \Biggr)
		\cdot \prod_{e = (f_{i},f_{j}) \in \setEfull} P_{e,\sigma_e}(\vx_{\efi,[M]}, \vx_{\efj,[M]}),
	\end{align*}
	%------------------------------------------------------------------------
	where step $(c)$ follows from the decomposition of $ p_{\vSigma}(\vsigma) = \prod_{e}p_{\Sigmae}(\sigma_e) $ in~\eqref{sec:sst:eqn:31} and the expression $ \vsigma = (\sigma_e)_{e \in \setEfull} $, as shown in Definition~\ref{def:graph:cover:construction:1}, and where step $(d)$ follows from the definition of $ P_{e} $ in Definition~\ref{sec:sst:def:4}.

\section{Proof of Theorem~\ref{sec:CheckCon:thm:1}}
\label{apx:check_graph_thm}

  This appendix proves Theorem~\ref{sec:CheckCon:thm:1}. First, necessary definitions and remarks are introduced to lay the groundwork for the proof.

  \begin{definition}\label{sec:CheckCon:def:1}
 The following definitions pertain to the loop-calculus transformed NFG $ \LCT{\sfN} $.
 \begin{enumerate}

  \item The set of all possible configurations for the variables on the edges is $ \LCTtset{X} \defeq \prod_{e} \LCTtset{X}_e$.

  \item Two collections of variables, $ \LCTvxs $ and $ \LCTvxl $, are defined based on an ordering of the function nodes. Assuming $ \set{F} = \{ f_{1},\ldots,f_{|\set{F}|} \} $ (from Definition~\ref{sec:DENFG:def:4}), for each edge $e = (f_{i},f_{j}) \in \setEfull$ with $i<j$:
  %-----------------------------------------------------------------------
  \begin{align*}
   \LCTvxs &\text{ includes the variable } \LCTt{x}_{e,f_{i}} \text{ (associated with the variable of smaller index)}, \nonumber \\
   \LCTvxl &\text{ includes the variable } \LCTt{x}_{e,f_{j}} \text{ (associated with the variable of larger index)}.
  \end{align*}
  %-----------------------------------------------------------------------
    More formally,
  \begin{align*}
   \LCTvxs \defeq
   \bigl( \LCTt{x}_{e,f_{i}}
   \bigr)_{ e = (f_{i},f_{j}) \in \setEfull:\, i<j }
   \in \LCTtset{X}, \\
   \LCTvxl \defeq \bigl( \LCTt{x}_{e,f_{j}}
   \bigr)_{ e = (f_{i},f_{j}) \in \setEfull:\, i<j }
   \in \LCTtset{X}. 
   % \label{eqn: def of LCT vs and LCT vy_revised}
  \end{align*}
  The collections $ \LCTvxs $ and $\LCTvxl$ consist of distinct variables, \ie, $ \LCTt{x}_{e,f_{i}} \neq \LCTt{x}_{e,f_{j}} $ is possible for any $ e = (f_{i},f_{j}) \in \setEfull $.


  \item The functions $ \gzero $ and $ \gone $ partition the product of loop-calculus transformed local functions based on the Hamming weight of $ \LCTvxs $ and $ \LCTvxl $:
  %-----------------------------------------------------------------------
  \begin{alignat}{3}
   \gzero
   (\LCTvxs, \LCTvxl)
   &\defeq
    \Biggl( \prod_{f}\LCT{f}( \LCTtv{x}_{\setpf,f}) \Biggr)
   \cdot
   \bigl[ \wh(\LCTvxs) + \wh( \LCTvxl) \!=\! 0 \bigr]
   \nonumber
   \\&\overset{(a)}{=} \ZBSPA^{*}(\graphN)
   \cdot \bigl[ \LCTvxs\!=\!\LCTvxl \!=\! \tv{0} \bigr],
   \qquad
   &\LCTvxs, \LCTvxl &\in \LCTtset{X},
   \label{sec:CheckCon:eqn:60}\\
   \gone(\LCTvxs, \LCTvxl) &\defeq
   \Biggl( \prod_{f}\LCT{f}( \LCTtv{x}_{\setpf,f}) \Biggr) \cdot
   \bigl[ \wh(\LCTvxs) + \wh( \LCTvxl) \!\geq\! 1 \bigr], \qquad
   &\LCTvxs, \LCTvxl &\in \LCTtset{X},
   \nonumber
   % \label{sec:CheckCon:eqn:59}
  \end{alignat}
  %-----------------------------------------------------------------------
  where step $(a)$ follows from equation~\eqref{sec:CheckCon:eqn:31} (which states $ \prod_{f}\LCT{f}( \tv{0} ) = \ZBSPA^{*}(\graphN) $) and the condition $ \wh(\LCTvxs) + \wh( \LCTvxl) \!=\! 0 $ which implies $ \LCTvxs = \tv{0} $ and $ \LCTvxl = \tv{0} $.
  The Hamming weight $ \wh(\cdot) $ of a vector $ \LCTtv{x}_{\set{I}} $ is the number of its non-zero elements:
  \begin{align*}
   \wh( \LCTtv{x}_{\set{I}} )
   &=
   \sum_{ e \in \set{I} }
   \bigl[ \LCTt{x}_{e} \!\neq\! \tilde{0} \bigr],\qquad
   \set{I} \subseteq \setEfull,
  \end{align*}
    where
    \begin{align*}
   \LCTtv{x}_{\set{I}} \defeq \bigl( \LCTt{x}_{e} \bigr)_{ e \in \set{I} }
   \in \prod_{e \in \set{I}} \LCTtset{X}_{e}.
  \end{align*}
  It follows from their definitions that $ \gzero $ and $ \gone $ form a partition:
  %-----------------------------------------------------------------------
  \begin{align}
   \prod_{f}\LCT{f}( \LCTtv{x}_{\setpf,f})
   =
   \gzero
   (\LCTvxs, \LCTvxl)
   + \gone(\LCTvxs, \LCTvxl). \label{eqn: property of g0 g1}
  \end{align}
  %-----------------------------------------------------------------------
 \end{enumerate}
 %---------------------------------------------------------------------------
 For the proof concerning the average $M$-cover of $ \LCT{\sfN} $, the following variables, indexed by $m \in [M]$, are introduced to represent configurations across $M$ copies.
 %----------------------------------------------------------------------------
 \begin{enumerate}
   \setcounter{enumi}{3} % Reset counter for a new list, effectively item 1 and 2 for these variables
   \item For any $ e \in \setpf $ and $ f \in \setF $, the variable
   $ \LCTt{x}_{\ef,m} \in \LCTtset{X}_e$ is introduced for each $ m \in [M] $. Define the collection for edge $e$ across $M$ copies as
   $ \LCTtv{x}_{\ef,[M]} \defeq ( \LCTt{x}_{\ef,m} )_{m \in [M]} \in \LCTtset{X}_{e}^{M} $.

   \item Similarly, define collections of variables for the ``small'' indexed variables across $M$ copies:
      $ \LCTvxsm \defeq ( \LCTt{x}_{\efi,m} )_{ e = (f_{i},f_{j}) \in \setEfull:\, i <j } \in \LCTtset{X} $ for each $ m \in [M] $,
    and $ \LCTvxsM \defeq (\LCTvxsm)_{m \in [M]} \in \LCTtset{X}^{M} $.
    Define
    $ \LCTvxlm $ and $ \LCTvxlM $ analogously for the ``large'' indexed variables.
 \end{enumerate}
 %----------------------------------------------------------------------------

 For conciseness, if unambiguous, $ ( \cdot )_{m} $,
 $\prod_{\LCTt{x}_{e}}$,
 $ \sum_{ \LCTvxs, \LCTvxl } $,
 $ \sum_{\LCTvxsM} $,
 and $ \sum_{\LCTvxlM} $
 will denote $ (\cdot)_{m \in [M]} $,
 $\prod_{\LCTt{x}_{e} \in \LCTtset{X}_{e}}$,
 $ \sum_{ \LCTvxs, \LCTvxl \in \LCTtset{X} } $,
 $ \sum_{\LCTvxsM \in \LCTtset{X}^{M} } $, and $ \sum_{\LCTvxlM \in \LCTtset{X}^{M} } $, respectively.
 \edefinition
\end{definition}
%---------------------------------------------------------------------------

\begin{remark}
  \label{remark: expression of Pe}
  For the loop-calculus transformed NFG $ \LCT{\sfN} $, the analysis in Section~\ref{sec:sst:DENFG:1} remains valid after replacing $ \txe $ and $ \tset{X}_{e} $ with $ \LCTt{x}_{e} $ and $ \LCTtset{X}_{e} $, respectively.
 In particular, for each $ e = (f_{i},f_{j}) \in \setEfull $ in $ \LCT{\sfN} $, the function $ P_{e} $ (related to the average over permutations in the $M$-cover) is
 \begin{align*}
   P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)
  =\begin{cases}
   \binom{M}{ M \cdot \vt_{e} }^{\!\! -1}
   & \text{if } \vt_{e}
    =\vt_e(\LCTtv{x}_{\efi,[M]})
    = \vt_e(\LCTtv{x}_{\efj,[M]}) \\
   0& \text{otherwise}
  \end{cases},
 \end{align*}
 where
 %-----------------------------------------------------------------------
 \begin{align*}
  \binom{M}{ M \cdot \vt_{e} }
  \defeq \frac{M!}{ \prod\limits_{\LCTt{x}_{e} \in \LCTtset{X}_{e}}
  \bigl( ( M \cdot t_{e,\LCTt{x}_{e}} ) ! \bigr) }.
 \end{align*}
 %-----------------------------------------------------------------------
 Note that $ \vt_{e} $, $ \vt_{e}(\cdot) $, and $ t_{e,\LCTt{x}_{e}} $ relate to the method of types
 and are defined in Definition~\ref{sec:sst:def:6}.
 \eremark
\end{remark}

%----------------------------------------------------------------------------
\begin{lemma}
  \label{lem: expression of go and g1 and pe}
 The $M$-th power of the degree-$M$ Bethe partition function can be expressed as:
 \begin{align*}
  &\hspace{-0.2 cm} \bigl( \ZBM(\graphN) \bigr)^{\! M}
  \\&=
  \sum_{ k = 0 }^{M}
  \binom{M}{k}
  \cdot
  \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k}
  \cdot \sum_{ \LCTvxsM, \LCTvxlM }
  \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
   \cdot
   \left(
    \prod_{ m \in [M] \setminus [k] }
    \gone( \LCTvxsm, \LCTvxlm )
   \right)
  \cdot \prod_{e}
  P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr).
 \end{align*}
\end{lemma}
%----------------------------------------------------------------------------
%----------------------------------------------------------------------------
\begin{proof}
  The derivation begins with the expression for $ \bigl( \ZBM(\graphN) \bigr)^{\! M} $ from equation~\eqref{eqn: Z for degree M average cover of DENFG} and applies a series of algebraic manipulations:
 \begin{align}
   &\hspace{-0.3 cm}
  \bigl( \ZBM(\graphN) \bigr)^{\! M}
  \nonumber\\
  &\overset{(a)}{=}
  \sum_{ \LCTvxsM, \LCTvxlM }
  \Biggl(
   \prod_{m \in [M]} \prod_{f}
   \LCT{f}( \LCTtv{x}_{\setpf,f,m})
  \Biggr)
  \cdot \prod_{e = (f_{i},f_{j}) \in \setEfull}
  P_{e}(\LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]})
  \nonumber\\
  &\overset{(b)}{=}
  \sum_{ \LCTvxsM, \LCTvxlM }
  \Biggl(
   \prod_{m \in [M]}
   \Bigl( \gzero( \LCTvxsm, \LCTvxlm )
   + \gone( \LCTvxsm, \LCTvxlm )
   \Bigr)
  \Biggr)
  \cdot \prod_{e = (f_{i},f_{j}) \in \setEfull}
  P_{e}(\LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]})
  \nonumber\\
    %%% The product over m terms, (g0 + g1), is expanded. This results in 2^M terms for each configuration (LCTvxsM, LCTvxlM).
    %%% These terms are grouped by k, the number of times g0 is chosen from the (g0 + g1) factors.
  &=
  \sum_{ k = 0 }^{M} % Sum over the number of g0 terms chosen
  \sum_{ \set{M} \subseteq [M]: |\set{M}| = k}\, % Sum over all subsets M of indices of size k where g0 is chosen
  \sum_{ \LCTvxsM, \LCTvxlM }
  \Biggl( \prod_{ m \in \set{M} } \gzero( \LCTvxsm, \LCTvxlm ) \Biggr)
  \cdot \Biggl( \prod_{ m \in [M] \setminus \set{M} } \gone( \LCTvxsm, \LCTvxlm ) \Biggr)
  \cdot \prod_{e = (f_{i},f_{j}) \in \setEfull}
  P_{e}(\LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]})
  \nonumber\\
    %%% A permutation sigma_M is introduced. This step re-indexes the summation variables 
    %%% (LCTvxsm, LCTvxlm) without changing the sum over all configurations.
    %%% This is valid because P_e is invariant under such permutations if the types match (step (d)).
  &\overset{(c)}{=}
  \sum_{ k = 0 }^{M}
  \sum_{ \set{M} \subseteq [M]: |\set{M}| = k}\,
  \sum_{ \LCTvxsM, \LCTvxlM }
  \Biggl( \prod_{ m \in [k] } \gzero( \tilde{\LCTv{x}}_{\mathrm{s}, \sigma_{\set{M}}(m)},
  \tilde{\LCTv{x}}_{\mathrm{l}, \sigma_{\set{M}}(m)} ) \Biggr)
  \cdot \Biggl( \prod_{ m \in [M] \setminus [k] } \gone( \tilde{\LCTv{x}}_{\mathrm{s}, \sigma_{\set{M}}(m)},
  \tilde{\LCTv{x}}_{\mathrm{l}, \sigma_{\set{M}}(m)} ) \Biggr)
  \nonumber\\
  &\hspace{4.7 cm} \cdot
  \prod_{e = (f_{i},f_{j}) \in \setEfull}
  \underbrace{
   P_{e}(\LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]})
  }_{ \overset{(d)}{=} P_{e}(\LCTtv{x}_{\efi,\sigma_{\set{M}}([M])}, \LCTtv{x}_{\efj,\sigma_{\set{M}}([M])}) }
  \nonumber\\
    %%% Due to the symmetry of the summand with respect to the choice of the k indices for g0 terms, 
    %%% the sum over all subsets M of size k simplifies. There are (M choose k) such subsets, 
    %%% and each contributes equally to the sum over configurations.
  &\overset{(e)}{=}
  \sum_{ k = 0 }^{M}
  \binom{M}{k}
  \sum_{ \LCTvxsM, \LCTvxlM }
  \Biggl( \prod_{ m \in [k] } \gzero( \LCTvxsm, \LCTvxlm ) \Biggr)
  \cdot \Biggl( \prod_{ m \in [M] \setminus [k] } \gone( \LCTvxsm, \LCTvxlm ) \Biggr)
  \cdot \prod_{e = (f_{i},f_{j}) \in \setEfull}
  P_{e}(\LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]})\nonumber\\
    %%% The definition of g0 from equation (sec:CheckCon:eqn:60) is substituted.
  &\overset{(f)}{=}
  \sum_{ k = 0 }^{M}
  \binom{M}{k}
  \cdot
  \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k}
  \cdot \sum_{ \LCTvxsM, \LCTvxlM }
  \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
   \cdot
   \left(
    \prod_{ m \in [M] \setminus [k] }
    \gone( \LCTvxsm, \LCTvxlm )
   \right)
  \cdot \prod_{e}
  P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr),\nonumber
 \end{align}
 where step $(a)$ follows from
 replacing $ \tx_{e} $, $ \tset{X}_e $, and
 $ f $ with $ \LCTt{x}_{e} $, $ \LCTtset{X}_{e} $, and $ \LCT{f} $, respectively, in equation~\eqref{eqn: Z for degree M average cover of DENFG}
 (equation~\eqref{eqn: Z for degree M average cover of DENFG} remains valid after these substitutions),
 where step $(b)$ follows from the property of $\gzero$ and $\gone$ in equation~\eqref{eqn: property of g0 g1},
 where at step $(c)$, a permutation $ \sigma_{\set{M}} \in \set{S}_{M} $ is introduced, satisfying
 $ \sigma_{\set{M}}( [k] ) = \set{M} $
 and
 $ \sigma_{\set{M}}( [M] \setminus [k] ) = [M] \setminus \set{M} $,
 where step $(d)$ follows because, first, it holds that
  %-----------------------------------------------------------------------
  \begin{align}
   \bm{t}_{e}(\LCTtv{x}_{\efi,[M]}) = \bm{t}_{e}(\LCTtv{x}_{\efi,\sigma_{\set{M}}([M])}), \qquad
   \bm{t}_{e}(\LCTtv{x}_{\efj,[M]}) = \bm{t}_{e}(\LCTtv{x}_{\efj,\sigma_{\set{M}}([M])}),
   \label{eqn: the type of lct vx}
  \end{align}
  %-----------------------------------------------------------------------
  and second, the expression of $ P_{e} $ in Remark~\ref{remark: expression of Pe} implies that
  if equation~\eqref{eqn: the type of lct vx} holds,
  then
  %-----------------------------------------------------------------------
  \begin{align*}
   P_{e}( \LCTtv{x}_{\efi,[M]},\LCTtv{x}_{\efj,[M]} ) 
   = P_{e}( \LCTtv{x}_{\efi,\sigma_{\set{M}}([M])}, \LCTtv{x}_{\efj,\sigma_{\set{M}}([M])} ),
  \end{align*}
  %-----------------------------------------------------------------------
 where step $(e)$ follows because the value of the sum $\sum_{ \LCTvxsM, \LCTvxlM } (\dots)$ is the same for any choice of the set $\set{M}$ of $k$ indices (due to the relabeling property of summation over all configurations and the invariance of $P_e$ shown in step $(d)$), and since there are $\binom{M}{k}$ ways to choose the set $\set{M}$ of $k$ indices for the $\gzero$ terms, the sum over $\set{M}$ simplifies to this combinatorial factor,
 and where step $(f)$ follows from the expression of $ \gzero $ in equation~\eqref{sec:CheckCon:eqn:60}.
\end{proof}
%----------------------------------------------------------------------------

In order to prove Theorem~\ref{sec:CheckCon:thm:1}, we study each term in the expression for the $M$-th power of the degree-$M$ Bethe partition function from Lemma~\ref{lem: expression of go and g1 and pe}. Specifically, we present properties of binomial coefficients and the functions $ \gone $ and $ P_{e} $.

%----------------------------------------------------------------------------
\begin{lemma}\label{sec:CheckCon:lem:2}
    \noindent
   %----------------------------------------------------------------------------
   \begin{enumerate}
     \item The binomial coefficient $ \binom{M}{k} $ increases with respect to $ k \in \sZ $ for $ 0 \leq k \leq M/2 $ and decreases with respect to $ k \in \sZ $ for $M/2 \leq k \leq M $.

     \item Consider an arbitrary integer $ M' \in \sZpp $ and a sequence of $M'$ integers $ k_{1},\ldots,k_{M'} \in \sZp $ such that $ \sum_{m' \in [M']} k_{m'} \leq M $.
      It holds that
    \begin{align}
     \prod\limits_{m' \in [M']}\binom{M}{ k_{m'} }
     \geq
     \begin{pmatrix}
       M \\ \sum\limits_{m' \in [M']} k_{m'}
     \end{pmatrix}. \label{sec:CheckCon:eqn:82}
    \end{align}
    %------------------------------------------------------------------------
   \end{enumerate}
   %----------------------------------------------------------------------------

\end{lemma}
%----------------------------------------------------------------------------
%----------------------------------------------------------------------------
\begin{proof}
  \noindent
  %----------------------------------------------------------------------------
  \begin{enumerate}
    \item The proof follows directly from the definition of the binomial coefficient
  and is omitted.

    \item It holds that
    \begin{align}
      \Biggl( \prod\limits_{m' \in [M']}\binom{M}{ k_{m'} } \Biggr)
      \cdot
      \frac{
        \biggl( M-\sum\limits_{m' \in [M']} k_{m'} \biggr)!
        \cdot \prod\limits_{m' \in [M']}(k_{m'}!)
      }{
      M!
      }
      = \frac{
        \prod\limits_{m' \in [M']}
           \bigl( M \cdot ( M - 1 ) \cdots
          (M +1 -k_{m'}) \bigr)
      }{
        M \cdot ( M - 1 ) \cdots
        \left( M +1 - \sum\limits_{m' \in [M']} k_{m'} \right)
      } \geq 1. \label{eqn: bound on binon coeff: 1}
    \end{align}
  Then by definition of binomial coefficients,
  %-----------------------------------------------------------------------
  \begin{align}
   \frac{
     M!
   }{
    \biggl( M-\sum\limits_{m' \in [M']} k_{m'} \biggr)!
    \cdot \prod\limits_{m' \in [M']}(k_{m'}!)
   }\geq \begin{pmatrix}
     M \\ \sum\limits_{m' \in [M']} k_{m'}
   \end{pmatrix}. \label{eqn: bound on binon coeff: 2}
  \end{align}
  %-----------------------------------------------------------------------
  Combining the inequalities in~\eqref{eqn: bound on binon coeff: 1}
  and~\eqref{eqn: bound on binon coeff: 2} yields the inequality in equation~\eqref{sec:CheckCon:eqn:82}.
  \end{enumerate}
  %----------------------------------------------------------------------------

\end{proof}
%----------------------------------------------------------------------------


%---------------------------------------------------------------------------
\begin{lemma}\label{sec:CheckCon:prop:properties of N(0)}
 \noindent
 \begin{enumerate}

  \item It holds that
    \begin{align*}
        \sum_{ \LCTvxs, \LCTvxl }
    \gone( \LCTvxs, \LCTvxl )
    = \prod_{f}
    \left(
      \sum_{\LCTtv{x}_{\setpf}}
      \LCT{f}( \LCTtv{x}_{\setpf} )
    \right)
    -
    \ZBSPA^{*}(\graphN).
    \end{align*}

  \item It holds that
    $
        \gone( \LCTvxs, \LCTvxl ) = \gone( \LCTvxs, \LCTvxl) \cdot
      \bigl[ \wh(\LCTvxs) + \wh( \LCTvxl) \!\geq\! 2 \bigr].
    $

 \end{enumerate}

\end{lemma}
\begin{proof}
  These properties follow directly from equation~\eqref{eqn: property of g0 g1} and the properties of the LCT proven in Proposition~\ref{prop:DENFG:LCT:1}.
\end{proof}



%----------------------------------------------------------------------------
\begin{lemma} \label{sec:CheckCon:lem: lower bound of Pe}
  Consider an integer $ M \in \sZpp $ and an integer $ k $ satisfying $ 0 \leq k \leq M-1 $.
  For any $ \LCTvxsM,\LCTvxlM \in \LCTtset{X}^{M} $, if
  \begin{alignat}{4}
    \LCTvxsm &= \LCTvxlm = \tv{0},\qquad &\forall& m \in [k], \label{eqn: assum on k}\\
    \wh(\LCTvxsm) &+ \wh( \LCTvxlm) \geq 2,\qquad &\forall& m \in [M] \setminus [k],
    \label{eqn: assum on M - k}
  \end{alignat}
  then
  %------------------------------------------------------------------------
  \begin{align*}
    \prod_{e}
    P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)
    \leq \binom{M}{k}^{\!\! -1}.
    % \label{sec:CheckCon:eqn:67}
  \end{align*}
  %------------------------------------------------------------------------
\end{lemma}
%----------------------------------------------------------------------------
%----------------------------------------------------------------------------
\begin{proof}
    In this proof, the collections of variables $ \LCTvxsM,\LCTvxlM \in \LCTtset{X}^{M} $ are fixed.
    For simplicity, we will use $ P_{e} $ for denoting
    $ P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)$.

    First, consider the case where an edge
  $ e_{1} \in \setEfull $ exists such that
  $ P_{e_{1}} \leq \binom{ M }{ k }^{\!\! -1} $.
  Then,
  \begin{align*}
    \prod_{e}
    P_{e}
   =
   P_{e_{1}}
   \cdot
   \prod_{e \in \setEfull \setminus \{e_{1}\}}
   P_{e}
   \overset{(a)}{\leq}\binom{M}{k}^{-1},
   % \label{eqn: upper bound of product of Pe: case 1}
  \end{align*}
  where step $(a)$ follows from $ P_{e} \leq 1 $ for all $ e \in \setEfull $, a property verifiable from the expression of $ P_{e} $ in Remark~\ref{remark: expression of Pe}.

  Next, consider the case where
  \begin{align*}
     P_{e}
    > \binom{ M }{ k }^{\!\! -1}, \qquad \forall e \in \setEfull.
  \end{align*}
  %-----------------------------------------------------------------------

  Fix an arbitrary edge $ e = (f_{i},f_{j}) \in \setEfull $.
  From the expression of $P_{e}$ in Remark~\ref{remark: expression of Pe},
  the following expressions hold:
  %-----------------------------------------------------------------------
  \begin{alignat}{3}
   \binom{M}{ M \cdot \vt_{e} }^{\!\!-1}
   &> \binom{ M }{ k }^{\!\! -1},
   \label{eqn: ineq of types te}\\
   \vt_{e}
   = \vt_e(\LCTtv{x}_{\efi,[M]})
   &= \vt_e(\LCTtv{x}_{\efj,[M]}).
   \label{eqn: positive of pe}
  \end{alignat}
  %-----------------------------------------------------------------------
    Then,
    \begin{alignat}{3}
      M \cdot t_{e,\tzero} &\overset{(a)}{\geq} \max\{ k, M-k \} + 1 \geq M/2,
   \label{eqn: lower bound of tzero}
  \end{alignat}
  %--------------------------------------------------------------------
  where step $(a)$ follows from a sequence of deductions. First, equation~\eqref{eqn: assum on k} implies the inequality
  \begin{align}
    M \cdot t_{e,\tzero} \geq k. \label{eqn: ineq of M tero: 1}
  \end{align}
  Second, it holds that
  \begin{align}
   \binom{M}{M \cdot t_{e,\tzero}}^{\!\! -1}
   =
   \frac{
    \bigl( (M \cdot t_{ e, \tzero })! \bigr)
    \cdot
    \bigl( ( M - M \cdot t_{ e, \tzero } )! \bigr)
    }{M!}
   \overset{(b)}{\geq}
   \binom{M}{ M \cdot \vt_{e} }^{\!\!-1}
   \overset{(c)}{>}\binom{ M }{ k }^{\!\! -1}
   = \binom{ M }{ M-k }^{\!\! -1}, \label{eqn: ineq of M tero: 2}
  \end{align}
  where step $(b)$ follows from the definition of the type
  $ t_{e,\LCTt{x}_{e}} $ in Definition~\ref{sec:sst:def:6} (\ie,
  $ M \cdot t_{e,\LCTt{z}_{e}} \in \sZp $ for all $ \LCTt{z}_{e} \in \LCTtset{X}_{e} $
  and \\ $ \sum_{\LCTt{z}_{e} \in \LCTtset{X}_{e} } M \cdot t_{e,\LCTt{z}_{e}} = M $),
  and where step $(c)$ follows from inequality~\eqref{eqn: ineq of types te}. 
    Third, the first statement in Lemma~\ref{sec:CheckCon:lem:2}, combined with inequality~\eqref{eqn: ineq of M tero: 1} and the result from inequality~\eqref{eqn: ineq of M tero: 2} (specifically, $\binom{M}{M \cdot t_{e,\tzero}} < \binom{M}{k}$), implies that $M \cdot t_{e,\tzero}$ must be further from $M/2$ than $k$ is, leading to the condition $M \cdot t_{e,\tzero} \geq \max\{k, M-k\} + 1 $.
  %-----------------------------------------------------------------------

  For the remainder of the proof, the edge $ e = (f_{i},f_{j}) \in \setEfull $ is not fixed.
  It holds that
  \begin{align}
    2(M-k)
    &\overset{(a)}{\leq}
    \sum_{m \in [M]} \bigl( \wh(\LCTvxsm) + \wh( \LCTvxlm) \bigr)
    \nonumber\\
    &= \wh(\LCTvxsM) + \wh(\LCTvxlM)
    \nonumber\\
    &\overset{(b)}{=}
    2 \wh(\LCTvxsM)
    \nonumber\\
    &=
    2 \sum_{e}
    \sum_{ \LCTt{z}_{e} \in \LCTtset{X}_{e} \setminus \{\tzero\} }
    M \cdot t_{ e, \LCTt{z}_{e} }
    \nonumber\\
    &\overset{(c)}{=} 2 \sum_{e}
   ( M - M \cdot t_{ e, \tzero } ),
   \label{existence of ke}
  \end{align}
  where step $(a)$ follows from inequality~\eqref{eqn: assum on M - k},
  where step $(b)$ follows from the equalities in equation~\eqref{eqn: positive of pe}
  holding for all $ e \in \setEfull $
  and from the property that
  if $ \vt_e(\LCTtv{x}_{\efi,[M]}) = \vt_e(\LCTtv{x}_{\efj,[M]}) $,
  then $ \wh(\LCTtv{x}_{\efi,[M]}) = \wh(\LCTtv{x}_{\efj,[M]}) $,
  and where step $(c)$ follows from $ \sum_{ \LCTt{z}_{e} \in \LCTtset{X}_{e} } t_{ e, \LCTt{z}_{e} } = 1 $.
  The inequality in equation~\eqref{existence of ke} implies the existence of a collection of integers
  $ (k_{e})_{e \in \setEfull} \in \sZp^{|\setEfull|} $ such that
  \begin{align}
   M - M \cdot t_{e,\tzero} - k_{e} &\geq 0, \qquad e \in \setEfull,
   \nonumber \\
   \sum_{e}
   ( M - M \cdot t_{e,\tzero} - k_{e} ) &= M-k.
   \label{sec:CheckCon:eqn:91}
  \end{align}
  Therefore, it holds that
  %------------------------------------------------------------------------
  \begin{align*}
    \prod_{e}
    P_{e}^{-1}
    &=
   \prod_{ e }
   \binom{M}{ M \cdot \vt_{e} }
   \nonumber\\
   &
   \overset{(a)}{\geq}
   \prod_{ e } \binom{ M }{
     M \cdot t_{ e, \tzero }
    }
   \nonumber\\
   &\overset{(b)}{\geq}
   \prod_{ e }
   \binom{ M }{
     M \cdot t_{e,\tzero} + k_{e}
   } \nonumber\\
   &\overset{(c)}{\geq}
   \begin{pmatrix}
     M \\ \sum\limits_{e}
       ( M - M \cdot t_{e,\tzero} - k_{e} )
   \end{pmatrix}
   \nonumber\\
   &\overset{(d)}{=} \binom{ M }{ k }, 
   % \label{sec:CheckCon:eqn:90}
  \end{align*}
  %------------------------------------------------------------------------
  where step $(a)$ follows from
  %-----------------------------------------------------------------------
  \begin{align*}
   \binom{M}{ M \cdot \vt_{e} }
   = \frac{ M! }{
    \bigl( M \cdot t_{ e, \tzero } \bigr)!
    \cdot
    \prod\limits_{ \LCTt{x}_{e} \in \LCTtset{X}_{e} \setminus \{\tzero\} }
    \Bigl(
     \bigl( M \cdot t_{ e, \LCTt{x}_{e} } \bigr)!
    \Bigr)
   }
   \geq
   \frac{ M! }{
    \bigl( M \cdot t_{ e, \tzero } \bigr)!
    \cdot
    \Bigl(
     \bigl( M - M \cdot t_{ e, \tzero } \bigr)!
    \Bigr)
   } =
   \binom{ M }{
    M \cdot t_{ e, \tzero }
   } ,
  \end{align*}
  %-----------------------------------------------------------------------
  where step $(b)$ follows from the first statement in Lemma~\ref{sec:CheckCon:lem:2} and 
   $ k_{e} \in \sZp $ and
   $ M \cdot t_{ e, \tzero } \geq M/2 $, as proven in inequality~\eqref{eqn: lower bound of tzero},
   where step $(c)$ follows from the inequality~\eqref{sec:CheckCon:eqn:82} in Lemma~\ref{sec:CheckCon:lem:2},
  and where step $(d)$ follows from equation~\eqref{sec:CheckCon:eqn:91}.
 \end{proof}

Now we are ready to prove Theorem~\ref{sec:CheckCon:thm:1}.


%----------------------------------------------------------------------------
\begin{lemma}\label{sec:CheckCon:lem:liminf Z N0 greater than ZSPA}
  If the strict inequality in~\eqref{sec:CheckCon:eqn:70} holds, then
  %------------------------------------------------------------------------
  \begin{align*}
    \liminf_{M \to \infty}
    \ZBM(\graphN)
    \geq \ZBSPA^{*}(\graphN).
  \end{align*}
  %------------------------------------------------------------------------
\end{lemma}
%----------------------------------------------------------------------------
%----------------------------------------------------------------------------
\begin{proof}
 Recall from Assumption~\ref{sec:DENFG:remk:1} that $ \ZBSPA^{*}(\graphN) \in \sRpp $.
  Define $ \alpha_{\graphN} $ to be
  %------------------------------------------------------------------------
  \begin{align}
    \alpha_{\graphN}
    &\defeq
    \frac{
     \sum\limits_{ \LCTvxs, \LCTvxl }
     \bigl|\gone( \LCTvxs, \LCTvxl )\bigr|
    }{
     \ZBSPA^{*}(\graphN) } \geq 0.
    \label{sec:CheckCon:eqn:71}
  \end{align}
  %------------------------------------------------------------------------
 Then,
  %------------------------------------------------------------------------
  \begin{align}
    &\hspace{-0.2 cm}\Biggl( \frac{ \ZBM(\graphN) }{ \ZBSPA^{*}(\graphN) } \Biggr)^{\!\! M}
    \nonumber
    \\
    &\overset{(a)}{=}
    1 + \sum_{k=0}^{M-1}
      \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M}
      \! \cdot \! \binom{M}{k}
      \cdot \!\! \!\! \!\!
      \sum_{ \LCTvxsM, \LCTvxlM }
       \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
       \! \cdot \!
       \Biggl(
        \prod_{ m \in [M] \setminus [k] }
        \gone( \LCTvxsm, \LCTvxlm )
       \Biggr)
     \!\!
      \cdot \prod_{e}
      P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)
    \nonumber\\
    %--------------------------------------------------------------------
    &\overset{(b)}{\geq}
    1 - \sum_{k =0}^{M-1} \alpha_{\graphN}^{M-k}
    \nonumber\\
    &=
    1 -
    \alpha_{\graphN}
    \cdot
    \frac{ 1 - \alpha_{\graphN}^{M}
    }{ 1-\alpha_{\graphN} }
    \nonumber\\
    &\overset{(c)}{\geq}
    1 -
     \frac{ \alpha_{\graphN}
     }{ 1-\alpha_{\graphN} }
    \nonumber\\
    &\overset{(d)}{>} 0,
    \label{sec:CheckCon:eqn:75}
  \end{align}
  %------------------------------------------------------------------------
  %----------------------------------------------------------------------------
  where step $(a)$ follows from Lemma~\ref{lem: expression of go and g1 and pe}.
      The derivation for step $(b)$ is as follows. For each term in the sum over $k$ (where $0 \leq k \leq M-1$), let
      \begin{align*}
        T_k \defeq \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M} \! \cdot \! \binom{M}{k} \cdot \sum_{ \LCTvxsM, \LCTvxlM } \bigl[ \LCTvxsm \! = \! \LCTvxlm  \! = \! \tv{0},\, \forall m \in [k] \bigr] \! \cdot \! \Biggl( \prod_{ m \in [M] \setminus [k] } \gone( \LCTvxsm, \LCTvxlm ) \Biggr) \!\! \cdot \prod_{e} P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr).
      \end{align*}
      By the triangle inequality, $ \prod_{ m \in [M] \setminus [k] } \gone( \LCTvxsm, \LCTvxlm ) \geq - \prod_{ m \in [M] \setminus [k] } |\gone( \LCTvxsm, \LCTvxlm )| $.
      Thus,
      \begin{align*}
        T_k &\geq - \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M} \cdot \binom{M}{k} \cdot \sum_{ \LCTvxsM, \LCTvxlM } \bigl[ \LCTvxsm \! = \! \LCTvxlm  \! = \! \tv{0},\, \forall m \in [k] \bigr] \cdot \Biggl( \prod_{ m \in [M] \setminus [k] } |\gone( \LCTvxsm, \LCTvxlm )| \Biggr) \cdot \prod_{e} P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr).
      \end{align*}
      Using the properties that $ \binom{M}{k} \cdot \prod_{e} P_{e} \leq 1 $ (from Lemma~\ref{sec:CheckCon:lem: lower bound of Pe} and the conditions on $k$ and the Hamming weights in inequality~\eqref{eqn: assum on M - k}, which are satisfied by terms where $\gone \neq 0$ due to Lemma~\ref{sec:CheckCon:prop:properties of N(0)}), $T_k$ is further lower bounded by
      \begin{align*}
         - \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M} \cdot \sum_{ \LCTvxsM, \LCTvxlM } \bigl[ \LCTvxsm \! = \! \LCTvxlm  \! = \! \tv{0},\, \forall m \in [k] \bigr] \cdot \prod_{ m \in [M] \setminus [k] } |\gone( \LCTvxsm, \LCTvxlm ) |.
      \end{align*}
      The distributive law applies because the indicator function depends only on variables for $m \in [k]$, and the product of $ |\gone(\cdot)| $ terms depends only on variables for $m \in [M] \setminus [k]$. Separating the summation gives
      \begin{align*}
        \Biggl( \prod_{m \in [k]} \sum_{ \LCTvxsm,\LCTvxlm } \bigl[ \LCTvxsm \! = \! \LCTvxlm  \! = \! \tv{0} \bigr] \Biggr) \cdot \Biggl( \prod_{m \in [M] \setminus [k] } \sum_{ \LCTvxsm,\LCTvxlm } |\gone( \LCTvxsm, \LCTvxlm )| \Biggr)
        = \Biggl( \sum\limits_{ \LCTvxs, \LCTvxl } |\gone( \LCTvxs, \LCTvxl )| \Biggr)^{\!\!\! M-k}.
      \end{align*}
      Using the definition of $ \alpha_{\sfN} $ in equation~\eqref{sec:CheckCon:eqn:71}, this becomes $ \bigl( \alpha_{\graphN} \cdot \ZBSPA^{*}(\graphN) \bigr)^{\!M-k} $.
      Thus, 
      %-----------------------------------------------------------------------
      \begin{align*}
          T_k \geq - \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M} 
          \cdot \bigl( \alpha_{\graphN} \cdot \ZBSPA^{*}(\graphN) \bigr)^{\!M-k} 
          = - \alpha_{\graphN}^{M-k}.
      \end{align*}
      %-----------------------------------------------------------------------
      Summing these lower bounds for $k$ from $0$ to $M-1$ yields the inequality for step $(b)$ in equation~\eqref{sec:CheckCon:eqn:75}.
      Step $(c)$ in equation~\eqref{sec:CheckCon:eqn:75} follows from $ \alpha_{\graphN} \geq 0 $.
   Step $(d)$ in equation~\eqref{sec:CheckCon:eqn:75} follows from
   \begin{align*}
    \alpha_{\graphN}
    =\frac{ \prod\limits_{f}
       \Biggl( \sum\limits_{\LCTtv{x}_{\setpf}}
       \bigl| \LCT{f}( \LCTtv{x}_{\setpf} ) \bigr|
       \Biggr)
    - \ZBSPA^{*}(\graphN)
    }{ \ZBSPA^{*}(\graphN) }
    < \frac{1}{2},
   \end{align*}
   %----------------------------------------------------------------------------
   where the equality follows from the property of $ g_{1} $, as proven in
   Lemma~\ref{sec:CheckCon:prop:properties of N(0)},
   and where
   the strict inequality follows from inequality~\eqref{sec:CheckCon:eqn:70}, as assumed in the statement of Theorem~\ref{sec:CheckCon:thm:1}.
  %--------------------------------------------------------------------------
  Thus,
  %-----------------------------------------------------------------------
  \begin{align*}
    \liminf_{M \to \infty}
    \ZBM(\graphN)
    &\overset{(a)}{\geq}
    \ZBSPA^{*}(\graphN)
    \cdot
    \liminf_{M \to \infty}
    \Biggl(
      1 -
      \frac{ \alpha_{\graphN}
      }{ 1-\alpha_{\graphN} }
    \Biggr)^{\! \!\! 1/M}
    \nonumber\\
    &\overset{(b)}{=} \ZBSPA^{*}(\graphN),
  \end{align*}
  %-----------------------------------------------------------------------
  where step $(a)$ follows from the inequalities in~\eqref{sec:CheckCon:eqn:75},
  and where step $(b)$ follows from the fact that for any positive-valued $ c $, $ \lim_{M \to \infty} c^{1/M} = 1 $.
\end{proof}
%----------------------------------------------------------------------------

%----------------------------------------------------------------------------
\begin{lemma}\label{sec:CheckCon:lem:limsup Z N0 smaller than ZSPA}
  If the strict inequality in~\eqref{sec:CheckCon:eqn:70} holds, then
  %------------------------------------------------------------------------
  \begin{align*}
    \limsup_{M \to \infty}
    \ZBM(\graphN)
    \leq \ZBSPA^{*}(\graphN).
  \end{align*}
  %------------------------------------------------------------------------
\end{lemma}
%----------------------------------------------------------------------------
%----------------------------------------------------------------------------
\begin{proof}
 Following a similar argument as in the proof of Lemma~\ref{sec:CheckCon:lem:liminf Z N0 greater than ZSPA} (specifically, the derivation leading to equation~\eqref{sec:CheckCon:eqn:75}), we obtain
 %-----------------------------------------------------------------------
 \begin{align*}
  &\hspace{-0.2 cm}\Biggl( \frac{ \ZBM(\graphN) }{ \ZBSPA^{*}(\graphN) } \Biggr)^{\!\! M}
    \nonumber
    \\
    &=
    \sum_{k=0}^{M}
    \bigl( \ZBSPA^{*}(\graphN) \bigr)^{\! k-M}
    \! \cdot \! \binom{M}{k}
    \cdot \!\! \!\! \!\!
    \sum_{ \LCTvxsM, \LCTvxlM }
     \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
     \! \cdot \!
     \Biggl(
      \prod_{ m \in [M] \setminus [k] }
      \gone( \LCTvxsm, \LCTvxlm )
     \Biggr)
     \!\!
    \cdot \prod_{e}
    P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)
    \nonumber\\
    %--------------------------------------------------------------------
    &\leq
    \sum_{k =0}^{M} \alpha_{\graphN}^{M-k}
    \nonumber\\
    &=
    \frac{ 1 - \alpha_{\graphN}^{M+1}
    }{ 1-\alpha_{\graphN} }
    \nonumber\\
    &\leq
    \frac{ 1
    }{ 1-\alpha_{\graphN} },
 \end{align*}
 %-----------------------------------------------------------------------
 which implies
 %-----------------------------------------------------------------------
 \begin{align*}
   \limsup_{M \to \infty}
   \ZBM(\graphN)
   &\leq
   \ZBSPA^{*}(\graphN)
   \cdot
   \limsup_{M \to \infty}
   \Biggl(\frac{ 1
   }{ 1-\alpha_{\graphN} }\Biggr)^{\!\!\! 1/M} 
   = \ZBSPA^{*}(\graphN).
 \end{align*}
 %-----------------------------------------------------------------------
\end{proof}
%----------------------------------------------------------------------------

By Lemmas~\ref{sec:CheckCon:lem:liminf Z N0 greater than ZSPA} and~\ref{sec:CheckCon:lem:limsup Z N0 smaller than ZSPA}, the proof of Theorem~\ref{sec:CheckCon:thm:1} is concluded.

\begin{remark}
 A key step in proving the bounds in Lemmas~\ref{sec:CheckCon:lem:liminf Z N0 greater than ZSPA} and~\ref{sec:CheckCon:lem:limsup Z N0 smaller than ZSPA} is the inequality:
 %-----------------------------------------------------------------------
 \begin{align*}
  &\hspace{-0.25 cm}
  \binom{M}{k}
  \cdot \!\! \!\! \!\!
  \sum_{ \LCTvxsM, \LCTvxlM }
   \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
   \! \cdot \!
   \Biggl(
    \prod_{ m \in [M] \setminus [k] }
    |\gone( \LCTvxsm, \LCTvxlm )|
   \Biggr)
   \!\!
  \cdot \prod_{e}
  P_{e}\bigl( \LCTtv{x}_{\efi,[M]}, \LCTtv{x}_{\efj,[M]} \bigr)
  \\
  &\leq
  \sum_{ \LCTvxsM, \LCTvxlM }
   \bigl[ \LCTvxsm \! = \! \LCTvxlm \! = \! \tv{0},\, \forall m \in [k] \bigr]
   \! \cdot \!
   \Biggl(
    \prod_{ m \in [M] \setminus [k] }
    |\gone( \LCTvxsm, \LCTvxlm )|
   \Biggr),
  \qquad\qquad\qquad\qquad\qquad\qquad 0 \leq k \leq M.
 \end{align*}
 %-----------------------------------------------------------------------
 This inequality's proof relies on a property of the LCT proven in Lemma~\ref{sec:CheckCon:prop:properties of N(0)}:
 %-----------------------------------------------------------------------
 \begin{align*}
  |\gone( \LCTvxsm, \LCTvxlm )| = |\gone( \LCTvxsm, \LCTvxlm )| \cdot
 \bigl[ \wh(\LCTvxsm) + \wh( \LCTvxlm) \!\geq\! 2 \bigr].
 \end{align*}
 %-----------------------------------------------------------------------
 \eremark
\end{remark}


