To define $G$, it will be convenient to consider a decomposition of $L$, given by the lemma below.
In this decomposition of $L$, one should think of $t=|[0,k]\setminus L|$ as the number of parts $V_{(1,1)}, \dots, V_{(t,1)}$ forming a horizontal chain as in~\cref{fig: tree structure}, and $h_i$ as the number of parts $V_{(i,1)},\dots,V_{(i,h_i)}$ forming a vertical chain at the $i$th layer. Moreover, these parameters are always chosen in such a way that for each $\ell \in [k-1]$, we have $\ell\not \in L$ if and only if $\ell=\sum_{i=i_0}^t h_i$ for some $i_0 \in [t-1]$.

\begin{lemma}\label{lemma:decomposeL}
    Let $k \ge 2$ and $L\subseteq [k-1]$ with $1\in L$. 
    Then there exist positive integers $t\geq 2$ and $h_i$ for each $i\in[t]$ such that $h_t=1$, $\sum_{i=1}^t h_i=k$, and
    \begin{align*}
        [k]\setminus L&=\Big\{\ell: \ell=\sum_{i=i_0}^t h_i\textnormal{ for some }i_0 \in [t-1]\Big\},\\
        L&=\{1\}\cup\bigcup_{i_0=1}^{t-1}  \Big\{\ell:\sum_{i=i_0+1}^t h_i< \ell<\sum_{i=i_0}^t h_i\Big\}.
    \end{align*}
\end{lemma}

\begin{proof}
    Let $t:=k+1-|L|$ and write $[0,k]\setminus L=\{a_1,\dots,a_{t}\}$ with $k=a_1>a_2>\dots>a_{t}=0$. Then let $h_t:=1$, $h_{t-1}:=a_{t-1}-1$, and $h_i:=a_{i}-a_{i+1}$ for all $i\in[t-2]$. It is easy to see that these satisfy the required conditions.
\end{proof}

