\begin{lemma} \label{lemma: properties of the sets}
    Let $n,m \ge 1$ and $k \ge 2$ be integers.
    Let $L\subseteq [k-1]$ with $1 \in L$, and let $t,h_1,\dots,t_t$ be as in \cref{lemma:decomposeL}.
    Set $P:=\{(a,b):a\in[t],b\in[h_a])$. 
    Then, there exist $k$ disjoints sets $V_{p}$ for $p \in P$ and a $k$-partite set system $\mc{F}$ with parts $(V_{p})_{p\in P}$ such that the following holds.

    Write $\mc{T}$ for the auxiliary tree on the vertex set $P$ where two vertices $(a,b)$ and $(a',b')$ are connected if $a=a',b=b'\pm 1$ or $b=b',a=a'\pm 1$.
    Define $G$ to be the graph with vertex set $\bigcup_{p \in P} V_{p}$ such that two vertices $u\in V_p, v \in V_q$ are connected precisely when $pq$ is an edge in $\mc{T}$ and some set in $\mc{F}$ contains both $u$ and $v$. Then, the following properties are satisfied.
    \begin{enumerate}\setcounter{enumi}{-1}
        \item $|V_{(1,1)}|=n^{t-2}m^{k-t+1}$ and $|\mc{F}|=n^{t-2}m^{2k-t}$. \label{prop: counts}
        \item Whenever $F,F' \in \mc{F}$, then $\{p\in P: F\cap F'\cap V_p\neq\emptyset\}$ induces a connected (or empty) subgraph of $\mc{T}$.\label{prop: connected}
        \item For all $a\in[t-1]$, each vertex in $V_{(a,1)}$ has exactly $m$ neighbours in $V_{(a+1,1)}$.\label{prop: outdegree horizontal}
        \item For all $a\in[2,t-1]$, each vertex in $V_{(a,1)}$ has exactly $n$ neighbours in $V_{(a-1,1)}$. Moreover, each vertex in $V_{(t,1)}$ has exactly $m$ neighbours in $V_{(t-1,1)}$. \label{prop: indegree horizontal}
        \item Whenever $(a,b)\in P$ with $b\geq 2$, then each vertex in $V_{(a,b)}$ has exactly $m$ neighbours in $V_{(a,b-1)}$%, and each vertex in $V_{(i,j-1)}$ has exactly $m^2$ neighbours in $V_{i,j}$
        .\label{prop: indegree vertical}
        \item If $a \in [t-1]$ with $h_a \ge 2$, $u \in V_{(a,1)}$, and $v \in V_{(a+1,1)}$, there exists a set $W_{u,v}\subseteq V_{(a,2)}$ of size $m$ such that every $F\in \mc{F}$ that contains $u,v$ must contain one of the vertices in $W_{u,v}$.\label{prop: backup}
        \item Let $a \in [t-1]$ with $h_a \ge 2$. If $F,F' \in \mc{F}$ satisfies $F\cap V_{(a,1)}=F' \cap V_{(a,1)}$ and $F \cap V_{(a+1,1)} \neq F'\cap V_{(a+1,1)}$, then $F\cap V_{(a,2)} \neq F' \cap V_{(a,2)}$. \label{prop: branchup}
        \item If $a \in [t-1]$, $b \in [3,h_a]$, $u \in V_{(a,b-1)}$, and $v \in V_{(a,b-2)}$, there exists a set $W_{u,v}\subseteq V_{(a,b)}$ of size $m$ such that every $F\in \mc{F}$ that contains $u,v$ must contain one of the vertices in $W_{u,v}$. \label{prop: up}
        \item Let $a \in [t-1]$ and $b \in [3,h_a]$. If $F,F' \in \mc{F}$ satisfies $F \cap V_{(a,b-1)}=F'\cap V_{(a,b-1)}$ and $F\cap V_{(a,b-2)} \neq F' \cap V_{(a,b-2)}$, then $F \cap V_{(a,b)} \neq F' \cap V_{(a,b)}$.\label{prop: branchup2}
    \end{enumerate}
\end{lemma}
We note that Properties~\ref{prop: connected}, \ref{prop: outdegree horizontal}, and \ref{prop: indegree horizontal} correspond to \ref{item: recall interval}, \ref{item: recall c to the right}, and \ref{item: recall n to the left}, respectively; Property~\ref{prop: indegree vertical} is the analogue of Property~\ref{item: recall c to the right} for $V_{(a,b)}$ with $b \ge 2$; Properties~\ref{prop: backup} and \ref{prop: branchup} correspond to \ref{item: new rule up}; and Properties~\ref{prop: up} and \ref{prop: branchup2} give the analogue of Property~\ref{item: new rule up} for the case $h_a \ge 3$.
We first prove \cref{theorem: forbidding sunflowers with one but zero} assuming \cref{lemma: properties of the sets} holds.
\begin{proof}[Proof of \cref{theorem: forbidding sunflowers with one but zero}]
    As discussed at the beginning of the appendix, we show $ r_{\textnormal{sf}}(k,L,m + 1) \le m^{-(k-1)}$.
    Let $t,h_1,\dots,h_t$ be as in \cref{lemma:decomposeL} and recall that 
        \begin{align*}
        [k]\setminus L=\Big\{\ell: \ell=\sum_{i=i_0}^t h_i\textnormal{ for some }i_0 \in [t-1]\Big\}\quad\text{and}\quad
        L=\{1\}\cup\bigcup_{i_0=1}^{t-1}  \Big\{\ell:\sum_{i=i_0+1}^t h_i< \ell<\sum_{i=i_0}^t h_i\Big\}.
    \end{align*}
    % Write $P:=\{(a,b):a\in[t],b\in[h_a]\}$ and $\mc{T}$ to be the tree on the vertex set $P$ where two vertices $(a,b)$ and $(a',b')$ are connected if $a=a',b=b'\pm 1$ or $a=a'\pm 1,b=b'$.
    Let $n$ be a sufficiently large integer in terms of $m$ and $k$, and let $(V_p)_{p\in P}$, $\mc{T}$, $\mc{F}$, and $G$ be as in \cref{lemma: properties of the sets}.
    Here, $P=\{(a,b):a\in[t],b\in[h_a]\}$.


    We claim that $\mc{F}$ has no $L$-sunflower with $m+1$ petals. 
    Suppose for contradiction that there exists a sunflower with $m+1$ petals whose kernel has size in $L$.
    Write $A$ for the projection of the kernel to $P$ (i.e., $A$ is the set of $p\in P$ such that the kernel intersects $V_p$). 
    We know $A$ is non-empty as $0 \notin L$, and $A$ is connected in $\mathcal{T}$ by Property~\ref{prop: connected}.
    % By Property~\ref{prop: connected}, $A$ is connected in the auxiliary graph $\mathcal{T}$.
    In particular, the set $\{a: (a,1) \in A\}$ must form an interval.
    Moreover, by Property~\ref{prop: outdegree horizontal}, $\{a:(a,1)\in A\}$ must be empty or of the form $[a_0,t]$ for some $a_0\in[t]$, and by Property~\ref{prop: indegree vertical}, for each $a$, the set $\{b:(a,b)\in A\}$ is empty or of the form $[1,b_a]$ for some $b_a\in[h_a]$. 
    Furthermore, by Property~\ref{prop: backup}, if $h_a\geq 2$ and $(a,1),(a+1,1)\in A$, then we must have $(a,2)\in A$, and by Property~\ref{prop: up}, if $b\in[3,h_a]$ and $(a,b-1),(a,b-2)\in A$, then $(a,b)\in A$. 
    It follows that $A$ is of the form $\{(a,b)\in P:a\geq a_0\}$ for some $a_0 \in [t]$, and hence $|A|=\sum_{i=a_0}^t h_i$. 
    This means $|A|\not \in L$, unless $a_0=t$ and $A=\{(t,1)\}$. 
    But in this case Property~\ref{prop: indegree horizontal} guarantees this sunflower can have at most $m$ petals, which is a contradiction.
    This proves the claim.

    Now, assume the subfamily $\mc{F}'\subseteq \mc{F}$ avoids intersections of size in $L$. 
    Our goal is to show 
    $$
    |\mc{F}'| \le \left(m^{-(k-1)}+o(1)\right)|\mc{F}|,
    $$
    where $o(1)$ stands for some function tending to zero as $n\to\infty$ (with $k,m$ fixed).
    Similarly to the proof when $L=\{1\}$, we want to classify edges in $G$ into heavy and light edges, and show that ``very few'' sets in $\mc{F}'$ contain at least one light edge, and every vertex $u$ in $G$ has at most one heavy edge ``to the right'' as well as at most one ``upwards''.

    We first classify edges ``to the right''.
    For each $a\in [t-1]$ and edge $uv$ of $G$ with $u \in V_{(a,1)}$ and $v \in V_{(a+1,1)}$, the edge $uv$ is \emph{heavy} if at least $n^{a-3/2}$ sets in $\mc{F}'$ contains $uv$, and \emph{light} otherwise. 
    We have the following claim.
    \begin{claim} \label{claim: horizontal heavy}
        Suppose $n$ is sufficiently large.
        For every $a \in [t-1]$ and every vertex $u \in V_{(a,1)}$, there is at most one $v \in V_{(a+1,1)}$ such that $uv$ is a heavy edge.
    \end{claim}
    \begin{proof}
        Assume that $u\in V_{(a,1)}$ and $v,v'\in V_{(a+1,1)}$ are such that $uv,uv'$ are both heavy. 
        Fix any set $F \in \mc{F}'$ containing $uv$ (so that $F\cap V_{(a,1)}=\{u\},F \cap V_{(a+1,1)} = \{v\}$). 
        Note that whenever $F'\in \mc{F}$ contains $uv'$, we must have $F\cap V_{(a,1)}=F'\cap V_{(a,1)}$ and $F\cap V_{(a+1,1)}\not =F'\cap V_{(a+1,1)}$. 
        Since $1\in L$, the sets $F,F'$ cannot intersect in exactly $1$ vertex. 
        By Property~\ref{prop: branchup}, we have $F\cap V_{(a,2)}\neq F'\cap V_{(a,2)}$.
        Using Property~\ref{prop: connected}, we see that we must have $a\ge 2$ and $F \cap V_{(a-1,1)}=F' \cap V_{(a-1,1)}$. 
        But the number of sets containing $u,v'$ and a specified vertex from $V_{(a-1,1)}$ is at most $n^{a-2}m^k$.
        Indeed, there are $n^{a-2}$ choices for the vertices in $V_{(a-2,1)},V_{(a-3,1)},\dots,V_{(1,1)}$ by repeated application of Property~\ref{prop: indegree horizontal}.
        After this, we look at the vertices in the sets $V_{(a+1,1)},V_{(a+2,1)},\dots,V_{(t,1)}$, and then those in sets of form $V_{(i,2)}$, then those in sets of form $V_{(i,3)}$, etc. Using Properties \ref{prop: outdegree horizontal}, \ref{prop: backup}, and \ref{prop: up}, each such a step gives at most $m$ choices, so in total they contribute at most a factor of $m^k$. So we get the claimed upper bound $n^{a-2}m^k$ of sets in $\FF'$ containing $uv'$, contradicting the assumption that $uv'$ is a heavy edge when $n$ is sufficiently large.
    \end{proof}

    We are now left to classify edges ``upwards'', i.e., edges between $V_{(a,b)}$ and $V_{(a,b+1)}$, for some $a \in [t-1],b\in [h_a-1]$.
    Note that there are $k-t$ such pairs $(a,b)$, so $k-t$ different ``types'' of edges left to classify.
    We will classify these $k-t$ types of edges recursively according to the ordering on these pairs $(a,b)$ where pairs $(a,b)$ with larger $a$-coordinates are listed first, and if two pairs have the same $a$-coordinate, then the one with smaller $b$-coordinate is listed earlier.
    Let this ordering be $(a_1,b_1),\dots,(a_{k-t},b_{k-t})$. (Thus, for example, in the setting depicted in \cref{fig: tree structure}, this ordering is given by $(4,1)$, $(4,2)$, $(2,1)$.)

    Assume that $s \in [k-t]$, and for all $r \in [s-1]$ we have already classified edges between $V_{(a_r,b_r)}$ and $V_{(a_r,b_r+1)}$. 
    Then, we say that a set $F \in \mc{F}'$ is {\em $(s-1)$-completely-heavy} if between all the parts where the edges of $G$ have already classified, $F$ gives a heavy edge in $G$. (In other words, this says that between $V_{(a,1)}$ and $V_{(a+1,1)}$ for all $a\in [t-1]$, as well as between $V_{(a_r,b_r)}$ and $V_{(a_r,b_r+1)}$ for all $r \in [s-1]$, the set $F$ must contain a heavy edge.)
    Now, given any edge $uv$ of $G$ with $u\in V_{(a_s,b_s)}$, $v\in V_{(a_s,b_s+1)}$, we say that $uv$ is \emph{heavy} if there are at least $n^{a_s-3/2}$ sets in $\mc{F}'$ that are $(s-1)$-completely-heavy and contain both $u$ and $v$.
    Similarly to Claim \ref{claim: horizontal heavy}, we have the following.
    \begin{claim} \label{claim: vertical heavy}
        Suppose $n$ is sufficiently large.
        For every $s \in [k-t]$, the heavy edges between $V_{(a_s,b_s)}$ and $V_{(a_s,b_s+1)}$ form a matching.
    \end{claim}
    \begin{proof}
        We will prove the claim by an induction on $s$.
        Let us assume that we already showed that the heavy edges between $V_{(a_r,b_r)}$ and $V_{(a_r,b_r+1)}$ form a matching for all $r \in [s-1]$.
        For convenience, write $a=a_s$ and $b=b_s$; we know that $a \in [t-1]$ and $b \in [h_a-1]$.
        First, observe that for every $v \in V_{(a,b+1)}$, there can be at most one $u \in V_{(a,b)}$ such that $uv$ is a heavy edge.
        Indeed, suppose $uv,u'v$ are distinct heavy edges with $u,u' \in V_{(a,b)}$.
        Consider any $F \in \mc{F}'$ containing $u,v$ and any $F' \in \mc{F}'$ containing $u',v$.
        Properties \ref{prop: connected} and \ref{prop: branchup2} imply $|F\cap F'|=1$, contradicting the fact that $\mc{F}$ avoids intersections of size in $L$.

        Second, let $u \in V_{(a,b)}$ and suppose for contradiction that $uv,uv'$ are distinct heavy edges with $v,v' \in V_{(a,b+1)}$.
        Consider any $(s-1)$-completely-heavy set $F \in \mc{F}'$ containing $u,v$ and any $(s-1)$-completely-heavy set $F' \in \mc{F}'$ containing $u,v'$.
        The definition of being $(s-1)$-completely-heavy implies that both $F$ and $F'$ contain only heavy edges between the parts $V_{(a',1)}$ and $V_{(a'+1,1)}$ for all $a' \in [t-1]$, and between the parts $V_{(a_r,b_r)}$ and $V_{(a_r,b_r+1)}$ for all $r \in [s-1]$.
        Using Claim~\ref{claim: horizontal heavy} and the induction hypothesis (as well as the definition of our ordering of the pairs $(a,b)$), we see that $F$ and $F'$ agree on every part $V_{(a',b')}$ with $a' > a$ or $a'=a,b'\le b$, i.e., $I:=\{p \in P: F\cap F'\cap V_p\neq \emptyset\}$ satisfies $I\supseteq \{(a',b') \in P: a' > a \text{ or } a'=a, b'\le b\}$.
        Notice that the number of such $(a',b')$ is equal to $\sum_{i=a+1}^t h_i + b \in L$.
        Thus, $F$ and $F'$ must intersect in some other part as well.
        Using Property \ref{prop: connected}, we must have $a \ge 2$ and $F\cap V_{(a-1,1)}=F\cap V'_{(a-1,1)}$. 
        Using a similar argument as in Claim \ref{claim: horizontal heavy}, we see that the number of $(s-1)$-completely heavy sets containing $u,v'$ and a specified vertex from $V_{(a-1,1)}$ is at most $n^{a-2}m^k$.
        This contradicts that $uv'$ is an heavy edge when $n$ is sufficiently large.
        Therefore, there is at most one heavy edges $uv$ with $v \in V_{(a,b+1)}$, and the claim follows.
    \end{proof}

    We now complete the proof by counting sets in $\mc{F}'$.
    By Properties~\ref{prop: outdegree horizontal}, \ref{prop: indegree horizontal}, and then \ref{prop: counts}, we know that for all $a\in[t-1]$, $|V_{(a,1)}|=|V_{(1,1)}|(m/n)^{a-1}=n^{t-a-1}m^{k-t+a}$.
    Notice that the number of sets in $\mc{F}'$ containing some light edge between $V_{(a,1)}$ and $V_{(a+1,1)}$ (for some $a \in [t-1]$) is at most $$
        \sum_{a=1}^{t-1} e_G(V_{(a,1)},V_{(a+1,1)})\cdot n^{a-3/2}
        =\sum_{a=1}^{t-1} m\cdot |V_{(a,1)}| \cdot n^{a-3/2}
        =\sum_{a=1}^{t-1} n^{t-a-1} m^{k-t+a+1} \cdot n^{a-3/2}=o\left(m^{-(k-1)}|\mc{F}|\right),
    $$
    where we used $|\FF|=n^{t-2}m^{2k-t}$ (by Property~\ref{prop: counts}) in the last step.

    For all $a \in [t-1]$ and $b\in[h_a-1]$, by Properties \ref{prop: outdegree horizontal} and~\ref{prop: backup} (if $b=1$) or Properties~\ref{prop: indegree vertical}~and~\ref{prop: up} (if $b>1$), each vertex in $V_{(a,b)}$ has at most $m^2$ $G$-neighbours in $V_{(a,b+1)}$. Hence, using Property~\ref{prop: indegree vertical}, we have $|V_{(a,b)}| \le |V_{(a,1)}|\cdot m^{b-1}=n^{t-a-1}m^{k-t+a+b-1}$ for all $a \in [t-1],b\in[h_a]$.
    By a similar calculation to the one above, the number of sets in $\mc{F}'$ for which all the corresponding edges between parts $V_{(a,1)}$ and $V_{(a+1,1)}$ are heavy but an edge between some pair $V_{(a,b)}$, $V_{(a,b+1)}$ is light, is $o(m^{-(k-1)}|\mc{F}|)$. Indeed, if $s\in[k-t]$, then the number of sets in $\FF'$ which are $(s-1)$-completely heavy but not $s$-completely heavy is easily seen to be at most
    $$
    |e_G(V_{(a_s,b_s)},V_{(a_s,b_s+1)})|n^{a_s-3/2}\leq n^{t-a_s-1}m^{k-t+a_s+b_s+1}n^{a_s-3/2}=o\left(m^{-(k-1)}|\mc{F}|\right),
    $$
    giving the count mentioned above.
    Thus, $\mc{F}'$ has $|\mc{F}'|-o(m^{-(k-1)}|\mc{F}|)$ sets $F$ such that between any two adjacent parts $V_{a,b},V_{a',b'}$ (in $\mc{T}$), the two corresponding vertices in $F$ form a heavy edge of $G$.
    However, using Claim \ref{claim: horizontal heavy} and Claim \ref{claim: vertical heavy}, we see that the number of such sets is at most $|V_{(1,1)}|=m^{-(k-1)}|\mc{F}|$. 
    Hence, $|\mc{F}'|\leq (1+o(1))m^{-(k-1)}|\mc{F}|$, finishing the proof.
\end{proof}


It remains to prove \cref{lemma: properties of the sets}, i.e., construct $(V_{p})_{p \in P}$ and $\mc{F}$. 
The construction is quite technical, but it may be helpful for the reader to compare it with the construction used in the proof of \cref{lemma: digraph}, which deals with the case $L=\{1\}$ (i.e., $t=k$, $h_1=\dots=h_k=1$).
\begin{proof}[Proof of \cref{lemma: properties of the sets}]
    Let $\mathcal{X}$ be the collection of sequences $$X=((x_i,y_i)_{i\in [t-1]},(x_{i,j},y_{i,j},z_{i,j})_{i\in[t-1],j\in[2,h_i]})$$ satisfying
\begin{itemize}
    \item  $x_{t-1},y_{t-1}\in[m]$;
    \item  $x_i\in[n]$ and $y_i\in[m]$ for all $i\in[t-2]$;
%    \item $x_{i,2},y_{i,2},z_{i,2}\in[m]$ for all $i\in[t-2]$ with $h_i\geq 2$;
    \item $x_{i,j},y_{i,j},z_{i,j}\in[m]$ for all $i\in[t-1]$ and $j\in[2,h_i]$;%[3,h_i]$;
    \item $y_{i,2}=y_{i}$ whenever $i\in[t-1]$ with $h_i\geq 2$;
    \item $y_{i,j+1}=x_{i,j}$ whenever $i\in [t-1]$ and $j\in[2,h_i-1]$.
\end{itemize}

Every $X \in \mc{X}$ will correspond to a set in our family $\mc{F}$ via the following functions, which will be the $k$ elements in the set.
For each $X \in \mc{X}$ and $p=(a,b) \in P$, let $f_p=f^X_p$ be the function with domain $P$ such that $f_{(a,b)}(t,1) =(a,b)$ and

\begin{align*}
    \textnormal{for } i \in \{1,\dots,a-1\}, \quad\quad\quad f_{(a,b)}(i,j) &=
    \begin{cases}
        y_i & \textnormal{if } j=1, \\
        (x_{i,j},y_{i,j}) & \textnormal{if } j \ge 2;
    \end{cases}  \\[3pt]
    \textnormal{for } i = a, \quad\quad\quad f_{(a,b)}(i,j) &=
    \begin{cases}
        x_i & \textnormal{if } j=1, \\
        (y_{i,j},z_{i,j}) & \textnormal{if } 2 \le j \le b, \\
        x_{i,j} & \textnormal{if } j=b+1, \\
        (x_{i,j}, y_{i,j}) & \textnormal{if } j \ge b + 2;
    \end{cases} \\[3pt]
    \textnormal{for } i\in \{a+1,\dots,t-1\}, \quad\quad\quad f_{(a,b)}(i,j) &=
    \begin{cases}
        x_i & \textnormal{if } j=1, \\
        x_{i,j} & \textnormal{if } j=2, \\
        (x_{i,j}, y_{i,j}) & \textnormal{if } j \ge 3.
    \end{cases}
\end{align*}


Let $F_X=\{f_p^X:p\in P\}$ for each $X\in \mathcal{X}$; this is a set of $|P|=k$ functions.
For each $p\in P$, we define $V_{p}=\{f_p^X:X\in \mathcal{X}\}$, and we let $\mc{F} = \{F_X:X\in \mathcal{X}\}$. 
It is easy to see that $F_X \neq F_{X'}$ for distinct $X,X' \in \mc{X}$, and $\mc{F} $ is $k$-partite with parts $(V_p)_{p\in P}$.
Before checking the properties in \cref{lemma: properties of the sets}, we need the following two auxiliary properties.
These two properties can be verified using the definition of $(f_{p})_{p \in P}$.
For example, to check Property \ref{propi}, one can see that $f_{(a,1)}(i,j)=f_{(a+1,1)}(i,j)$ whenever $i \in [1,a-1]\cup[a+1,t-1]$, so it suffices to look at $i=a$.
The rest is then easy to see.
\begin{enumerate}[(i)]
    \item Whenever $a\in[t-1]$, then $f_{(a,1)}$ and $f_{(a+1,1)}$ agree at every point apart from $(t,1)$, except possibly $(a,1)$ and $(a,2)$ (if $h_a\geq 2$), for which values we have $f_{(a,1)}(a,1)=x_a$, $f_{(a+1,1)}(a,1)=y_a$, $f_{(a,1)}(a,2)=x_{a,2}$, $f_{(a+1,1)}(a,2)=(x_{a,2},y_{a,2})=(x_{a,2},y_{a})$.\label{propi}
    \item Whenever $a\in[t-1]$ and $b\in[2,h_a]$, then $f_{(a,b)}$ and $f_{(a,b-1)}$ agree on every point apart from $(t,1)$, except possibly $(a,b)$ and $(a,b+1)$ (if $h_a\geq b+1)$, for which values we have $f_{(a,b)}(a,b)=(y_{a,b},z_{a,b})$, $f_{(a,b-1)}(a,b)=x_{a,b}$, $f_{(a,b)}(a,b+1)=x_{a,b+1}$, $f_{(a,b-1)}(a,b+1)=(x_{a,b+1},y_{a,b+1})=(x_{a,b+1},x_{a,b})$.\label{propii}
\end{enumerate}

Now, we (briefly) verify the properties required by the lemma.
\begin{description}
    \item[For Property \ref{prop: counts}:] Note that $$
        f_{(1,1)}(i,j) =
        \begin{cases}
            x_i & \textnormal{if } j=1, \\
            x_{i,2} & \textnormal{if } j=2, \\
            (x_{i,j}, y_{i,j})=(x_{i,j},x_{i,j-1}) & \textnormal{if } j > 2.
        \end{cases}
    $$ 
        This means $f_{(1,1)}$ is uniquely determined by all $x_i$s and $x_{i,j}$s, so $|V_{(1,1)}|=m\cdot n^{t-2}\cdot m^{k-t}=n^{t-2}m^{k-t+1}$.
        In addition, $F_X\neq F_{X'}$ whenever $X\neq X'$, so a similar calculation shows $|\mc{F}|=m^2 \cdot n^{t-2} \cdot m^{t-2} \cdot m^{2(k-t)}=n^{t-2}m^{2k-t}$.
    \item[For Property \ref{prop: connected}:] If $f^X_{(a,1)}=f^Y_{(a,1)}$ but $f^X_{(a+1,1)}\not =f^Y_{(a+1,1)}$, then \ref{propi} shows $X$ and $Y$ disagree on the value of $y_a$ and hence $f^X_{a',b'}\not =f^Y_{a',b'}$ whenever $a'\geq a+1$. 
        Similarly, if $f^X_{(a,b)}=f^Y_{(a,b)}$ but $f^X_{(a,b-1)}\not =f^Y_{(a,b-1)}$, then $X$ and $Y$ disagree on the value of $x_{a,b}$ and hence $f^X_{a',b'}\not =f^Y_{a',b'}$ whenever $a'\not = a$ and also whenever $a'=a,b'\leq b-1$. 
    \item[For Property \ref{prop: outdegree horizontal}]: This follows from \ref{propi} for the $m$ choices of $y_a$.
    \item[For Property \ref{prop: indegree horizontal}]: This follows from \ref{propi} for the $n$ choices of $x_{a-1}$ when $a \in [t-2]$ and the $m$ choices of $x_{a-1}$ when $a=t-1$.
    \item[For Property \ref{prop: indegree vertical}]: This follows from \ref{propii} for the $m$ choices of $x_{a,b}$.
    \item[For Property \ref{prop: backup}]: Given $f_{(a,1)},f_{(a+1,1)}$, we know the value of $y_a=y_{a,2}$ (using \ref{propi}). Then, there are $m$ choices for $z_{a,2}$, and hence for $f_{(a,2)}$ by \ref{propii} with $b=2$.
    \item[For Property \ref{prop: branchup}]: If $F_X$ and $F_Y$ give the same $f_{(a,1)}$ but different $f_{(a+1,1)}$, then $X$ and $Y$ disagree on the value of $y_a=y_{a,2}$ (using \ref{propi}). Hence, they give different vertices $f_{(a,2)}$ (using \ref{propii} for $b=2$).
    \item[For Property \ref{prop: up}]: Given $f_{(a,b-1)},f_{(a,b-2)}$, we know the value of $x_{a,b-1}=y_{a,b}$ (by \ref{propii}). Then, there are $m$ choices for $z_{a,b}$ and hence for $f_{(a,b)}$ by \ref{propii}.
    \item[For Property \ref{prop: branchup2}]: If $F_X$ and $F_Y$ give the same $f_{(a,b-1)}$ but different $f_{(a,b-2)}$, then $X$ and $Y$ disagree on the value of $x_{a,b-1}=y_{a,b}$ (using \ref{propii}). Hence, they give different vertices $f_{(a,b)}$ (using \ref{propii} again).
    \qedhere
\end{description}
\end{proof}


\section{Proof of Lemma~\ref{lem:qs:fermionic}}
\label{section: appendix quantum}

Finally, we explain how to obtain the algorithm we need for the applications in quantum computing.

\begin{proof}[Proof of Lemma~\ref{lem:qs:fermionic}]
    By \cref{thm:modularstructure}, there exists some $\chi=\min\{O_k(m^k),|\FF|\}$ such that for any non-negative weighting $w \in \mb{R}_{\ge 0}^{\mc{F}}$ on $\mc{F}$, there is a subfamily $\mc{F}'$ that avoids intersections of size in $L$ and whose weight satisfies $\sum_{F \in \mc{F}'} w(F) \ge \frac{1}{\chi}\sum_{F \in \mc{F}} w(F)$; this $\mc{F}'$ corresponds to an independent set of the associated graph $G_\mc{F}$.
    Moreover, the proof of \cref{thm:modularstructure} guarantees that we can find this $\mc{F}'$ in running time $\mathrm{poly}(n,|\mc{F}|)=\mathrm{poly}(n^k)$.
    Indeed, in the proof, we iteratively shrink the ground set by two each time and keep track of the weighting along the way.
    The key step of this iteration is to locate two elements in the ground set that accumulate sufficiently large weights (see Claim~\ref{claim:modularstructure_1} and surrounding arguments), which runs efficiently in time $\mathrm{poly}(n,|\mc F|)\le\mathrm{poly}(n^k)$.
    Thus, in total, the algorithm has running time $\mathrm{poly}(n^k)$.

    As we have seen in \cref{theorem: modular clique fractional chromatic number}, the above implies that the fractional chromatic number of $G_\mc{F}$ is at most $\chi$. By increasing the value of $\chi$ if necessary, we may assume that $\chi\geq 2$.
    In order to efficiently find a ``small'' fractional colouring, it suffices to find $T=20\chi^2\ln(|\mc{F}|)=\mathrm{poly}(n^k)$ independent sets $\mc{I}^{(1)},\dots,\mc{I}^{(T)}$ of $G_\mc{F}$ in running time $\mathrm{poly}(n^k)$ such that if we uniformly sample $i \in [T]$, the random independent set $\mc{I}:=\mc{I}^{(i)}$ satisfies $\Pr[F \in \mc{I}] = \Omega(\chi^{-1})$ for all $F \in \mc{F}$.
    Then, the distribution of $\mc{I}$ is a fractional colouring of $G_\mc{F}$ of size $O(\chi)=O_k(m^k)$.

    To this end, we apply the multiplicative weight update method as follows; see \cite[Section 3.3]{arora2012multiplicative} for the analysis in more general settings.
    \begin{enumerate}
        \item Initialize $w^{(1)}\in\mb{R}_{\ge0}^{\mc F}$ by setting $w^{(1)}_F=\frac{1}{|\mc{F}|}$ for all $F\in\mc F$.
        \item For each step $t=1,\dots,T$, find an independent set $\mc{I}^{(t)}\subseteq \mc{F}$ of $G_\mc{F}$ satisfying \begin{equation} \label{eq: indset with large weight}
            \sum_{F \in \mc{I}^{(t)}} w^{(t)}(F) \ge \frac{1}{\chi}\sum_{F \in \mc{F}} w^{(t)}(F),
        \end{equation} 
        and let $w^{(t+1)} \in \mb{R}^{\mc{F}}_{\ge 0}$ be the weighting given by $$
            w^{(t+1)}(F) = \begin{cases}
                w^{(t)}(F) \cdot \big(1+\frac{1}{4\chi^2} \big) & \text{ if } F \notin \mc{I}^{(t)},\\
                w^{(t)}(F) \cdot \big(1-\frac{1}{4\chi}+\frac{1}{4\chi^2} \big) & \text{ if } F \in \mc{I}^{(t)}.
            \end{cases}
        $$
    \end{enumerate}

    As discussed above, we can find the independent set $\mc{I}^{(t)}$ in running time $\mathrm{poly}(n^k)$.
    So it suffices to show that if we uniformly sample $i \in [T]$, then $\mathbb{P}[F \in \mc{I}^{(i)}] = \Omega(\chi^{-1})$ for all $F \in \mc{F}$.
    In other words, for each $F \in \mc{F}$, at least $\Omega(T/\chi)$ of the independent sets among $\mc{I}^{(1)},\dots,\mc{I}^{(T)}$ (with multiplicity) contain $F$.

    We first observe that $w^{(T+1)}(F) \le 1$ holds for all $F \in \mc{F}$.
    To see this, for any $t \in [T]$,
    \begin{align*}
        \sum_{F \in \mc{F}} w^{(t+1)}(F)
        &= \sum_{F \in \mc{I}^{(t)}} w^{(t+1)}(F) + \sum_{F \notin \mc{I}^{(t)}} w^{(t+1)}(F)\\
        &= \sum_{F \in \mc{F}} w^{(t)}(F) \cdot \left(1 + \frac{1}{4\chi^2} \right) - \frac{1}{4\chi}\sum_{F \in \mc{I}^{(t)}} w^{(t)}(F)
        \le \sum_{F \in \mc{F}} w^{(t)}(F),
    \end{align*}
    where we used \eqref{eq: indset with large weight} in the last inequality.
    Hence, $\sum_{F \in \mc{F}} w^{(T+1)}(F) \le\cdots\le\sum_{F \in \mc{F}} w^{(1)}(F)=1$.
    In particular, $w^{(T+1)}(F) \le 1$ for all $F \in \mc{F}$ since the weights are clearly all non-negative.

    Now, suppose $a$ of the independent sets among $\mc{I}^{(1)},\dots,\mc{I}^{(T)}$ contain $F$.
    Then, using that $1+x \ge e^{x/2}$ and $1-x \ge e^{-2x}$ for all $x \in [0,1/2]$, we know $$
        \begin{aligned}
            w^{(T+1)}(F) 
            = w^{(1)}(F)\cdot \Big(1+\frac{1}{4\chi^2}\Big)^{T-a}\Big(1-\frac{1}{4\chi}+\frac{1}{4\chi^2}\Big)^a
            \geq \frac{1}{|\mc{F}|} \cdot \Big(1+\frac{1}{4\chi^2}\Big)^{T-a} \Big(1-\frac{1}{2\chi}\Big)^{2a}
            \ge \frac{1}{|\mc{F}|} \cdot e^{\frac{T-a}{8\chi^2} - \frac{2a}{\chi}}.
        \end{aligned}
    $$
    We know that $w^{(T+1)}(F) \le 1$, so $\frac{T-a}{8\chi^2}-\frac{2a}{\chi} \le \ln|\mc{F}|$.
    Recall $T=20\chi^2\ln|\FF|$.
    Solving this inequality, we see that 
    $$
    a \ge\frac{12\chi^2\ln|\mc{F}|}{16\chi+1} \ge \frac{2\chi\ln|\mc{F}|}{3}=\Omega(T/\chi).
    $$
    Therefore every $F$ is contained in at least $\Omega(T/\chi)$ independent sets among $\mc{I}^{(1)}, \dots, \mc{I}^{(T)}$ (with multiplicity).
\end{proof}


\begin{comment}
    Let $\mc I$ be the set of all independent sets of $G_\mc{F}$, and let $A \in \mb{R}^{\mc{F} \times \mc{I}}$ be the matrix whose rows are indexed by the sets in $\mc F$ and whose columns are indexed by the independent sets in $\mc I$ such that $A_{F,I}=1$ if $F\in I$ while $A_{F,I}=0$ otherwise.

    It suffices to find a probability distribution $x \in \mb{R}^{\mc{I}}_{\ge 0}$ over the independent sets such that $Ax \ge \frac{1}{2\chi} \mathbbm{1}$, where $\mathbbm{1}\in \mb{R}^{\mc{F}}$ is the all-ones vector, and such that $x$ has at most $\mathrm{poly}(n^k)$ non-zero entries, with running time $\mathrm{poly}(n^k)$.
    Indeed, given this distribution, one just need to scan over the non-zero entries of $x$ to sample an independent set corresponding to the fractional colouring $x$ of size at most $2\chi$.

    In order to find such an $x$, we utilize the multiplicative weight update method, largely following the presentation in \cite[Section 3.3]{arora2012multiplicative} as follows.

    \begin{enumerate}
        \item\label{itm:lem:qs:fermionic_1} Initialize a weight vector $w^{(1)}\in\mb{R}_{\ge0}^{\mc F}$ by setting $w^{(1)}_F=1$ for all $F\in\mc F$.
        \item\label{itm:lem:qs:fermionic_2} For each step $t=1,2,3,\ldots,R$ (for some $R$ specified later), 
            \begin{enumerate}
                \item\label{itm:lem:qs:fermionic_2_1} 
                define the weight probability vector $p^{(t)}\in\mb{R}_{\ge0}^{\mc F}$ by setting 
                $$
                p_F^{(t)}=\frac{w_F^{(t)}}{\sum_{F\in\mc F}w_F^{(t)}}
                \quad\text{for each } F\in\mc F;
                $$
                \item\label{itm:lem:qs:fermionic_2_2} 
                compute a solution $x^{(t)}\in\mb{R}_{\ge0}^{\mc I}$ such that $\sum_{I\in\mc I}x_I^{(t)}=1$ and
                $$
                \left\langle p^{(t)},Ax^{(t)}\right\rangle\ge\left\langle p^{(t)},\frac{1}{\chi} \mathbbm{1}\right\rangle=\frac{1}{\chi},
                $$
                where $\langle,\rangle$ is the vector inner product;
                \item\label{itm:lem:qs:fermionic_2_3} 
                construct the weight vector $w^{(t+1)}\in\mb{R}_{\ge0}^{\mc F}$ for next round by setting
                $$
                w^{(t+1)}=w^{(t)}\odot\left(\mathbbm{1}-\frac{1}{4\chi}\cdot\left(Ax^{(t)} -\frac{1}{\chi} \mathbbm{1}\right)\right),
                $$
                where $\odot$ denotes the entrywise product of two vectors.
            \end{enumerate}
        \item\label{itm:lem:qs:fermionic_3} Output the final answer $x=\frac1R\sum_{t=1}^R x^{(t)}$.
    \end{enumerate}

    Now we analyse the correctness and efficiency of the above algorithm.
    Firstly, note that the definition of $A$ and the fact that $x^{(t)}$ is a distribution imply that each entry of $Ax^{(t)}-\frac{1}{\chi}\mathbbm{1}$ is in $[-1,1]$. Hence each $w^{(t)}$ is a vector with all coordinates strictly positive, which makes each $p^{(t)}$ a well-defined distribution.
    Given this and the proof of \cref{thm:modularstructure}, we show that \cref{itm:lem:qs:fermionic_2_2} is efficient and the solution can be taken to be a vector with precisely one non-zero entry.

    \begin{claim}\label{clm:itm:lem:qs:fermionic_2_2}
    For each step $t\in[R]$, \cref{itm:lem:qs:fermionic_2_2} has a solution $x^{(t)}$ where $x^{(t)}_{I^{(t)}}=1$ for some $I^{(t)}\in\mc I$. Moreover, this $I^{(t)}$ can be found in time $\mathrm{poly}(n^k)$.
    \end{claim}
    \begin{proof}
        Observe that
        $$
            \left\langle p^{(t)},Ax^{(t)}\right\rangle
            =\sum_{F\in\mc F} p^{(t)}_F \sum_{I: F\in I\in\mc{I}} x_I^{(t)}=\sum_{I\in\mc I}x_I^{(t)}\sum_{F\in I}p_F^{(t)}
            \quad\text{and}\quad
            \left\langle p^{(t)},
            \frac{1}{\chi} \mathbbm{1} \right\rangle=\frac{1}{\chi}\left(\sum_{F\in\mc F}p_F^{(t)}\right).
        $$
        Note that $p^{(t)}$ is a non-negative weighting on $\mc F$.
        \cref{thm:modularstructure} and the choice of $\chi$ imply that there exists some $I^{(t)}\in\mc I$ with $\sum_{F\in I^{(t)}}p_F^{(t)}\ge\frac{1}{\chi}\sum_{F\in\mc F}p_F^{(t)}$.
        Hence it suffices to set $x^{(t)}_{I^{(t)}}=1$ and $x^{(t)}_{I'}=0$ for other $I'\in\mc I$.
        As discussed at the beginning of the proof of this lemma, this $I^{(t)}$ can be found in time $\mathrm{poly}(n^k)$.
    \end{proof}

    With Claim \ref{clm:itm:lem:qs:fermionic_2_2}, we see that the whole algorithm takes time $\mathrm{poly}(R,n^k)$ and $x$ from \cref{itm:lem:qs:fermionic_3} simply selects a uniformly random independent set from $I^{(1)},\ldots,I^{(R)}$.
    It remains to upper bound $R$ and show the validity of the final $x$ for this choice of $R$.
    For this, we refer interested readers to \cite[Section 3.3]{arora2012multiplicative}.
    Essentially, \cite[Theorem~3.3]{arora2012multiplicative}, with $\ell=\rho=1$ and $m=|\mc{F}|\le \binom{2n}{2k}$ in their notation, guarantees that we can set $R=O\left(\chi^2\log(|\mc F|)\right)$, which is $\mathrm{poly}(n^k)$, and the final $x$ will satisfy $Ax \ge \frac{1}{2\chi} \mathbbm{1}$, as desired.
