\subsection{\setupagent :  Orchestration of Different Agents }
\label{sec:agent_flow}
% The overall workflow of \setupagent is summarized in Algorithm~\ref{alg:swe_collector}. For each issue, the system iteratively coordinates its four agents, sharing a common context and memory pool throughout the process. 

The workflow of \setupagent is an iterative process that orchestrates the four agents to construct and refine a valid evaluation environment, as detailed in Algorithm~\ref{alg:swe_collector}. The process begins with a comprehensive initial iteration. In this first step, the Repository Explorer collects setup information while the system retrieves a relevant reference from the Evaluation Environment Memory Pool. This combined information serves as the initial context for the Environment Manager and Test Manager to generate the first versions of the Dockerfile and evaluation script, which are then passed to the Test Analyst for validation.

In contrast, subsequent iterations are not exhaustive but are instead targeted based on feedback from the Test Analyst. If a validation attempt fails, the Test Analyst identifies the cause of the error and provides specific guidance to the agent responsible for the flawed component. For example, if only the test script contains an error, the workflow invokes only the Test Manager to generate a revised script, bypassing the other agents. The corrected script is then passed back for another round of validation. This refinement cycle continues until the environment is successfully validated or the maximum number of iterations is reached.


\begin{algorithm}[ht]
\caption{\setupagent Agent Workflow}
\label{alg:swe_collector}
\KwIn{
    Issue $\mathcal{I}$; evaluation environment memory pool $\mathcal{M}$; Max iteration number $\mathcal{N}$;\\
    Context retrieval agent $\mathrm{Agent}_{\text{repo}}$; Dockerfile generation agent $\mathrm{Agent}_{\text{docker}}$; \\
    Evaluation script generation agent $\mathrm{Agent}_{\text{script}}$
}
\KwOut{Dockerfile $\mathcal{D}$, evaluation script $\mathcal{S}$}

\textbf{Initialization:} $S_{\text{repo}}, S_{\text{dockerfile}}, S_{\text{script}} \gets \textbf{False}$;\\
\hspace*{1em} // $S_{\text{repo}}$: collected information ready\\
\hspace*{1em} // $S_{\text{dockerfile}}$: Dockerfile generated\\
\hspace*{1em} // $S_{\text{script}}$: evaluation script generated

\For{$i = 1$ \KwTo $\mathcal{N}$}{
    \If{!$S_{\text{repo}}$}{
        collected\_information = $\mathrm{Agent}_{\text{repo}}$.run()\;
        \If{collected\_information}{
            $S_{\text{repo}} \gets \textbf{True}$;
            $\mathrm{Agent}_{\text{docker}}$.update\_context(collected\_information)\;
            $\mathrm{Agent}_{\text{script}}$.update\_context(collected\_information)\;
        }
    }
    reference\_val\_env = $\mathcal{M}$.retrieve\_closet\_version($\mathcal{I}$)\;
    $\mathrm{Agent}_{\text{docker}}$.update\_context(reference\_val\_env.dockerfile)\;
    $\mathrm{Agent}_{\text{script}}$.update\_context(reference\_val\_env.eval\_script)\;

    \If{$S_{\text{repo}}$ \textbf{and} !$S_{\text{dockerfile}}$}{
        $\mathcal{D}$, ok = $\mathrm{Agent}_{\text{docker}}$.run()\;
        \If{ok}{$S_{\text{dockerfile}} \gets \textbf{True}$;}
    }
    \If{$S_{\text{repo}}$ \textbf{and} $S_{\text{dockerfile}}$ \textbf{and} !$S_{\text{script}}$}{
        $\mathcal{S}$, ok = $\mathrm{Agent}_{\text{script}}$.run($\mathcal{D}$)\;
        \If{ok}{$S_{\text{script}} \gets \textbf{True}$;}
    }
    \If{$S_{\text{repo}}$ \textbf{and} $S_{\text{dockerfile}}$ \textbf{and} $S_{\text{script}}$}{
        analysis = test\_analysis\_agent.run($\mathcal{D}$, $\mathcal{S}$)\;
        \If{analysis.is\_finish}{
            $\mathcal{M}$.update($\mathcal{I}$, $\mathcal{D}$, $\mathcal{S}$)\;
            \Return $\mathcal{D}$, $\mathcal{S}$;
        }
        \If{analysis.guidance\_collected\_information}{
            $S_{\text{repo}} \gets \textbf{False}$; $\mathrm{Agent}_{\text{repo}}$.update\_context(analysis.guidance\_retrieval);}
        \If{analysis.guidance\_docker}{
            $S_{\text{dockerfile}} \gets \textbf{False}$; $\mathrm{Agent}_{\text{docker}}$.update\_context(analysis.guidance\_docker);}
        \If{analysis.guidance\_eval\_script}{
            $S_{\text{script}} \gets \textbf{False}$; $\mathrm{Agent}_{\text{script}}$.update\_context(analysis.guidance\_eval\_script);}
    }
}
\end{algorithm}




