    \begin{tabular}{|c|c|c|}
        \hline
        Source programs & Untrained & Trained \\
        \hline
        MBPP Train & 75.99\% & \textbf{86.98\%} \\
        \hline
        MBPP Test & 88.37\% & \textbf{91.67\%} \\
        \hline
    \end{tabular}
    \caption{Percentages of semantic inequivalence game instances solved by Bob, without or with training.}
    \label{TAB:EXPERIMENTS:INTEVAL}
