\documentclass{article}
\usepackage{structure}

\newcommand{\preclex}{\preceq_{\text{lex}}}
\renewcommand{\vec}[1]{\mathbf{#1}}
\newcommand{\PA}{\mathcal{PA}}

\title{Discrepancy of Arithmetic Progressions in Boxes and Convex Bodies}
% Authors: full names plus addresses.
\author{Lily Li\thanks{University of Toronto, Department of Computer Science (xinyuan@cs.toronto.edu).} \ and Aleksandar Nikolov\thanks{University of Toronto, Department of Computer Science (anikolov@cs.toronto.edu).}}
\date{}

\begin{document}
\maketitle
\begin{abstract}
    The combinatorial discrepancy of arithmetic progressions inside $[N] := \{1, \ldots, N\}$ is the smallest integer $D$ for which $[N]$ can be colored with two colors so that any arithmetic progression in $[N]$ contains at most $D$ more elements from one color class than the other. Bounding the discrepancy of such set systems is a classical problem in discrepancy theory. More recently, this problem was generalized to arithmetic progressions in grids like $[N]^d$ (Valk{\'o}) and $[N_1]\times \ldots \times [N_d]$ (Fox, Xu, and Zhou). In the latter setting, Fox, Xu, and Zhou gave upper and lower bounds on the discrepancy that match within a $\frac{\log |\Omega|}{\log \log |\Omega|}$ factor, where $\Omega := [N_1]\times \ldots \times [N_d]$ is the ground set. In this work, we use the connection between factorization norms and discrepancy to improve their upper bound to be within a $\sqrt{\log|\Omega|}$ factor from the lower bound. We also generalize Fox, Xu, and Zhou's lower bound, and our upper bounds to arithmetic progressions in arbitrary convex bodies.
    %
    %The set of all arithmetic progressions on the interval of length $N$ is a set system whose universe consists of the integers $\Omega \coloneqq [N]$ and contains all sets $S \in \mathcal{S}$ of the form $S = \{a + ib: i = 0, ..., \ell - 1\} \cap [N]$ for positive integers $a, b, \ell$. Bounding the discrepancy of such set systems is a classic problem in discrepancy theory. In higher dimensions the problem generalizes to finding the discrepancy of all arithmetic progressions in $d$-dimensional, axis-aligned rectangle $[N_1] \times \cdots \times [N_d]$ whose integer points are denoted $\Omega$. Recently, Fox, Xu, and Zhou [Mathematika, 2024] showed that the discrepancy of all arithmetic progressions in a $d$-dimensional rectangle is bounded below by $f(N_1, ..., N_d) \coloneqq \max_{I \subseteq [d]} \left(\prod_{i \in I} N_i\right)^{\frac{1}{2|I|+2}}$ and above by $\frac{\log |\Omega|}{\log \log \Omega}\cdot f(N_1, ..., N_d)$. We improve the upper bound to $\sqrt{\log |\Omega|}\cdot f(N_1, ..., N_d)$. Further, our upper bound is constructive --- as opposed to the existential bound of Fox, Xu, Zhou --- and uses only simple properties of the $\gamma_2$-norm --- as opposed to the complex number theoretic properties used by Fox, Xu, Zhou. To generalize the type of bounding body considered, we found upper and lower bound on the discrepancy of all arithmetic progressions in any convex body where the gap between the upper and lower bound again differs by $\sqrt{\log |\Omega|}$ where $\Omega$ is the set of integer points inside the body. 
\end{abstract}
\section{Introduction}
Combinatorial discrepancy theory studies set systems (or, equivalently, hypergraphs) $(\Omega, \mathcal{S})$ where $\Omega$ is the underlying (finite) universe of elements and $\mathcal{S}$ is a family of subsets of $\Omega$. For a fixed coloring $\chi: \Omega \rightarrow \{-1, 1\}$, the discrepancy of $\mathcal{S}$ with respect to $\chi$, denoted $\disc(\mathcal{S}, \chi)$, is defined as 
\begin{equation}
    \disc\left(\mathcal{S}, \chi\right) \coloneqq \max_{S \in \SS}\left|\sum_{\omega \in S}\chi(i)\right|.
\end{equation}
Then the discrepancy of $\mathcal{S}$, denoted by $\disc(\mathcal{S})$, is defined as
\begin{equation}\label{eq:disc}
    \disc\left(\mathcal{S}\right) \coloneqq \min_{\chi: \Omega \to \{-1, 1\}} \disc\left(\mathcal{S}, \chi\right)= \min_{\chi: \Omega \to \{-1, 1\}}\max_{S \in \SS}\left|\sum_{\omega \in S}\chi(i)\right|.
\end{equation}
Thus, a set system has low discrepancy if it is possible to color its universe elements with two colors so that all the sets in the system are simultaneously balanced. Combinatorial discrepancy has numerous connections to other fields of mathematics and computer science, e.g., to irregularities of distribution~\cite{BeckChen}, approximation algorithms for $\mathsf{NP}$-hard problems~\cite{Rothvoss-binpacking,HR17-binpacking,BRS22-flowtime}, data structures~\cite{Larsen-range}, among others. We refer to the books~\cite{matousek2009geometric,Chazelle-book}, and the thesis~\cite{sasho-thesis} for further references.

One of the first set systems whose discrepancy was thoroughly studied is the set of all arithmetic progressions (APs) on $[N] \eqdef \{1, \ldots, N\}$. We denote this set system as $\left([N], \AA_N\right)$ where, $\AA_N \eqdef \{\AP(a,b,\ell) \cap [N]: a,b \in [N], \ell \in \mathbb{Z}_{>0}\}$, and $\AP(a,b,\ell)$ is the arithmetic progression starting at $a$ with difference $b$ and length $\ell$:
\begin{equation}\label{eq:ap}
    \mathrm{AP}(a, b, \ell) =  \{a + i b: i = 0, \ldots, \ell-1\}.
\end{equation} 
In an important early paper~\cite{roth1964remark}, Roth used a Fourier theoretic argument to show that
\begin{equation}\label{eq:rothlb}
    \disc(\AA) \gtrsim N^{1/4},
\end{equation}
where the notation $A \gtrsim B$ means that there exists an absolute constant $C$ such that $A \ge CB$. We will similarly use $A \lesssim B$ for $B \gtrsim A$. Roth remarked that his lower bound shows that ``there are various limitations to the extent to which a sequence of natural numbers can be well-distributed simultaneously among and within all congruence classes.'' Indeed, since $[N]$ is itself an arithmetic progression, a low discrepancy coloring must color about half of $[N]$ with $+1$. Taking $s$ to be the sequence of all integers in $[N]$ colored $+1$, Roth's lower bound~\eqref{eq:rothlb} shows that the density of $s$ in some arithmetic progression must be substantially different from $\frac12$. Thus $s$ cannot be simultaneously well distributed within all arithmetic progressions. This fact is of similar nature as, for example, van der Waerden's theorem.

A uniformly random coloring of $[N]$ achieves discrepancy in $O(\sqrt{N\log N})$ with high probability, and Roth conjectured that this simple upper bound ought to be closer to the truth than his lower bound~\eqref{eq:rothlb}. This turned out to be false, and, after some weaker results, Beck showed that $\disc(\AA) \lesssim N^{1/4}\left(\log N\right)^{5/2}$, which matches~\eqref{eq:rothlb} up to the logarithmic factors~\cite{beck1981roth}. Beck introduced his celebrated partial coloring method in the proof of this upper bound. A subsequent refinement of the partial coloring method was used by Matou\v{s}ek and Spencer to show that
\begin{equation}\label{eq:matousekub}
   \disc(\AA) \lesssim N^{1/4} 
\end{equation} 
proving that Roth's lower bound was tight up to constant factors~\cite{matouvsek1996discrepancy}.  

Since then, Valk{\'o}~\cite{valko2002discrepancy} and Fox, Xu, Zhou~\cite{fox2024discrepancy} have investigated upper and lower bounds on the discrepancy of arithmetic progressions in $d$-dimensional axis-aligned boxes. We define the set system of $d$-dimensional arithmetic progressions following the notation of Fox, Xu, Zhou~\cite{fox2024discrepancy}. Here, the universe is the set of all integer points inside an axis-aligned, $d$-dimensional box. In particular, given positive integers $N_1, ..., N_d$, define the vector $\mathbf{N} \coloneqq (N_1, \ldots, N_d)$, which will represent the side lengths of the box in each dimension. Then we have $\Omega_{\mathbf{N}} \eqdef [N_1] \times \cdots \times [N_d]$. Note that the size of $\Omega_{\mathbf{N}}$ is $|\Omega_{\mathbf{N}}| = N_1 \cdots N_d$. The set system of arithmetic progressions in $\Omega_{\vec{N}}$, denoted $\AA_{\mathbf{N}}$, contains all sets of the form $\Omega_{\mathbf{N}} \cap \mathrm{AP}_d(\mathbf{a}, \mathbf{b},\ell)$, where 
\begin{equation}\label{eq:apd}
    \mathrm{AP}_d(\mathbf{a}, \mathbf{b},\ell) \eqdef \{\mathbf{a} + i\mathbf{b}: i = 0, \ldots, \ell-1\},
\end{equation}
and $\mathbf{a}$ and $\mathbf{b}$ are vectors in $\Z^d$ and $\ell$ is a positive integer. This matches the one-dimensional definition given in equation~\eqref{eq:ap}. 

Next, we define a function which bounds the discrepancy of the set system $(\Omega_{\mathbf{N}}, \AA_{\mathbf{N}})$. Let $f: \Z^d \rightarrow \R$ be
\begin{equation}\label{eq:ub}
    f\left(\mathbf{N}\right) \eqdef \max_{I \subseteq [d]} \left(\prod_{i \in I} N_i\right)^{\frac{1}{2|I| + 2}},
\end{equation}
where the empty product is equal to one by definition. When $d = 1$, we have $f(N_1) = N_1^{1/4}$ which is asymptotically the upper and lower bound on $\AA_N$ as we have seen in equations~\eqref{eq:rothlb} and~\eqref{eq:matousekub}.

Valk\'{o}~\cite{valko2002discrepancy} considered the cube $\Omega = [N]^d$ and showed that 
\[f(\textbf{N}) = N^{\frac{d}{2d + 2}} \lesssim_d \disc\left(\AA_{\mathbf{N}}\right) \lesssim_d N^{\frac{d}{2d + 2}}\left(\log N\right)^{5/2}.\] 
Here, the notation $A \lesssim_d B$ means that there exists a constant $C_d$ that only depends on the dimension $d$ such that $A \le C_d B$. Analogously, $A\gtrsim_d B$ is equivalent to $B\lesssim_d A$.

Later, Fox, Xu, Zhou~\cite{fox2024discrepancy} removed the logarithmic term from Valk\'{o}'s upper bound, and considered general $d$-dimensional boxes, showing the following bounds on $\disc\left(\AA_{\mathbf{N}}\right)$.
\begin{theorem}{\cite[Theorem 1.3]{fox2024discrepancy}}\label{thm:FXZ}
    For any positive integer $d$ and vector $\mathbf{N} = \left(N_1, \ldots, N_d\right)$, where each $N_i$ is an integer greater than $1$, let $\AA_{\mathbf{N}}$ be the family of all arithmetic progression defined on the universe $\Omega_{\mathbf{N}} $. Then the discrepancy of $\AA_{\mathbf{N}}$ is bound by
    % \begin{equation}\label{eq:FXZ}
    %     c\max_{I \subseteq [d]}\left(\prod_{i \in I} N_i\right)^{\frac{1}{2|I| + 2}}
    %     \le
    %     \disc(\AA_{\mathbf{N}}) \le C\frac{\log |\Omega|}{\log \log |\Omega|} 
    %     \max_{I \subseteq [d]}\left(\prod_{i \in I} N_i\right)^{\frac{1}{2|I| + 2}},
    % \end{equation}
    \begin{equation}\label{eq:FXZ}
        f\left(\mathbf{N}\right) \lesssim_d
        \disc\left(\AA_{\mathbf{N}}\right) \lesssim_d
        \frac{\log |\Omega_{\mathbf{N}}|}{\log \log |\Omega_{\mathbf{N}}|} \cdot  f\left(\mathbf{N}\right).
    \end{equation}
    % \begin{equation}\label{eq:FXZ}
    %     f\left(\mathbf{N}\right) \lesssim_d
    %     \disc\left(\AA_{\mathbf{N}}\right) \lesssim_d
    %     \frac{\log N}{\log \log N} f\left(\mathbf{N}\right).
    % \end{equation}
\end{theorem}
Note that a weaker upper bound of $\left(\log |\Omega_{\mathbf{N}}|\right)\cdot f\left(\mathbf{N}\right)$ can be achieved using standard partial coloring methods~\cite{matousek2009geometric}. The improvement by a $\log \log |\Omega_{\mathbf{N}}|$ factor relies on Fox, Xu, Zhou's upper bound for $[N]^d$, which itself relies on a sophisticated argument involving techniques from the geometry of numbers.% Further, this upper bound is non-constructive as the proof relies upon an entropy-based method similar to the one used by Matou\v{s}ek and Spencer~\cite{matouvsek1996discrepancy} to prove the upper bound on the discrepancy of arithmetic progression in one-dimension (equation~\eqref{eq:matousekub}) as well as Spencer's foundational result bounding the discrepancy of all set systems~\cite{spencer1985six}. 

In this work, one of our main results, \Cref{thm:main}, is a tighter upper bound on the discrepancy of arithmetic progressions in $d$-dimensional boxes. 
\begin{restatable}[APs in Boxes]{theorem}{main}
\label{thm:main}%
    For any positive integer $d$ and $\mathbf{N} = \left(N_1, \ldots, N_d\right)$, where each $N_i$ is an integer greater than $1$, let $\AA_{\mathbf{N}}$ be the family of all arithmetic progression defined on the universe $\Omega_{\mathbf{N}} $. The discrepancy of $\AA_{\mathbf{N}}$ is bounded above as 
    \begin{equation}\label{eq:main}
        \disc\left(\AA_{\mathbf{N}}\right) \lesssim_d
        \sqrt{\log |\Omega_{\mathbf{N}}|} \cdot f\left(\mathbf{N}\right).
    \end{equation}
    Further, the upper bound is constructive, i.e., there exists a randomized algorithm which computes a coloring $\chi$ in time polynomial in $|\Omega_{\mathbf{N}}|$ such that, with  high probability, $\disc\left(\AA_{\mathbf{N}}, \chi\right) \lesssim \sqrt{\log |\Omega_{\mathbf{N}}|}\cdot f(\mathbf{N})$.
\end{restatable}
%\main* % Leaving this here so I don't forget how to call the theorem again
Unlike Theorem~\ref{thm:FXZ}, Theorem~\ref{thm:main} uses the connection between discrepancy and the $\gamma_2$ factorization norm due to Matou\v{s}ek, Nikolov, and Talwar~\cite{matouvsek2020factorization}, rather than the partial coloring technique. 
Instead of the delicate number theoretic arguments used by Fox, Xu, and Zhou, our proof uses only simple combinatorial arguments, and properties of factorization norms.

As had Fox, Xu, Zhou, we conjecture that the lower bound in equation~\eqref{eq:FXZ} is tight. Unfortunately, there seems to be no way to remove the final $\sqrt{\log |\Omega_{\mathbf{N}}|}$ factor using our methods. It is conceivable that partial coloring arguments --- even more sophisticated than the one used by Fox, Xu, Zhou~\cite{fox2024discrepancy} --- could give a tight bound.

In addition to arithmetic progressions in $d$-dimension axis-aligned boxes, we can generalize our upper  bounds to arithmetic progressions in \emph{any} $d$-dimensional convex body. First, we will need to extend our definition of $f$ from equation~\eqref{eq:ub} in order to encapsulate these new structures. Let $K$ be a $d$-dimensional convex body (i.e., a closed bounded convex set with non-empty interior) and $t$ a scalar.  Recall that $K-K$, i.e., the Minkowski sum of $K$ and $-K$, is defined as $\{\mathbf{x}-\mathbf{y}: \mathbf{x}, \mathbf{y} \in K\}$. Then define
\begin{equation}\label{eq:ub-general}
    \zeta_{K-K}(t) \eqdef |\Z^d \cap t(K-K)|. % = |\{\mathbf{x} \in \Z^d: \|\mathbf{x}\|_K \le t\}|
\end{equation}
to be the number of integer points inside $t(K-K)$. Further define 
\begin{equation}\label{eq:ub-body}
    f(K) \coloneqq \sqrt{s^*}\mbox{ where }s^* = \inf\left\{s: s \ge \zeta_{K-K}\left(\frac{1}{s}\right)\right\}.
\end{equation}
Note, that when we restrict $K$ to be the $d$-dimensional box $[1, N_1]\times\cdots\times [1, N_d]$, we have $K-K=[-N_1+1, N_1-1] \times \cdots \times [-N_d+1,N_d-1]$, and thus
\[
\zeta_{K-K}(t) = 
\prod_{i=1}^d \left(1 + 2\floor{t (N_i-1)}\right)
\asymp_d \max_{I\subseteq [d]}\left(t^{|I|} \prod_{i \in I} N_i\right),
\]
where $A\asymp_d B$ is shorthand for  $A \lesssim_d B$ and $B\lesssim_d A$ holding simultaneously.
In the proof of Lemma~\ref{lem:gamma2-map-ub} (see equation~\eqref{eq:prod-s}) we show that $s=f(\mathbf{N})^2$ is the unique value satisfying
\(
s = \max_{I\subseteq [d]}\left(\frac{1}{s^{|I|}} \prod_{i \in I} N_i\right),
\)
and thus $f(K) \asymp_d f(\mathbf{N})$ in the special case where $K$ is an axis-aligned box. 

Similarly to~\Cref{thm:main}, \Cref{thm:generalbodiesthm} below bounds the discrepancy of arithmetic sequences in general $d$-dimensional convex bodies. 
\begin{restatable}[APs in Convex Bodies]{theorem}{generalbodiesthm}
\label{thm:generalbodiesthm}%
    Let $K$ be any $d$-dimensional convex body, $\mathbf{v}\in \R^d$ be a vector, and let $\Omega_{\mathbf{v}+K}$ be all the integer points in $\mathbf{v}+K$. If $\AA_{\mathbf{v} + K}$ is  the family of all arithmetic progression defined on the universe $\Omega_{\mathbf{v} + K}$, then
    \begin{equation}\label{eq:generalbodies}
        f(K) \lesssim_d \sup_{\mathbf{v}\in \R^d} \disc\left(\AA_{\mathbf{v} + K}\right) \lesssim_d
        \sqrt{\log (1+|\Omega_{\mathbf{v} + K}|)}\cdot f\left(K\right).
    \end{equation}
    where $f$ is defined in equation~\eqref{eq:ub-body}. 

    Moreover, if $K=-K$, i.e., $K$ is symmetric around the origin, then for $\AA_K \eqdef \AA_{\vec{0} + K}$,
    \begin{equation}\label{eq:generalbodies-sym}
        f(K) \lesssim_d \disc\left(\AA_{K}\right) \lesssim_d
        \sqrt{\log (1+|\Omega_K|)}\cdot f\left(K\right).
    \end{equation}

\end{restatable}

We note here that our proof of  \Cref{thm:generalbodiesthm} is not constructive, in the sense that we cannot, at present, guarantee an algorithm that finds a coloring achieving the claimed bound in time polynomial in the number of integer points in $K$. In addition to technical issues, like how the convex body $K$ would be given to an algorithm, and how the integer points inside it can be enumerated, this is also due to our reliance on a result of Banaszczyk~\cite{bana12} that presently has no algorithmic counterpart. This is the same reason why the best known bound for the discrepancy of axis-aligned boxes~\cite{nikolov-boxes}, and the best bounds for the Steinitz problem~\cite{bana12} are not constructive. 

Theorem~\ref{thm:generalbodiesthm} shows how the discrepancy of arithmetic progressions inside a convex body $K$ can be derived from the geometric properties of $K$. To illustrate its use, we state a simple corollary that determines how $\disc(\AA_{rK})$ grows as $r\to \infty$. 

\begin{corollary}
    Let $K$ be a $d$-dimensional convex body of volume $1$. Define $\AA_{\vec{v} + K}$ as in Theorem~\ref{thm:generalbodiesthm}. Then,
    \[
    \limsup_{r\to\infty} \frac{\sup_{\vec{v} \in \R^d} \disc(\AA_{\vec{v}+rK})}{r^{\frac{d}{2(d+1)}}\sqrt{\log r}} \lesssim_d 1; \hspace{2em} \liminf_{r\to\infty} \frac{\sup_{\vec{v} \in \R^d} \disc(\AA_{\vec{v}+rK})}{r^{\frac{d}{2(d+1)}}} \gtrsim_d 1.
    \]
    If, in addition, $K$ is centrally symmetric, then 
    \[\limsup_{r\to\infty} \frac{\disc\left(\AA_{rK}\right)}{r^{\frac{d}{2(d+1)}}\sqrt{\log r}} \lesssim_d 1;\hspace{2em} \liminf_{r\rightarrow\infty}\frac{\disc\left(\AA_{rK}\right)}{r^{\frac{d}{2(d+1)}}} \gtrsim_d 1.\]
\end{corollary}
\begin{proof}
    Let $\vol_d(\cdot)$ be the $d$-dimensional Lebesgue measure. Then, since $K-K$ is convex, and therefore, Jordan measurable, we have~\cite[Section 7.2]{Gruber-convgeom}
    \begin{equation}\label{eq:zeta-limit}
    %\lim_{r\to \infty} \frac{|\Z^d \cap (\vec{v} + rK)|}{r^d} = \vol_d(K) = 1;
    %\hspace{2.5em}
    \lim_{r\to \infty} \frac{\zeta_{K-K}(r)}{r^d} = \vol_d(K-K).
    \end{equation}
    By the the Brunn-Minkowski and Rogers-Shephard inequalities~\cite{RogersShephard57},  we have $2^d \le \vol_d(K-K) \le 4^d$. Therefore, for abny $\vec{v} \in \R^d$, and any large enough $r$ we can assume that $|\Omega_{\vec{v}+rK}| \le \zeta_{K-K}(r) \asymp r^d$ (see Lemma~\ref{lem:zeta-maxshift} for the first inequality). Moreover, for a suitable constant $C_d$ depending only on $d$, and for all large enough $r$, choosing $s = (C_dr^d)^{\frac{1}{d+1}}$ gives us
    \[
    \zeta_{K-K}\left(\frac{r}{s}\right) \le \frac{C_d r^d}{s^d} = s.
    \]
    Therefore, $f(rK) \lesssim_d r^{\frac{d}{2(d+1)}}$. Similarly, for a suitable constant $c_d$ depending only on $d$, and all large enough $r$, choosing $s < (c_dr^d)^{\frac{1}{d+1}}$ gives us
    \[
    \zeta_{K-K}\left(\frac{r}{s}\right) \ge \frac{c_d r^d}{s^d} > s,
    \]
    implying that $f(rK) \gtrsim_d r^{\frac{d}{2(d+1)}}$, as well. So, for all large enough $r$, we have the estimate $f(rK) \asymp_d r^{\frac{d}{2(d+1)}}$, and the corollary follows from~\Cref{thm:generalbodiesthm}.
\end{proof}

More refined bounds on the growth rate of $\zeta_{K-K}(t)$ than the limit~\eqref{eq:zeta-limit} would automatically lead to sharper bounds on the discrepancy.

