\section{Background}
Our proof will require several facts about factorization norms, which we will recount in~\Cref{sec:gamma2norm}, as well a variant of discrepancy which we define now.   

First, recall the definition of the discrepancy of $(\Omega, \mathcal{S})$ given in equation~\ref{eq:disc}
\begin{equation*}
    \disc\left(\mathcal{S}\right) = \min_{\chi: \Omega \to \{-1, 1\}}\max_{S \in \SS}\left|\sum_{\omega \in S}\chi(\omega)\right|.
\end{equation*}
Note that we can give an equivalent definition of $\disc\left(\mathcal{S}\right)$ with respect to the \emph{incidence} matrix $\mathbf{A}_{\mathcal{S}}$ of $(\Omega, \mathcal{S})$. Taking $\Omega = [n]$ and $\mathcal{S} = \{S_1, \ldots, S_m\}$ for simplicity, $\mathbf{A}_{\mathcal{S}}$ is the $m \times n$ zero-one matrix whose $(i,j)$ entry is equal to one if and only if $j \in S_i$ and is zero otherwise. It follows that $\disc(\mathcal{S})$ is equal to 
\begin{equation}\label{eq:disc-alt}
    \disc\left(\mathbf{A}_{\mathcal{S}}\right) = \min_{\mathbf{x} \in \{-1, +1\}^{n}}\left\|\mathbf{A}_{\mathcal{S}}\mathbf{x}\right\|_{\infty}.
\end{equation}

Next, let $\sigma: \Omega \to [|\Omega|]$ be a bijection. We think of $\sigma$ as giving an ordering to $\Omega$. The \emph{prefix discrepancy} of $\mathcal{S}$ with respect to $\sigma$ as is defined as
\[
\pdisc(\mathcal{S},\sigma) \eqdef
\min_{\chi:\Omega\to\{-1,+1\}}
\max_{j = 1}^{n}
\max_{S \in \mathcal{S}} \left|\sum_{\omega \in S: \sigma(\omega) \le j} \chi(e)\right|.
\]
Again $\pdisc(\mathcal{S},\sigma)$ has an equivalent definition $\pdisc\left(\mathbf{A}_{\mathcal{S}}\right)$ with respect to the incidence matrix $\mathbf{A}_{\mathcal{S}}$ of $\mathcal{S}$ with columns ordered according to $\sigma$: the first column indicates the incidences of $\sigma^{-1}(1)$, the second of $\sigma^{-1}(2)$, etc. Next, we can define the \emph{prefix discrepancy} of $\mathbf{A}_{\mathcal{S}}$ by 
\begin{equation}\label{eq:pdisc}
    \pdisc\left(\mathbf{A}_{\mathcal{S}}\right) \eqdef \min_{\mathbf{x} \in \{-1,+1\}^n} \max_{j = 1}^{n} \left\|\sum_{i=1}^j x_i \mathbf{a}_i\right\|_\infty,
\end{equation}
where $\mathbf{a}_i$ is the $i$-th column of $\mathbf{A}_{\mathcal{S}}$. 

\subsection{\texorpdfstring{$\gamma_2$}{gamma-2} Norm}\label{sec:gamma2norm}
Recall that the factorization norm of a matrix $\mathbf{A}$, denoted  $\gamma_2(\mathbf{A})$, equals 
\[\gamma_2\left(\mathbf{A}\right) = \inf\{\|\mathbf{L}\|_{2\to\infty} \|\mathbf{R}\|_{1\to 2}: \mathbf{LR} = \mathbf{A}\}.\]
Here, $\|\mathbf{L}\|_{2\to\infty}$ is the $\ell_2 \to \ell_\infty$ operator norm, and equals the maximum $\ell_2$ norm of a row of $\vec{L}$, and $\|\vec{R}\|_{1\to 2}$ is the $\ell_1 \to \ell_2$ operator norm, and equals the maximum $\ell_2$ norm of a column of $\vec{R}$.

We extend this definition to set systems by writing $\gamma_2(\SS) = \gamma_2\left(\mathbf{A}_{\mathcal{S}}\right)$, where $\mathbf{A}_{\mathcal{S}}$ is, as above, the incidence matrix of $\SS$. Notice that $\gamma_2(\mathcal{S})$ is invariant under isomorphism and, similarly, $\gamma_2\left(\mathbf{A}_{\mathcal{S}}\right)$ is invariant under permuting the rows or columns of $\mathbf{A}_{\mathcal{S}}$.

We recall a few basic properties of the $\gamma_2$ norm. See Section~7~of~\cite{matouvsek2020factorization} for the proofs of these properties.

\begin{lemma}{\cite{matouvsek2020factorization}.}\label{lem:gamma2}
    The $\gamma_2$ norm satisfies the following properties.
    \begin{itemize} 
        \item (Triangle Inequality) For any matrices $\vec{A}$ and $\vec{B}$ of equal dimensions,
        \begin{equation}\label{eq:gamma2-triangle}
            \gamma_2\left(\mathbf{A} + \mathbf{B}\right) \le \gamma_2\left(\mathbf{A}\right) + \gamma_2\left(\mathbf{B}\right)
        \end{equation}
        \item (Union Property) For any two set systems $\SS$ and $\SS'$ on the same universe,
        \begin{equation}\label{eq:gamma2-union}
            \gamma_2(\SS \cup \SS')^2 \le \gamma_2(\SS)^2 + \gamma_2(\SS')^2.
        \end{equation}
        \item (Degree Bound) If $\mathcal{S}$ is a set system such that each element of the universe is contained in at most $t$ sets, then 
        \begin{equation}\label{eq:gamma2-degreebound}
            \gamma_2(\mathcal{S}) \le \sqrt{t}.
        \end{equation}
        \item (Size Bound) If all sets in a set system $\mathcal{S}$ have size at most $t$, then 
        \begin{equation}\label{eq:gamma2-sizebound}
            \gamma_2(\mathcal{S}) \le \sqrt{t}.
        \end{equation}
        \item (Disjoint Supports) If $\mathcal{S}$ and $\mathcal{S}'$ are set systems on disjoint universes, then 
        \begin{equation}
            \gamma_2\left(\mathcal{S} \cup \mathcal{S}'\right) = \max\left(\gamma_2\left(\mathcal{S}\right), \gamma_2\left(\mathcal{S}'\right)\right).
        \end{equation}
    \end{itemize}
\end{lemma}

We also state a property that is an immediate consequence of the triangle inequality when applied to set systems. A slightly less general variant was also stated as Property E in Section 7 of~\cite{matouvsek2020factorization}.
\begin{lemma}\label{lem:triangle-ss}
Suppose that $\SS$, $\SS_1$, $\SS_2$ are set systems on the same universe, so that each set $S$ in $\SS$ can be written as the disjoint union of sets $S_1 \in \SS_1$ and $S_2 \in \SS_2$. Then $\gamma_2(\SS) \le \gamma_2(\SS_1) + \gamma_2(\SS_2)$.

Similarly, suppose each set $S$ in $\SS$ can be written as $S_1 \setminus S_2$ where $S_1 \in \SS_1$, $S_2 \in \SS_2$, and $S_2 \subseteq S_1$. Then $\gamma_2(\SS) \le \gamma_2(\SS_1) + \gamma_2(\SS_2)$.
\end{lemma}
\begin{proof}
    Let $\vec{A},\vec{A}_1,\vec{A}_2$ be the incidence matrices of, respectively, $\SS, \SS_1,\SS_2$. Under the first assumption, we can re-arrange, and, if necessary, duplicate the rows of the matrices so that $\vec{A}=\vec{A}_1+\vec{A}_2$, and then the lemma follows from the triangle inequality property of $\gamma_2$, and the obvious property that duplicating and re-arranging rows does not change the $\gamma_2$ norm of a matrix. The proof under the second assumption is analogous, but we get the equation $\vec{A}=\vec{A}_1-\vec{A}_2$ instead.
\end{proof}

The relevance of the $\gamma_2$ norm to discrepancy theory stems from the following result, which is a constructive version of Theorem 3.4~from~\cite{matouvsek2020factorization}. 
\begin{theorem}[\cite{GSwalk}]\label{thm:gswalk}
    There exists a randomized polynomial time algorithm that, for any $m\times n$ matrix $\vec{A}$ with rational entries, computes in time polynomial in $m,n$, and the bit complexity of $\vec{A}$ a coloring $\vec{x} \in \{-1,+1\}^n$ such that, with high probability, 
    \[
    \|\vec{A}\vec{x}\|_\infty \lesssim \sqrt{\log 2m}\, \gamma_2(\vec{A}).
    \]
    In particular, there exists a randomized algorithm that, for any set system $(\Omega,\SS)$, computes in time polynomial in $|\Omega|$ and $|\SS|$, a coloring $\chi:\Omega\to\{-1,+1\}$ so that, with high probability,
    \[
    \disc(\SS,\chi) \lesssim \sqrt{\log 2|\SS|}\, \gamma_2(\vec{A}).
    \]
\end{theorem}
It is worth noting here that $\gamma_2(\vec{A})$ and $\gamma_2(\SS)$ also implies lower bounds on the hereditary discrepancy of $\vec{A}$ and $\SS$, respectively~\cite{matouvsek2020factorization}. We will not use this fact here.

We also need the following result of Banaszczyk.%{Lemma 2.5}
\begin{theorem}{\cite[Lemma 2.5]{bana12}}\label{thm:bana-ss}
    Suppose $\mathbf{v}_1, \ldots, \mathbf{v}_n\in \R^m$ satisfy $\|\mathbf{v}_i\|_2 \le 1$ for all $i \in \{1, \ldots, n\}$.
    For any closed symmetric convex set $K\subseteq \R^m$ with Gaussian measure at least $1-\frac{1}{2n}$, there exists a coloring $\mathbf{x} \in \{-1,+1\}^n$ such that, for each $j \in \{1, \ldots, n\}$, $\sum_{i = 1}^j x_i \mathbf{v}_i \in 5K$.
\end{theorem}

The following theorem is an easy consequence of Theorem~\ref{thm:bana-ss}, which is implicit in the second author's work on the discrepancy of boxes and polytopes~\cite{nikolov-boxes}. We include the short proof here.

\begin{theorem}\label{thm:gamma2-pdisc}
    For any $m\times n$ matrix $\mathbf{A}$, 
    \[
    \pdisc\left(\mathbf{A}\right) \lesssim \sqrt{\log(2mn)} \,\gamma_2\left(\mathbf{A}\right).
    \]
    As a special case, for any set system $(\Omega, \mathcal{S})$, and any $\sigma:\Omega \to [|\Omega|]$
    \[
    \pdisc(\mathcal{S},\sigma) \lesssim \sqrt{\log(2mn)} \, \gamma_2(\mathcal{S}).
    \]    
\end{theorem}
\begin{proof}
    Suppose that the factorization $\mathbf{A} = \mathbf{L}\mathbf{R}$, where $\mathbf{L}$ is $m\times k$ and $\mathbf{R}$ is $k\times n$, achieves $\gamma_2(\mathbf{A})$. In particular, suppose that $\|\mathbf{L}\|_{2\to\infty} = \gamma_2(\mathbf{A})$ and $\|\mathbf{R}\|_{1\to 2} =1$. We can always make sure this is the case by multiplying $L$ by $\frac{\gamma_2(\mathbf{A})}{\|\mathbf{L}\|_{2\to\infty}}$ and $R$ by $\frac{\|\mathbf{L}\|_{2\to\infty}}{\gamma_2(\mathbf{A})} = \frac{1}{\|\mathbf{R}\|_{1\to 2}}$. 

    Now let $K$ be the convex body $K=\{\mathbf{y} \in \R^k: \|\mathbf{Ly}\|_\infty \le t\gamma_2(\mathbf{A})\}$, for a value of $t$ we will choose shortly. A standard calculation (see the proof of Theorem 3.4 of~\cite{matouvsek2020factorization}) shows that the Gaussian measure of $K$ is at least $(1-e^{-t^2/2})^m \ge 1-me^{-t^2/2}$, which is $1-\frac{1}{2n}$ for $t = \sqrt{2\ln(2mn)}$. We can then apply Theorem~\ref{thm:bana-ss} to $K$ and the column vectors $\mathbf{r}_1, \ldots, \mathbf{r}_n$ of $\mathbf{R}$, and conclude that there is a $\mathbf{x}\in \{-1,+1\}^n$ such that, for each $j \in \{1, \ldots, n\}$,
    \begin{align*}
    \sum_{i=1}^j x_i \mathbf{r}_i \in 5K
    &\iff
    \left\|\sum_{i=1}^j x_i \mathbf{L}\mathbf{r}_i\right\|_\infty \le 5\sqrt{2\ln(2mn)}\,\gamma_2(\mathbf{A})\\
    &\iff 
    \left\|\sum_{i=1}^j x_i \mathbf{a}_i\right\|_\infty \le 5\sqrt{2\ln(2mn)}\,\gamma_2(\mathbf{A}).
    \end{align*}
    Above, we first used the definition of $K$, and next we used the property $\mathbf{LR} = \mathbf{A}$. Since $j \in \{1, \ldots, n\}$ was arbitrary, this completes the proof.
    \end{proof}

We remark here that there is no known polynomial time algorithm to find the colorings guaranteed by Theorem~\ref{thm:gamma2-pdisc}.

\subsection{A Few More Facts}
Our proof will also require a simple counting lemma and an observation about the function $f$ defined in equation~\eqref{eq:ub} for $d$-dimensional axis-aligned boxes. 

Let us first introduce the concept of a \emph{maximal arithmetic progression}. We say that an arithmetic progression $\AP_d(\mathbf{a}, \mathbf{b},\ell)$ is \emph{maximal} inside $\Omega_{\mathbf{N}}$ for $\mathbf{N} = (N_1, \ldots, N_d)$, if $\mathbf{a} + \ell\cdot \mathbf{b}$ and $\mathbf{a} - \mathbf{b}$ are both not in $\Omega_{\mathbf{N}}$, i.e., the arithmetic progression is maximal if it cannot be extended in either direction while staying inside $\Omega_{\mathbf{N}}$. Notice that, for any $\mathbf{a}$ and $\mathbf{b}$ in $\Z^d$ there is at most one maximal $\AP_d(\mathbf{a}, \mathbf{b}, \ell)$. We use the notation $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ for the unique maximal arithmetic progression with step $\mathbf{b}$ containing $\mathbf{a}$. Note that we don't require $\mathbf{a}$ to be an endpoint of the $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$. Equivalently, $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ is the intersection of the residue class of $\mathbf{a} \pmod{\mathbf{b}}$ with $\Omega_{\mathbf{N}}$. This alternative definition also makes clear that, for a fixed $\mathbf{b}$, the sets $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ partition $\Omega_{\mathbf{N}}$. 

The following is stated in the proof of Lemma 2.3 of Fox, Xu, Zhou~\cite{fox2024discrepancy}.
\begin{lemma}\label{lem:large-sets}
    For every $s \ge 2$, the quantity
    \[
    \left|\left\{\mathbf{b} \in \Z^d: \max_{\mathbf{a} \in \Z^d} |\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})| \ge s\right\}\right|
    \] is bounded above by 
    \[
    \prod_{i=1}^d \left(\frac{4N_i}{s} + 1\right)
    %\le 4^d \sum_{S \subseteq [d]} s^{-|S|}\prod_{i \in S}N_i
    %\lesssim_d \max_{k=1}^d \max_{S \subseteq [d]: |S| = k}\prod_{i \in S}\left(\frac{N_i}{s}\right).
    \lesssim_d \max_{I \subseteq [d]}\prod_{i \in I}\left(\frac{N_i}{s}\right).
    \]
\end{lemma}

Next, we consider the function $f$ from equation~\eqref{eq:ub}, and characterize it in a way that is often easier to work with. 
\begin{lemma}\label{lm:f-alt}
    Let $f: \Z^d \rightarrow \R$ be 
    \begin{equation*}
        f\left(\mathbf{N}\right) \eqdef \max_{I \subseteq [d]} \left(\prod_{i \in I} N_i\right)^{\frac{1}{2|I| + 2}},
    \end{equation*}
    as defined in equation~\eqref{eq:ub}.  Assume $\mathbf{N} = (N_1, ..., N_d)$ is such that  $N_1 \ge N_2 \ge \ldots \ge N_d$. Let $k^*$ be the smallest value of $k \in [d-1]$ for which $N_{k+1} < \left(\prod_{i = 1}^k N_i\right)^{\frac{1}{k+1}}$, or $k^* = d$ if no such value exists. Then 
    \[f\left(\mathbf{N}\right)=\left(\prod_{i = 1}^{k^*}N_i\right)^{\frac{1}{2k^*+2}}.\]
   % \begin{equation}\label{eq:f-alt}
   %     f\left(\mathbf{N}\right) = \begin{cases}
   %     N_1^{\frac{1}{4}} &\mbox{if } N_2 < N_1^{\frac{1}{2}}\\
   %     \left(N_1N_2\right)^{\frac{1}{6}} &\mbox{if } N_3 < \left(N_1 N_2\right)^{\frac{1}{3}}\\
   %     &\vdots\\
   %     \left(\prod_{i=1}^{k}N_i\right)^{\frac{1}{2k + 2}}&\mbox{if } N_{k+1} < \left(\prod_{i=1}^{k}N_i\right)^{\frac{1}{k + 1}}\\
   %     &\vdots\\
   %     \left(\prod_{i=1}^{d-1}N_i\right)^{\frac{1}{2d}}&\mbox{if } N_{d} < %\left(\prod_{i=1}^{d-1}N_i\right)^{\frac{1}{d}}\\
   %     \left(\prod_{i=1}^{d}N_i\right)^{\frac{1}{2d + 2}} &\mbox{otherwise}
   %     \end{cases}.
   % \end{equation}
\end{lemma}
\begin{proof}
    Since $N_1 \ge N_2 \ge \ldots \ge N_d$, 
    \begin{equation}\label{eq:ub-simplified}
        f\left(\mathbf{N}\right)^2 = \max_{I \subseteq [d]} \left(\prod_{i \in I} N_i\right)^{\frac{1}{|I| + 1}}
        =\max_{k = 1}^d \left(\prod_{i=1}^k N_i\right)^{\frac{1}{k+1}}.
    \end{equation}
    Suppose that $k^*$ achieves the max on the right hand side of equation~\eqref{eq:ub-simplified}. We need to show that this $k^*$ is the smallest  integer $k \in [d-1]$ for which we have \(\left(\prod_{i=1}^k N_i\right)^{\frac{1}{k+1}} > N_{k+1},\) or $d$ if there is no such integer.

    For any two integers $k$ and $\ell$ in $[d]$ such that $k < \ell$, we have
    \[
    \left(\prod_{i=1}^k N_i\right)^{\frac{1}{k+1}}
    > \left(\prod_{i=1}^\ell N_i\right)^{\frac{1}{\ell+1}}
    \iff
    \left(\prod_{i=1}^k N_i\right)^{\frac{1}{k+1}}
    > 
    \left(\prod_{i=k+1}^\ell N_i\right)^{\frac{1}{\ell-k}}.
    \]
    Notice that $\left(\prod_{i=k+1}^\ell N_i\right)^{\frac{1}{\ell-k}}$ is the geometric mean of $N_{k+1} \ge \ldots \ge N_\ell$, and is, therefore, non-increasing with $\ell$. This means that the inequality on the right hand size holds for every $\ell > k$ as long as it holds for $\ell=k+1$. From this, we obtain the characterization of $k^*$ as required.
\end{proof}

\section{Discrepancy Upper Bound}
We are now ready to prove the main theorem, restated below.% for ease of use. 
\main*
The structure of the proof is as follows. Let $\AA_{\mathbf{N}}$ be the set of arithmetic progressions and $\MM_{\mathbf{N}}$ be the corresponding set of maximal arithmetic progressions. We first show $\gamma_2\left(\MM_{\mathbf{N}}\right) \leq f(\mathbf{N})$ in~\Cref{lem:gamma2-map-ub} of Section~\ref{sec:gamma2-bound-map}. Roughly we do so by defining two set systems: $\MM_{> s}$, and $\MM_{\le s}$. $\MM_{> s}$ consists of all maximal APs $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ for which $|\MAP_{\mathbf{N}}(\mathbf{a}', \mathbf{b})| > s$ for at least one $\mathbf{a}'$ (not necessarily equal to $\mathbf{a}$). Lemma~\ref{lem:large-sets} allows us to bound the degree of  $\MM_{> s}$. Then $\MM_{\le s}$ consists of all $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ for which $|\MAP_{\mathbf{N}}(a',b)| \le s$ for all $a'$. Here every set has size at most $s$. Since $\MM_{\mathbf{N}} = \MM_{> s} \cup \MM_{\le s}$, using the $\gamma_2$ properties stated in Section~\ref{sec:gamma2norm} we can bound $\gamma_2\left(\MM_{\mathbf{N}}\right)$ by bounding $\gamma_2\left(\MM_{> s}\right)$ and $\gamma_2\left(\MM_{\le s}\right)$. 

This alone is sufficient for a proof of the discrepancy upper bound in~\Cref{thm:main}, given in Section~\ref{sec:nonconstructive}. We argue that there is an ordering $\sigma:\Omega_{\vec{N}} \to [|\Omega_{\vec{N}}|]$ such that $\disc(\AA_{\mathbf{N}}) \lesssim \pdisc(\MM_{\mathbf{N}},\sigma)$. This holds for the $\sigma$ given by the lexicographic order: $\sigma(x) < \sigma(y)$ if, for the smallest coordinate index $i$ for which $x_i \neq y_i$, we have $x_i < y_i$.

We also prove a tight upper bound $\gamma_2\left(\AA_{\mathbf{N}}\right)\lesssim f(\mathbf{N})$ on the $\gamma_2$ norm of arithmetic progressions in~\Cref{lem:gamma2-ap-ub} of Section~\ref{sec:gamma2-bound}. This gives another proof of the upper bound in~\Cref{thm:main}, and implies an efficient randomized algorithm to compute a coloring achieving the discrepancy upper bound via~\Cref{thm:gswalk}.

\subsection{Maximal Arithmetic Progressions}\label{sec:gamma2-bound-map}

As in the outline above, we first prove an upper bound on the set system $\MM_{\vec{N}}$ of all maximal APs.

\begin{lemma}\label{lem:gamma2-map-ub}
    Let $\MM_{\mathbf{N}} = \{\MAP_{\mathbf{N}}\left(\mathbf{a},\mathbf{b}\right): \mathbf{a},\mathbf{b}\in \Z^d\}$ be the set of all maximal APs in $\Omega_{\mathbf{N}}$. Then 
    \(\gamma_2(\MM_{\mathbf{N}}) \lesssim_d f\left(\mathbf{N}\right).\)
\end{lemma}
\begin{proof}
Let $s \ge 1$ be a parameter to be determined later.
Let $\MM_{\le s}$ consist of all $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ for which $|\MAP_{\mathbf{N}}(\mathbf{a'},\mathbf{b})| \le s$ for all $\mathbf{a}' \in \Z^d$. Since all sets in $\MM_{\le s}$ have cardinality at most $s$, the bound $\gamma_2(\MM_{\le s}) \le \sqrt{s}$ holds by the size bound of Lemma~\ref{lem:gamma2}.

Define the set $B$ as 
\[
B \eqdef \left\{\mathbf{b} \in \Z^d: \max_{\mathbf{a} \in \Z^d} |\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})| > s\right\}.
\]
Let $\MM_{> s} = \MM_{\mathbf{N}}\setminus \MM_{\le s}$, and notice that \[\MM_{> s} \eqdef \{\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b}): \mathbf{a} \in \Z^d, \mathbf{b} \in B\}.\] Recall that, for any $\mathbf{b}$, the sets $\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})$ partition $\Omega_{\mathbf{N}}$. Therefore, for any $\mathbf{b}$, $\MM_{\mathbf{N}}(\mathbf{b}) \eqdef \{\MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b}): \mathbf{a} \in \Z^d\}$ is a set system of disjoint sets, i.e., it has maximum degree one. It follows that the maximum degree of $\MM_{> s} = \bigcup_{b \in B} \MM_{\mathbf{N}}(b)$ is at most $|B|$, and, by the degree bound of Lemma~\ref{lem:gamma2}, and using Lemma~\ref{lem:large-sets},  we get
\[
\gamma_2(\MM_{> s}) \le
\sqrt{|B|} \lesssim_d\left(\max_{I \subseteq [d]}\prod_{i \in I}{\frac{N_i}{s}}\right)^{\frac12}.
\]
Since $\MM_{\mathbf{N}} = \MM_{\le s} \cup \MM_{> s}$, the union property of Lemma~\ref{lem:gamma2} gives us
\begin{equation}\label{eq:gamma2-mm}
\gamma_2(\MM_{\mathbf{N}})^2 \lesssim_d s + \max_{I \subseteq [d]}\prod_{i \in I}\frac{N_i}{s}.
\end{equation}
To get the final bound, we minimize the right hand side over $s$. Let us assume, without loss of generality, that $N_1 \ge \ldots \ge N_d$. We set $s \eqdef f(\mathbf{N})^2$. By~\Cref{lm:f-alt}, let $k^*$ be the smallest value of $k \in [d-1]$ for which $N_{k+1} < \left(\prod_{i = 1}^k N_i\right)^{\frac{1}{k+1}}$, or $k = d$ if no such value exists. Then, by Lemma~\ref{lm:f-alt},
\[
s = f\left(\mathbf{N}\right)^2 = \left(\prod_{i=1}^{k^*} N_i\right)^{\frac{1}{k^* + 1}}.
\]
Notice that
\begin{equation}\label{eq:prod-max}
 \max_{I \subseteq [d]} \prod_{i \in I}{\frac{N_i}{s}}
 = \max_{k=1}^d \prod_{i = 1}^k{\frac{N_i}{s}}.
% = \prod_{i = 1}^{k^*}{\frac{N_i}{s}},
\end{equation}
Clearly, for any value of $s$, the maximum on the right is achieved for a $k$ such that $N_k \ge s > N_{k+1}$, if one exists, or for $k=d$ otherwise. We claim that this is satisfied by $k = k^*$. First we show that $s \le N_{k^*}$. This is trivial if $k^* = 1$, since $s = N_1^{1/2} \le N_1$. Otherwise, by the definitions of $s$ and $k^*$, we have 
\[
\left(\frac{s^{k^*+1}}{N_{k^*}}\right)^{\frac{1}{k^*}} = \left(\prod_{i = 1}^{k^*-1}N_i\right)^{\frac{1}{k^*}} \le N_{k^*},
\]
which, after re-arranging, gives $s \le N_{k^*}$. Again, by the definition of $s$ and $k^*$, we have $s > N_{k^*+1}$ if $k^* < d$. Thus, we have shown that 
\begin{equation}\label{eq:prod-s}
   \max_{k=1}^d \prod_{i = 1}^k{\frac{N_i}{s}}
 = \prod_{i = 1}^{k^*}{\frac{N_i}{s}} = s^{-k^*}\prod_{i = 1}^{k^*}{N_i}=s. 
\end{equation}
Combining equations \eqref{eq:gamma2-mm}, \eqref{eq:prod-max}, and \eqref{eq:prod-s} gives us the desired result.
\end{proof}

\subsection{Upper Bound via Prefix Discrepancy}\label{sec:nonconstructive}

Here we prove the discrepancy upper bound part of~\Cref{thm:main}, with an argument that does not imply the constructive part. Formally, we show the following theorem.

\begin{theorem}\label{thm:main-ub}
    For any positive integer $d$ and vector $\mathbf{N} = \left(N_1, \ldots, N_d\right)$, where each $N_i$ is an integer greater than $1$, let $\AA_{\mathbf{N}}$ be the family of all arithmetic progression defined on the universe $\Omega_{\mathbf{N}} $. The discrepancy of $\AA_{\mathbf{N}}$ is bounded above as 
    \begin{equation*}%\label{eq:main}
        \disc\left(\AA_{\mathbf{N}}\right) \lesssim_d
        \sqrt{\log |\Omega_{\mathbf{N}}|} \cdot f\left(\mathbf{N}\right).
    \end{equation*}
\end{theorem}

While we don't need \Cref{thm:main-ub} to prove \Cref{thm:main}, we include its proof here because of its simplicity, and because we believe the technique of using prefix discrepancy to prove bounds on the discrepancy of set system is useful and may have further application. It is also the technique we use in proving the discrepancy upper bounds in Theorem~\ref{thm:generalbodiesthm}, and was previously used by Nikolov in his upper bound on the discrepancy of axis-aligned boxes~\cite{nikolov-boxes}.

Before we prove~\Cref{thm:main-ub}, we first establish a useful lemma. For the statement of the lemma, let $\preclex$ be the lexicographic order on $\Z^d$, i.e., $\vec{x} \preclex \vec{y}$ if $\vec{x} = \vec{y}$, or if $x_i < y_i$ holds for the smallest integer $i$ for which $x_i \neq y_i$. 

\begin{lemma}\label{lem:lex}
    For any arithmetic progression $\AP_d(\mathbf{a},\mathbf{b},\ell)$ in $\Z^d$, there exist $\vec{x}, \vec{y} \in \AP_d(\mathbf{a},\mathbf{b},\ell)$ so that
    \[
    \AP_d(\mathbf{a},\mathbf{b},\ell) = 
    \{\vec{a} + i \vec{b}: i \in \Z\} \cap \{\vec{z}: \vec{x} \preclex \vec{z}\preclex \vec{y}\}.
    \]
\end{lemma}
\begin{proof}
    Fix $\vec{a}$ and $\vec{b} \neq 0$ (the lemma is trivial for $\vec{b} = 0$), and let $k$ be the smallest integer such that $b_k \neq 0$. We will assume that $b_k > 0$. This is without loss of generality, since for $\vec{a}' \eqdef \mathbf{a} + (\ell-1)\vec{b}$ we have 
    \(
    \AP_d(\mathbf{a},\mathbf{b},\ell) = \AP_d(\mathbf{a}',-\mathbf{b},\ell),
    \)
    and 
    \(
    \{\vec{a} + i \vec{b}: i \in \Z\} = \{\vec{a} - i \vec{b}: i \in \Z\},
    \)
    and, therefore, we can replace $\vec{a}$ with $\mathbf{a}'$ and $\vec{b}$ with $-\vec{b}$.

    Let $\vec{a}' = \mathbf{a} + (\ell-1)\vec{b}$ as above. Note that 
    \[
    \AP_d(\mathbf{a},\mathbf{b},\ell)
    = 
    \{\vec{a} + i \vec{b}: i \in \Z, i \ge 0\} 
    \cap 
    \{\vec{a}' + i \vec{b}: i \in \Z, i \le 0\}.
    \]
    We claim that 
    \begin{equation}\label{eq:AP-repr-pref}
    \{\vec{a} + i \vec{b}: i \in \Z, i \ge 0\}  = 
    \{\vec{a} + i \vec{b}: i \in \Z\} \cap\{\vec{z}: \vec{a} \preclex \vec{z}\},
    \end{equation}
    and 
    \begin{equation}\label{eq:AP-repr-suf}
    \{\vec{a}' + i \vec{b}: i \in \Z, i \le 0\}  = 
    \{\vec{a} + i \vec{b}: i \in \Z\} \cap\{\vec{z}: \vec{z}\preclex \vec{a}'\},
    \end{equation}
    and then the theorem follows from these two equation after setting $\vec{x} \eqdef \vec{a}$ and $\vec{y} \eqdef \vec{a}'$.

    Let us first prove \eqref{eq:AP-repr-pref}. 
    Since $b_j = 0$ for $j < k$ and $b_k > 0$, we have that, for any $\vec{z} = \vec{a} + i \vec{b}$, $i \ge 0$ if and only if $a_k \le z_k$. Moreover any such $\vec{z}$ satisfies $z_j = a_j$ for all $j < k$. This means that $\vec{a} \preclex \vec{z}$ if and only if $i \ge 0$. 

    The proof of \eqref{eq:AP-repr-suf} is analogous. First note that $\{\vec{a} + i \vec{b}: i \in \Z\}=\{\vec{a}' + i \vec{b}: i \in \Z\}$. Then, for any $\vec{z} = \vec{a}'+ i \vec{b}$, $i \le 0$ if and only if $a'_k \ge z_k$. Moreover any such $\vec{z}$ satisfies $z_j = a'_j$ for all $j < k$. This means that $\vec{z} \preclex \vec{a}'$ if and only if $i \ge 0$. 
\end{proof}

In addition to the proof of~\Cref{thm:main-ub} below, we also use Lemma~\ref{lem:lex} in the proof of the upper bound in Theorem~\ref{thm:generalbodiesthm}.

\begin{proof}[Proof of~\Cref{thm:main-ub}]
    We claim that there exists a bijection $\sigma:\Omega_{\mathbf{N}} \to [|\Omega_{\mathbf{N}}|]$ for which $\disc(\AA_{\mathbf{N}}) \le 2 \pdisc(\MM_{\mathbf{N}}, \sigma)$. Once we establish this, \Cref{thm:main} follows from~\Cref{thm:gamma2-pdisc} and \Cref{lem:gamma2-map-ub}.

    Define $\sigma(\mathbf{x})$ to be the rank of $\mathbf{x}$ in the lexicographic ordering of $\Omega_{\mathbf{N}}$: $\sigma(\mathbf{x}) = i$ if and only if there are exactly $i-1$ elements $\vec{y}$ of $\Omega_{\mathbf{N}}$ such that $\vec{y} \preclex\vec{x}$ and $\vec{y} \neq \vec{x}$.

    Consider an arithmetic progression $\AP_d(\mathbf{a},\mathbf{b},\ell)$ in $\AA_{\vec{N}}$. It follows from Lemma~\ref{lem:lex} that there exist integers $i$ and $j$ such that 
    \begin{equation}\label{eq:AP-repr}
        \AP_d(\mathbf{a},\mathbf{b},\ell) = \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b}) \cap \{\mathbf{x}\in \Omega_{\mathbf{N}}: i \le \sigma(\mathbf{x}) \le j\}.
    \end{equation}
    Indeed, if $\vec{x}$ and $\vec{y}$ are the points guaranteed by the Lemma~\ref{lem:lex}, we can take $i = \sigma(\vec{x})$ and $j = \sigma(\vec{y})$. Then equation~\eqref{eq:AP-repr} follows from the lemma and the observation that 
    \(
    \{\vec{a} + i\vec{b}: i \in \Z\} \cap \Omega_{\vec{N}}
    = \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b}).
    \)

    Now let $\chi:\Omega_{\mathbf{N}} \to \{-1,+1\}$ achieve $\pdisc(\MM_{\mathbf{N}},\sigma)$. By equation~\eqref{eq:AP-repr}, for any arithmetic progression $\AP_d(\mathbf{a},\mathbf{b},\ell)$ in $\Omega_{\mathbf{N}}$ there exist $i$ and $j$ such that
    \begin{align*}
    \left|\sum_{\mathbf{z} \in \AP_d(\mathbf{a},\mathbf{b},\ell)} \chi(\mathbf{z}) \right|
    &=
    \left|\sum_{\substack{\mathbf{z} \in \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})\\ i \le \sigma(\mathbf{z}) \le j}} \chi(\mathbf{z}) \right|\\
    &= \left|\sum_{\substack{\mathbf{z} \in \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})\\ \sigma(\mathbf{z}) \le j}} \chi(\mathbf{z})  - \sum_{\substack{\mathbf{z} \in \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})\\ \sigma(\mathbf{z}) < i}} \chi(\mathbf{z})\right|\\
    &\le \left|\sum_{\substack{\mathbf{z} \in \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})\\ \sigma(\mathbf{z}) \le j}} \chi(\mathbf{z})\right|  + \left|\sum_{\substack{\mathbf{z} \in \MAP_{\mathbf{N}}(\mathbf{a},\mathbf{b})\\ \sigma(\mathbf{z}) < i}} \chi(\mathbf{z})\right|\\
    &\le 2\pdisc(\MM_{\mathbf{N}},\sigma).
    \end{align*}
    Since $\AP_d(\mathbf{a},\mathbf{b},\ell)$ was arbitrary, this proves that $\disc(\AA_{\mathbf{N}}) \le 2\pdisc(\MM_{\mathbf{N}},\sigma)$, and the theorem follows from Theorem~\ref{thm:gamma2-pdisc} and Lemma~\ref{lem:gamma2-map-ub}.
\end{proof}

\subsection{Bound on \texorpdfstring{$\gamma_2\left(\AA_{\mathbf{N}}\right)$}{gamma-two of AP}}\label{sec:gamma2-bound}

In this section, we give a tight bound on $\gamma_2(\AA_{\mathbf{N}})$. This bound and Theorem~\ref{thm:gswalk} then imply Theorem~\ref{thm:main}, and, in particular, imply an efficient algorithm to find the low discrepancy coloring guaranteed to exist by Theorem~\ref{thm:main-ub}. 

The lemma below and its proof are a generalization of Proposition~7.1 of Matou\v{s}ek, Nikolov, and Talwar~\cite{matouvsek2020factorization}.

\begin{lemma}\label{lem:gamma2-ap-ub}
    For $N_1, ..., N_d \in \Z$, let $\mathbf{N} = \left(N_1, ..., N_d\right)$. Let $\AA_{\mathbf{N}}$ be the set of all arithmetic progressions in $\Omega_{\mathbf{N}}$. Then 
    \(
    \gamma_2(\AA_{\mathbf{N}}) \lesssim_d f\left(\mathbf{N}\right).
    \)
\end{lemma}
\begin{proof}
    Without loss of generality, we will assume $N_1 \ge N_2 \ldots \ge N_d$. Moreover, we will assume that each $N_i$ is a power of $2$. This is also without loss of generality, since rounding up each $N_i$ to the nearest power of $2$ changes $f(\vec{N})$ by at most a constant factor.

    Let $\mathcal{PA}_{\vec{N}}$ be the set of prefix-maximal arithmetic progressions in $\Omega_{\vec{N}}$, i.e., arithmetic progressions $\AP(\vec{a},\vec{b},\ell)$ for which $\vec{a}-\vec{b} \not \in \Omega_{\vec{N}}$. Clearly any arithmetic progression in $\AA_{\vec{N}}$ is the set difference of at most two prefix-maximal arithmetic progressions in $\mathcal{PA}_{\vec{N}}$, so $\gamma_2\left(\AA_{\vec{N}}\right) \le 2 \gamma_2(\mathcal{PA}_{\vec{N}})$ by Lemma~\ref{lem:triangle-ss}. Therefore, it suffices to prove that $\gamma_2(\mathcal{PA}_{\vec{N}}) \lesssim_d f(\vec{N})$. 

    We prove this bound by induction on $|\Omega_{\vec{N}}|$, with the inductive hypothesis 
    \(
    \gamma_2(\mathcal{PA}_{\vec{N}}) \le C_d f\left(\mathbf{N}\right),
    \)
    where $C_d$ is a constant depending on $d$ that we will decide later. 
    The base case $|\Omega_{\vec{N}}| = 1$ is trivial, and the rest of the proof establishes the inductive step.

    Let $N'_1 \eqdef N_1/2$ (recall that we assumed $N_1$ is a power of $2$). Let also $\vec{N}' \eqdef (N'_1, N_2, \ldots, N_d)$, and define $\Omega' \eqdef \Omega_{\vec{N}'} = [N'_1]\times [N_2]\times \ldots \times [N_d]$, and $\Omega'' \eqdef \vec{v} + \Omega_{\vec{N}'}$, where $\vec{v}$ is the vector with $N_1'$ in the first coordinate, and $0$ in every other coordinate. Notice that $\Omega'$ and $\Omega''$ partition $\Omega_{\vec{N}}$. 
    Let $\PA'$ and $\PA''$ be, respectively, the set of all prefix-maximal arithmetic progressions in $\Omega'$, and the set of all prefix-maximal arithmetic progressions in $\Omega''$. Note that $\PA'$ and $\PA''$ are isomorphic: for every $\AP_d(\vec{a},\vec{b},\ell) \in \PA''$, $\AP_d(\vec{a}-\vec{v},\vec{b},\ell) \in \PA'$, and, conversely, for any $\AP_d(\vec{a},\vec{b},\ell) \in \PA'$, $\AP_d(\vec{a} + \vec{v},\vec{b},\ell) \in \PA''$. Moreover, $\PA' = \PA_{\vec{N}'}$ by definition. Similarly, let $\MM'$ and $\MM''$ be, respectively, the set of maximal arithmetic progressions in $\Omega'$ and in $\Omega''$. Again, $\MM'$ and $\MM''$ are both isomorphic to $\mathcal{M}_{\vec{N}'}$, the set of all maximal arithmetic progressions in $\Omega_{\vec{N}'}$.

    Take $\AP_d(\vec{a},\vec{b},\ell)$ to be a prefix-maximal arithmetic progression in $\PA_{\mathbf{N}}$ that is not fully contained in $\Omega'$ or $\Omega''$. Notice that this means $b_1 \neq 0$. If $b_1 > 0$, this is equivalent to $a_1 \le N'_1$ and $a_1 + (\ell-1)b_1 > N'_1$. Then $\AP_d(\vec{a},\vec{b},\ell) \cap \Omega' \in \MM'$, and $\AP_d(\vec{a},\vec{b},\ell) \cap \Omega'' \in \PA''$. Similarly, if $b_1 < 0$, then $\AP_d(\vec{a},\vec{b},\ell)$ not being fully contained in  $\Omega'$ or $\Omega''$ is equivalent to $a_1 > N'_1$ and $a_1 + (\ell-1)b_1 \le N'_1$. Then $\AP_d(\vec{a},\vec{b},\ell) \cap \Omega'' \in \MM''$, and $\AP_d(\vec{a},\vec{b},\ell) \cap \Omega' \in \PA'$. 

    In summary, one of the following cases holds for any $\AP_d(\vec{a},\vec{b},\ell) \in \PA_{\vec{N}}$:
    \begin{enumerate}
        \item $\AP_d(\vec{a},\vec{b},\ell) \in \PA'$ or $\AP_d(\vec{a},\vec{b},\ell) \in \PA''$;

        \item $\AP_d(\vec{a},\vec{b},\ell) = M' \cup A''$, where $M' \in \MM'$ and $A'' \in \PA''$;

        \item $\AP_d(\vec{a},\vec{b},\ell) = M'' \cup A'$, where $M'' \in \MM''$ and $A' \in \PA'$.
    \end{enumerate}
    Let $\SS_1$ be the set system on $\Omega_{\vec{N}}$ with sets $\PA'\cup \PA''$. By the disjoint supports property in Lemma~\ref{lem:gamma2}, and the fact that $\PA'$ and $\PA''$ are both isomorphic to $\PA_{\vec{N}'}$, we have $\gamma_2(\SS_1) = \gamma_2(\PA_{\vec{N}'})$. Similarly, let $\SS_2$ be the set system on $\Omega_{\vec{N}}$ with sets $\MM'\cup \MM''$. Again by the disjoint supports property in Lemma~\ref{lem:gamma2}, $\gamma_2(\SS_1) = \gamma_2(\MM_{\vec{N}'})$. By the observations above, each $\AP_d(\vec{a},\vec{b},\ell) \in \PA_{\vec{N}}$ can be written as $S_1 \cup S_2$ for two disjoint sets $S_1 \in \SS_1$ and $S_2 \in \SS_2$ (where we assume, without loss of generality, that the empty set is contained in $\SS_2$). By Lemma~\ref{lem:triangle-ss}, this gives us
    \[
    \gamma_2(\PA_{\vec{N}}) \le \gamma_2(\mathcal{M}_{\vec{N}'}) + \gamma_2(\PA_{\vec{N}'}) 
    \le (C'_d + C_d) f(\vec{N}').
    \]
    For the second inequality, we used the inductive hypothesis and Lemma~\ref{lem:gamma2-map-ub}, with $C'_d$ defined as the implied constant in the upper bound on $\gamma_2(\mathcal{M}_{\vec{N}})$ given by Lemma~\ref{lem:gamma2-map-ub}. To complete the proof, we notice that, by Lemma~\ref{lm:f-alt}, there is some $k^* \in [d]$ for which 
    \[
    f(\vec{N}') = \left(\prod_{i = 1}^{k^*}N'_i\right)^{\frac{1}{2k^*+2}}
    = 2^{-\frac{1}{2k^*+2}}\left(\prod_{i = 1}^{k^*}N_i\right)^{\frac{1}{2k^*+2}}
    \le 2^{-\frac{1}{2d+2}}f(\vec{N}).
    \]
    Therefore, the bound $\gamma_2(\PA_{\vec{N}}) \le C_d f(\vec{N})$ holds as long as $C_d \ge C'_d / (2^{\frac{1}{2d+2}}-1)$. This completes the proof of the inductive step.
\end{proof}

Theorem~\ref{thm:main} is now a direct consequence of Lemma~\ref{lem:gamma2-ap-ub} and Theorem~\ref{thm:gswalk}.

We remark here that Lemma~\ref{lem:gamma2-ap-ub} is tight up to constants depending on the dimension. This follows from the proof of Theorem 5.1 of~\cite{fox2024discrepancy}. An inspection of the proof shows that it gives a lower bound on the average squared discrepancy of some collection of APs in $\Omega_{\vec{N}}$, and that the lower bounds holds for any coloring $\chi:\Omega_{\vec{N}} \to \R$ with $\sum_{\vec{z} \in \Omega_{\vec{N}}} |\chi(\vec{z})|^2 = |\Omega_{\vec{N}}|$. Thus, the lower bound in Theorem 5.1 of~\cite{fox2024discrepancy} in fact gives a lower bound on the smallest singular value of a matrix $\vec{A}$ whose rows are indicator vectors of APs in $\Omega_{\vec{N}}$. In particular, if the number of rows of $\vec{A}$ is $M$, then the lower  bound is 
\[
\sigma_{\min}(\vec{A}) \gtrsim_d \frac{f(\vec{N})\sqrt{M}}{\sqrt{ |\Omega_{\vec{N}}| }}.
\]
The nuclear norm (sum of singular values) of $\vec{A}$, denoted $\|\vec{A}\|_*$, is then bounded as $\|\vec{A}\|_* \gtrsim_d f(\vec{N})\sqrt{M|\Omega_{\vec{N}}|}$, which implies $\gamma_2(\AA_{\vec{N}}) \ge \gamma_2(\vec{A}) \gtrsim_d f(\vec{N})$ by equation~(4)~of~\cite{matouvsek2020factorization}.

