\section{Arithmetic Progressions in a Convex Set}

Let us now consider the general setting of convex bodies $K$ in $\R^d$. Let $\Omega_K$ be the integer points in $K$, i.e., $\Omega_K \eqdef \Z^d \cap K$. Let $\AA_K$ be the set system of all arithmetic progressions restricted to $\Omega_K$. We want to prove the following.

\generalbodiesthm*

\subsection{Upper Bound}

In analogy with our arguments for the $d$-dimensional axis-aligned box, let $\MAP_K(\mathbf{a},\mathbf{b})$ be an arithmetic progression inside $K$ containing $\mathbf{a}$ and with difference $\mathbf{b}$ that cannot be extended further in either direction, i.e., a maximal arithmetic progression in $K$. We have the following bound.

\begin{lemma}\label{lem:generalK-MAP}
    Let $\MM_K := \{\MAP_K(\mathbf{a},\mathbf{b}): \mathbf{a},\mathbf{b} \in \Z^d\}$ be the set of all maximal APs in $\Omega_K$. Then $\gamma_2(\MM_K) \lesssim f(K)$.
\end{lemma}
\begin{proof}
    The proof follows along the same lines as that of Lemma~\ref{lem:gamma2-map-ub}. Fix some $s \ge 1$ to be determined later, and let $\MM_{\le s}$ consist of all $\MAP_K(\mathbf{a},\mathbf{b})$ for which $|\MAP_K(\mathbf{a}',\mathbf{b})| \le s$ for all $\mathbf{a}' \in \Z^d$. As in Lemma~\ref{lem:gamma2-map-ub}, $\gamma_2(\MM_{\le s}) \le \sqrt{s}$ because all sets in $\MM_{\le s}$ have cardinality at most $s$.

    Then let $\MM_{> s} := \MM_K \setminus \MM_{\le s}$. Defining 
    \[
     B \eqdef \left\{\mathbf{b} \in \Z^d: \max_{\mathbf{a} \in \Z^d} |\MAP_{K}(\mathbf{a},\mathbf{b})| > s\right\},
    \]
    we have $\MM_{> s} = \{\MAP_K(\mathbf{a},\mathbf{b}): \mathbf{a} \in \Z^d, \mathbf{b} \in B\}$. Analogous to Lemma~\ref{lem:gamma2-map-ub}, we have $\gamma_2(\MM_{> s}) \le \sqrt{|B|}$. 

    We estimate $|B|$. Take some $\mathbf{b} \in B$ and $\mathbf{a} \in \Z^d$ such that $|\MAP_{K}(\mathbf{a},\mathbf{b})| > s$. Let $\mathbf{x}$ and $\mathbf{y}$ be the endpoints of $\MAP_{K}(\mathbf{a},\mathbf{b})$, i.e., $\mathbf{x},\mathbf{y} \in \MAP_{K}(\mathbf{a},\mathbf{b})$, but $\mathbf{x}-\mathbf{b} \not \in \MAP_{K}(\mathbf{a},\mathbf{b})$, and $\mathbf{y}+\mathbf{b} \not \in \MAP_{K}(\mathbf{a},\mathbf{b})$. Then $\mathbf{y} - \mathbf{x} = \ell \mathbf{b}$ for some $\ell \ge s$. Since both $\mathbf{x}$ and $\mathbf{y}$ are in $K$, this means that $s\mathbf{b} \in K-K$, or, equivalently, $\mathbf{b} \in \frac{1}{s} (K-K)$. We then have that $|B| \le \zeta_{K-K}\left(\frac{1}{s}\right)$.

    Combining the bounds above, we get
    \[
    \gamma_2(\MM_K)^2 =\gamma_2(\MM_{\le s}\cup \MM_{> s})^2
    \le s + \zeta_{K-K}\left(\frac{1}{s}\right).
    \]
    In particular, we have 
    \[
    \gamma_2(\MM_K)^2
    \le 2\inf\left\{s: s \ge \zeta_{K-K}\left(\frac{1}{s}\right)\right\}
    = 2 f(K)^2,
    \]
    as we needed to prove.
\end{proof}

Next we prove the upper bound in Theorem~\ref{thm:generalbodiesthm}, restated as the next theorem.

\begin{theorem}\label{thm:generalbodies-ub}
    For any $d$-dimensional convex body $K$, any $\vec{v} \in \R^d$, $\Omega_{\vec{v} + K} \eqdef \Z^d \cap (\vec{v} + K)$, and the set system $\AA_{\vec{v} + K}$ of all arithmetic progressions on the universe $\Omega_{\vec{v} + K}$, we have
    \[
    \disc(\AA_{\vec{v} + K}) \lesssim \sqrt{\log (1+|\Omega_{\vec{v} + K}|)}\cdot f(K).
    \]
\end{theorem}
\begin{proof}
    Let $K' = \vec{v} + K$ and note that $K'-K' = K-K$, so $f(K') = f(K)$. The proof is analogous to the proof of Theorem~\ref{thm:main} via prefix discrepancy. We construct a bijection $\sigma:\Omega_{K'} \to [|\Omega_{K'}|]$ such that $\disc(A_{K'}) \le 2 \pdisc(\MM_{K'},\sigma)$. The theorem then follows from Theorem~\ref{thm:gamma2-pdisc} and Lemma~\ref{lem:generalK-MAP}. 

    As in the proof of Theorem~\ref{thm:main}, we order $\Omega_{K'}$ lexicographically (i.e., according to $\preclex$), and let $\sigma(\vec{x})$ be the rank of $\vec{x} \in \Omega_{K'}$ in this ordering. Then it follows from Lemma~\ref{lem:lex} that for any arithmethic progression $\AP_d(\vec{a}, \vec{b}, \ell)$ in $\AA_{K'}$ there exist integers $i$ and $j$ for which 
    \[
    \AP_d(\vec{a}, \vec{b}, \ell) = \MAP_K(\vec{a},\vec{b}) \cap \{\vec{x}: i \le \sigma(\vec{x}) \le j\}.
    \]
    Then $\disc(A_{K'}) \le 2 \pdisc(\MM_{K'},\sigma)$ follows from an analogous calculation as the one in the proof of Theorem~\ref{thm:main}. 
\end{proof}

\subsection{Lower Bound}
We would like a lower bound for $\disc(\AA_K)$ with respect to $f(K)$ in~\Cref{thm:generalbodiesthm}. However, the inequality is not true when $K$ is a ``narrow" convex body which avoids all the integer points. For example, we can take $K = [0.25,0.75] \times [0,1]$ in two dimensions, which contains no integer points so $\disc(\AA_K) = 0$, while $f(K) > 0$. Instead, we present a lower bound for $\sup_{\mathbf{v} \in \R^d} \disc(\AA_{\mathbf{v} + K})$ with respect to $f(K)$ using a Fourier analytic proof. The result and its proof generalizes Roth's 1/4-theorem for one-dimensional arithmetic progressions and the lower bound of Fox, Xu, Zhou~\cite{fox2024discrepancy}. 

First, we need a couple of geometric lemmas. The first relates the number of integer points in $\vec{v}+K$ to the number of integer points in ${K-K}$. It can be seen as a counting version of the Rogers-Shephard inequality. We note that other counting versions of the inequality are known~\cite{discrete-rogsh}.
\begin{lemma}\label{lem:zeta-maxshift}
    For any convex body $K$ in $\R^d$,  we have the inequalities
    \[
    \max_{\vec{v} \in \R^d} |\Z^d \cap (\vec{v} + K)| 
    \le |\Z^d \cap (K-K)| 
    \lesssim_d \max_{\vec{v} \in \R^d} |\Z^d \cap (\vec{v} + K)|.
    \]
\end{lemma}
\begin{proof}
    Let us take any $\vec{v} \in \R^d$. To prove the first inequality, we need to show that 
    \(
    |\Z^d \cap (\vec{v} + K)| \le |\Z^d \cap (K-K)|.
    \)
    This is trivial if $\Z^d \cap (\vec{v} + K) = \emptyset$, so let us assume otherwise. Fix any $\vec{x} \in \Z^d \cap (\vec{v} + K)$. Then 
    \[
    |\Z^d \cap (\vec{v} + K)| = |\{\vec{y}-\vec{x}: \vec{y} \in \Z^d \cap (\vec{v} + K)\}| \le |\Z^d \cap (K-K)|,
    \]
    where the last inequality follows since $\vec{y}-\vec{x} \in K - K$ for any $\vec{x},\vec{y} \in \vec{v}+K$. This proves the first inequality.

    Let us now prove the second inequality. Without loss of generality, we can assume that $\vec{0} \in K$, since both sides of the inequality are invariant to shifting $K$. By the standard volumetric argument, there exist vectors $\vec{v}_1, \ldots, \vec{v}_N$ such that $K-K \subseteq \bigcup_{i =1}^N (\vec{v}_i + K)$, where 
    \[
    N \le \frac{2^d\vol_d\left((K-K) + \frac{1}{2}K \right)}{\vol_d(K)}.    
    \]
    Here $\vol_d(\cdot)$ is the $d$-dimensional Lebesgue measure. For a proof, see \cite[Chapter 4]{convgeom-book}. Using the assumption that $\vec{0} \in K$, we have that $K\subseteq K-K$, so $(K-K) + \frac{1}{2}K\subseteq \frac32(K-K)$, and we have
    \[
    N\le \frac{3^d\vol_d(K-K)}{\vol_d(K)} \le 12^d,
    \]
    where the final bound follows from the Rogers-Shephard inequality~\cite{RogersShephard57}. We now have that, for at least one of the $\vec{v}_i$ vectors, by the pigeonhole principle
    \[
    |\Z^d \cap (\vec{v}_i + K)| \ge \frac{1}{N} |\Z^d \cap (K-K)|
    \gtrsim_d |\Z^d \cap (K-K)|,
    \]
    proving the second inequality.
\end{proof}

We also need the following lemma, which is Proposition~4 of Gillet and Soul\'{e}~\cite{gillet1991number}. We include a short proof, which also gives better constants.
\begin{lemma}\label{lem:zeta-scaling}
    For any centrally symmetric convex body $K$ in $\R^d$, i.e., one such that $K = -K$, and any $t \ge 1$, we have
    \[
     \zeta_K(1) \leq \zeta_K(t) \lesssim_d t^d\zeta_K(1).
    \]
\end{lemma}
\begin{proof}
    The first inequality is trivial for $t \ge 1$ so we prove the second one. The standard volumetric argument (referring, again, to~\cite[Chapter 4]{convgeom-book} for a proof) gives that there exist vectors $\vec{v}_1, \ldots, \vec{v}_N$ such that $tK \subseteq \bigcup_{i =1}^N (\vec{v}_i + \frac12 K)$, where 
    \[
    N \le \frac{2^d\vol_d\left(tK + \frac{1}{4}K \right)}{\vol_d(\frac12 K)} =  (4t+1)^d.
    \]
    Therefore, at least one of the $\vec{v}_i$ vectors, by the pigeonhole principle, 
    \[
    |\Z^d \cap (\vec{v}_i + \frac12 K)| \ge \frac{1}{N} |\Z^d \cap tK|
    \ge \frac{1}{(4t+1)^d}\zeta_K(t).
    \]
    The first inequality in Lemma~\ref{lem:zeta-maxshift} then give us that $|\Z^d \cap (\vec{v}_i + \frac12 K)| \le \zeta_K(1)$, since $\frac12K - \frac12 K = K$ by the symmetry of $K$. We thus get 
    \[
    \zeta_K(t) \le (4t+1)^d \zeta_K(1) \le 5^d t^d \zeta_K(1),
    \]
    where we used $t \ge 1$.
\end{proof}

Finally, we recall some basics from Fourier analysis. Let $\ip{\cdot,\cdot}$ be the standard inner product in $\R^d$, and fix $i \eqdef \sqrt{-1}$. For any functions $f, g: \Z^d \rightarrow \C$ with finite support, the Fourier transform $\widehat{f}: [0,1]^d \rightarrow \C$ is defined by $\widehat{f}(\mathbf{r}) \eqdef \sum_{x \in \Z^d}f(\mathbf{x})e^{-2\pi i\ip{\mathbf{x},\mathbf{r}}}$, and the convolution of $f$ and $g$ is $(f\star g)(\mathbf{x}) \eqdef \sum_{\mathbf{r} \in \Z^d}f(\mathbf{r})g(\mathbf{x} - \mathbf{r})$. Further, the convolution identity states that $\widehat{f\star g} = \widehat{f}\cdot\widehat{g}$ pointwise, and Parseval's identity states that 
\[\sum_{\mathbf{x} \in \Z^d}f(\mathbf{x})\overline{g(\mathbf{x})} = \int_{[0,1]^d}\widehat{f}(\mathbf{r})\overline{\widehat{g}(\mathbf{r})}d\mathbf{r}.\]

The next theorem is the lower bound part of Theorem~\ref{thm:generalbodiesthm}.
\begin{theorem}[Convex Body Lower Bound]\label{thm:generalbodies-lb}
    For any convex body $K \subseteq \R^d$ and $\mathbf{v} \in \R^d$, define $\AA_{\mathbf{v} + K}$ to be the family of all arithmetic progressions restricted to $\Omega_{\mathbf{v} + K}$, the set of integer points in $\vec{v} + K$. Then
    \[f\left(K\right) \lesssim_d \sup_{\mathbf{v} \in \R^d} \disc\left(\AA_{\mathbf{v} + K}\right).\]
    Moreover, if $K=-K$, then 
    \(
    f\left(K\right) \lesssim_d \disc\left(\AA_{K}\right).
    \)
\end{theorem}
\begin{proof}
    %First, assume that $\zeta_{K-K}(1) > 1$. Otherwise, there is at most one integer point in $K-K$ and the inequality is already true by shifting $K$ as necessary. 

    We choose $\vec{v}$ to achieve $\max_{v \in R^d} |\Z^d \cap (\vec{v} + K)|$.
    Take a coloring $\chi:\Omega_{\vec{v} + K} \to \{-1,+1\}$, and extend it to a function $\chi: \Z^{d} \rightarrow \{-1, 0, 1\}$ by setting $\chi(\mathbf{x}) = 0$ for all $\mathbf{x} \notin \Omega_{\mathbf{v} + K}$. Further, for each $\mathbf{b} \in \Z^d\setminus \{\vec{0}\}$, define the ``comb'' function $g_{\mathbf{b}}: \Z^{d}\rightarrow \{0, 1\}$ as the indicator function of the set $\{\mathbf{0}, \mathbf{b}, ..., (\ell - 1)\mathbf{b}\}$ for a positive integer $\ell$ to be determined. Note that the convolution $g_{\textbf{b}}\star \chi(\mathbf{x})$ is exactly the discrepancy of an arithmetic progression with step size $-\mathbf{b}$ whose first point is $\mathbf{x}$, i.e.,
    \[
    g_{\mathbf{b}}\star\chi(\mathbf{x}) 
    = \chi\left(\Omega_{\mathbf{v} + K} \cap \{\mathbf{x} - t\mathbf{b}: 0 \leq t < \ell\}\right)
    =\chi(\Omega_{\vec{v} + K} \cap \AP_d(\vec{x},-\vec{b},\ell)),
    \]
    where we used the convention $\chi(S) \eqdef \sum_{\vec{z} \in S}(\vec{z})$ for a set $S \subseteq \Z^d$.
    Let $\mathbf{b} \in m(K - K)\setminus \{\vec{0}\}$ for some real value $m$ to be determined, and define $\widetilde{K} \eqdef K + m\ell(K-K)$. We have
    \begin{equation}\label{eq:generallb-disc-inequality}
         \sum_{\mathbf{x} \in \Z^d}|g_{\mathbf{b}}\star\chi(\mathbf{x})|^2 \leq \disc\left(\AA_{\mathbf{v} + K}\right)^2|\Z^d \cap (\vec{v} + \widetilde{K})|,
    \end{equation}
    since there are at most $|\Z^d \cap (\vec{v} + \widetilde{K})|$ values of $\mathbf{x}$ for which $g_{\mathbf{b}}\star\chi(\mathbf{x})$ is non-zero, and each such value is the discrepancy of an arithmetic progression in $\AA_{\vec{v}+K}$. To see this, recall that $\mathbf{b} \in m(K - K)$ and that $\chi$ is nonzero only on $\Omega_{\vec{v} + K}$. Thus every $\mathbf{x}$ for which $g_{\mathbf{b}}\star\chi(\mathbf{x})\neq 0$ must satisfy $\vec{x} - t\vec{b} \in \vec{v} + K$ for some $0 \le t < \ell$, which implies that $\vec{x} \in \vec{v} + K + m\ell(K-K)$. 

    Since $\widetilde{K} - \widetilde{K} = (1+2m\ell)(K-K)$, equation~\eqref{eq:generallb-disc-inequality} and Lemma~\ref{lem:zeta-maxshift} imply that
    \begin{equation}\label{eq:lb-disc-diffK}
        \sum_{\mathbf{x} \in \Z^d}|g_{\mathbf{b}}\star\chi(\mathbf{x})|^2
        \le 
        \disc\left(\AA_{\mathbf{v} + K}\right)^2\zeta_{K-K}\left(1+2m\ell\right).
    \end{equation}
    On the other hand, by Parseval's identity and the convolution identity, we have
    \begin{align*}
        \sum_{\mathbf{x} \in \Z^d}|g_{\mathbf{b}}\star\chi(\mathbf{x})|^2 &= \int_{[0,1]^d}\widehat{g_{\mathbf{b}}\star\chi}(\mathbf{r})\overline{\widehat{g_{\mathbf{b}}\star\chi}(\mathbf{r})}d\mathbf{r}\\ 
        &= \int_{[0,1]^d}\widehat{g_{\mathbf{b}}}(\mathbf{r})\widehat{\chi}(\mathbf{r})\overline{\widehat{g_{\mathbf{r}}}(\mathbf{r})\widehat{\chi}(\mathbf{r})} d\mathbf{r}
        =\int_{[0,1]^d}|\widehat{g_{\mathbf{b}}}(\mathbf{r})|^2|\widehat{\chi}(\mathbf{r})|^2 d\mathbf{r}.
    \end{align*}
    Together with equation~\eqref{eq:lb-disc-diffK}, we obtain  
    \begin{equation}
        \int_{[0,1]^d}|\widehat{g}_{\mathbf{b}}(\mathbf{r})|^2|\widehat{\chi}(\mathbf{r})|^2 d\mathbf{r} \leq \disc\left(\AA_{\mathbf{v} + K}\right)^2\zeta_{K-K}\left(1+2m\ell\right).
    \end{equation}
    %Consider the convex body $K' := 2m(K - K)$. Note that for any two $\mathbf{b}_1, \mathbf{b}_2 \in m(K-K)$, their difference is in $K'$. Further, the number of integer points in $K'$ is exactly $\zeta_{K-K}(2m)$. 
    Summing over all $\mathbf{b} \in B\eqdef m(K-K)\setminus \{\vec{0}\}$, we have that 
    \begin{equation}\label{eq:generallb-summed}
        \int_{[0,1]^d}\left(\sum_{\mathbf{b} \in B}|\widehat{g_{\mathbf{b}}}(\mathbf{r})|^2\right) |\widehat{\chi}(\mathbf{r})|^2 d\mathbf{r} \leq \disc\left(\AA_{\mathbf{v} + K}\right)^2\zeta_{K-K}\left(1+2m\ell\right)\zeta_{K-K}\left(m\right).
    \end{equation}
    We will now show that the sum $\sum_{\mathbf{b} \in B}|\widehat{g_{\mathbf{b}}}(\mathbf{r})|^2$ can be bounded uniformly from below by a constant multiple of $\ell^2$.
    Let us fix some $\mathbf{r} \in [0, 1]^{d}$. We can find distinct integer points $\mathbf{b}_1, \mathbf{b}_2 \in \frac{m}{2}(K-K)$ such that the fractional parts of $\ip{\mathbf{b}_1,\mathbf{r}}$ and $\ip{\mathbf{b}_2,\mathbf{r}}$ differ by at most $\varepsilon \eqdef \frac{1}{\zeta_{K-K}(m/2)-1}$ by the pigeonhole principle. It follows that there exists some $\mathbf{b}_{\vec{r}} \in B$ such that the fractional part of $\ip{\mathbf{b}_{\vec{r}}, \mathbf{r}}$ lies in $\left[0, \varepsilon\right]$, namely $\vec{b}_{\vec{r}} \eqdef \mathbf{b}_1 - \mathbf{b}_2$. For any 
    \begin{equation}\label{eq:lb-ell-bound}
    \ell \le 1+\frac{1}{6\varepsilon} = \frac{5}{6} + \frac{1}{6}\zeta_{K-K}(m/2),
    \end{equation}
    and any $0 \le t \le \ell-1$, we have
    \[
   1\ge \Re \exp\left(-2\pi i t\ip{\vec{b}_{\vec{r}}, \vec{r}}\right)\ge \cos(2\pi(\ell-1)\varepsilon) \ge \cos\left(\frac{\pi}{3}\right) = \frac{1}{2}.
    \]
    Therefore, we get the bound
    \begin{equation}\label{eq:generallb-gbbound}
        \sum_{\mathbf{b} \in B}|\widehat{g_{\mathbf{b}}}(\mathbf{r})|^2 \geq |\widehat{g_{\mathbf{b}_{\vec{r}}}}(\mathbf{r})|^2 = \left|\sum_{t = 0}^{\ell - 1} \exp\left(- 2\pi i t\ip{\mathbf{b}_{\vec{r}},\mathbf{r}}\right)\right|^2 \ge \frac{\ell^2}{4}.
    \end{equation}
    Since we also have, by Parseval's identity,
    \begin{equation*}
        \int_{[0,1]^d}|\widehat{\chi}(\mathbf{r})|^2 = \sum_{\mathbf{x} \in \Z^d}|\chi(\mathbf{x})|^2 = |\Z^d\cap \mathbf{v} + K|,
    \end{equation*}
    together with equation~\eqref{eq:generallb-summed} and equation~\eqref{eq:generallb-gbbound}, for any $\ell$ satisfying \eqref{eq:lb-ell-bound} we have the inequality
    \begin{equation}\label{eq:generallb-finalbound}
        \disc\left(\AA_{\mathbf{v} + K}\right)^2\zeta_{K-K}\left(1+2m\ell\right)\zeta_{K-K}\left(m\right) \ge \frac{1}{4}\ell^2|\Z^d\cap \mathbf{v} + K|.
    \end{equation}
    We can now choose values for the parameters $\ell$ and $m$.
    Let $\ell \eqdef \frac{f(K)^2}{12}$ and $m \eqdef \frac{4}{f(K)^2}$. First we show that $\ell \leq \frac{\zeta_{K-K}(m/2)}{6}$, which implies that equation~\eqref{eq:lb-ell-bound} holds. Since $f(K)^2$ is defined to be the \emph{smallest} $s$ such that $\zeta_{K-K}\left(\frac{1}{s}\right) \leq s$ (see equation~\eqref{eq:ub-body}), values of $s$ less than $f(K)^2$, namely $\frac{f(K)^2}{2} = \frac{2}{m}$, must satisfy 
    \[\zeta_{K-K}\left(m/2\right) > \frac{2}{m} =  \frac{f(K)^2}{2}.\]
    It follows that $\frac{\zeta_{K-K}(m/2)}{6} > \frac{f(K)^2}{12} = \ell$ as required. 

    Substituting $\ell = \frac{f(K)^2}{12}$ and $m = \frac{4}{f(K)^2}$ into equation~\eqref{eq:generallb-finalbound}, we have
    \begin{align}
        \disc\left(\AA_{\mathbf{v} + K}\right)^2\zeta_{K-K}\left(\frac{5}{3}\right)\zeta_{K-K}\left(\frac{4}{f(K)^2}\right) \gtrsim f(K)^4|\Z^d\cap \mathbf{v} + K|.\label{eq:lb-substituted}
    \end{align}
    By Lemmas~\ref{lem:zeta-maxshift}~and~\ref{lem:zeta-scaling},
    \begin{equation}\label{eq:lb-const-scale}
        \zeta_{K-K}\left(\frac53\right) \lesssim_d \zeta_{K-K}(1) \lesssim_d |\Z^d\cap \mathbf{v} + K|,
    \end{equation}
    where, in the last inequality, we used both Lemma~\ref{lem:zeta-maxshift} and the choice of $\vec{v}$ to maximize $|\Z^d \cap (\vec{v} + K)|$. Furthermore, by Lemma~\ref{lem:zeta-scaling}, and the definition of $f(K)$, we have
    \begin{equation}\label{eq:lb-fK}
        \zeta_{K-K}\left(\frac{4}{f(K)^2}\right) \lesssim_d \zeta_{K-K}\left(\frac{1}{f(K)^2}\right) \le f(K)^2.
    \end{equation} 
    Together, the inequalities \eqref{eq:lb-substituted}, \eqref{eq:lb-const-scale}, and \eqref{eq:lb-fK} give us $\disc(\AA_{\vec{v}+K})^2 \gtrsim_d f(K)^2$, as we needed to prove.

    To see that the stronger lower bound for centrally symmetric convex bodies $K$ (ones that satisfy $K=-K$) holds, observe that the only place where we used the choice of $\vec{v}$ was in establishing the last inequality in \eqref{eq:lb-const-scale}. All other inequalities we derived hold for an arbitrary $\vec{v}$, including $\vec{v} = \vec{0}$.  For centrally symmetric convex bodies, equation~\eqref{eq:lb-const-scale} instead becomes
    \[
    \zeta_{K}\left(\frac53\right) \lesssim_d \zeta_{K}(1)
    \]
    using the symmetry of $K$ and Lemma~\ref{lem:zeta-scaling}. The rest of the proof is identical.
\end{proof}

Similarly to our discussion of $\gamma_2(\AA_{\vec{N}})$ after the proof of Lemma~\ref{lem:gamma2-ap-ub}, the proof of Theorem~\ref{thm:generalbodies-lb} also shows the lower bound $\sup_{\vec{v} \in \R^d} \gamma_2(\AA_{\vec{v} + K}) \gtrsim_d f(K)$ for convex bodies $K$, and also $\gamma_2(\AA_{K}) \gtrsim_d f(K)$ when $K$ is centrally symmetric. At present we do not have a matching upper bound on the $\gamma_2$ norm. Proving such an upper bound would also imply a constructive version of Theorem~\ref{thm:generalbodies-ub} (i.e., the upper bound part of Theorem~\ref{thm:generalbodiesthm}).

