\title{
FastMamba: A High-Speed and Efficient Mamba Accelerator on FPGA with Accurate Quantization
}

\author{
\IEEEauthorblockN{Aotao Wang$^{1}$, Haikuo Shao$^{1}$, Shaobo Ma$^{1}$, and Zhongfeng Wang$^{1,2}$}
