\section{Preliminaries} 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Recall that, according to the definition of fully-adaptive source-oblivious broadcast introduced in \cite{GholamiH22a}, once a vertex $v$ is informed, say at round~$t$, it will follow its list of neighbors $\ell_v$ (cf. Eq.~\eqref{eq:thelists}), and pass the message to the first vertex on the list which is not already informed before round $t+1$. In other words, not only node~$v$ skips all its neighbors from which it  received the message, but $v$ also skip all other informed neighbors. Given a set $L=(\ell_v)_{v\in V(G)}$ of lists, the number of rounds for broadcasting a message from $s\in V(G)$ to all the other nodes of~$G$ using lists~$L$ under the fully adaptive model is denoted by $b_{\fa}(G,s,L)$. 
The broadcast time of a graph~$G$ under the fully adaptive model is then defined as
\[
b_{\fa}(G)=\min_L\max_{s\in V(G)}b_{\fa}(G,s,L).
\]
%
%
% It is obvious that for an arbitrary graph $G$, $b(G) \leq b_{fa}(G) \leq b_{a}(G) \leq b_{na}(G)$ \cite{GholamiH22b}. Considering graph $G=(V,E)$ in which $|V|=n$, a broadcast scheme for non-adaptive, adaptive, or fully-adaptive model can be viewed as a matrix $\sigma_{n\times \Delta}$, where row $i$ of $\sigma$ corresponds to an ordering of the neighbors of vertex $v_i$. Assuming this vertex has degree $d_i$, the cells $\sigma_{[i][d_i+1]},\sigma_{[i][d_i+2]},\cdots,\sigma_{[i][\Delta]}$ will be NULL. By definition: $\Delta=\max\{d_i: 1\leq i \leq n\}$. Denote all possible schemes by $\Sigma$. Let $M$ be one of the three models using universal lists ($M \in \{na,a,f a\}$) and fix a graph $G$. For any broadcast scheme $\sigma\in\Sigma$, we denote by $b_M^\sigma(v,G)$ the time steps needed to inform all the vertices in $G$ from the source $v$ while following the scheme $\sigma$ under model $M$. Moreover, the broadcast time of a graph $G$ under model $M$ with scheme $\sigma$, $b_M^\sigma(G)$, is defined as the maximum $b_M^\sigma(v,G)$ over all possible originators $v \in V(G)$. Lastly, $b_M(G)$ is the minimum $b_M^\sigma (G)$ over all possible schemes $\sigma\in\Sigma$:
% \begin{equation}
% \begin{split}
% b_M^\sigma(G) & = \max_{v \in V} \{b_M^\sigma(v, G)\} \\
% b_M(G) & = \min_{\sigma \in \Sigma} \{b_M^\sigma(G)\}
% % b_M(G) & = \max_{v \in V} \{b_M(v, G)\}
% \end{split}
% \end{equation}
%
The following results illustrate the above definition, and may serve as a warm up for the rest of the paper.  The first proposition shows that the broadcast time using protocols encoded with lists cannot be more than twice the broadcast time using general protocols. 

\begin{proposition}\label{prop:2b}
For every  graph $G=(V,E)$, the broadcast complexity of $G$ under the fully-adaptive source-oblivious model is at most $2\,\min_{s\in V}b(G,s)$, that~is,
\[b_{\fa}(G)\leq 2\; \min_{s\in V}b(G,s).\] 
\end{proposition}

\begin{proof}
Let $s\in V$ with minimum broadcast time among all nodes in~$G$, i.e., $b(G,s)=\min_{s'\in V}b(G,s')$. Let $T$ be a broadcast tree rooted at $s$, enabling broadcast from $s$ in $b(G,s)$ rounds. (Such a tree is a spanning tree of~$G$ rooted at~$s$ in which the children of any node~$v$ are ordered, specifying the order in which these children must be informed by~$v$ upon reception of a message from~$s$.) Let $v\neq s$ be a node of~$T$, let $w$ be the parent of $v$ in~$T$, and let $u_1,\dots,u_d$ be the $d$ children of $v$ in~$T$ enumerated in the order in which they are called in an optimal broadcast protocol from $s$ in~$T$. The list assigned to~$v$ is 
\[
\ell_v=(w,u_1,\dots,u_d).
\]
Similarly, the list assigned to~$s$ is 
\[
\ell_s=(u_1,\dots,u_d)
\]
where $u_1,\dots,u_d$ are the $d$ children of $s$ in~$T$ enumerated in the order in which they are called in an optimal broadcast protocol from $s$ in~$T$. 

To show that this set of lists enable fully adaptive broadcast to perform in at most $2b(G,s)$ rounds, let $u$ be a source node. Following the assigned universal lists every vertex makes the first call to its parent once gets informed. Thus, a message broadcast from~$u$ reaches the root~$s$ of~$T$ after at most $\mbox{depth}(T)$ rounds. Since $b(G,s)\geq \mbox{depth}(T)$, the message reaches~$s$ after at most $b(G,s)$ rounds. 
Once at~$s$, the message is broadcast down the tree in at most $b(G,s)$ rounds since, for every node~$v\neq s$, the parent~$w$ of~$v$ in the list $\ell_v$ is skipped in the fully adaptive model. The upward and downward phases amount for a total of $2\, b(G,s)$ rounds. 
\end{proof}

The following is a direct consequence of Proposition~\ref{prop:2b}.

\begin{corollary}
For every  graph $G$, the broadcast complexity of $G$ under the fully-adaptive source-oblivious model is at most $2\,b(G)$, i.e., $$b_{\fa}(G)\leq 2\,b(G).$$
\end{corollary}

Note that Proposition~\ref{prop:2b} also holds in the adaptive source-oblivious model (in this model every node~$v$ just skips the neighbors in~$\ell_v$ from which it received the message). The second proposition shows that there is a price to pay for using broadcast protocols encoded with lists, in the sense that the broadcast time using such protocols may be larger than the broadcast time using general protocols. 

\begin{proposition}\label{prop:lafamille}
There is an infinite family of graphs  $\mathcal{F}$ such that, for every $G\in \mathcal{F}$, the broadcast complexity of $G$ in the fully-adaptive source-oblivious model is larger than its broadcast time, that is $b_{\fa}(G)>b(G)$. 
\end{proposition}

\begin{figure}[tb]
  \centering
  \includegraphics[width=.5\linewidth]{Figures/at-least-b-plus-1.pdf}
  \caption{Graph in the proof of Proposition~\ref{prop:lafamille}, for $k=2$.}
  \label{fig:2cycless}
\end{figure}

\begin{proof}
    A basic example of such a family of graphs is obtained from two cycles $C_{2k+1}$ of length $2k+1$, by merging two of their vertices into one (see Fig.~\ref{fig:2cycless}). For every $k\geq 1$, the resulting graph~$G_k$ has $4k+1$ vertices, with a cut vertex~$v$ at the intersection of the two cycles. It is known~\cite{HedetniemiHL88} that $b(C_{2k+1})=k+1$, from which it follows that $b(G_k)=2k+1$. Now, in the fully-adaptive source-oblivious model, let $\ell_v$ be the list of node~$v$, and let~$u$ be the neighbor of~$v$ occurring first in this list. Let $w$ be the vertex antipodal to the edge $\{u,v\}$ in the cycle containing both $u$ and~$v$. If $w$ does not call first its neighbor on the shortest path from $w$ to~$v$ in~$G_k$, then broadcast from~$w$ will take at least~$2k+2$ rounds. On the other hand, if $w$ calls first its neighbor on the shortest path from $w$ to~$v$ in~$G_k$, then $v$ will receive the information in round~$k$. Since~$u$ has not yet received the information at the end of round~$k$, $v$~will proceed according to its list~$\ell_v$, and call~$u$ at round~$k+1$. As a result, $v$ will start broadcasting in the other cycle (the one not containing $u$ and $w$), no sooner than round $k+2$, and thus the whole protocol will not complete before $2k+2$ rounds. 
\end{proof}

