\section{Algorithms for local conflicts}\label{app:algos}


\begin{algorithm}[ht]
\caption{Construct Local Conflict Graph $ \varrho(\cdot) $}
\label{algo:lch}
\begin{flushleft}
\hspace*{\algorithmicindent} 
\textbf{Input}: $\delta^+_{\ccalG^n}(i), \{e_j:w_{e_j}\}_{j\in \hat{\ccalN}_{\ccalH}(i)\cup\{i\}} $ \\
\hspace*{\algorithmicindent} 
\textbf{Output}: $\ccalG^c_i=(\ccalE_i,\ccalH_i), \bbomega^i$     
\end{flushleft}
\begin{algorithmic}[1] 
\STATE $\ccalE_i= \{e_i\}$, $\omega^i_i=w_{e_i}$, $\ccalH_i=\emptyset $ 
\FOR{ $ j\in \hat{\ccalN}_{\ccalH}(i)  $}
\IF{ $ e_j \in \delta^+_{\ccalG^n}(i) $ or $j$ is a known interferer}
\STATE $ \ccalE_i\leftarrow\ccalE_i\cup\{e_j\} $, $\omega^i_{e_j}=w_{e_j}$
\STATE $ \ccalH_i\leftarrow\ccalH_i\cup( 1:\{e_i, e_j\} ) $ \COMMENTS{half-duplex or interference}
\ELSE 
\STATE Analyze signal properties (e.g., DoA, RSS) of RTS for $e_j$
\FOR{ $ e_{j'}\in\delta^+_{\ccalG^n}(i) $ and $e_{j'}$ would be interfered by $e_j$}
\STATE \textbf{if} $ e_j\notin\ccalE_i $ \textbf{then} $ \ccalE_i\leftarrow\ccalE_i\cup\{e_j\} $, $\omega^i_{e_j}=w_{e_j}$
\STATE $ \ccalH_i\leftarrow\ccalH_i\cup( 1:\{e_{j'}, e_j\} ) $ \COMMENTS{new interference}
\ENDFOR
\ENDIF
\ENDFOR
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[ht]
\caption{Greedy MWIS on Local Conflict Graph $\varphi(\cdot) $}
\label{algo:greedy}
\begin{flushleft}
\hspace*{\algorithmicindent} 
\textbf{Input}: $\ccalG^c_i=(\ccalE_i,\ccalH_i), \bbomega^i $ \\
\hspace*{\algorithmicindent} 
\textbf{Output}: independent set $\varepsilon_i$     
\end{flushleft}
\begin{algorithmic}[1] 
\STATE $\varepsilon_i =\emptyset$; $m_e=-1,\forall e \in \ccalE_i$; $\tilde{\bbe}=\arg\textup{sort}_{\downarrow}\left[\omega^i_{e}\right]_{e\in\ccalE_i}  $
\FOR{ $n=1,\dots,|\ccalE_i|$ } 
% \STATE $e=(a,b)=\tilde{\bbe}_n $ 
\IF{ $m_{ \tilde{\bbe}_n}=-1$ and $\omega^i_{\tilde{\bbe}_n}>0$ }  
\STATE $\varepsilon_i \leftarrow\varepsilon_i \cup \{\tilde{\bbe}_n\} $ 
\STATE $ m_{e}=0 , \forall\; e\in \ccalN^1_{\ccalG^c_i}(\tilde{\bbe}_n)$ \COMMENTS{mute all regular neighbors}
\ENDIF
\ENDFOR
\end{algorithmic}
\end{algorithm}


