    \textbf{Model} & \textbf{Total FLOPs / token} & \textbf{Complexity in $L$} \\
    \midrule
    Softmax self-attention            & $\displaystyle 2L d_{\mathrm{model}}$                          & $\Theta(L^2 d_{\mathrm{model}})$ \\
    \midrule
    HGRN-1 (vector, $H\!=\!1$)        & $\displaystyle 5 d_{\mathrm{model}}$                            & $\Theta(L d_{\mathrm{model}})$ \\
    Hawk (RG-LRU, vector)              & $\displaystyle 5 d_{\mathrm{model}}$                            & $\Theta(L d_{\mathrm{model}})$ \\
    \midrule
    RetNet / Lightning                 & $\displaystyle 5\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    Mamba-2                            & $\displaystyle 5\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    GLA                                & $\displaystyle 7\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    RWKV-6                             & $\displaystyle 7\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    HGRN-2 / MetaLA                    & $\displaystyle 7\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    DeltaNet                           & $\displaystyle 8\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    Gated DeltaNet                     & $\displaystyle 8\,\frac{d_{\mathrm{model}}^{2}}{H}$            & $\Theta\bigl(L d_{\mathrm{model}}^{2}/H\bigr)$ \\
    \bottomrule
  \end{tabular}
  \caption{Per-token forward FLOP counts \emph{summed over all heads}.  Multiply by $L$ to obtain the per-layer sequence cost.  For HGRN-1 the mixer is single-head by design ($H=1$); all other models allow arbitrary $H$.  Softmax attention is quadratic in $L$, whereas the linear/recurrent mixers are linear.}
  \label{tab:flops_summary_all_heads}
\end{table}

\paragraph{Baseline: softmax self-attention}
The dot-product matrix $QK^{\top}$ is strictly lower-triangular under causal masking.  Forming and applying it costs $(H\,L(L+1)d_{\mathrm{head}})$ multiplies plus the same number of adds.  Using $d_{\mathrm{model}} = H d_{\mathrm{head}}$ gives
\begin{equation}
  \mathrm{FLOPs}_{\text{softmax}} \;\approx\; 2L^2 d_{\mathrm{model}}.
  \label{eq:softmax_total_heads}
\end{equation}
Importantly the head count cancels, so the quadratic term depends only on the model width.

\paragraph{Vector-state mixers (classical / gated RNNs)}
A single hidden vector $h_t\!\in\!\mathbb{R}^{d_{\mathrm{head}}}$ is maintained \emph{per head}.  Each head therefore needs $5d_{\mathrm{head}}$ FLOPs per token. Aggregating over $H$ heads:
\begin{equation}
  \mathrm{FLOPs}_{\text{vector}} = 5H d_{\mathrm{head}} = 5 d_{\mathrm{model}}.
\end{equation}
For HGRN-1 and Hawk, the reference implementation is single-head; we therefore take $H=1$ and $d_{\mathrm{head}} = d_{\mathrm{model}}$.

\paragraph{Matrix-state mixers (outer-product family)}
Each head carries a dense state $S_t \in \mathbb{R}^{d_{\mathrm{head}}\times d_{\mathrm{head}}}$.
If an update costs $k\,d_{\mathrm{head}}^{2}$ FLOPs per head (where $k$ is a constant that varies between different models), the layer total is:
\begin{equation}
  \mathrm{FLOPs}_{\text{matrix}} = k H d_{\mathrm{head}}^{2} \;=\; k\,\frac{d_{\mathrm{model}}^{2}}{H}.
  \label{eq:matrix_family_general}
\end{equation}
Hence adding more heads \emph{reduces} the cost of these mixers at fixed $d_{\mathrm{model}}$.
Each ``pass'' over the $d_{\mathrm{head}} \times d_{\mathrm{head}}$ matrix either multiplies all entries or adds a rank--1 outer product, each costing $d_{\mathrm{head}}^{2}$ FLOPs.  Summing the passes per token per head gives:
\begin{itemize}
  \item \textit{RetNet / Mamba--2}: five passes $\Rightarrow$ k=5.
  \item \textit{GLA, RWKV--6, HGRN--2}: two extra gating passes (seven total) $\Rightarrow$ k=7.
  \item \textit{DeltaNet (\& Gated)}: one further forget/restore pass (eight total) $\Rightarrow$ k=8.
\end{itemize}

\paragraph{Summary}
Table \ref{tab:flops_summary_all_heads} shows a comparison between all models presented in Table 1. Once head aggregation is included the classical vector mixers (HGRN-1, Hawk) remain linear in $L$ and independent of $H$.  Outer-product and Delta-rule mixers grow as $d_{\mathrm{model}}^{2}/H$—wider models prefer more heads from a FLOP viewpoint—yet are still asymptotically cheaper than softmax self-attention for long sequences. Figure \ref{fig:flop-scaling} shows how the FLOPs scale with sequence lengths for different pure (non-hybrid) token mixers.

