\section{Preliminaries}
\label{sec:preliminaries}

%
We assume familiarity with basic concepts from category theory, such as categories, functors and adjunctions (see, e.g., \cite{Awodey2006CategoryTheory,MacLane1971CategoriesWorking}), and from the theory of $\omega$-regular languages (e.g., \cite{GreenBook}).
%


\subsection{Languages of Infinite Words}
Throughout this paper, we fix a set of symbols $\Sigma = \{ a, b, \dotsc \}$, called an \emph{alphabet}. Let $\words$ denote the set of \emph{finite words} over $\Sigma$ and $\newords$ denote the set of \emph{non-empty words}. We have $\newords = \words \setminus \{\epsilon\}$, where $\epsilon$ stands for the empty word. We often use the notation $au$ or $ua$, where $a \in \Sigma$ and $u \in \words$, for an arbitrary non-empty word. An \emph{infinite word} over $\Sigma$ is a sequence of elements of $\Sigma$ of length $\omega$. An \emph{ultimately periodic word} is an infinite word of the form $uv^\omega \coloneqq uvv\dotsc$, and the set of all ultimately periodic words is written as $\upwords$. A \emph{lasso} is a pair $(u, v) \in \words\times \newords$, with the set of all lassos written as $\lassos$. Intuitively, the lasso $(u,v)$ represents the ultimately periodic word $uv^\omega$. A \emph{lasso language} is a subset of $\lassos$. Similarly, a \emph{language of infinitely periodic words} is a subset of $\upwords$. A lasso language $L$ is \emph{saturated} if $u_1v_1^\omega = u_2v_2^\omega$ implies $(u_1,v_1) \in L \iff (u_2,v_2)\in L$.

Given some $u = a_1\dotsc a_n \in \words$, we write $u^\rev \coloneqq a_n\dotsc a_1$ for the \emph{reverse word of $u$}. While infinite words cannot be reversed, lassos can, because they are finite objects. Thus define the \emph{reverse of a lasso} $(u,av)$ as the lasso $(u,av)^\rev \coloneqq (v^\rev, au^\rev)$. On the level of languages, given a lasso language $L$, we write $L^\rev \coloneqq \{ (u,av)^\rev \mid (u,av) \in \lassos \}$ for the \emph{reverse lasso language of $L$}.

\subsection{Lasso Automata and $\Omega$-Automata}
\emph{Lasso automata} were introduced in \cite{CianciaVenema2012StreamAutomataAreCoalgebras,CianciaVenema2019OmegaAutomataACoalgebraicPerspective} as acceptors of lasso languages.
\begin{definition}[Lasso automaton {\cite{CianciaVenema2012StreamAutomataAreCoalgebras}}]
    A \emph{lasso automaton} is a tuple $A = (X, Y, q,\rho, \sigma, \xi, F)$ where:
    \begin{itemize}
        \item $X$ and $Y$ are disjoint finite sets whose elements are called \emph{states};
        \item $q$ is a state in $X$ called the \emph{initial state};
        \item the functions $\rho: X \times \Sigma \to X$, $\sigma: X \times \Sigma \to Y$ and $\xi: Y \times \Sigma \to Y$ are called \emph{transition functions};
        \item $F$ is a subset of $Y$ whose elements are called \emph{final states}.
    \end{itemize}
\end{definition}
The transition function $\rho$ will often be tacitly used as a function from $X \times \Sigma^*$ to $X$ in the standard way. That is, $\rho(x, \epsilon) \coloneqq x$ and $\rho(x, ua) \coloneqq \rho(\rho(x, u), a)$. This applies analogously to $\xi$.

The lasso automaton structure allows for a natural definition of lasso acceptance. A lasso $(u,av)$ is read as follows: $\rho$ transitions read $u$, $\sigma$ reads $a$, and $\xi$ reads $v$. Formally, given a lasso automaton $A = (X, Y, q,\rho, \sigma, \xi, F)$, define \emph{the lasso language accepted by $A$} as $\Lasso(A) \coloneqq \{ (u,av)\in\lassos \mid \xi(\sigma(\rho(q,u),a),v) \in F \}$. A lasso language is called \emph{regular} if it is accepted by some \emph{finite} lasso automaton.

\begin{example}
    In \Cref{fig:lassoAut} we see two examples of lasso automata for $\Sigma = \{a,b\}$. 
    It can easily be verified that $\Lasso(A_1) = \{ (u, bv) \mid u,v \in \words \}$
    and $\Lasso(A_2) = \{ (ub, a^n) \mid u \in \words, n \in \omega \}$. Note that $\Lasso(A_1)$ is not saturated, since it contains $(\epsilon,ba)$, but not $(b,ab)$.
%
\end{example}
