A state $z$ in a lasso automaton is called \emph{reachable} if there exists a path along $\rho$, $\sigma$ and $\xi$ from the initial state to $z$. If all states in an automaton are reachable, we call it a \emph{reachable automaton}.

A \emph{lasso automaton morphism} is a structure-preserving map between lasso automata. More precisely, given two lasso automata $A_i = (X_i, Y_i, q_i,$ $\rho_i, \sigma_i, \xi_i, F_i)$, for $i \in \{1,2\}$, a lasso automaton morphism is a pair of maps $h = (h^X, h^Y)$ such that $h^X: X_1 \to X_2$ and $h^Y: Y_1 \to Y_2$ satisfy:
\begin{itemize}
    \item $h^X(q_1) = q_2$;
    \item for all $x \in X_1, y \in Y_1, a \in \Sigma$: 
    $h^X(\rho_1(x, a)) = \rho_2(h^X(x), a)$ and \\
    \phantom{xxx} \hfill $h^Y(\sigma_1(x, a)) = \sigma_2(h^X(x), a)$ and $h^Y(\xi_1(y, a)) = \xi_2(h^Y(y), a)$;
    \item  for all $y \in Y_1$: $y \in F_1 \iff h^Y(y) \in F_2$.
\end{itemize}

\begin{remark}
    Consider the endofunctor $G$ on $\Set \times \Set$ defined by $G(X, Y)$ $\coloneqq \langle X^\Sigma \times Y^\Sigma, Y^\Sigma \times 2 \rangle$ on objects \cite{CianciaVenema2012StreamAutomataAreCoalgebras}. Lasso automata are $G$-coalgebras, together with an initial state. Lasso automaton morphisms coincide with initial-state-preserving $G$-coalgebra morphisms.
\end{remark}

In order to capture lasso languages of the form $\{ (u, v) \mid uv^\omega \in L \}$ for an $\omega$-regular language $L$, \cite{CianciaVenema2012StreamAutomataAreCoalgebras} introduces a subclass of lasso automata called $\Omega$-automata. 
%

\begin{definition}[$\Omega$-automaton {\cite{CianciaVenema2012StreamAutomataAreCoalgebras}}]
    An \emph{$\Omega$-automaton} is a lasso automaton $A = (X, Y, q,\rho, \sigma, \xi, F)$ that satisfies the following two conditions.
    \begin{description}
        \item[Circularity] For all $x \in X, av \in \newords, k > 0$:\\
        $\xi(\sigma(x, a),v) \in F \iff \xi(\sigma(x, a),v(av)^k) \in F$.
        \item[Coherence] For all $x \in X, abv \in \newords$:\\  
        $\xi(\sigma(x, a),bv) \in F \iff \xi(\sigma(\rho(x, a),b),va) \in F$.
    \end{description}
\end{definition}

It is shown in \cite{CianciaVenema2012StreamAutomataAreCoalgebras} that for any $\Omega$-automaton $A$, the language $\Lasso(A)$ is \emph{saturated}. Furthermore, $\Omega$-automata accept precisely the languages of the form $\{ (u, v) \mid uv^\omega \in L \}$ for an $\omega$-regular language $L$.

\begin{example}
    In \Cref{fig:lassoAut}, the automaton $A_2$ is an $\Omega$-automaton, and its  corresponding $\omega$-regular language is $(a+b)^*ba^\omega$. The automaton $A_1$ is circular, but not coherent, because $\xi(\sigma(x,b),a) = y_2 \in F$, $\xi(\sigma(\rho(x, b),a),b) = y_1 \notin F$.
\end{example}

\subsection{Wilke Algebras}
Another approach to characterising the ultimately periodic fragments of $\omega$-regular languages is via recognition by Wilke algebra homomorphisms \cite{Wilke93AlgTheoryForRegLanguagesFinInf} (see also \cite[Section~2.5]{PerrinPin2004InfiniteWords}).

\begin{definition}[Wilke algebra {\cite{Wilke93AlgTheoryForRegLanguagesFinInf}}]\label{def:Wilke-alg}
    A \emph{Wilke algebra} is a two-sorted algebra of the form $W = (\fint W, \inft W, \cdot, \times, (-)^\omega)$, where $\fint W, \inft W$ are sets equipped with the operations:
    \begin{equation*}
        \cdot: \fint W \times \fint W \to \fint W, \qquad
        \times: \fint W \times \inft W \to \inft W,
        \qquad
        (-)^\omega: \fint W \to \inft W,
    \end{equation*}
    satisfying the axioms:
    \begin{align*}
        (s \cdot t) \cdot u &= s \cdot (t \cdot u), &
        s \times (t \times \alpha) &= (s \cdot t) \times \alpha, \\
        (s^n)^\omega &= s^\omega, &
        s \times (t \cdot s)^\omega &= (s \cdot t)^\omega.
    \end{align*}
    for all $s, t \in \fint W$, $\alpha \in \inft W$. The axioms in the second line are called \emph{circularity} and \emph{coherence}, respectively.
\end{definition}
If no confusion arises, we write $W = (\fint W, \inft W)$, i.e., we omit the operations.
A \emph{Wilke algebra homomorphism} between $W_1$ and $W_2$ is a pair $f = (\fint f, \inft f)$ of maps $\fint f: \fint W_1 \to \fint W_2$ and $\inft f: \inft W_1 \to \inft W_2$ that preserves the operations $\cdot$, $\times$ and $(-)^\omega$. That is:
\begin{align*}
    \fint f(s \cdot t) &= \fint f(s) \cdot \fint f(t), &
    \inft f(s \times \alpha) &= \fint f(s) \times \inft f(\alpha), \\
    \inft f(s^{\omega}) &= (\fint f(s))^{\omega}.
\end{align*}
The freely generated Wilke algebra with generators $(\Sigma,\emptyset)$ is $(\newords, \upwords)$, where $\cdot$ is finite-word concatenation, $\times$ is finite-infinite-word concatenation, and $(-)^\omega$ is infinite power. Given a Wilke algebra $W$ and a homomorphism $f: (\newords, \upwords) \to W$, we say $f$ \emph{recognises} a language $L$ of ultimately periodic words if $L = (\inft f)\inv(P)$ for some \emph{recognising subset} $P \subseteq \inft W$, and we write $L = \UP(W, f, P)$. The languages recognised by homomorphisms into \emph{finite} Wilke algebras are precisely the languages of the form $\{ uv^\omega \mid uv^\omega \in L \}$ for an $\omega$-regular $L$.

