\subsection{Nested $\tL$-measures as Bilevel Optimization Problems}
\label{sec:3.2}

In this section, we analyze some optimization models that allow us to minimize measures that require a nested $\tL$-measure, in their definition, i.e., given $\x, \blambda \in \R^n$ we aim to compute:
\begin{equation}
\label{eq:NestedMeasure}
\bfrak (\x, \rho) := \min  \rho \big(\x,  \sum_{k=1}^n \lambda_k x_{(k)} \big).
\end{equation}
for a given loss function $\rho$.

We will cast the calculation of this measure as a special class of optimization problems: bilevel optimization problem. A bilevel optimization problem (BOP) represents the relationship in a decision process involving hierarchical decision-making in which an upper-level decision maker aims to optimize its own objective function by selecting a decision that limits the lower-level decision's space, from which the lower-level decision maker needs to select its best decision in terms of its own objective function, see \cite{Bracken1973, Candler1977}.
In case the lower-level problem is a linear optimization program, the most frequent solution method for such BOPs in practice, and the one that we adopt in this section, is to reformulate the model as a single-level problem by means of the Karush-Kuhn-Tucker (KKT) conditions \cite{KKT1939, KKT1951} of the lower-level problem, that allow to incorporate the optimality conditions of this level as constraints in the upper level.  The interested reader is referred to the survey on exact methods for bilevel otimization by \cite{Kleinert2021} for further details.

First, let us rewrite the expression of  $\bfrak (\x, \rho)$ as a BOP. In the lower-level problem, the computation of the $\tL$-measure, $\ell(\x,\blambda) = \sum_{k=1}^n \lambda_k x_{(k)}$, is considered, and which will be represented by a nonnegative variable $\theta \geq 0$, that is
\begin{align}
  \label{cons:N_1}
  \bfrak (\x, \rho) = & \min \rho(\x, \theta) \\ \mbox{s.t. \ } 
  & \theta =  \ell(\x,\blambda) \label{theta:l}
\end{align}

Note that constraint \eqref{theta:l} can be represented as any of the optimization models described in the previous sections. 
Since our goal will be to reformulate this problem as a single level problem, we will focus on the two linear optimization formulations for its computation described in Proposition \ref{prop:L_ksum} and Theorem \ref{theo:L_q}.
Using the $k$-sum reformulation provided in Proposition \ref{prop:L_ksum} we obtain the reformulation detailed in the following result.
\begin{theorem}
\label{thr:nested-1}
Let $\x, \blambda \in \R^n$. Then:
\begin{subequations}
\label{form:N_1}
\begin{align}
\bfrak_1(\x, \rho) = & \min \ \rho(\x, \theta)  \label{cons:N_1_0} \\ \mbox{s.t. \ } 
& \theta = \sum_{k \in \Delta^{+}} |\Delta_{k}| \big((n-k+1) t_{k} + \sum_{i=1}^n v_{ik} \big) - \sum_{k \in \Delta^{-}} |\Delta_{k}| \sum_{i=1}^n d_{ik} x_{i},  \label{cons:N_1_1} \\ 
& \theta = - \sum_{k \in \Delta^{-}} |\Delta_{k}| \big((n-k+1) t_{k} + \sum_{i=1}^n v_{ik} \big) + \sum_{k \in \Delta^{+}} |\Delta_{k}| \sum_{i=1}^n d_{ik} x_{i}, \label{cons:N_1_2} \\ 
& t_k+v_{ik} \geq x_i,                 & \forall i,k \in N,     \label{cons:N_1_3} \\
& \sum_{i=1}^n d_{ik}=n-k+1,           & \forall k \in N,       \label{cons:N_1_4} \\
& t_{k} \in \mathbb{R}, v_{ik} \geq 0, & \forall i,k \in N,     \label{cons:N_1_5} \\
& 0 \le d_{ik} \leq 1,                 & \forall i,k \in N,     \label{cons:N_1_6} \\
& \theta \geq 0.                                                \label{cons:N_1_7}
\end{align}
\end{subequations}
\end{theorem}

\begin{proof}
Note that the dual problem of the $k$-sum problem \eqref{cons:L_2_0}-\eqref{cons:L_2_4} is:
\begin{subequations}
\begin{align}
& \max \ \sum_{k \in \Delta^+} \sum_{i=1}^n d^*_{ik} x_{i} + \sum_{k \in \Delta^-} ((n-k+1)t_k^* + \sum_{i=1}^n v^*_{ik}) \label{cons:Nd_1_0} \\ \mbox{s.t. \ } 
& \sum_{i=1}^n d^*_{ik} = (n-k+1) \Delta_k ,    & \forall k \in \Delta^+,       \label{cons:Nd_1_2} \\
& 0 \le d_{ik}^* \leq \Delta_k,                 & \forall i,k \in \Delta^+,     \label{cons:Nd_1_3} \\
& t^*_k+v^*_{ik} \leq x_i \Delta_k,             & \forall i,k \in \Delta^-,     \label{cons:Nd_1_4} \\
& t^*_{k} \in \mathbb{R}, v^*_{ik} \geq 0,      & \forall i,k \in \Delta^-.     \label{cons:Nd_1_5}
\end{align}
\end{subequations}
Then, by scaling the decision variables and rewriting:
\begin{equation}
    d_{ik}=\frac{d^*_{ik}}{|\Delta_k|}, i \in N, k \in \Delta^+, 
    t_k = - \frac{t_k^*}{|\Delta_k|}, v_{ik} = - \frac{v_{ik}^*}{|\Delta_k|}, i \in N, k \in \Delta^-, 
\end{equation}
we get that problem \eqref{cons:Nd_1_0}- \eqref{cons:Nd_1_5} is equivalent to:
\begin{subequations}
\begin{align}
& \max \ \sum_{k \in \Delta^+} |\Delta_k| \sum_{i=1}^n d_{ik} x_{i} - \sum_{k \in \Delta^-} |\Delta_k| ((n-k+1)t_k + \sum_{i=1}^n v_{ik}) \label{cons:NdE_1_0} \\ \mbox{s.t. \ } 
& \sum_{i=1}^n d_{ik} = (n-k+1),            & \forall k \in \Delta^+,     \label{cons:NdE_1_1} \\
& 0 \le d_{ik} \leq 1,                      & \forall i,k \in \Delta^+,   \label{cons:NdE_1_2} \\
& t_k+v_{ik} \geq x_i,                      & \forall i,k \in \Delta^-,   \label{cons:NdE_1_3} \\
& t_{k} \in \mathbb{R}, v_{ik} \geq 0,      & \forall i,k \in \Delta^-.   \label{cons:NdE_1_4}
\end{align}
\end{subequations}
Therefore, by considering the lower-level primal constraints \eqref{cons:L_2_1}-\eqref{cons:L_2_4} and dual constraints \eqref{cons:NdE_1_1}-\eqref{cons:NdE_1_4}, and both objective functions equivalence, we get the single-level formulation \eqref{cons:N_1_0}-\eqref{cons:N_1_7}
\end{proof}

For the $\tau$-quantile formulation (Theorem \ref{theo:L_q}), and using duality conditions similar to those in the previous result, we obtain the single-level reformulation described in the following result.
\begin{theorem}
\label{thr:nested-2}
Let $\x, \blambda \in \R^n$. Then:
\begin{subequations}
\label{form:N_2}
\begin{align}
\bfrak_2 (\x, \rho) = & \min \ \rho(\x, \theta)  \label{cons:N_2_0} \\ \mbox{s.t. \ } 
& \theta = \sum_{k \in \Delta^{+}} \sum_{i\in N} |\Delta_{k}| \Big( \frac{k}{n} u_{ik} + (1-\frac{k}{n}) v_{ik} \Big) + \sum_{k \in \Delta^{-}} \sum_{i\in N} |\Delta_{k}| \alpha_{ik} x_{i} \notag \\  
& \hspace{0.5cm} + \sum_{k \in N} \sum_{i\in N} \Delta_{k} (1-\frac{k}{n}) x_i, \label{cons:N_2_1} \\ 
& \theta = - \sum_{k \in \Delta^{-}} \sum_{i\in N} |\Delta_{k}| \Big( \frac{k}{n} u_{ik} + (1-\frac{k}{n}) v_{ik} \Big) - \sum_{k \in \Delta^{+}} \sum_{i\in N} |\Delta_{k}| \alpha_{ik} x_{i}  \notag \\ 
& \hspace{0.5cm} + \sum_{k \in N} \sum_{i\in N} \Delta_{k} (1-\frac{k}{n}) x_i, \label{cons:N_2_2} \\ 
& u_{ik} - v_{ik} + \gamma_k = x_i,                 & \forall i,k \in N,  \label{cons:N_2_3} \\
& \sum_{i\in N} \alpha_{ik}=0,                      & \forall k \in N,    \label{cons:N_2_4} \\
& \gamma_k \in \mathbb{R}, u_{ik}, v_{ik} \geq 0,   & \forall i, k \in N, \label{cons:N_2_5} \\
& -\frac{k}{n} \leq \alpha_{ik} \leq 1-\frac{k}{n}, & \forall i, k \in N, \label{cons:N_2_6} \\
& \theta \geq 0.                                                          \label{cons:N_2_7}
\end{align}
\end{subequations}
\end{theorem}

Note that the two proposed single-level optimization models to compute $\bfrak (\x, \rho)$ consist of linear constraints, and the non-linearity arises when $\rho$ is nonlinear. This is true even for the most popular loss functions, the absolute or quadratic deviations, or shape measures such as the skewness or kurtosis coefficients, as well as some of the already introduced functions.

In the following, we give an illustrative example detailing how to proceed in the important case where the loss function is the absolute deviation.

\hfill

\begin{example}
    Let us consider the loss function $\rho(\x,\theta)=\dsum_{i\in N}|\x_i-\theta|$ which induces the mean absolute deviation with respect to any  $\tL$-measure:
\begin{equation}
    MeanAD_{\blambda}(\x)  = \frac{1}{n} \sum_{i=1}^n \left|\x_i - \sum_{k=1}^n \lambda_k x_{(k)}\right|,
\end{equation}
Introducing variables $r_{i}^{+}, r_{i}^{-} \geq 0$, $i \in N$, to linearize the absolute values, we get that each of the addends in the above sum can be expressed as:
$$
\begin{aligned}
&  |x_i - \sum_{k=1}^n \lambda_k x_{(k)} | = r_{i}^{+}+r_{i}^{-}\\
& x_i - \sum_{k=1}^n \lambda_k x_{(k)} =  r_{i}^{+}-r_{i}^{-}, \\
& r_{i}^{+}, r_{i}^{-} \geq 0, r_{i}^{+} r_{i}^{-}=0, i \in N.
\end{aligned}
$$

Thus, we have that: 
\begin{subequations}
\label{form:bilevel_2}
\begin{align}
  MeanAD_{\blambda}(\x) = & \min \sum_{i=1}^n (r_{i}^{+} + r_{i}^{-}) &         \label{cons:BL_2_0} \\ \text{s.t.: } 
  & r_{i}^{+} - r_{i}^{-} = x_i - \theta,                          & i \in N,   \label{cons:BL_2_1} \\
  & r_{i}^{+}, r_{i}^{-} \geq 0,                                   & i \in N,   \label{cons:BL_2_3} \\
  & (r_{i}^{+}, r_{i}^{-}): \SOS,                                  & i \in N,   \label{cons:BL_2_4} \\
  & \theta = \sum_{k=1}^n \lambda_k x_{(k)}
\end{align}
\end{subequations}

where, \SOS  stands for the Special Ordered Sets of type 1, introduced by \cite{Beale1970}, which are a special set of variables for which at most one of them can take a non-zero value, while all other remain zero.
Then, following the same rationale as in Proposition \ref{prop:L_ksum} or Theorem \ref{theo:L_q}, one can rewrite the problem as a single-level linear optimization problem with \SOS constraints.
\end{example}

Finally, we would like to highlight that tailored models for cases where the nested measure (the $\tL$-measure) has some simplified form, as the maximum, the minimum, the mean or the quantile, give rise to simpler optimization models  (\eqref{form:max_linear}, \eqref{form:min_linear}, \eqref{form:mean_linear} or \eqref{form:quant_lp}, respectively). 

\section{A new family of quadratic measures, $\QO$-measures}
\label{sec:4}

In this section we introduce a new family of measures that extend the definition of $\tL$-measure by means of quadratic terms, and that include as particular cases the most popular measures of scale, as well as the linear $\tL$-measures.

\hfill 

\begin{definition}
\label{eq:QO_M}
Let $\x \in \mathbb{R}^n$, and a  matrix $\M = (m_{ij})_{i,j=1}^n \in \mathbb{R}^{n\times n}$, we define the quadratic ordered operator, namely $\QO$-measure, as:
\begin{equation}
\QO(\x, \M) = \sum_{i,j=1}^n m_{ij} x_{(i)} x_{(j)} %= \sum_{i=1}^n m_{ii} x_{(i)}^2 + \sum_{\substack{ i,j=1 \\ i \neq j }}^n m_{ij} x_{(i)} x_{(j)} \hspace{-10cm} 
\end{equation}
\end{definition}

Note that particular choices of $\M$ result in different measures which require quadratic terms. 
It is straightforward to check that $\QO(x, \M)$ is continuous,  symmetric, and (strictly) convex if and only if $\M$ is a (positive) semidefinite matrix. 
%In case $\M$ is positive definite, then the problem of minimizing $\QO_{\M}(x)$ has a unique minimum.
Quadratic terms allow us to measure interactions between the different elements of the vector, defined as product of the components, that is, one can consider the interaction between the maximum and the minimum value, $x_{(1)} x_{(n)},$
or the sum of the pairs of consecutive values, 
$x_{(1)} x_{(2)}(x) + x_{(2)} x_{(3)} + ... + x_{(n-1)} x_{(n)}.$
Note that, this approach can be generalized to include interactions of other orders by considering tensors instead of matrices.

Before analyzing the optimization-based approach that we propose to compute this type of operator, we provide some well-known interesting measures that can be rewritten as a $\QO$-measure.

\hfill

\begin{example}[Squared Deviation with respect to a $\tL$-measure]\label{ex:2}
Let us consider the nested $\tL$-measure where $\rho$ is the mean squared deviation function and $\ell (\x, \blambda) = \sum_{k=1}^n \lambda_k x_{(k)}$, this is:
$$\bfrak(\x,\rho) = \sum_{i = 1}^n \big( x_i - \ell (\x, \blambda) \big)^2.$$
Note that:
$$
\begin{aligned}
\sum_{i = 1}^n \big( x_i - \ell (\x, \blambda) \big)^2  
& = \sum_{i = 1}^n \big( x_i - \sum_{j = 1}^n \lambda_j x_{(j)} \big)^2 =  \sum_{i = 1}^n \big( x_{(i)} - \sum_{j = 1}^n \lambda_j x_{(j)} \big)^2 \\
& = \sum_{i=1}^n x_{(i)}^2 + \sum_{i=1}^n \Big( \sum_{j = 1}^n \lambda_j x_{(j)} \Big)^2 - \sum_{i=1}^n2 x_{(i)} \sum_{j=1}^n \lambda_j x_{(j)} \\
& = \sum_{i=1}^n x_{(i)}^2 + n \sum_{i=1}^n \lambda_{i}^2 x_{(i)}^2 + n \sum_{\substack{i,j=1\\ i\neq j} }^n \lambda_i \lambda_j x_{(i)} x_{(j)} - 2  \sum_{i=1}^n \lambda_{i} x_{(i)}^2 - 2 \sum_{\substack{i,j=1\\ i\neq j} }^n \lambda_j x_{(i)} x_{(j)} \\
& = \sum_{i=1}^n (1+n \lambda_i^2 - 2 \lambda_i) x_{(i)}^2 + \sum_{\substack{i,j=1\\ i\neq j} }^n (n\lambda_i \lambda_j - 2 \lambda_j) x_{(i)} x_{(j)}.
\end{aligned}
$$
Thus, choosing $\M = (m_{ij})_{i,j = 1}^n \in \mathbb{R}^{n \times n}$ with
$$m_{ij} = \begin{cases}
1+n \lambda_i^2 - 2 \lambda_i,      & i = j, \\
n\lambda_i \lambda_j - 2 \lambda_j,  & i \neq j,
\end{cases}$$
we get that $\bfrak(\x,\rho) = \QO(\x, \M)$.
\end{example}

\begin{example}[Variance]
The variance of the vector $\x$ can be obtained as a quadratic ordered measure by choosing:
$$\M = \frac{1}{n} \cdot \begin{pmatrix}
1-\frac{1}{n}  & -\frac{1}{n}  & \ldots       & -\frac{1}{n} \\ 
-\frac{1}{n}   & 1-\frac{1}{n} & \ddots       & \vdots       \\ 
\vdots         & \ddots        & \ddots       & -\frac{1}{n} \\ 
-\frac{1}{n}   & \ldots        & -\frac{1}{n} & 1-\frac{1}{n}
\end{pmatrix}$$
then $\QO(\x , \M)$ represents the variance of the values, i.e.,
$$\displaystyle{\frac{1}{n} \sum_{i=1}^n \big(x_i - \frac{1}{n} \sum_{j=1}^n x_j \big)^2}.$$
\end{example}

