& = \sum_{k \in N} \left[ \left(\sum_{i,j \in N} x_{ij}^k c_{ij} - \frac{1}{n} \sum_{\ell \in N} \sum_{i,j \in N} x_{ij}^\ell c_{i j}\right)^2 + \frac{2}{n} \left(\sum_{\ell \in N} \sum_{i,j \in N} x^\ell_{ij} c_{ij} \right)^2 - \frac{2n}{n^2} \left(\sum_{\ell \in N} \sum_{i,j \in N} x_{ij}^{\ell} c_{ij} \right)^2 \right] = \\
& = \sum_{k \in N} \left(\sum_{i,j \in N} x_{ij}^k c_{ij} - \frac{1}{n} \sum_{\ell \in N} \sum_{i,j \in N} x_{ij}^\ell c_{i j}\right)^2 
\notag
\end{align*}
\end{subequations}

which attends for the assignments minimizing the variance.
