\begin{example}[$(r,s)$-winsorized variance]
The $(r,s)$-winsorized variance is proportional to,
\begin{equation}
\hspace{-3cm}  r \big(x_{(r+1)} - W_{(r,s)}(\x)\big)^2 + \sum_{i=r+1}^{n-s} \big(x_{(i)} - W_{(r,s)}(\x) \big)^2 + s \big(x_{(n-s)} - W_{(r,s)}(\x) \big)^2 \hspace{-3cm} \label{eq:win-variance}
\end{equation}
where $W_{(r,s)}(\x)$ is the $(r,s)$-winsorized mean in Table \ref{table:location_lambdas}, by means of 
$$m_{ij} = \begin{cases}
1+r-\frac{(r+1)^2}{n}, & i = j = r+1, \\
1+s-\frac{(s+1)^2}{n}, & i = j = n-s, \\
1-\frac{1}{n},          & r+1 < i=j < n-s, \\
-\frac{(rs+r+s+1)}{n}, & i=r+1 \text{ and } j=n-1 \text{ (and vicerversa)}, \\
-\frac{(r+1)}{n},      & i=r+1 \text{ and } r+1<j<n-s \text{ (and vicerversa)}, \\
-\frac{(s+1)}{n},      & i=n-s \text{ and } r+1<j<n-s \text{ (and vicerversa)}, \\
-\frac{1}{n},         & r+1 < i \neq j < n-s, \\
0,                     & otherwise.
\end{cases}$$
\end{example}
