Pseudo code for the algorithm is provided (Algorithm \ref{alg:hybrid_control}), and its flowchart is given in Fig. \ref{fig:system_diagram}. In the next section, we will analyze test cases and show that this practical stability intuition indeed holds true.


\begin{algorithm}[h]
%\small
\caption{Optimization-Augmented Force Control}
\label{alg:hybrid_control}
\begin{algorithmic}[1]
\Require Target configuration $\mathbf{q}_{\text{target}}$, Target force $\mathbf{F}_{\text{target}}$, Target position in task space $\mathbf{pos}_{\text{target}}$
\Require Robot state: $\mathbf{q}$, $\mathbf{\dot{q}}$, $\mathbf{F}$, $\mathbf{pos}$
\Require Robot dynamics: Mass matrix $\mathbf{M}(\mathbf{q})$, Coriolis matrix $\mathbf{C}(\mathbf{q}, \mathbf{\dot{q}})$, Gravity vector $\mathbf{G}(\mathbf{q})$
\Require Controller gains: $K_p$, $K_d$, $K_i$ (PID), $K_p^F$, $K_i^F$ (PI for force), $K_p^x$, $K_d^x$ (Impedance)
\Require Threshold $\epsilon$, $\epsilon_{pos}$

\While{$(\|\mathbf{q}_{\text{target}} - \mathbf{q}\| > \epsilon \lor \|\mathbf{pos}_{\text{target}} - \mathbf{pos}\| > \epsilon_{pos})$}

    \State \textbf{// Compute Optimization-Based Control (PID)}
    \State $\mathbf{\tau}_{\text{optimization}} = K_p (\mathbf{q}_{\text{target}} - \mathbf{q}) + K_d (\mathbf{\dot{q}}_{\text{target}} - \mathbf{\dot{q}}) + K_i \int (\mathbf{q}_{\text{target}} - \mathbf{q}) dt$

    \State \textbf{// Compute Force Control (PI)}
    \State $\mathbf{F}_{\text{error}} = \mathbf{F}_{\text{target}} - \mathbf{F}$
    \State $\mathbf{F}_{\text{cmd}} = K_p^F \mathbf{F}_{\text{error}} + K_i^F \int \mathbf{F}_{\text{error}} dt$
    \State $\mathbf{\tau}_{\text{contact}} = \mathbf{J}^T \mathbf{F}_{\text{cmd}}$

    \State \textbf{// Compute Cartesien Impedance Control }
    \State $\mathbf{x}_{\text{error}} = \mathbf{pos}_{\text{target}} - \mathbf{pos}$
    \State $\mathbf{F}_{\text{impedance}} = K_p^x \mathbf{x}_{\text{error}} + K_d^x (\mathbf{\dot{pos}}_{\text{target}} - \mathbf{\dot{pos}})$
    \State $\mathbf{\tau}_{\text{position}} = \mathbf{J}^T \mathbf{F}_{\text{impedance}}$

    \State \textbf{// Compute Final Commanded Torque}
    \State $\mathbf{\tau}_{\text{cmd}} = \mathbf{\tau}_{\text{optimization}} + \mathbf{\tau}_{\text{contact}} + \mathbf{\tau}_{\text{position}}$

    \State \textbf{// Apply Inverse Dynamics Compensation}
    \State $\mathbf{\tau} = \mathbf{M}(\mathbf{q}) \mathbf{\ddot{q}} + \mathbf{C}(\mathbf{q}, \mathbf{\dot{q}}) \mathbf{\dot{q}} + \mathbf{G}(\mathbf{q}) + \mathbf{\tau}_{\text{cmd}}$

    \State \textbf{// Apply Torque to Robot Actuators}
    \State Send $\mathbf{\tau}$ to robot

    \State \textbf{// Update Robot State}
    \State Read $\mathbf{q}, \mathbf{\dot{q}}, \mathbf{F}, \mathbf{pos}$
\EndWhile
\end{algorithmic}
\end{algorithm}

