\begin{lemma} \label{lem:lipschitz_continuity_of_solutions_kernel_w}
    \cfconsiderloaded{lem:lipschitz_continuity_of_solutions_kernel_w}
    %
    Assume \cref{set:stability_w},
    %
    let $\eta, c, L, K \in [0, \infty)$,
    %
    assume $cL < 1$ and $\eta L < 1$,
    %
    let $f \colon \R^\dm \times \R^{\abs{A}} \to \R$ be measurable,
    %
    assume for all $x, y \in \R^\dm$, $r, s \in \R^{\abs{A}}$ that $\abs{ f(x,r) - f(x, s) } \le L \max_{a \in A} \abs{r(a) - s(a)}$ and $\abs{f(x,r) - f(y, r)} \le K \norm{x - y}$,
    %
    let $\tker^{\pr{a}} \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $a \in A$, be stochastic kernels,
    %
    assume for all $x \in \R^\dm$, $a \in A$ that $\int_{\R^\dm} \abs{\w(y)} \tker^{\pr{a}}(x, \dxx y) \le c \w(x)$ and $\int_{\R^\dm} \norm{y} \tker^{\pr{a}}(x, \dxx y) < \infty$,
    %
    assume
    %
    \begin{equation}
        \begin{split}
            \sup_{(x, a) \in \R^\dm \times A} \abs{\w(x)}^{-1} \int_{\R^\dm} \abs{f\pr{ y, 0 }} \tker^{\pr{a}}(x, \dxx y) < \infty,
        \end{split}
    \end{equation}
    %
    assume for all $x, y \in \R^\dm$, $a \in A$ that $\wdist_\dm \pr{ \tker^{\pr{a}}(x, \cdot), \tker^{\pr{a}}(y, \cdot) } \le \eta \norm{x - y}$.
    %
    Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:lipschitz_continuity_of_solutions_kernel_w_ex_uniq} there exists a unique $u \in \W$ such that for every $x \in \R^\dm$, $a \in A$ it holds that
        \begin{equation}
            \int_{\R^\dm} \abs{ f\pr{y, u(y)} } \tker^{\pr{a}}\pr{x, \dxx y} < \infty \qquad \text{and} \qquad \pr{u\pr{x}}\pr{a} = \int_{\R^\dm} f\pr{y, u(y)} \tker^{\pr{a}}\pr{x, \dxx y}
        \end{equation}
        and
        \item \label{item:lipschitz_continuity_of_solutions_kernel_w_result} it holds for all $x, y \in \R^\dm$, $a \in A$ that 
        \begin{equation} \label{eq:lipschitz_continuity_of_solutions_kernel_w}
            \abs{ (u(x))(a) - (u(y))(a)} \le \tfrac{\eta K}{1 - \eta L} \norm{x - y}
        \end{equation}
    \end{enumerate}
    %
    \cfout.    
\end{lemma}

\begin{mproof}{\cref{lem:lipschitz_continuity_of_solutions_kernel_w}}
    First, observe that the assumption that $\w$ is measurable,
    %
    the assumption that $cL < 1$,
    %
    the assumption that for all $x \in \R^\dm$, $r,s \in \R^{\abs{A}}$ it holds that $\abs{ f\pr{x,r} - f\pr{x,s} } \le L \max_{a \in A} \abs{r\pr{a} - s\pr{a}}$,
    %
    the assumption that for all $x \in \R^\dm$, $a \in A$ it holds that $\int_{\R^\dm} \abs{\w(y)} \tker^{\pr{a}}\pr{x, \dxx y} \le c \w(x)$,
    %
    the assumption that $\sup_{(x, a) \in \R^\dm \times A} \abs{\w(x)}^{-1} \int_{\R^\dm} \abs{f\pr{ y, 0 }} \tker^{\pr{a}}(x, \dxx y) < \infty$,
    %
    and \cite[Lemma~2.2]{beck2023nonlinctrl} (applied with $c \with c$, $L \with L$, $\pr{\X, \mathcal{X}} \with \pr{\R^\dm, \cB(\R^\dm)}$, $A \with A$, $\pr{\tker_a}_{a \in A} \with \pr{\tker^{\pr{a}}}_{a \in A}$, $f \with f$, $\w \with \br{ \R^\dm \ni x \mapsto \br{ A \ni a \mapsto \w(x) \in \pr{0,\infty} } \in \pr{0, \infty}^{\abs{A}} }$ in the notation of \cite[Lemma~2.2]{beck2023nonlinctrl}) demonstrates \cref{item:lipschitz_continuity_of_solutions_kernel_w_ex_uniq}.
    %
    %
    Throughout the remainder of this proof let $u_n \colon \R^\dm \rightarrow \R^{\abs{A}}$, $ n \in \N_0$, satisfy for all $n \in \N$, $x \in \R^\dm$, $a \in A$ that $u_0 = 0$ and 
    \begin{equation} \label{eq:lipschitz_continuity_of_solutions_kernel_w_def_iterate}
        \begin{split}
            (u_n(x))(a) = \int_{\R^\dm} f\pr{y, u_{n - 1}(y)} \tker^{\pr{a}}(x, \dxx y).
        \end{split}
    \end{equation}
    %
    %
    Next, note that the assumption that for all $a \in A$ it holds that $\tker^{\pr{a}}$ is a stochastic kernel,
    %
    the assumption that for all $x \in \R^\dm$, $r, s \in \R^{\abs{A}}$ it holds that $|f(x, r) - f(x, s)| \le L \max_{a \in A} |r(a)-s(a)|$,
    %
    the assumption that $cL \in [0,1)$,
    %
    the assumption that for all $x \in \R^\dm$, $a \in A$ it holds that $\int_{\R^\dm} \abs{\w(y)} \tker^{\pr{a}}(x, \dxx y) \le c \w(x)$,
    %
    the assumption that $\sup_{(x, a) \in \R^\dm \times A} \abs{\w(x)}^{-1} \int_{\R^\dm} \abs{f(y, 0)} \tker^{\pr{a}}(x, \dxx y) < \infty$,
    %
    and induction ensure for all $n \in \N_0$ that $u_n \in \fW$.
    %
    Combining the assumption that for all $x \in \R^\dm$, $r, s \in \R^A$ it holds that $ |f(x,r) - f(x, s)| \le L \max_{a \in A} | r(a) - s(a) |$
    %
    and the assumption that $cL \in [0,1)$
    %
    with \cref{item:lipschitz_continuity_of_solutions_kernel_w_ex_uniq}
    %
    yields that $ \lim_{n \to \infty} \big( \sup_{(x,a) \in \R^\dm \times A}  \abs{\w(x)}^{-1} \abs{(u_n(x))(a) - (u(x))(a)} \big) = 0$.
    %
    We prove by induction that for all $n \in \N_0$, $x, y \in \R^\dm$, $a \in A$ it holds that 
    \begin{equation} \label{eq:lipschitz_continuity_of_fixed_point_iterates_kernel_w}
        \abs{ (u_n(x))(a) - (u_n(y))(a) } \le  \br*{\eta K \SmallSum{i = 0}{n - 1} ( \eta L )^i} \norm{x - y}.
    \end{equation}
    Note that for all $x, y \in \R^\dm$, $a \in A$ it holds that $ | (u_0(x))(a) - (u_0(y))(a) | = 0 = [\eta K \sum_{i = 0}^{-1} (\eta L)^i] \|x - y\| $.
    %
    This proves \eqref{eq:lipschitz_continuity_of_fixed_point_iterates_kernel_w} for the base case $n = 0$.
    %
    For the induction step $\N_0 \ni (n - 1) \induct n \in \N$ fix $n \in \N$ and assume for all $l \in \N_0 \cap [0, n - 1] $, $x, y \in \R^\dm$, $a \in A$ that
    \begin{equation}
        \abs{ (u_l(x))(a) - (u_l(y))(a) } \le \br*{\eta K \SmallSum{i = 0}{l - 1} ( \eta L )^i} \norm{x - y}.
    \end{equation}
    %
    %
    Moreover, note that for all $x, y \in \R^\dm$, $a \in A$, $\gamma \in \coup_\dm( \tker^{\pr{a}}(x, \cdot ), \tker^{\pr{a}}(y, \cdot))$, $B \in \Borel(\R^\dm)$ it holds that $\gamma(B \times \R^\dm) = \tker^{\pr{a}}(x, B)$ and $\gamma(\R^\dm \times B) = \tker^{\pr{a}}(y, B)$.
    %
    Combining this, \eqref{eq:lipschitz_continuity_of_solutions_kernel_w_def_iterate},
    %
    the triangle inequality,
    %
    the assumption that for all $x, y \in \R^\dm$, $r, s \in \R^A$ it holds that $\abs{ f(x,r) - f(x,s) } \le L \max_{a \in A} \abs{r(a) - s(a)} $ and $\abs{f(x,r) - f(y, r)} \le K \norm{x - y}$,
    %
    and the induction hypothesis that for all $l\in \N_0 \cap \br{ 0, n - 1 } $, $x, y \in \R^\dm$, $a \in A$ it holds that $\abs{ (u_l(x))(a) - (u_l(y))(a) } \le \br{ \eta K \sum_{i = 0}^{l - 1} (\eta L)^i } \norm{x - y}$ imply for all $x, y \in \R^\dm$, $a \in A$, $\gamma \in \coup_\dm(\tker^{\pr{a}}(x, \cdot), \tker^{\pr{a}}(y, \cdot))$ that
    \begin{align}
            \abs{ (u_n(x))(a) - (u_n(y))(a)} &= \abs*{ \int_{\R^\dm} f(\bfx, u_{n - 1}(\bfx)) \tker^{\pr{a}}(x, \dxx \bfx) - \int_{\R^\dm} f(\bfy, u_{n - 1}(\bfy)) \tker^{\pr{a}}(y, \dxx\bfy)} \nonumber \\
            %
            %
            &= \abs*{ \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} f(\bfx, u_{n - 1}(\bfx)) \gamma(\dxx(\bfx, \bfy)) - \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} f(\bfy, u_{n - 1}(\bfy)) \gamma(\dxx(\bfx, \bfy)) } \nonumber \\
            %
            %
            &\le \int_{\R^\dm \times \R^\dm}\hspace{-0.5cm} \abs*{ f(\bfx, u_{n - 1}(\bfx)) - f(\bfy, u_{n - 1}(\bfy)) } \gamma (\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            &\le \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs*{ f(\bfx, u_{n - 1}(\bfx)) - f(\bfx, u_{n - 1}(\bfy)) } \gamma (\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            %
            &\quad + \int_{\R^\dm \times \R^\dm}\hspace{-0.5cm} \abs*{ f(\bfx, u_{n - 1}(\bfy)) - f(\bfy, u_{n - 1}(\bfy)) } \gamma (\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            &\le L \int_{\R^\dm \times \R^\dm}  \max_{b \in A} \abs{ (u_{n - 1}(\bfx))(b) - (u_{n - 1}(\bfy))(b) } \gamma(\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            %
            &\quad+ K \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} \norm{ \bfx - \bfy } \gamma(\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            &\le L \br*{ \eta K \SmallSum{i = 0}{n - 2} (\eta L)^i } \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} \norm{\bfx - \bfy} \gamma(\dxx(\bfx, \bfy)) + K \!\! \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} \norm{\bfx - \bfy} \gamma(\dxx(\bfx, \bfy)) \nonumber \\
            %
            %
            %
            &= \br*{K \SmallSum{i = 0}{n - 1}(\eta L)^i} \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} \norm{\bfx - \bfy} \gamma(\dxx(\bfx, \bfy)).
    \end{align}
    %
    %
    This and the assumption that for all $x, y \in \R^\dm$, $a \in A$ it holds that $\wdist_\dm ( \tker^{\pr{a}}(x, \cdot), \tker^{\pr{a}}(y, \cdot) ) \le \eta  \norm{x - y} $ assure for all $x, y \in \R^\dm$, $a\in A$ that
    \begin{align}
        \abs{ (u_n(x))(a) - (u_n(y))(a) } &\le  \br*{ K \SmallSum{i = 0}{n - 1} (\eta L)^i } \inf_{\gamma \in \coup_\dm(\tker^{\pr{a}}(x,\cdot), \tker^{\pr{a}}(y,\cdot))} \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} \norm{\bfx - \bfy} \gamma(\dxx(\bfx, \bfy)) \\
        %
        &= \br*{K \SmallSum{i = 0}{n - 1} (\eta L)^i}  \wdist_\dm \big( \tker^{\pr{a}}(x, \cdot), \tker_{\pr{a}}(y, \cdot) \big) \le  \br*{ \eta K \SmallSum{i = 0}{n - 1} (\eta L)^i } \norm{x - y}. \nonumber
    \end{align}
    This and induction prove \eqref{eq:lipschitz_continuity_of_fixed_point_iterates_kernel_w}.
    %
    Furthermore, note that the assumption that $\eta L \in [0,1)$ ensures for all $n \in \N_0$ that $ \sum_{i = 0}^{n - 1} (\eta L)^i \le \sum_{i = 0}^{\infty} (\eta L)^i = \frac{1}{1 - \eta L}$.
    %
    This yields that for all $n \in \N_0$, $x,y \in \R^\dm$, $a \in A$ it holds that 
    \begin{equation}
        \abs{ (u_n(x))(a) - (u_n(y))(a) } \le \tfrac{\eta K}{1 - \eta L} \|x - y\|.
    \end{equation}
    %
    Combining this with the fact that $\lim_{n \to \infty} \big( \sup_{x \in \R^\dm, a \in A} \abs{\w(x)}^{-1} \abs{ (u_n(x))(a) - (u(x))(a) } \big) = 0$ establishes for all $x,y \in \R^\dm$, $a \in A$ that %\orange{(validity)}
    %
    \begin{equation}
        \abs{ (u(x))(a) - (u(y))(a) } = \lim_{n \rightarrow \infty} \abs{ (u_n(x))(a) - (u_n(y))(a) } \le \tfrac{\eta K}{1 - \eta L} \| x - y \|.
    \end{equation}
    This proves \cref{item:lipschitz_continuity_of_solutions_kernel_w_result}. The proof of \cref{lem:lipschitz_continuity_of_solutions_kernel_w} is thus complete.
\end{mproof}

