    This,
    %
    the triangle inequality,
    %
    and the assumption that for all $x, y \in \R^\dm$, $r, s \in \R^{\abs{A}}$ it holds that $\abs{ f(x,r) - f(x,s) } \le L \max_{a \in A} \abs{ r(a) - s(a) }$ and $\abs{ f(x,r) - f(y, r) } \le K \norm{x - y}$
    %
    demonstrate for all $x, y \in \R^\dm$ that 
    \begin{align}
        \begin{split}
            \abs*{ f(x, u_2(x)) - f(y, u_2(y)) } &\le \abs{ f(x, u_2(x)) - f(x, u_2(y)) } + \abs{f(x, u_2(y)) - f(y, u_2(y))}\\
            %
            %
            &\le L \max_{a \in A} \abs{ (u_2(x))(a) - (u_2(y))(a) } + K \norm{x - y} \\
            %
            %
            &\le \pr*{L \tfrac{\eta K}{1 - \eta L} + K} \norm{x - y} = \tfrac{K}{1 - \eta L} \norm{x - y}.
        \end{split}
    \end{align}
    %
    %
    Combining this,
    %
    the fact that for all $x \in \R^\dm$, $a \in A$, $\gamma \in \coup_\dm(\tker_{1}^{\pr{a}}(x, \cdot), \tker_{2}^{\pr{a}}(x,\cdot))$, $B \in \Borel(\R^\dm)$ it holds that $\gamma(B \times \R^\dm) = \tker_{1}^{\pr{a}}(x, B)$ and $\gamma(\R^\dm \times B) = \tker_{2}^{\pr{a}}(x, B)$,
    %
    the triangle inequality,
    %
    the assumption that for all $x \in \R^\dm$, $r,s\in \R^{\abs{A}}$ it holds that $\abs{ f(x,r) - f(x,s) } \le L \max_{a \in A} \abs{r(a) - s(a)}$,
    %
    and the assumption that for all $i \in \{1,2\}$, $x \in \R^\dm$ $a \in A$ it holds that $\int_{\R^\dm} \abs{\w(\bfx)} \tker^{\pr{a}}_i(x, \dxx \bfx) \le c \w(x)$
    %
    with \cref{item:stability_kernel_w_kernel_ex_uniq}
    %
    assures for all $x \in \R^\dm$, $a \in A$, $\gamma \in \coup_\dm(\tker_{1}^{\pr{a}}(x, \cdot), \tker_{2}^{\pr{a}}(x, \cdot))$ that
    \begin{align}
        \begin{split}
            \tfrac{\abs{ (u_1(x))(a) - (u_2(x))(a) }}{\abs{\w(x)}} &= \tfrac{1}{\abs{\w(x)}} \abs*{ \int_{\R^\dm} f\pr{\bfx, u_1(\bfx)} \tker_{1}^{\pr{a}}(x, \dxx \bfx) - \int_{\R^\dm} f\pr{\bfy, u_2(\bfy)} \tker_{2}^{\pr{a}}(x, \dxx \bfy) }  \\
            %
            %
            &= \tfrac{1}{\abs{\w(x)}} \abs*{ \int_{\R^\dm \times \R^\dm} \hspace{-0.7cm} f\pr{ \bfx, u_1(\bfx) } - f\pr{\bfy, u_2(\bfy)} \gamma (\dxx (\bfx, \bfy)) } \\
            %
            %
            &\le \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs*{ f\pr{ \bfx, u_1(\bfx) } - f\pr{\bfy, u_2(\bfy)} } \gamma (\dxx (\bfx, \bfy)) \\
            %
            %
            &\le \tfrac{1}{\abs{\w(x)}}  \pr[\bigg]{\int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{f\pr{ \bfx, u_1(\bfx) } - f\pr{\bfx, u_2(\bfx)}} \gamma(\dxx(\bfx, \bfy)) \\
            %
            %
            %
            &\quad+ \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{f\pr{ \bfx, u_2(\bfx) } - f\pr{\bfy, u_2(\bfy)}} \gamma(\dxx(\bfx, \bfy))}  \\
            %
            %
            &\le \tfrac{1}{\abs{\w(x)}} \pr[\bigg]{L \int_{\R^\dm \times \R^\dm} \max_{b \in A} \abs{ (u_1(\bfx))(b) - (u_2(\bfx)(b) } \gamma(\dxx(\bfx, \bfy)) \\
            %
            %
            %
            &\quad+ \tfrac{K}{1 - \eta L} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfx - \bfy} \gamma (\dxx (\bfx, \bfy))} \\
            %
            %
            %
            &\le \tfrac{L}{\abs{\w(x)}} \br[\bigg]{ \sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{\abs{ (u_1(y))(b) - (u_2(y))(b) } }{ \abs{\w(y)} }} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{\w(\bfx)} \gamma (\dxx (\bfx, \bfy)) \\
            %
            %
            %
            &\quad+ \tfrac{K}{(1 - \eta L) \abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfx - \bfy} \gamma (\dxx (\bfx, \bfy))\\
            %
            %
            %
            &\le cL \br[\bigg]{ \sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{\abs{ (u_1(y))(b) - (u_2(y))(b) } }{ \abs{\w(y)} }} + \tfrac{K}{(1 - \eta L) \abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfx - \bfy} \gamma (\dxx (\bfx, \bfy)).
        \end{split}
    \end{align}
    %
    %
    Hence, it holds for all $x \in \R^\dm$, $a \in A$ that
    \begin{align}
        \begin{split}
            &\tfrac{\abs{ (u_1(x))(a) - (u_2(x))(a) }}{\abs{\w(x)}} - cL \br[\bigg]{ \sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{\abs{ (u_1(y))(b) - (u_2(y))(b) } }{ \abs{\w(y)} }}\\
            %
            %
            %
            &\quad\le \tfrac{K}{(1 - \eta L) \abs{\w(x)}} \pr*{\inf_{\gamma \in \coup_\dm( \tker_{1}^{\pr{a}}(x, \cdot), \tker_{2}^{\pr{a}}(x, \cdot ))} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfx - \bfy} \gamma (\dxx (\bfx, \bfy))} \\
            %
            %
            %
            &\quad= \tfrac{K}{1 - \eta L} \tfrac{\wdist_\dm( \tker_{1}^{\pr{a}}(x, \cdot), \tker_{2}^{\pr{a}}(x, \cdot) )}{\abs{\w(x)}}.
        \end{split}
    \end{align}
    %
    %
    Combining this,
    %
    the assumption that $cL < 1$,
    %
    and \cref{item:stability_kernel_w_kernel_ex_uniq}
    %
    shows that 
    \begin{equation}
        \br[\bigg]{\sup_{(x, a) \in \R^\dm \times A}\!\!\!\! \tfrac{\abs{ (u_1(x))(a) - (u_2(x))(a) }}{\w(x)} } \le \tfrac{K}{(1 - \eta L) (1 - cL)} \br[\bigg]{ \sup_{(y, b) \in \R^\dm \times A} \!\!\!\! \tfrac{\wdist_\dm \pr{ \tker_{1}^{\pr{b}}(y, \cdot), \tker_{2}^{b}(y, \cdot) }}{\abs{\w(y)}} }.
    \end{equation}
    %
    This proves \cref{item:stability_kernel_w_kernel_result}. The proof of \cref{lem:stability_kernel_w_kernel} is thus complete.
\end{mproof}


\cfclear
\begin{propo} \label{prop:stability_kernel_w}
    \cfconsiderloaded{prop:stability_kernel_w}
    %
    Assume \cref{set:stability_w},
    %
    let $\eta, c, K \in [0, \infty)$,
    %
    let $L_i \in [0, \infty)$, $i \in \{1,2\}$,
    %
    assume for all $i \in \{1,2\}$ that $cL_i < 1$ and $\eta L_2 < 1$,
    %
    let $f_i \colon \R^\dm \times \R^{\abs{A}} \to \R$, $i \in \{1, 2\}$, be measurable, 
    %
    assume for all $i \in \{1,2\}$, $x, y \in \R^\dm$, $r, s \in \R^{\abs{A}}$ that $\abs{ f_i(x,r) - f_i(x,s) } \le L_i \max_{a \in A} \abs{ r(a) - s(a)}$ and $\abs{f_2(x,r) - f_2(y, r)} \le K \norm{x - y}$,
    %
    let $\tker^{\pr{a}}_i \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $i \in \{1,2\}$, $a \in A$, be stochastic kernels,
    %
    assume for all $i \in \{1,2\}$, $x \in \R^\dm$, $a \in A$ that $\int_{\R^\dm} \abs{\w(y)} \tker_i^{\pr{a}}(x, \dxx y) \le c \w(x)$,
    %
    assume for all $i \in \cu{1,2}$ that
    %
    \begin{equation}
        \begin{split}
            \sup_{(x, a) \in \R^\dm \times A} \abs{\w(x)}^{-1} \int_{\R^\dm} \abs{ f_i \pr{y, 0} } \tker_i^{\pr{a}}(x, \dxx y) < \infty,
        \end{split}
    \end{equation}
    %
    assume for all $i \in \cu{1,2}$ that $\sup_{ (x, a) \in \R^\dm \times A } \abs{\w(x)}^{-1} \int_{\R^\dm} \norm{y} \tker_i^{\pr{a}}(x, \dxx y) < \infty $,
    %
    assume for all $x, y \in \R^\dm$, $a \in A$ that $\wdist_\dm \pr{ \tker_2^{\pr{a}}(x, \cdot), \tker_2^{\pr{a}}(y, \cdot) } \le \eta \norm{x-y}$.
    %
    Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:stability_kernel_w_ex_uniq} there exist unique $u_i \in \W$, $i\in \cu{1,2}$, such that for all $i \in \cu{1,2}$, $x \in \R^\dm$, $a \in A$ it holds that
        \begin{equation}
            \begin{split}
                \int_{\R^\dm} \abs{ f_i\pr{ y, u_i(y)} } \tker_i^{\pr{a}}\pr{x, \dxx y} < \infty \qquad \text{and} \qquad \pr{u_i\pr{x}}\pr{a} = \int_{\R^\dm} f_i \pr{y, u_i\pr{y}}\tker_i^{\pr{a}}\pr{x, \dxx y}
            \end{split}
        \end{equation}
        and

        \item \label{item:stability_kernel_w_result} it holds that
        \begin{equation} \label{eq:stability_kernel_w}
            \begin{split}   
                \br[\bigg]{ \sup_{(x,a) \in \R^\dm \times A} \!\!\!\!\! \tfrac{\abs{ (u_1(x))(a) - (u_2(x))(a) }}{\abs{ \w(x) }} } &\le \tfrac{c}{1 - c(\min\{L_1, L_2))} \br[\bigg]{ \sup_{ (y,r) \in \R^\dm \times \R^{\abs{A}} } \!\!\!\!\! \tfrac{ \abs{ f_1(y,r) - f_2(y,r) } }{ \abs{\w(y)} } } \\
                %
                %
                %
                &\quad+ \tfrac{K}{(1 - \eta L_2) (1 - cL_2)} \br[\bigg]{ \sup_{(y, b) \in \R^\dm \times A} \!\!\!\! \tfrac{\wdist_\dm \pr{ \tker_{1}^{\pr{b}}(y, \cdot), \tker_{2}^{\pr{b}}(y, \cdot) }}{\abs{\w(y)}} }
            \end{split} 
        \end{equation}
    \end{enumerate}
    %
    %
    \cfout.
\end{propo}

\begin{mproof}{\cref{prop:stability_kernel_w}}
    First, observe that
    %
    the assumption that $\w$ is measurable,
    %
    the assumption that for all $i \in \cu{1,2}$ it holds that $cL_i < 1$,
    %
    the assumption that for all $i \in \cu{1,2}$, $x \in \R^\dm$, $r,s \in \R^{\abs{A}}$ it holds that $\abs{f_i\pr{ x, r} - f_i\pr{x,s}} \le L_i \max_{a \in A} \abs{ r\pr{a} - s\pr{a}}$,
    %
    the assumption that for all $i \in \cu{1,2}$, $x \in \R^\dm$, $a \in A$ it holds that $\int_{\R^\dm} \abs{\w(y)} \tker_i^{\pr{a}}\pr{x, \dxx y} \le c \w(x)$,
    %
    the assumption that for all $i \in \cu{1,2}$ it holds that $\sup_{\pr{x,a} \in \R^\dm \times A} \abs{\w(x)}^{-1} \int_{\R^\dm} \abs{ f_i \pr{y, u_i\pr{y}}} \tker_i^{\pr{a}}\pr{x, \dxx y} < \infty $,
    %
    and \cite[Lemma~2.2]{beck2023nonlinctrl} (applied for every $i \in \cu{1,2}$ with $c \with c$, $L \with L_i$, $\pr{\X, \mathcal{X}} \with \pr{\R^\dm, \cB\pr{\R^\dm}}$, $A\with A$, $\pr{\tker_a}_{a \in A} \with \pr{\tker_i^{\pr{a}}}_{a \in A}$, $f \with f_i$, $\w \with \br{ \R^\dm \ni x \mapsto \br{A \ni a \mapsto \w(x) \in \pr{0,\infty}} \in \pr{0,\infty}^{\abs{A}} }$ in the notation of \cite[Lemma~2.2]{beck2023nonlinctrl}) establishes \cref{item:stability_kernel_w_ex_uniq}.
    %
    Next, note that the assumption that for all $i \in \cu{1,2}$ it holds that $\sup_{\pr{x,a} \in \R^\dm \times A} \abs{\w(x)}^{- 1} \int_{\R^\dm} \norm{y} \tker_i^{\pr{a}}\pr{x, \dxx y} \le c \w(x)$
    %
    and the fact that for all $x \in \R^\dm$ it holds that $\w(x) > 0$
    %
    imply that for all $i \in \cu{1,2}$, $x \in \R^\dm$, $a \in A$ it holds that
    \begin{equation} \label{eq:stability_kernel_w_finite_first_moment}
        \begin{split}
            \int_{\R^\dm} \norm{y} \tker_i^{\pr{a}} \pr{x, \dxx y} &= \tfrac{\abs{\w(x)}}{\abs{\w(x)}} \int_{\R^\dm} \norm{y} \tker_i^{\pr{a}} \pr{x, \dxx y} \\
            %
            &\le \abs{\w(x)} \br[\bigg]{\sup_{\pr{z,b} \in \R^\dm \times A} \!\!\!\!  \abs{\w(z)}^{-1} \!\! \int_{\R^\dm} \norm{y} \tker_i^{\pr{b}} \pr{z, \dxx y}} < \infty.
        \end{split}
    \end{equation}
    %
    %
    %
    Moreover, note that Fubini's theorem,
    %
    the triangle inequality, 
    %
    and the assumption that for all $x, y \in \R^\dm$, $r \in \R^{\abs{A}}$ it holds that $\abs{ f_2(x,r) - f_2(y,r) } \le K \norm{x - y}$
    %
    ensure for all $x \in \R^\dm$, $a \in A$ that
    %
    %
    \begin{equation} \label{eq:stability_kernel_w_cross_intregrability}
        \begin{split}
            \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm} \abs{f_2\pr{\bfx, 0}} \tker_1^{\pr{a}}(x, \dxx \bfx) &= \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm}\abs{ f_2\pr{\bfx, 0} } \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) } \\
            %
            %
            &\le \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{ f_2\pr{\bfx, 0} - f_2\pr{\bfy, 0} } \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) }  \\
            %
            &\quad+ \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{ f_2\pr{\bfy, 0} } \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) } \\
            %
            %
            &\le \tfrac{K}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm}\norm{ \bfx - \bfy} \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) }\\
            %
            &\quad+ \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{ f_2\pr{\bfy, 0} } \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) }\\
            %
            %
            &\le \tfrac{K}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfx} \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) }\\
            %
            &\quad+ \tfrac{K}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \norm{\bfy} \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) } \\
            %
            &\quad+ \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm \times \R^\dm} \hspace{-0.5cm} \abs{ f_2\pr{\bfy, 0} } \pr[\big]{ \tker_1^{\pr{a}}(x, \dxx \bfx) \otimes \tker_2^{\pr{a}}(x, \dxx \bfy) }\\
            %
            %
            &= \tfrac{K}{\abs{\w(x)}} \int_{\R^\dm} \norm{\bfx} \tker_1^{\pr{a}}(x, \dxx \bfx) + \tfrac{K}{\abs{\w(x)}} \int_{\R^\dm} \norm{\bfy} \tker_2^{\pr{a}}(x, \dxx \bfy)\\
            %
            &\quad+ \tfrac{1}{\abs{\w(x)}} \int_{\R^\dm} \abs{f_2\pr{\bfy, 0}} \tker_2^{\pr{a}} (x, \dxx \bfy)\\
            %
            &\le K \pr*{ \br[\bigg]{\sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{\int_{\R^\dm} \norm{\bfx} \tker_1^{\pr{b}}(y, \dxx \bfx) }{ \abs{\w(y)} } } + \br[\bigg]{\sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{\int_{\R^\dm} \norm{\bfy} \tker_2^{\pr{b}} (y, \dxx \bfy)}{ \abs{\w(y)} } }  }\\
            %
            &\quad+ \br[\bigg]{ \sup_{(y,b) \in \R^\dm \times A} \!\!\!\! \tfrac{ \int_{\R^\dm} \abs{f_2 \pr{ \bfy, 0 } } \tker_2^{\pr{b}}(y, \dxx \bfy) }{ \abs{\w(y)} } }.
        \end{split}
    \end{equation}
    %
    %
    %
    This,
    %
    the assumption that for all $i \in \{1, 2\}$ it holds that $\sup_{(y,b) \in \R^\dm \times A} \abs{\w(y)}^{-1} \int_{\R^\dm} \abs{f_i\pr{\bfy, 0}} \tker_i^{\pr{b}}(y, \dxx \bfy) <\infty$,
    %
    and the assumption that for all $i \in \{1,2\}$ it holds that $\sup_{(y,b) \in \R^\dm \times A} \abs{\w(y)}^{-1} \int_{\R^\dm} \norm{\bfy} \tker_i^{\pr{b}} (y, \dxx \bfy) <\infty$,
    %
    show that $\sup_{(y, b) \in \R^\dm \times A} \abs{\w(y)}^{-1} \int_{\R^\dm} \abs{f_2\pr{\bfy, 0}} \tker_1^{\pr{b}}(y, \dxx \bfy) < \infty$.
    %
    %
    Combining this
    %
    with \cite[Lemma~2.2]{beck2023nonlinctrl} (applied with $c \with c$, $L \with L_2$, $(\X, \mathcal{X}) \with (\R^\dm, \Borel(\R^\dm))$, $A \with A$, $(\tker_a)_{a \in A} \with (\tker^{\pr{a}}_1)_{a \in A}$, $f \with f_2$, $\w \with \br{ \R^\dm \ni x \mapsto \br{ A \ni a \mapsto \w(x) \in \pr{0, \infty}  } \in \pr{0, \infty}^{\abs{A}}}$ in the notation of \cite[Lemma~2.2]{beck2023nonlinctrl})
    %
    proves that there exists a unique $u \in \W$ such that for all $x \in \R^\dm$, $a \in A$ it holds that
    $\int_{\R^\dm} \abs{ f_2 \pr{y, u(y)} } \tker_1^{\pr{a}}(x, \dxx y) < \infty$ and $(u(x))(a) = \int_{\R^\dm}  f_2\pr{y, u(y)}  \tker_1^{\pr{a}}(x, \dxx y)$.
    %
    %
    %
    This,
    %
    \cref{eq:stability_kernel_w_finite_first_moment},
    %
    the triangle inequality,
    %
    \cref{item:stability_kernel_w_nonlinearity_result} in \cref{lem:stability_kernel_w_nonlinearity} (applied with
    %
    $c \with c$,
    %
    $L_1 \with L_1$,
    %
    $L_2 \with L_2$,
    %
    $f_1 \with f_1$,
    %
    $f_2 \with f_2$,
    %
    $\pr{\tker^{\pr{a}}}_{a \in A} \with \pr{\tker^{\pr{a}}_1}_{a \in A}$
    %
    in the notation of \cref{lem:stability_kernel_w_nonlinearity}),
    %
    and \cref{item:stability_kernel_w_kernel_result} \cref{lem:stability_kernel_w_kernel} (applied with
    %
    $\eta \with \eta$,
    %
    $c \with c$,
    %
    $L \with L_2$,
    %
    $K \with K$,
    %
    $f \with f_2$,
    %
    $\pr{ \tker^{\pr{a}}_1 }_{a \in A} \with \pr{\tker^{\pr{a}}_1}_{a \in A}$,
    %
    $\pr{ \tker^{\pr{a}}_2 }_{a \in A} \with \pr{\tker^{\pr{a}}_2}_{a \in A}$
    %
    in the notation of \cref{lem:stability_kernel_w_kernel})
    %
    demonstrate that
    \begin{equation}
        \begin{split}
            \br[\bigg]{ \sup_{(x,a) \in \R^\dm \times A} \!\!\!\!\!\! \tfrac{\abs{ (u_1(x))(a) - (u_2(x))(a) }}{\abs{ \w(x) }} } &\le \br[\bigg]{ \sup_{(x,a) \in \R^\dm \times A} \!\!\!\!\! \tfrac{\abs{ (u_1(x))(a) - (u(x))(a) }}{\abs{ \w(x) }} } + \br[\bigg]{ \sup_{(x,a) \in \R^\dm \times A} \!\!\!\!\! \tfrac{\abs{ (u(x))(a) - (u_2(x))(a) }}{\abs{ \w(x) }} } \\
            %
            %
            %
            &\le \tfrac{c}{1 - c(\min\cu{L_1, L_2})} \br[\bigg]{ \sup_{ (y,r) \in \R^\dm \times \R^{\abs{A}} } \!\!\!\!\! \tfrac{ \abs{ f_1(y,r) - f_2(y,r) } }{ \abs{\w(y)} } } \\
            %
            %
            %
            &\quad+ \tfrac{K}{(1 - \eta L_2) (1 - cL_2)} \br[\bigg]{ \sup_{(y, b) \in \R^\dm \times A} \!\!\!\!\! \tfrac{\wdist_\dm \pr{ \tker_{1}^{\pr{b}}(y, \cdot), \tker_{2}^{\pr{b}}(y, \cdot) }}{\abs{\w(y)}} }.
        \end{split}
    \end{equation}
    %
    This proves \cref{item:stability_kernel_w_result}. The proof of \cref{prop:stability_kernel_w} is thus complete.
\end{mproof}





\section{Artificial neural network (ANN) calculus}
\label{sec:ann_calculus} 

In this section we recall necessary notions and statements on ANNs which we need for the remainder of this work. The content of this section is well-known in the literature and the specific definitions and statements mostly consist of slightly extended or modified excerpts from Grohs et al. \cite[Section~2]{GrohsHornungJentzen2019published}, Grohs et al. \cite[Section~3]{grohs2019deep_published}, and Ackermann et al. \cite[Section~2]{ackermann2023deep}.

In particular,
%
\cref{def:ANN} is a slightly extended version of \cite[Definition~2.1]{GrohsHornungJentzen2019published},
%
\cref{def:multi} is \cite[Definition~2.2]{GrohsHornungJentzen2019published},
%
