\subsection{Structured description of ANNs}
\label{subsec:ann_description}



\begin{definition}[ANNs] \label{def:ANN}
    We denote by $\bN$ the set given by
    %
    \begin{equation} \label{eq:ANN_set}
        \textstyle
        \bN =
        \textstyle
        \bigcup_{L \in \N} \bigcup_{l_0, l_1, \dots, l_L \in \N} \pr[\big]{\bigtimes_{k = 1}^{L}   \pr{\R^{l_k \times l_{k - 1}} \times \R^{l_k}}}
    \end{equation}
    %
    and we denote by
    %
    $\paramANN \colon \bN \to \N$,
    %
    $\cL \colon \bN \to \N$,
    %
    $\cI \colon \bN \to \N$,
    %
    $\cO \colon \bN \rightarrow \N$,
    %
    $\cH \colon \bN \rightarrow \N_0 = \N \cup \{ 0 \}$,
    %
    $\cD \colon \bN \rightarrow \cup_{l = 2}^\infty \N^l$,
    %
    and $\dimANNlevel_n \colon \bN \rightarrow \N_0$, $n\in \N_0$,
    %
    the functions which satisfy for all $L \in \N$, $l_0, l_1, \dots, l_L \in \N$, $\Phi \in \pr[\big]{\bigtimes_{k = 1}^{L} ( \R^{l_k \times l_{k - 1}} \times \R^{l_k} )} $, $n \in \N_0$ that $ \paramANN(\Phi) = \sum_{k = 1}^{L} l_k(l_{k - 1} + 1) $, $\cL(\Phi) = L$, $\cI(\Phi) = l_0$, $\cO(\Phi) = l_L$, $\cH(\Phi) = L - 1$, $\cD(\Phi) = (l_0, l_1, \dots, l_L)$, and
    \begin{equation} \label{eq:ANN_nth_layer}
        \dimANNlevel_n(\Phi) = \begin{cases}
            l_n
            &
            \colon
            n \le L
            \\
            0
            &
            \colon
            n > L.
        \end{cases}
    \end{equation}
\end{definition}

\cfclear
\begin{definition}[ANN] \label{def:ANN2}
    %
    We say that $\Phi$ is an ANN if and only if it holds that $\Phi \in \bN$
    %
    \cfout[.]
\end{definition}


\cfclear
\begin{lemma}\label{lem:ANN_size_estimate}
    \cfconsiderloaded{lem:ANN_size_estimate}
    For every $\dm \in \N$, $x \in \pr{x_1, \dots, x_\dm} \in \R^\dm$ let $\fnorm{x} \in \R$ satisfy $\fnorm{x} = \max_{i \in \cu{1,\dots, \dm}} \abs{x_i}$.
    %
    Then it holds for all $\Phi \in \bN$ that $\max\{ \cL(\Phi), \fnorm{\cD(\Phi)} \} \le \paramANN(\Phi)$ and $\paramANN(\Phi) \le 2 \cL(\Phi) \fnorm{\cD(\Phi)}^2$
    %
    \cfout[.]
\end{lemma}

\begin{mproof}{\cref{lem:ANN_size_estimate}}
    %
    First, note that \cite[Lemma~2.4]{ackermann2023deep} demonstrates for all $\Phi \in \bN$ that $\cL(\Phi) + \fnorm{\cD(\Phi)} \le \paramANN(\Phi)$.
    %
    Hence, it holds for all $\Phi \in \bN$ that $\max\{ \cL(\Phi), \fnorm{\cD(\Phi)} \} \le \paramANN(\Phi)$.
    %
    Moreover, observe that for all $L \in \N$, $l_0, l_1, \dots, l_L \in \N$, $\Phi \in \pr{\bigtimes_{k = 1}^L \pr{ \R^{l_k \times l_{k - 1}} \times \R^{l_k} }}$ it holds that
    %
    \begin{equation}
        \begin{split}
            \paramANN\pr{\Phi} = \sum_{k = 1}^L l_k\pr{l_{k - 1} + 1} \le \sum_{k = 1}^{L} \fnorm{\cD\pr{\Phi}} \pr{ \fnorm{\cD\pr{ \Phi }} + 1} \le 2L \fnorm{\cD \pr{ \Phi}}^2 = 2 \cL \pr{\Phi} \fnorm{\cD \pr{\Phi}}^2.
        \end{split}
    \end{equation}
    %
    The proof of \cref{lem:ANN_size_estimate} is thus complete.
\end{mproof}

\begin{definition}[Multidimensional version] \label{def:multi}
    Let $\dm \in \N$, $\activation \in C(\R, \R)$.
    %
    Then we denote by $\activationDim{\dm} \colon \R^\dm \to \R^\dm$ the function which satisfies for all $x = (x_1, x_2, \dots, x_\dm) \in \R^\dm$ that
    %
    \begin{equation}
        \activationDim{\dm} (x) = \big( \activation(x_1), \activation(x_2), \dots, \activation(x_\dm) \big).
    \end{equation} 
\end{definition}

\cfclear
\begin{definition}[Realization associated to an ANN]\label{def:realization}
    \cfconsiderloaded{def:realization}
    Let $\activation \in C(\R, \R)$.
    %
    Then we denote by $\cR_\activation \colon \bN \to  \cup_{k,l \in \N} C(\R^k, \R^l)$ the function which satisfies for all $L \in \N$, $l_0, l_1, \dots, l_L \in \N$, $\Phi = ( (W_1, B_1), (W_2, B_2), \dots, (W_L, B_L) ) \in \pr[\big]{\bigtimes_{k = 1}^L  (\R^{l_k \times l_{k - 1}} \times \R^{l_k})}$, $x_0 \in \R^{l_0}$, $x_1 \in \R^{l_1}$, \dots, $x_{L - 1} \in \R^{l_{L - 1}}$ with $x_k = \activationDim{l_k} (W_k x_{k - 1} + B_k)$, $k \in \N_0 \cap [1, L-1]$, that
    %
    \begin{equation}
        \cR_\activation(\Phi) \in C(\R^{l_0}, \R^{l_L}), \quad \text{and} \quad \big(\cR_\activation(\Phi)\big)(x_0) = W_L x_{L - 1} + B_L.
    \end{equation}
    %
    \cfout.
\end{definition}


\subsection{Compositions, affine linear transformations, powers, and extensions of ANNs}

\cfclear
\begin{definition}[Compositions of ANNs] \label{def:compositions_of_anns}
    %
    \cfconsiderloaded{def:compositions_of_anns}
    %
    We denote by $ \ANNcomp \colon \{ (\Phi_1, \Phi_2) \in \bN \times \bN : \cI(\Phi_1) = \cO(\Phi_2) \} \rightarrow \bN$ the function which satisfies for all $K, L \in \N$, $k_0, k_1, \dots, k_K, l_0, l_1, \dots, l_L \in \N$,
    %
    $\Phi_1 = \pr{(W_1, B_1), \dots, (W_K, B_K)} \in  \pr[\big]{\bigtimes_{j = 1}^{K}  \pr{\R^{k_j \times k_{j - 1}}  \times \R^{k_j}} }$,
    %
    $\Phi_2 = \pr{(\mathscr{W}_1, \mathscr{B}_1), \dots, (\mathscr{W}_L, \mathscr{B}_L)} \in \pr[\big]{\bigtimes_{j = 1}^{L} \pr{\R^{ l_j \times l_{j - 1} } \times \R^{l_j}}}$
    %
    with $ k_0 = \cI(\Phi_1) = \cO(\Phi_2) = l_L$ that
    \begin{align} \label{eq:definition_compositions_of_anns}
        \begin{split}
            &\Phi_1 \bullet \Phi_2 = \\
            &\begin{cases}
                \pr[\big]{(W_1 \mathscr{W}_1, W_1\mathscr{B}_1 + B_1 )}
                &\colon K = 1 = L\\[1ex]
                %
                \pr[\big]{(W_1 \mathscr{W}_1, W_1  \mathscr{B}_1 + B_1), (W_2, B_2), \dots, (W_K, B_K)} 
                &\colon K > 1 = L  \\[1ex]
                %
                \pr[\big]{(\mathscr{W}_1, \mathscr{B}_1),(\mathscr{W}_2, \mathscr{B}_2), \dots (\mathscr{W}_{L - 1}, \mathscr{B}_{L - 1}), (W_1 \mathscr{W}_L, W_1 \mathscr{B}_L + B_1)}
                &\colon K = 1 < L \\[1ex]
                %
                \begin{aligned}
                    &\pr[\big]{(\mathscr{W}_1, \mathscr{B}_1), (\mathscr{W}_2, \mathscr{B}_2), \dots, (\mathscr{W}_{L - 1}, \mathscr{B}_{L - 1}), (W_1 \mathscr{W}_L, W_1 \mathscr{B}_L + B_1), \\ &\hspace{0.2cm}(W_2, B_2), \dots, (W_K, B_K)}
                \end{aligned}
                &\colon K > 1 < L
            \end{cases}
        \end{split}
    \end{align}
    \cfout.
\end{definition}

\cfclear
\begin{lemma}[Compositions of ANNs] \label{lem:compositions_of_anns}
    %
    %
    \cfconsiderloaded{\cref{lem:compositions_of_anns}}
    %
    %
    Let $K, L \in \N$, $k_0, k_1, \dots, k_K, l_0, l_1, \dots, l_L \in \N$,
    %
    let $\Phi_1 = \pr{(W_1, B_1), \dots, (W_K, B_K)}  \in  \pr[\big]{\bigtimes_{j = 1}^{K}  \pr{\R^{k_j \times k_{j - 1}}  \times \R^{k_j}}}$, $ \Phi_2 =  \pr{(\mathscr{W}_1, \mathscr{B}_1), \dots, (\mathscr{W}_L, \mathscr{B}_L)} \in \pr[\big]{ \bigtimes_{j = 1}^{L}  \pr{\R^{ l_j \times l_{j - 1} } \times \R^{l_j} }} $ satisfy $ k_0 = \cI(\Phi_1) = \cO(\Phi_2) = l_L$.
    %
    Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:compositions_of_anns_layer_structure} it holds that $ \cD ( \Phi_1 \bullet \Phi_2 ) = (l_0, \dots, l_{L - 1}, k_1, \dots, k_K) \in \N^{L + K} $,

        \item \label{item:compositions_of_anns_depth} it holds that $ \cL ( \Phi_1 \bullet \Phi_2) = \cL(\Phi_1) + \cL(\Phi_2) - 1 $,

        \item \label{item:compositions_of_anns_hidden_layers} it holds that $ \cH (\Phi_1 \bullet \Phi_2) = \cH(\Phi_1) + \cH(\Phi_2)$,

        \item \label{item:compositions_of_anns_size} it holds that 
        \begin{align}
            \begin{split}
                \paramANN ( \Phi_1 \bullet \Phi_2 ) &= \paramANN(\Phi_1) + \paramANN ( \Phi_2 ) + k_1 ( l_{L - 1} + 1 ) - k_1(k_0 + 1) - l_L ( l_{L-  1} + 1 )\\
                &= \paramANN(\Phi_1) + \paramANN(\Phi_2) + k_1 l_{L - 1} - k_1 k_0 - l_Ll_{L - 1} - l_L \\
                &\le \paramANN(\Phi_1) + \paramANN(\Phi_2) + k_1 l_{L - 1},
            \end{split}
        \end{align}
        and

        \item \label{item:compositions_of_anns_realizations} it holds for all $\activation \in C(\R, \R)$ that $ \cR_\activation( \Phi_1 \ANNcomp \Phi_2 ) \in C ( \R^{\cI(\Phi_2)  }, \R^{ \cO (\Phi_1) } ) $ and $ \cR_\activation ( \Phi_1 \bullet \Phi_2 ) = \cR_\activation ( \Phi_1 ) \circ \cR_\activation ( \Phi_2 )$
    \end{enumerate}
    %
    %
    % \cfload
    \cfout.
\end{lemma}


\cfclear
\begin{lemma}[Associativity of compositions of ANNs] \label{lem:associativity_compositions_of_anns}
    %
    %
    \cfconsiderloaded{\lem:associativity_compositions_of_anns}
    %
    %
    Let $\Phi_1, \Phi_2, \Phi_3 \in \bN$ satisfy that $\cI (\Phi_1) = \cO (\Phi_2)$ and $\cI (\Phi_2) = \cO (\Phi_3)$. Then it holds that 
    \begin{equation}
        \left( \Phi_1 \ANNcomp \Phi_2 \right) \ANNcomp \Phi_3 = \Phi_1 \ANNcomp \left( \Phi_2 \ANNcomp \Phi_3 \right)
    \end{equation}
    \cfload.
\end{lemma}

\cfclear
\begin{definition}[Identity matrix] \label{def:identity_matrix}
    %
    \cfconsiderloaded{def:identity_matrix}
    %
    Let $\dm \in \N$. Then we denote by $\id_\dm \in \R^{\dm \times \dm}$ the identity matrix in $\R^{\dm \times \dm}$
    %
    \cfout. 
\end{definition}


\cfclear
\begin{definition}[Powers of ANNs] \label{def:powers_of_anns}
    %
    %
    % \cfconsiderloaded{\def:powers_of_anns}
    %
    %
    We denote by $(\cdot)^{\bullet n} \colon \{ \Phi \in \bN : \cI(\Phi) = \cO(\Phi) \} \rightarrow \bN$, $n \in \N_0$, the functions which satisfy for all $n \in \N_0$, $\Phi \in \bN$ with $\cI(\Phi) = \cO(\Phi)$ that
    \begin{equation} \label{eq:def_powers_of_anns}
        \Phi^{\bullet n } = \begin{cases}
            \left( \id_{\cO(\Phi)}, (0, 0, \dots, 0) \right) \in \left( \R^{\cO(\Phi) \times \cO(\Phi)} \times \R^{\cO(\Phi)} \right)
            &\colon
            n = 0
            \\
            \Phi \ANNcomp (\Phi^{\bullet (n - 1)})
            &\colon
            n \in \N
        \end{cases}
    \end{equation}
    %
    \cfout.
\end{definition}


\cfclear
\begin{definition}[Extensions of ANNs] \label{def:extensions_of_anns}
    %
    %
    \cfconsiderloaded{def:extensions_of_anns}
    %
    %
    Let $L\in \N$, let $\Psi \in \bN$ with $\cI (\Psi) = \cO (\Psi)$. Then we denote by $\longerANN{L, \Psi} \colon \{ \Phi \in \bN : ( \cL (\Phi) \le L \text{ and } \cO (\Phi) = \cI (\Psi)  ) \} \rightarrow \bN$ satisfy for all $\Phi \in \bN$ with $ \cL (\Phi) \le L $ and $ \cI (\Psi) = \cO (\Phi) $ that $ \mathcal{E}_{L, \Psi} (\Phi) = \compANN{ (\power{\Psi}{(L - \cL (\Phi))}) }{\Phi}$
    %
    %
    \cfout.
\end{definition}

\cfclear
\begin{lemma}[Certain powers and extensions of ANNs] \label{lem:certain_extensions_of_anns}
    Let $\dm, l \in \N$, let $\Psi \in \bN$ satisfy $ \cD (\Psi) = (\dm , l , \dm) \in \N^3 $. Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:certain_extensions_of_anns_item_power} it holds for all $n \in \N_0$ that $ \cL (\power{\Psi}{n}) = n + 1 $, $ \cD (\Psi^{\bullet n}) \in \N^{n + 2} $, and
        \begin{equation}
            \cD (\Psi^{ \bullet n }) = \begin{cases}
                (\dm, \dm) &: n = 0 \\
                (\dm, l, l, \dots, l, \dm) &: n \in \N,
            \end{cases}
        \end{equation}

        \item \label{item:certain_extensions_of_anns_item_extension} it holds for all $\Phi \in \bN$, $L \in \N \cap [\cL (\Phi), \infty)$ with $\cO (\Phi) = \dm$ that $ \cL (\mathcal{E}_{L, \Psi} (\Phi) ) = L $ and
        \begin{equation}
            \hspace{-0.42cm}\mathcal{P} ( \mathcal{E}_{L, \Psi} (\Phi) ) \le \begin{cases}
                \mathcal{P} (\Phi) &: \cL (\Phi) = L \\
                \left[ \left( \max \{ 1, \frac{l}{\dm} \} \right) \mathcal{P} (\Phi) + \left( \left( L - \cL (\Phi) - 1 \right) l + \dm \right)(l + 1)  \right] &: \cL (\Phi) < L,
            \end{cases}
        \end{equation} and 

        \item \label{item:certain_extensions_of_anns_item_extension_to_same_length} it holds for all $\Phi \in \bN$ with $\cO (\Phi) = \dm$ that $\longerANN{\cL(\Phi), \Psi} (\Phi) = \Phi$
    \end{enumerate}
    \cfout.
\end{lemma}

\begin{mproof}{\cref{lem:certain_extensions_of_anns}}
    %
    %
    First, note that \cite[Lemma~2.13]{GrohsHornungJentzen2019published} proves \cref{item:certain_extensions_of_anns_item_power,item:certain_extensions_of_anns_item_extension}.
    %
    %
    Next, observe that it holds that $\longerANN{\cL(\Phi), \Psi}(\Phi) = (\Psi^{\bullet (\cL(\Psi) - \cL(\Phi))}) \bullet \Phi = \Psi^{\bullet 0} \bullet \Phi$.
    %
    This,
    %
    the assumption that $\cO (\Phi) = \cI (\Psi) = \dm$,
    %
    the fact that $\Psi^{\bullet 0} = ( \id_\dm, (0, 0, \dots, 0) ) \in \R^{\dm \times \dm} \times \R^\dm$,
    %
    and \cref{lem:compositions_of_anns} demonstrate that $\longerANN{\cL (\Phi), \Psi} (\Phi) = \Psi^{\bullet 0} \bullet \Phi = \Phi$.
    %
    This proves \cref{item:certain_extensions_of_anns_item_extension_to_same_length}.
    %
    The proof of \cref{lem:certain_extensions_of_anns} is thus complete.
\end{mproof}

\cfclear
\begin{lemma}[Extensions of ANNs involving identities] \label{lem:extensions_of_anns_involving_identities}
    %
    Let $\activation \in C(\R, \R)$,
    %
    let $\mathbb{I} \in \bN$ satisfy for all $x \in \R^{ \cI (\mathbb{I}) }$ that $\cI (\mathbb{I}) = \cO (\mathbb{I})$ and $ \big(\cR_\activation(\mathbb{I})\big)(x) = x $.
    %
    Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:extensions_of_anns_involving_identities_item_powers_of_identity} it holds for all $n \in \N_0$, $ x \in \R^{ \cI (\mathbb{I}) } $ that $ \cR_\activation ( \power{\mathbb{I}}{n} ) \in C \left( \R^{ \cI (\mathbb{I}) }, \R^{ \cI (\mathbb{I}) } \right) $ and $ \big(\cR_\activation (\mathbb{I}^{\bullet n})\big)( x ) = x$ and

        \item \label{item:extensions_of_anns_involving_identities_item_extension_by_identity} it holds for all $\Phi \in \bN$, $L \in \N \cap [\cL  (\Phi), \infty)$, $x \in \R^{ \cI (\Phi) }$ with $ \cI (\mathbb{I}) = \cO (\Phi)$ that $ \cR_\activation (\longerANN{L, \mathbb{I}}(\Phi) ) \in C (\R^{ \cI (\Phi) }, \R^{ \cO (\Phi)  } )$ and $ \big(\cR_\activation (\mathcal{E}_{ L, \mathbb{I}})  (\Phi)  \big)(x) = \big(\cR_\activation(\Phi)\big)(x) $
    \end{enumerate}
    %
    %
    \cfout.
\end{lemma}


\subsection{Parallelizations of ANNs}
\label{subsec:parallelizations_of_anns} 


\cfclear
\begin{definition}[Parallelizations of ANNs with the same depth] \label{def:parallelizations_of_anns_same_depth}
    %
    %
    \cfconsiderloaded{def:parallelizations_of_anns_same_depth}
    %
    %
    Let $n \in \N$. Then we denote by $\paraANN{n} \colon \{ (\Phi_1, \dots, \Phi_n) \in \bN^n : \cL (\Phi_1) = \cL (\Phi_2) = \dots = \cL (\Phi_n)  \} \rightarrow \bN $ the function which satisfies for all $L \in \N$, $ (l_{1,0}, l_{1,1}, \dots,  l_{1, L}), \dots, ( l_{n, 0}, l_{n, 1}, \dots, l_{n, L} ) \in \N^{L + 1} $,
    %
    \begin{align}
        \begin{split}
            \Phi_1 &= ( (W_{1,1}, B_{1,1}), (W_{1,2}, B_{1,2}), \dots, (W_{1,L}, B_{1,L})  ) \in \textstyle \pr[\big]{\bigtimes_{k = 1}^{L}  ( \R^{ l_{1,k} \times l_{1, k- 1} }  \times \R^{l_{1,k}} ) } ,\\
            %
            %
            %
            \Phi_2 &= ((W_{2,1}, B_{2,1}), (W_{2,2}, B_{2,2}), \dots, (W_{2,L}, B_{2,L})) \in \textstyle \pr[\big]{\bigtimes_{k = 1}^{L}  ( \R^{ l_{2,k} \times l_{2, k- 1} }  \times \R^{l_{2,k}} )  }, \\
            %
            %
            %
            &\vdots\\
            %
            %
            %
            \Phi_n &= ((W_{n,1}, B_{n,1}), (W_{n,2}, B_{n,2}), \dots, (W_{n,L}, B_{n,L})) \in \textstyle \pr[\big]{\bigtimes_{k = 1}^{L}  ( \R^{ l_{n,k} \times l_{n, k- 1} }  \times \R^{l_{n,k}} )}  ,
        \end{split}
    \end{align}
    %
    %
    \noindent
    $\pr*{ (\mathscr{W}_1, \mathscr{B}_1), (\mathscr{W}_2, \mathscr{B}_2), \dots, ( \mathscr{W}_L, \mathscr{B}_L )}  \in  \pr[\big]{\bigtimes_{j = 1}^{L} ( \R^{  (\sum_{k = 1}^{n} l_{k, j} )  \times  ( \sum_{k = 1}^{n} l_{k, j - 1} )}  \times \R^{ (\sum_{k = 1}^{n} l_{k, j} ) } )}  $ with 
    \begin{equation} \label{eq:parallelizations_of_anns_same_depth_def_matrix}
        \forall i \in \N \cap \in [1, L]: ( \mathscr{W}_i, \mathscr{B}_i ) = \begin{pmatrix}
            \begin{pmatrix}
                W_{1, i} & 0 & 0 & \hdots & 0\\
                0 & W_{2, i} & 0 & \hdots & 0\\
                0 & 0 & W_{3, i} & \hdots & 0\\
                \vdots & \vdots & \vdots & \ddots & \vdots \\
                0 & 0 & 0 & \hdots & W_{n, i}
            \end{pmatrix},
            \begin{pmatrix}
                B_{1, i} \\ B_{2, i} \\ B_{3, i} \\ \vdots \\ B_{n, i}
            \end{pmatrix}
        \end{pmatrix},
    \end{equation}
    that
    \begin{align}\label{eq:parallelizations_of_anns_same_depth_def_p_n}
        \begin{split}
            \paraANN{n} ( \Phi_1, \Phi_2, \dots \Phi_n  ) = \pr*{(\mathscr{W}_1, \mathscr{B}_1), (\mathscr{W}_2, \mathscr{B}_2), \dots, ( \mathscr{W}_L, \mathscr{B}_L ) }
        \end{split}
    \end{align}
    %
    %
    \cfout.
\end{definition}

\cfclear
\begin{lemma}\label{lem:parallelizations_of_anns_same_depth} 
    Let $n, L \in \N$, let $ (l_{1,0}, l_{1,1}, \dots,  l_{1, L}), \dots, ( l_{n, 0}, l_{n, 1}, \dots, l_{n, L} ) \in \N^{L + 1} $, and let 
    %
    \begin{align}
        \begin{split}
            \Phi_1 &= ( (W_{1,1}, B_{1,1}), (W_{1,2}, B_{1,2}), \dots, (W_{1,L}, B_{1,L})  ) \in \textstyle \pr[\big]{ \bigtimes_{k = 1}^{L}  ( \R^{ l_{1,k} \times l_{1, k- 1} }  \times \R^{l_{1,k}} )} ,\\
            %
            %
            %
            \Phi_2 &= ((W_{2,1}, B_{2,1}), (W_{2,2}, B_{2,2}), \dots, (W_{2,L}, B_{2,L})) \in \textstyle \pr[\big]{\bigtimes_{k = 1}^{L}  ( \R^{ l_{2,k} \times l_{2, k- 1} }  \times \R^{l_{2,k}} )}, \\
            %
            %
            %
            &\vdots\\
            %
            %
            %
            \Phi_n &= ((W_{n,1}, B_{n,1}), (W_{n,2}, B_{n,2}), \dots, (W_{n,L}, B_{n,L})) \in \textstyle \pr[\big]{\bigtimes_{k = 1}^{L}  ( \R^{ l_{n,k} \times l_{n, k- 1} }  \times \R^{l_{n,k}} )}.
        \end{split}
    \end{align}
    %
    %
    %
    \cfload
    %
    \noindent Then
    \begin{enumerate}[label=(\roman *)] 
        \item \label{item:parallelizations_of_anns_same_depth_item_element_in_set_of_anns} it holds that
        \begin{equation}
            \paraANN{n} ( \Phi_1, \dots, \Phi_n ) \in \textstyle \pr[\big]{\bigtimes_{j = 1}^{L} ( \R^{  (\sum_{k = 1}^{n} l_{k, j} )  \times  ( \sum_{k = 1}^{n} l_{k, j - 1} )}  \times \R^{ (\sum_{k = 1}^{n} l_{k, j} ) } )} \subseteq \bN,
        \end{equation}

        \item \label{item:parallelizations_of_anns_same_depth_item_realization} it holds that
        \begin{equation}
            \cR_\activation  ( \paraANN{n} ( \Phi_1, \dots, \Phi_n ) ) \in C ( \R^{ (\sum_{k = 1}^{n} \cI (\Phi_k) ) }, \R^{ ( \sum_{k = 1}^{n} \cO (\Phi_k) ) } ),
        \end{equation}

        \item \label{item:parallelizations_of_anns_same_depth_item_realization_evaluated} it holds for all $ x_1 \in \R^{\cI (\Phi_1)} $, $x_2 \in \R^{ \cI (\Phi_2) }$, \dots, $ x_n \in \R^{ \cI ( \Phi_n ) } $ that
        \begin{multline}
            \big(\cR_\activation ( \paraANN{n} ( \Phi_1, \dots, \Phi_n ) )\big)( x_1, x_2, \dots, x_n )\\
            %
            %
            %
            = \left( \big(\cR_\activation (\Phi_1)\big)(x_1), \big(\cR_\activation (\Phi_2)\big)(x_2), \dots, \big(\cR_\activation (\Phi_n)\big)(x_n) \right) \in \R^{ ( \sum_{k = 1}^{n} \cO (\Phi_k) ) },
        \end{multline}
        and

        \item \label{item:parallelizations_of_anns_same_depth_item_layer_structure} it holds that
        \begin{equation}
            \cD  ( \paraANN{n} ( \Phi_1, \dots, \Phi_n ) ) ) = \bigg( \SmallSum{k = 1}{n} l_{k, 0}, \SmallSum{k = 1}{n} l_{k, 1}, \dots, \SmallSum{k = 1}{n} l_{k, L} \bigg) 
        \end{equation}

    \end{enumerate}
    \cfout.
    %
    %
\end{lemma}





\cfclear
\begin{definition}[Parallelizations of ANNs with different layer structure] \label{def:parallelizations_of_anns_with_different_layer_structure}
    %
    %
    \cfconsiderloaded{def:parallelizations_of_anns_with_different_layer_structure}
    %
    %
    Let $n\in\N$, $ \Psi = (\Psi_1, \Psi_2, \dots, \Psi_n) \in \bN^n$ satisfy for all $i \in \N \cap [1, n]$ that $\cL (\Psi_i) = 2$, $\cI (\Psi_i) = \cO (\Psi_i)$. Then we denote by $ \paraLANN{n}{\Psi} \colon \{ (\Phi_1, \Phi_2, \dots, \Phi_n) \in \bN^n : \cI (\Psi_i) = \cO (\Phi_i), i \in \N \cap [1, n]\} \rightarrow \bN$ the function which satisfies for all $ \Phi = (\Phi_1, \dots, \Phi_n) \in \bN^n$ with $ \cI (\Psi_i) = \cO (\Phi_i) $, $i \in \N \cap [1,n]$, that
    %
    \begin{equation} \label{eq:parallelizations_of_anns_with_different_layer_structure_definition}
        \paraLANN{n}{\Psi}(\Phi) = \paraANN{n} \Big( \longerANN{\max_{i \in \N \cap  [1,n]  } \cL(\Phi_i), \Psi_1}(\Phi_1), \dots, \longerANN{\max_{i \in \N \cap [1,n] } \cL(\Phi_i), \Psi_n}(\Phi_n) \Big)
    \end{equation}
    %
    %
    \cfout.
\end{definition}

\cfclear
\begin{corollary} \label{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities}
    %
    %
    Let $n \in \N$, $\activation \in C(\R, \R)$, $\mathbb{I} = (\mathbb{I}_1, \mathbb{I}_2, \dots, \mathbb{I}_n), \Phi = (\Phi_1, \Phi_2, \dots, \Phi_n) \in \bN^n$ satisfy for all $i \in \N \cap [1, n] $, $x \in \R^{\cO (\Phi_i)}$ that $ \cL (\mathbb{I}_i) = 2 $, $\cI (\mathbb{I}_i) = \cO (\mathbb{I}_i) = \cO (\Phi_i)$, and $\big(\cR_\activation (\mathbb{I}_i)\big)(x) = x$. Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_realization} it holds that $ \cR_\activation \big( \paraLANN{n}{\mathbb{I}}(\Phi)  \big) \in C \big( \R^{ (\sum_{i = 1}^{n} \cI (\Phi_i) ) }, \R^{ (\sum_{i = 1}^{n} \cO (\Phi_i) ) } \big) $ and

        \item \label{item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_realization_evaluated} it holds for all $x_1 \in \R^{ \cI (\Phi_1) }, \dots, x_n \in \R^{ \cI (\Phi_n) }$ that

        \begin{equation}
            \big(\cR_\activation(\paraLANN{n}{\mathbb{I}}(\Phi) )\big)(x_1, x_2, \dots, x_n) = \begin{pmatrix}
                \big(\cR_\activation(\Phi_1)\big)(x_1)\\
                \big(\cR_\activation(\Phi_2)\big)(x_2)\\
                \vdots\\
                \big(\cR_\activation(\Phi_n)\big)(x_n)
            \end{pmatrix} \in \R^{ (\sum_{i = 1}^{n} \cO (\Phi_i) )  },
        \end{equation}
        and
        %
        \item \label{item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_architecture} it holds that
        %
        \begin{equation}
            \begin{split}
                \cD \pr*{ \paraLANN{n}{\I}\pr{\Phi} } &= \bigg( \SmallSum{k = 1}{n} \dimANNlevel_0\pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} },
                %
                \SmallSum{k = 1}{n} \dimANNlevel_1\pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} }, \dots \\
                %
                &\quad \dots, \SmallSum{k = 1}{n} \dimANNlevel_{\max_{i \in \N \cap \br{1,n}} \cL\pr{\Phi_i} } \pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} } \bigg)
            \end{split}
        \end{equation}
    \end{enumerate}
    %
    %
    \cfout.
\end{corollary}

\begin{mproof}{\cref{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities}}
    %
    First, note that \cite[Corollary~2.23]{GrohsHornungJentzen2019published} proves
    \cref{item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_realization,item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_realization_evaluated}.
    %
    Moreover, observe that the assumption that for all $i \in \N \cap \br{1, n}$ it holds that $\cL\pr{\I_i} = 2$,
    %
    the assumption that for all $i \in \N \cap \br{1,n}$ it holds that $\cI\pr{\I_i} = \cO\pr{\I_i} = \cO\pr{\Phi_i}$,
    %
    and \cref{item:certain_extensions_of_anns_item_extension} in \cref{lem:certain_extensions_of_anns}
    %
    ensure for all $k \in \N \cap \br{1,n}$ it holds that $\cL \pr{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL\pr{\Phi_i}, \Psi_k  } \pr{\Phi_k} } = \max_{i \in \N \cap \br{1,n}} \cL\pr{\Phi_i}$.
    %
    Combining this,
    %
    \eqref{eq:ANN_nth_layer},
    %
    \eqref{eq:parallelizations_of_anns_with_different_layer_structure_definition},
    %
    and \cref{item:parallelizations_of_anns_same_depth_item_layer_structure} in \cref{lem:parallelizations_of_anns_same_depth}
    %
    yields that
    %
    \begin{equation}
        \begin{split}
            \cD \pr*{ \paraLANN{n}{\I}\pr{\Phi} } &= \bigg( \SmallSum{k = 1}{n} \dimANNlevel_0\pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} },
            %
            \SmallSum{k = 1}{n} \dimANNlevel_1\pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} }, \dots \\
            %
            &\quad \dots, \SmallSum{k = 1}{n} \dimANNlevel_{\max_{i \in \N \cap \br{1,n}} \cL\pr{\Phi_i} } \pr[\big]{ \longerANN{\max_{i \in \N \cap \br{1,n}} \cL(\Phi_i), \Psi_k}\pr{\Phi_k} } \bigg).
        \end{split}
    \end{equation}
    %
    This proves \cref{item:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities_architecture}.
    %
    The proof of \cref{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities} is thus complete.
\end{mproof}


\subsection{Linear combinations of ANNs}
\label{subsec:ann_calculus_linear_combinations}


\cfclear
\begin{definition} \label{def:sum_transpose_anns}
    %
    %
    \cfconsiderloaded{def:sum_transpose_anns}
    %
    Let $m, n\in \N$. Then we denote by $\fS_{m,n} \in \R^{m \times (m n)} \times \R^m$, $\fT_{m, n} \in \R^{(m n) \times m} \times \R^{m n} $ the ANNs given by
    \begin{align}
        \begin{split}
            \fS_{m,n} &= \Big( \begin{pmatrix}
                \id_m &\id_m & \hdots & \id_m
            \end{pmatrix}, 0 \Big)  \qquad \text{and} \qquad
            %
            %
            %
            \fT_{m, n} = \begin{pmatrix}
                \begin{pmatrix}
                    \id_m \\ \id_m \\ \vdots \\ \id_m
                \end{pmatrix}, 0
            \end{pmatrix}
        \end{split}
    \end{align}
    \cfout.
\end{definition}

\cfclear
\begin{definition}[Sums of ANNs with the same length] \label{def:sum_of_anns_same_length}
    %
    %
    \cfconsiderloaded{def:sum_of_anns_same_length}
    %
    %
    Let $u \in \Z$, $v \in \Z \cap [u, \infty)$, $\Phi_u, \Phi_{u + 1}, \dots, \Phi_v \in \bN$ satisfy for all $i \in \Z \cap [u, v]$ that $\cL(\Phi_i) = \cL (\Phi_u)$, $\cI(\Phi_i) = \cI(\Phi_u)$, $\cO(\Phi_i) = \cO(\Phi_u)$. Then we denote by $\oSum_{i = u}^v \Phi_i$ the ANN given by
    \begin{equation}
        \OSum{i = u}{v} \Phi_i = \Big( \fS_{\cO(\Phi_u), v - u + 1} \ANNcomp \big[ \paraANN{v - u + 1} (\Phi_u, \Phi_{u + 1}, \dots, \Phi_v) \big] \ANNcomp \fT_{\cI(\Phi_u), v - u + 1} \Big) \in \bN
    \end{equation}
    %
    %
    \cfout.
\end{definition}

\cfclear
\begin{definition}[Sums of ANNs with different lengths] \label{def:sum_of_anns_diff_length}
    %
    %
    \cfconsiderloaded{def:sum_of_anns_diff_length}
    %
    %
    Let $u \in \Z$, $v \in \Z \cap [u, \infty)$, $\Phi_u, \Phi_{u + 1}, \dots, \Phi_{v}, \Psi \in \bN$ satisfy for all $i \in \Z \cap [u, v]$ that $\cI( \Phi_i) = \cI(\Phi_u)$, $\cO(\Phi_i) = \cI(\Psi) = \cO(\Psi)$, and $\cL(\Psi) = 2$. Then denote by $\bSum_{i = u, \Psi}^v \Phi_i$ the ANN given by
    \begin{equation}
        \BSum{i = u}{\Psi}{v} \Phi_i = \OSum{i = u}{v} \longerANN{\max_{j \in \Z \cap [u, v]} \cL (\Phi_j), \Psi} (\Phi_i)
    \end{equation}
    %
    %
    \cfout.
\end{definition}


\cfclear
\begin{definition}[Scalar multiplications of ANNs]\label{def:scalar_multiplications_of_anns}
    %
    %
    \cfconsiderloaded{def:scalar_multiplications_of_anns}
    %
    %
    We denote by $\scalarANN \colon \R \times \bN \rightarrow \bN$ the function which satisfies for all $\alpha \in \R$, $\Phi \in \bN$ that
    \begin{equation}
        \alpha \circledast \Phi = \left( \alpha \id_{\cO (\Phi)}, 0 \right) \ANNcomp \Phi
    \end{equation}
    \cfout.
\end{definition}

\cfclear
\begin{lemma}\label{lem:scalar_multiplications_of_anns} 
    %
    %
    Let $\alpha \in \R$, $\Phi \in \bN$. Then
    %
    %
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:scalar_multiplications_of_anns_layer_structure} it holds that $\cD (\alpha \scalarANN \Phi) = \cD (\Phi)$,

        \item \label{item:scalar_multiplications_of_anns_realization} it holds that $\cR_\activation ( \alpha \circledast \Phi ) \in C (\R^{\cI (\Phi)}, \R^{\cO (\Phi)})$, and

        \item \label{item:scalar_multiplications_of_anns_realization_evaluated} it holds for all $x \in \R^{\cI (\Phi)}$ that $ \big(\cR_\activation (\alpha \circledast \Phi)\big)(x) = \alpha \big( \cR_\activation (\Phi) \big)(x) $
    \end{enumerate}
    %
    %
    \cfout.
\end{lemma}

\cfclear
\begin{lemma}[Linear combinations of ANNs with the same length]
    \label{lem:linear_combinations_anns_same_length}
    %
    % \cfconsiderloaded{lem:linear_combinations_anns_same_length}
    % \cfload
    %
    Let $u \in \Z$, $v \in \Z \cap [u, \infty)$, $h_u, h_{u + 1}, \dots, h_v \in \R$, $\activation \in C(\R, \R)$, $\Phi_u, \Phi_{u + 1}, \dots, \Phi_v, \Psi \in \bN$, satisfy for all $i \in \Z \cap [u, v]$ that $\cI(\Phi_i) = \cI (\Phi_u)$, $\cO(\Phi_i) = \cO (\Phi_u)$, $\cL(\Phi_i) = \cL(\Phi_u)$ and $ \Psi = \oSum_{i = u}^{v} ( h_i \scalarANN \Phi_i)$. Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:linear_combinations_anns_same_length_layer_structure} it holds that
        \begin{equation} 
            \cD (\Psi) = \Big( \cI (\Phi_u), \SmallSum{i = u}{v}\dimANNlevel_1(\Phi_i) ,\dots, \SmallSum{i = u}{v} \dimANNlevel_{\cL(\Phi_u) - 1} (\Phi_i) , \cO(\Phi_u) \Big),
        \end{equation}

        \item \label{item:linear_combinations_anns_same_length_realization} it holds that $\cR_\activation (\Psi) \in C(\R^{\cI (\Phi_u)}, \R^{\cO(\Phi_u)})$, and

        \item \label{item:linear_combinations_anns_same_length_realization_evaluated}
        it holds for all $x \in \R^{\cI(\Phi_u)}$ that
        \begin{equation}
            \big( \cR_\activation(\Psi) \big)(x) = \sum_{i = u}^{v} h_i \big( \cR_\activation(\Phi_i) \big)(x)
        \end{equation}
    \end{enumerate}
    \cfout[.]
\end{lemma}

\begin{mproof}{\cref{lem:linear_combinations_anns_same_length}}
    First, note that \cref{lem:scalar_multiplications_of_anns} ensures for all $i \in \Z \cap [u, v]$ that $\cD( h_i \circledast \Phi_i ) = \cD (\Phi_i)$. This, the fact that $\cD (\fS_{\cO(\Phi_u), v - u + 1}) = ((v - u + 1)\cO (\Phi_u), \cO(\Phi_u))$, the fact that $\cD (\fT_{\cI(\Phi_u), v - u + 1}) = ( \cI(\Phi_u), (v - u + 1)\cI(\Phi_u) )$, \cref{lem:compositions_of_anns}, and \cref{item:parallelizations_of_anns_same_depth_item_layer_structure} in \cref{lem:parallelizations_of_anns_same_depth} yield 
    \begin{equation}
        \cD (\Psi) = \Big( \cI(\Phi_u), \SmallSum{i = u}{v} \dimANNlevel_1(\Phi_i), \SmallSum{i = u}{v} \dimANNlevel_{2}(\Phi_i), \dots, \SmallSum{i = u}{v} \dimANNlevel_{\cL (\Phi_u) - 1} (\Phi_i) ,\cO(\Phi_u) \Big).
    \end{equation}
    This proves \cref{item:linear_combinations_anns_same_length_layer_structure}. Moreover, observe that \cref{lem:compositions_of_anns} and \cref{item:scalar_multiplications_of_anns_realization_evaluated} in \cref{lem:scalar_multiplications_of_anns} establish for all $x \in \R^{\cI(\Phi_u)}$ that
    \begin{align}
        \begin{split}
            \big( \cR_\activation (\Psi) \big)(x) &= \big( \cR_\activation(\fS_{\cO(\Phi_u), v - u + 1}) \circ \paraANN{v - u + 1}( h_u \circledast \Phi_u, h_{u + 1} \circledast \Phi_{u + 1}, \dots, h_v \circledast \Phi_v) \circ \fT_{\cI(\Phi_u), v - u + 1}\big) (x) \\
            &= \big( \cR_\activation (\fS_{\cO(\Phi_u), v-u +1}) \circ \paraANN{v - u + 1}(h_u \circledast \Phi_u, h_{u + 1} \circledast \Phi_{u + 1}, \dots, h_v \circledast \Phi_v) \big) (x, x, \dots, x)\\
            &= \big( \cR_\activation(\fS_{\cO(\Phi_u), v- u +1}) \big) \begin{pmatrix}
                \big( \cR_\activation (h_u \circledast \Phi_u) \big)(x) \\
                \big( \cR_\activation (h_{u + 1} \circledast \Phi_{u + 1}) \big)(x) \\
                \vdots\\
                \big( \cR_\activation (h_v \circledast \Phi_v) \big)(x)
            \end{pmatrix} = \sum_{i = u}^{v} h_i \big( \cR_\activation(\Phi_i) \big)(x).
        \end{split} 
    \end{align}
    This proves \cref{item:linear_combinations_anns_same_length_realization} and \cref{item:linear_combinations_anns_same_length_realization_evaluated}. The proof of \cref{lem:linear_combinations_anns_same_length} is thus complete.
\end{mproof}

\cfclear
\begin{lemma}[Linear combinations of ANNs with different lengths] \label{lem:linear_combination_anns_different_length}
    %
    % \cfconsiderloaded{lem:linear_combination_anns_different_length}
    % \cfload
    %
    Let $L\in \N$, $\activation \in C(\R, \R)$, $u \in \Z$, $v \in [u, \infty) \cup \Z$, $h_u, h_{u + 1}, \dots, h_v \in \R$, $\Phi_u, \Phi_{u + 1}, \dots, \Phi_v, \Psi, \fJ \in \bN$ satisfy for all $x \in \R^{\cI(\fJ)}$, $i \in \Z \cap [u, v]$ that $\cI(\Phi_i) = \cI(\Phi_u)$, $\cO(\Phi_i) = \cI (\fJ) = \cO (\fJ)$, $L = \max_{j \in \Z \cap [u, v]} \cL(\Phi_j)$, $\cL (\fJ) = 2$, $\big( \cR_\activation (\fJ) \big)(x) = x$, and $\Psi = \bSum_{i = u, \fJ}^v (h_i \scalarANN \Phi_i)$. Then
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:linear_combinations_anns_different_length_layer_structure} it holds that
        \begin{equation}
            \cD (\Psi) = \Big( \cI(\Phi_u), \SmallSum{i = u}{v} \dimANNlevel_1(\longerANN{L, \fJ}(\Phi_i)), \dots, \SmallSum{i = u}{v} \dimANNlevel_{L - 1}( \longerANN{L, \fJ}(\Phi_i) ), \cO(\Phi_u) \Big),
        \end{equation}

        \item \label{item:linear_combinations_anns_different_length_realization} it holds that $\cR_\activation (\Psi) \in C(\R^{\cI(\Phi_u)}, \R^{\cO(\Phi_u)}  )$, and

        \item \label{item:linear_combinations_anns_different_length_realization_evaluated} it holds for all $x \in \R^{\cI(\Phi_u)}$ that
        \begin{equation}
            \big( \cR_\activation(\Psi) \big)(x) = \sum_{i = u}^{v} h_i \big( \cR_\activation(\Phi_i) \big)(x)
        \end{equation}
    \end{enumerate} 
    \cfout.
\end{lemma}

\begin{mproof}{\cref{lem:linear_combination_anns_different_length}}
    First, note that \cref{item:scalar_multiplications_of_anns_layer_structure} in \cref{lem:scalar_multiplications_of_anns} ensures for all $i \in \Z \cap [u, v]$ that $\cD (h_i \scalarANN \Phi_i) = \cD(\Phi_i)$.\ %
    %
    Combining this,
    %
    the assumption that it holds that $\cL(\fJ) = 2$,
    %
    the assumption that it holds that $\cI(\fJ) = \cO(\fJ)$,
    %
    the assumption that for all $x \in \R^{\cI(\fJ)}$ it holds that $\pr*{ \cR_\activation(\fJ) }(x) = x$, and
    %
    \cref{item:certain_extensions_of_anns_item_power,item:certain_extensions_of_anns_item_extension,item:certain_extensions_of_anns_item_extension_to_same_length} in \cref{lem:certain_extensions_of_anns}
    %
    yields for all $i \in \Z \cap [u, v]$ that $\cD (\longerANN{L, \fJ} ( h_i \scalarANN \Phi_i ) ) = \cD(\longerANN{L, \fJ}(\Phi_i))$.\ %
    %
    This and \cref{item:linear_combinations_anns_same_length_layer_structure} in \cref{lem:linear_combinations_anns_same_length}
    %
    % 
    %
    demonstrate that
    \begin{align}
        \begin{split}
            \cD(\Psi) &= \cD \pr*{ \BSum{i = u}{\fJ}{v} (h_i \scalarANN \Phi_i) } = \cD \pr*{ \OSum{i = u}{v} \longerANN{L, \fJ}(h_i \scalarANN \Phi_i)} \\
            %
            &= \pr[\big]{ \cI(\longerANN{L, \fJ} (h_u \scalarANN \Phi_u)), \smallsum_{i = u}^{v} \dimANNlevel_1(\longerANN{ L, \fJ }(h_i \scalarANN \Phi_i)), \dots\\
            %
            &\quad \dots, \smallsum_{i = u}^{v} \dimANNlevel_{L - 1}( \longerANN{L, \fJ}(h_i \scalarANN \Phi_i) ), \cO(\longerANN{L, \fJ} (h_u \scalarANN \Phi_u)) } \\
            %
            &= \pr[\big]{ \cI(\Phi_u), \smallsum_{i = u}^{v} \dimANNlevel_1(h_i \scalarANN \Phi_i), \dots, \smallsum_{i = u}^{v} \dimANNlevel_{L - 1}(h_i \scalarANN \Phi_i), \cO (\Phi_u) } \in \N^{L + 2}.
        \end{split}
    \end{align}
    %
    Hence, it holds that $\cR_\activation(\Psi) \in C(\R^{\cI(\Phi_u)}, \R^{\cO(\Phi_u)})$.\ %
    %
    This proves \cref{item:linear_combinations_anns_different_length_layer_structure,item:linear_combinations_anns_different_length_realization}.\ %
    %
    Furthermore, observe that \cref{item:linear_combinations_anns_same_length_realization_evaluated} in \cref{lem:linear_combinations_anns_same_length},
    %
    \cref{item:scalar_multiplications_of_anns_realization_evaluated} in \cref{lem:scalar_multiplications_of_anns}
    %
    assures for all $x \in \R^{\cI(\Phi_u)}$ that
    %
    \begin{align}
        \begin{split}
            \pr*{ \cR_\activation (\Psi) }(x) &= \sum_{i = u}^{v} \pr[\big]{ \cR_\activation(h_i \scalarANN \Phi_i) }(x) = \sum_{i = u}^{v} h_i \pr[\big]{\cR_\activation(\Phi_i)}(x).
        \end{split}
    \end{align}
    This proves \cref{item:linear_combinations_anns_different_length_realization_evaluated}.\ %
    %
    The proof of \cref{lem:linear_combination_anns_different_length} is thus complete.
\end{mproof}

