\section{ANN representations}
\label{sec:ann_representations}

In this section, we develop representation results for ANNs.
%
In \cref{subsec:ann_representations_max} we establish a representation for maxima through ANNs with leaky ReLU activation function. To this end, we refer to the notions found in \cite[Section~4.2.2]{jentzen2023mathematicalintroductiondeeplearning} for a representation for maxima through ReLU ANNs.
%
In \cref{subsec:ann_representations_MLFP} we develop representations for MLFP approximations through ANNs with general activation function.

\subsection{ANN representations for the maximum function on finite sets}
\label{subsec:ann_representations_max}


\cfclear
\begin{lemma}\label{lem:max_one_step_leaky}
    Let $\beta \in [0, \infty)\backslash \{1 \}$,
    %
    let $\activation \in C(\R, \R)$ satisfy for all $x \in \R$ that $\phi(x) = \max\{ x, \beta x\}$.
    %
    Then there exists $\Phi_n \in \bN$, $n \in \N \cap [2, \infty)$, such that
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:max_one_step_leaky_realization} it holds for all $n \in \N \cap [2, \infty)$ that \begin{equation}
            \cR_\activation (\Phi_n) \in \begin{cases}
                C(\R^n, \R^{\nicefrac{n}{2}}) &\colon n \text{ is even} \\
                C(\R^n, \R^{\nicefrac{(n + 1)}{2}}) &\colon n \text{ is odd},
            \end{cases}
        \end{equation}


        \item \label{item:max_one_step_leaky_realization_evaluated} it holds for all $n \in \N \cap [2, \infty)$, $x = (x_1, x_2, \dots, x_n) \in \R^n$ that
        \begin{equation}
            \big( \cR_\activation (\Phi_n) \big)(x) = \begin{cases}
                ( \max\{x_1, x_2\}, \dots, \max\{x_{n - 1}, x_n\}) \in \R^{\nicefrac{n}{2}} &\colon n \text{ is even}\\
                ( \max\{x_1, x_2 \}, \dots, \max\{x_{n - 2}, x_{n - 1} \}, x_n) \in \R^{\nicefrac{(n + 1)}{2}} &\colon n \text{ is odd,}
            \end{cases}
        \end{equation}


        \item \label{item:max_one_step_leaky_architecture} it holds for all $n \in \N \cap [2, \infty)$ that
        \begin{equation}
            \cD (\Phi_n) = \begin{cases}
                (n, 2n, \tfrac{n}{2}) &\colon n \text{ is even}\\
                (n, 2n, \tfrac{n + 1}{2}) &\colon n \text{ is odd},
            \end{cases}
        \end{equation}
        and

        \item \label{item:max_one_step_leaky_depth} it holds for all $n \in \N \cap [2, \infty)$ that $\cL(\Phi_n) = 2$
    \end{enumerate}
    %
    %
    \cfout.
\end{lemma}

\begin{mproof}{\cref{lem:max_one_step_leaky}}
    Throughout this proof let $\gamma, \delta \in \R$ satisfy $\gamma = \tfrac{|1 - \beta|}{(1 - \beta)(1 - \beta^2)}$ and $ \delta = \tfrac{|1 - \beta|}{1 - \beta}$,
    %
    let $T \in \R^{1 \times 2}$, $w_1 \in \R^{4 \times 2}$, $w_2 \in \R^{1 \times 4}$ satisfy
    \begin{align}
        \begin{split} \label{eq:max_one_step_leaky_def_matrix}
            T &= \begin{pmatrix}
                (1 + \beta)^{-1} & - (1+ \beta)^{-1}
            \end{pmatrix}, \qquad w_1 = \begin{pmatrix}
                \phantom{-}\delta & -\delta \\
                -\delta & \phantom{-}\delta \\
                \phantom{-}0 & \phantom{-}\delta \\
                \phantom{-}0 & -\delta
            \end{pmatrix}, \qquad \text{and}\\
            w_2 &= \begin{pmatrix}
                \gamma & \gamma \beta & \gamma(1 - \beta) & \gamma (\beta - 1)
            \end{pmatrix},
        \end{split}
    \end{align}
    let $\fJ, \bM \in \bN$ satisfy
    \begin{equation} \label{eq:max_one_step_leaky_def_nets_id_max}
        \fJ = \begin{pmatrix}
            \begin{pmatrix}
                \begin{pmatrix}
                    \phantom{-}1 \\ -1
                \end{pmatrix}, \begin{pmatrix}
                    0 \\ 0
                \end{pmatrix}
            \end{pmatrix},
            %
            %
            %
            \begin{pmatrix}
                T, 0
            \end{pmatrix}

        \end{pmatrix}
        %
        %
        %
        \qquad \text{and} \qquad 
            \bM = \begin{pmatrix}
                \begin{pmatrix}
                    w_1, 0
                \end{pmatrix}, \begin{pmatrix}
                    w_2, 0
                \end{pmatrix}
            \end{pmatrix},
    \end{equation}
    %
    %
    %
    let $\Phi_n \in \bN$, $n \in \N \cap [2, \infty)$, satisfy for all $n \in \N \cap [2, \infty)$ that
    \begin{align} \label{eq:max_one_step_leaky_def_Phi_n}
        \Phi_n = \begin{cases}
            \paraANN{\tfrac{n}{2}}(\bM, \bM, \dots, \bM) &: n \text{ is even},\\
            \paraANN{\frac{n + 1}{2}}(\bM, \bM, \dots, \bM, \fJ) &: n \text{ is odd}.
        \end{cases}
    \end{align}
    %
    %
    First, note that \cite[Equation (4.99)]{ackermann2023deep} ensures for all  $x \in \R$ that $\max\{x, 0\} = \gamma \beta \activation (- \delta x) + \gamma \activation (\delta x)$
    %
    This,
    %
    \eqref{eq:max_one_step_leaky_def_matrix},
    %
    and \eqref{eq:max_one_step_leaky_def_nets_id_max},
    %
    imply that for all $x \in \R$, $y = (y_1, y_2) \in \R^2$ it holds that $\cL(\fJ) = \cL(\bM) =  2$, $\cD(\fJ) = (1,2,1) \in \N^3$, $\cD(\bM) = (2, 4, 1) \in \N^3$, $\cR_\activation (\fJ) \in C(\R, \R)$, $\cR_\activation (\bM) \in C(\R^2, \R)$,
    \begin{align}
        \begin{split}
            \big( \cR_\activation (\fJ)\big)(x) &= T \activationDim{2} \left( \begin{pmatrix}
                \phantom{-}1 \\-1
            \end{pmatrix}x \right) = (1 + \beta)^{-1} (\activation (x) - \activation ( - x)) \\
            %
            %
            %
            &= (1 + \beta)^{-1} \big( \max\{x, \beta x\} - \max\{- x, -\beta x\} \big) = \tfrac{x + \beta x}{1 + \beta} = x, \qquad\text{ and}    
        \end{split}\\
        \begin{split}
            \big( \cR_\activation (\bM) \big)(y) &= w_2 \activationDim{4} \left( w_1 \begin{pmatrix}
                y_1 \\ y_2
            \end{pmatrix} \right) = w_2 \activationDim{4} \left( \begin{pmatrix}
                \phantom{-}\delta & -\delta\\
                -\delta & \phantom{-}\delta\\
                \phantom{-}0 & \phantom{-}\delta \\
                \phantom{-}0 & -\delta
            \end{pmatrix} \begin{pmatrix}
                y_1 \\ y_2
            \end{pmatrix}\right) \\
            %
            %
            %
            &= \begin{pmatrix}
                \gamma & \gamma \beta & \gamma(1 - \beta) & \gamma (\beta - 1)
            \end{pmatrix} \begin{pmatrix}
                \activation(\delta (y_1 - y_2)) \\
                \activation(- \delta (y_1 - y_2)) \\
                \activation(\delta y_2) \\
                \activation(-\delta y_2)
            \end{pmatrix} \\
            %
            %
            %
            &= \gamma \activation(\delta (y_1 - y_2)) + \gamma \beta \activation(- \delta (y_1 - y_2)) + \gamma \activation(\delta y_2) + \gamma \beta \activation(-\delta y_2)\\
            %
            %
            &\quad- \gamma \beta \activation(\delta y_2) - \gamma \activation(-\delta y_2) \\
            %
            %
            %
            &= \max\{y_1 - y_2, 0 \} + \max\{y_2, 0 \} - \max\{-y_2, 0 \} =  \max\{y_1, y_2\}.
        \end{split}
    \end{align}
    %
    %
    %
    Combining this,
    %
    \eqref{eq:max_one_step_leaky_def_Phi_n},
    %
    and \cref{lem:parallelizations_of_anns_same_depth} therefore demonstrates for all $n \in \N \cap [2, \infty)$, $x = (x_1, x_2, \dots, x_n) \in \R^n$ that $\cL (\Phi_n) = 2$, 
    \begin{align}
        \begin{split}
            \cD( \Phi_n ) &= \begin{cases}
                (n, 2n, \frac{n}{2}) &: n \text{ is even}\\
                (n, 2n, \frac{n + 1}{2}) &: n \text{ is odd},
            \end{cases} 
        \end{split}\\
        \begin{split}
            \cR_\activation (\Phi_n) &\in \begin{cases}
                C(\R^n, \R^{\nicefrac{n}{2}}) &: n \text{ is even}\\
                C(\R^n, \R^{\nicefrac{(n + 1)}{2}}) &: n \text{ is odd},
            \end{cases}
        \end{split}
    \end{align}
    and 
    \begin{align}
        \begin{split}
            \big( \cR_\activation (\Phi_n) \big)(x) &= \begin{cases}
                \big(\cR_\activation (\paraANN{\tfrac{n}{2}}(\bM, \bM, \dots, \bM))\big)(x_1, x_2, \dots, x_n) &: n \text{ is even}\\
                %
                %
                \big(\cR_\activation(\paraANN{\frac{n + 1}{2}}(\bM, \bM, \dots, \bM, \fJ))\big) (x_1, x_2, \dots, x_n) &: n \text{ is odd}
            \end{cases}\\
            %
            %
            %
            &= \begin{cases}
                \begin{pmatrix}
                    \big( \cR_\activation(\bM) \big)(x_1, x_2)\\
                    \big( \cR_\activation(\bM) \big)(x_3, x_4)\\
                    \vdots\\
                    \big( \cR_\activation(\bM) \big)(x_{n - 1}, x_n)\\
                \end{pmatrix} &: n \text{ is even}\\
                \begin{pmatrix}
                    \big( \cR_\activation(\bM) \big)(x_1, x_2)\\
                    \big( \cR_\activation(\bM) \big)(x_3, x_4)\\
                    \vdots\\
                    \big( \cR_\activation(\bM) \big)(x_{n - 2}, x_{n - 1})\\
                    \big( \cR_\activation(\fJ) \big)(x_n)
                \end{pmatrix} &: n \text{ is odd}
            \end{cases} \\
            %
            %
            %
            &= \begin{cases}
                \big( \max\{x_1, x_2\}, \max\{x_3, x_4\}, \dots, \max\{x_{n - 1}, x_n\} \big) &: n \text{ is even}\\
                \big(\max\{x_1, x_2\}, \max\{x_3, x_4\}, \dots, \max\{x_{n - 2}, x_{n - 1}\}, x_n \big) &: n \text{ is odd}.
            \end{cases}
        \end{split}
    \end{align}
    %
    %
    %
    This proves \cref{item:max_one_step_leaky_realization,item:max_one_step_leaky_realization_evaluated,item:max_one_step_leaky_architecture,item:max_one_step_leaky_depth}. The proof of \cref{lem:max_one_step_leaky} is thus complete.
\end{mproof}



\cfclear
\begin{lemma}[Maximum of finite set of real numbers (leaky ReLU ANN)] \label{lem:max_of_finite_set_leaky}
    Let $\beta \in [0, \infty) \backslash \{1\}$,
    %
    for every $\dm \in \N$, $x = \pr{x_1, \dots, x_\dm} \in \R^\dm$ let $\fnorm{x} \in \R$ satisfy $\fnorm{x} = \max_{i \in \cu{1,\dots, \dm}} \abs{x_i}$,
    %
    let $\ceil{\cdot} \colon \R \to \Z$ satisfy for all $x \in \R$ that $\ceil{x} = \min \{ l \in \Z : l \ge x \}$,
    %
    let $\activation \in C(\R, \R)$ satisfy for all $x \in \R$ that $\activation(x) = \max\{x, \beta x\}$.
    %
    Then there exists $\Psi_m \in \bN$, $m \in \N \cap [2, \infty)$, such that
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:max_of_finite_set_leaky_realization} it holds for all $m \in \N \cap [2, \infty)$ that $\cR_\activation (\Psi_m) \in C(\R^m, \R)$,
        %
        %
        %
        \item \label{item:max_of_finite_set_leaky_realization_evaluated} it holds for all $m \in \N \cap [2, \infty)$, $x = (x_1, x_2, \dots, x_m) \in \R^m$ that
        \begin{equation}
            \big( \cR_\activation (\Psi_m) \big)(x) = \max_{i \in [1, m] \cap \N} x_i,
        \end{equation}
        %
        % 
        %
        and
        %
        \item \label{item:max_of_finite_set_leaky_width_depth_size} it holds for all $m \in \N \cap [2, \infty)$ that
        \begin{equation}
            \fnorm{\cD(\Psi_m)} \le 2m \qquad \text{ and } \qquad  \cL(\Psi_m) = \ceil{\log_2(m)} + 1
        \end{equation}
    \end{enumerate}
    %
    %
    \cfout.
\end{lemma}

\begin{mproof}{\cref{lem:max_of_finite_set_leaky}}
    First, note that \cref{lem:max_one_step_leaky} assures that there exist $\Phi_n \in \bN$, $n \in \N \cap [2, \infty)$, such that \cref{item:max_one_step_leaky_realization,item:max_one_step_leaky_realization_evaluated,item:max_one_step_leaky_architecture,item:max_one_step_leaky_depth} in \cref{lem:max_one_step_leaky} hold true.
    %
    Throughout the remainder of this proof let $\Psi_m \in \bN$, $m \in \N \in [2, \infty)$, satisfy for all $m \in \N \cap [3, \infty)$ that $\Psi_2 = \Phi_2$ and $\Psi_m = \Psi_{\ceil{\frac{m}{2}}} \bullet \Phi_m$.
    %
    We prove \cref{item:max_of_finite_set_leaky_realization,item:max_of_finite_set_leaky_realization_evaluated,item:max_of_finite_set_leaky_width_depth_size} by induction on $m \in \N \cap [2, \infty)$.
    %
    For the base case $m = 2$ observe that the fact that $\Psi_2 = \Phi_2$
    %
    and \cref{item:max_one_step_leaky_realization,item:max_one_step_leaky_realization_evaluated,item:max_one_step_leaky_architecture} in \cref{lem:max_one_step_leaky}
    %
    imply for all $x = (x_1, x_2) \in \R^2$ that $\cR_\activation (\Psi_2) \in C(\R^2, \R)$, $\big( \cR_\activation (\Psi_2) \big)(x_1, x_2) = \max\{x_1, x_2\}$, $\fnorm{\cD(\Psi_2)} = 4$, and $\cL(\Psi_2) = 2 = \ceil{\log_2(2)} + 1$.
    %
    This proves \cref{item:max_of_finite_set_leaky_realization,item:max_of_finite_set_leaky_realization_evaluated,item:max_of_finite_set_leaky_width_depth_size} for the base case $m = 2$.
    %
    For the induction step $ \N \cap [2, \infty) \ni (m - 1) \induct m \in \N \cap [3, \infty)$ let $m \in \N \cap [3, \infty)$ and assume that \cref{item:max_of_finite_set_leaky_realization,item:max_of_finite_set_leaky_realization_evaluated,item:max_of_finite_set_leaky_width_depth_size} hold true for all $l \in \N \cap [2, m - 1]$.
    %
    Observe that the fact that for all $l \in \Z$ it holds that
    \begin{equation}
        \ceil[\big]{\tfrac{l}{2}} = \begin{cases}
            \tfrac{l}{2} &: l \text{ is even}\\
            \tfrac{l + 1}{2} &: l \text{ is odd}
        \end{cases}
    \end{equation}
    and \cref{item:max_one_step_leaky_architecture} in \cref{lem:max_one_step_leaky} demonstrate for all $l \in \N \cap [2, \infty)$ that
    \begin{equation} \label{eq:max_of_finite_set_leaky_architecture_Phi_n}
        \cD (\Phi_l) = \left. \begin{cases}
            (l, 2l, \nicefrac{l}{2}) &: l \text{ is even}\\
            (l, 2l, \nicefrac{(l + 1)}{2}) &: l \text{ is odd}
        \end{cases} \right\} = (l, 2l, \ceil{\tfrac{l}{2}}) \in \N^3.
    \end{equation}
    %
    %
    %
    This, \cref{lem:compositions_of_anns}, and the induction hypothesis establish that 
    \begin{align}
        \begin{split} \label{eq:max_of_finite_set_leaky_in_out_realization}
            \cI (\Psi_m) &= \cI (\Phi_m) = m, \qquad \cO (\Psi_m) = \cO( \Psi_{\ceil{\frac{m}{2}}}) = 1,\\
            %
            \text{and} \qquad \cR_\activation(\Psi_m) &= \cR_\activation(\Psi_{\ceil{\frac{m}{2}}}) \circ \cR_\activation(\Phi_m) \in C(\R^m, \R).
        \end{split}
    \end{align}
    %
    %
    %
    Moreover, note that \cref{lem:compositions_of_anns},
    %
    \cref{item:max_one_step_leaky_realization_evaluated} in \cref{lem:max_one_step_leaky},
    %
    the fact that for all $l \in \N \cap [2, \infty)$ it holds that $\ceil{\tfrac{l}{2}} < l$,
    %
    and the induction hypothesis that for all $l \in \N \cap [2, m - 1]$, $x = (x_1, \dots, x_l) \in \R^l$ it holds that $\big( \cR_\activation (\Psi_l)\big)(x) = \max_{i \in \N \cap [1, l]} x_i$
    %
    show for all $x = (x_1, x_2, \dots, x_m) \in \R^m$ that 
    \begin{align} \label{eq:max_of_finite_set_leaky_realization_evaluated}
        \big( \cR_\activation (\Psi_m) \big)(x) &= \big( \cR_\activation (\Psi_{\ceil{\frac{m}{2}}}) \circ \cR_\activation (\Phi_{m}) \big)(x_1, x_2, \dots, x_m) \nonumber \\
        %
        %
        %
        &= \begin{cases}
            \max\!\big\{\! \max\{x_1, x_2\}, \max\{x_3, x_4\}, \dots, \max\{x_{m - 1}, x_m\}\! \big\} &: m \text{ is even}\\
            %
            %
            \max\!\big\{\! \max\{x_1, x_2\}, \max\{x_3, x_4\}, \dots, \max\{x_{m - 2}, x_{m - 1}\}, x_m\! \big\} &: m \text{ is even}
        \end{cases} \nonumber \\
        %
        %
        %
        &= \max\{ x_1, x_2, \dots, x_m \}.
    \end{align}
    %
    %
    %
    In addition, observe that \cref{lem:compositions_of_anns},
    %
    \eqref{eq:max_one_step_leaky_def_Phi_n},
    %
    the fact that for all $l \in \N \cap [2, \infty)$ it holds that $\ceil{\tfrac{l}{2}} < l$,
    %
    and the induction hypothesis assure that
    \begin{equation} \label{eq:max_of_finite_set_leaky_width_Psi_m}
        \fnorm{ \cD (\Psi_m )} \le \max\big\{  \fnorm{\cD (\Psi_{\ceil{\frac{m}{2}}})}, \fnorm{ \cD (\Phi_m)} \big\} \le \max\big\{ 2 \ceil{\tfrac{m}{2}}, 2m \big\} = 2m.
    \end{equation}
    %
    Furthermore, note that the fact that for all $l\in \N \cap [2, \infty)$ it holds that $\ceil{\log_2(2 \ceil{\nicefrac{l}{2}})} = \ceil{\log_2(l)}$,
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{item:max_one_step_leaky_depth} in \cref{lem:max_one_step_leaky},
    %
    and the induction hypothesis imply that
    \begin{align}
        \begin{split}
            \cL(\Psi_m) &= \cL(\Psi_{\ceil{\frac{m}{2}}}) + \cL(\Phi_m) - 1 = \cL(\Psi_{\ceil{\frac{m}{2}}}) + 1 = \big( \ceil{\log_2(\ceil{\nicefrac{m}{2}})} + 1 \big) + 1\\
            &= \big( \ceil{\log_2(2 \ceil{\nicefrac{m}{2}})} \big) + 1 = \ceil{\log_2(m)} + 1.
        \end{split}
    \end{align}
    %
    %
    %
    Combining this,
    %
    \eqref{eq:max_of_finite_set_leaky_in_out_realization},
    %
    \eqref{eq:max_of_finite_set_leaky_realization_evaluated},
    %
    and \eqref{eq:max_of_finite_set_leaky_width_Psi_m} completes the induction step. Induction hence proves \cref{item:max_of_finite_set_leaky_realization,item:max_of_finite_set_leaky_realization_evaluated,item:max_of_finite_set_leaky_width_depth_size}. The proof of \cref{lem:max_of_finite_set_leaky} is thus complete.
\end{mproof}

