\subsection{ANN representations for MLFP approximations}
\label{subsec:ann_representations_MLFP}

\cfclear
\begin{lemma}[ANN representations for MLFP Approximations] \label{lem:mlfp_as_ann_general}
    Let $\dm, \fd \in \N$,
    %
    let $M \in \N \cap [2, \infty)$,
    %
    let $\Theta = \cup_{n \in \N} \Z^n$,
    %
    let $A$ be a nonempty finite set,
    %
    let $\action \in A$,
    %
    let $\activation \in C(\R, \R)$,
    %
    let $\fJ, \bF \in \bN$ satisfy $\cD (\fJ) = (1, \fd, 1)$, $\cR_\activation(\fJ) = \idfunc_{\R}$, and $\cR_\activation (\bF) \in C(\R^{\dm + |A|}, \R) $,
    %
    let $\bX_a^\theta \in \bN$, $\theta \in \Theta$, $a \in A$, satisfy for all $\theta \in \Theta$, $a \in A$ that $\cD (\bX_a^\theta) = \cD (\bX_\action^0)$ and $\cR_\activation(\bX_a^\theta) \in C(\R^\dm, \R^\dm)$,
    %
    for every $\dm \in \N$, $x \in \pr{x_1, \dots, x_\dm} \in \R^\dm$ let $\fnorm{x} \in \R$ satisfy $\fnorm{x} = \max_{i \in \cu{1,\dots, \dm}} \abs{x_i}$,
    %
    let $c = 2 \max\{ \fnorm{\cD(\bF)}, \fnorm{\cD(\bX_\action^0)},  \fd \dm + \fd \abs{A} \}$,
    %
    let $\varmlfp_n^\theta \colon \R^\dm \to \R^{|A|}$, $\theta \in \Theta$, $n \in \N_0$, satisfy for all $\theta \in \Theta$, $n \in \N_0$, $x \in \R^\dm$, $a \in A$ that
    %
    %
    %
    \begin{multline} \label{eq:mlfp_as_ann_general_def_mlfp_scheme}
        \big(\varmlfp_{n}^{\theta} (x) \big)(a) = \sum_{l = 0}^{n - 1} \frac{1}{M^{n - l}} \sum_{i = 1}^{M^{n - l}} \Big[ \big( \cR_\activation(\bF) \big) \big(  \big( \cR_\activation(\bX_a^{(\theta, l, i)}) \big)(x), \varmlfp_{l}^{(\theta, l, i)} \big( \big(\cR_\activation( \bX_a^{(\theta, l, i)} ) \big)(x)  \big) \big)\\
        %
        %
        %
        -\mathbbm{1}_{\N}\pr{l} \bigl( \cR_\activation (\bF) \bigr) \bigl( \bigl(\cR_\activation (\bX_a^{(\theta, l, i)})\bigr)(x) , \varmlfp_{\max\{l - 1, 0\}}^{(\theta, -l, i)} \bigl( \bigl( \cR_\activation (\bX_a^{(\theta, l, i)}) \bigr)(x) \bigr)  \bigr) \Big].
    \end{multline}
    %
    %
    %
    Then there exists $\Phi_n^\theta \in \bN$, $\theta \in \Theta$, $n \in \N_0$, such that
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:mlfp_as_ann_general_realization} it holds for all $\theta \in \Theta$, $n \in \N_0$ that $\cR_\activation(\Phi_n^\theta) \in C(\R^\dm, \R^{|A|})$,

        \item \label{item:mlfp_as_ann_general_realization_evaluated} it holds for all $\theta \in \Theta$, $n \in \N_0$, $x \in \R^\dm$ that $\bigl( \cR_\activation (\Phi_n^\theta) \bigr) (x) = \varmlfp_n^\theta(x) \in \R^{|A|}$,

        \item \label{item:mlfp_as_ann_general_layer_structure} it holds for all $\theta \in \Theta$, $n \in \N_0$ that $ \cD(\Phi_n^\theta) = \cD(\Phi_n^0)$,

        \item \label{item:mlfp_as_ann_general_depth} it holds for all $\theta \in \Theta$, $n \in \N_0$ that
        \begin{equation}
            \cL(\Phi_n^\theta) \le n \big( \cL(\bF) + \cL(\bX_\action^0) - 1 \big) + 1,
        \end{equation}

        \item \label{item:mlfp_as_ann_general_width} it holds for all $\theta \in \Theta$, $n \in \N_0$ that
        \begin{equation}
            \fnorm{\cD (\Phi_n^\theta)} \le c (4 |A| M)^n,
        \end{equation}
        and
        \item \label{item:mlfp_as_ann_general_size} it holds for all $\theta \in \Theta$, $n \in \N_0$ that
        \begin{equation}
            \paramANN(\Phi_n^\theta) \le 2 \bigl( n \bigl( \cL(\bF) + \cL(\bX_\action^0) - 1 \bigr) + 1 \bigr) c^2 (4|A|M)^{2n}
        \end{equation}
    \end{enumerate}
    \cfout.
\end{lemma}

\begin{mproof}{\cref{lem:mlfp_as_ann_general}}
    Throughout this proof let $\I_k \in \bN$, $k \in \N$, satisfy for all $k \in \N$ that
    \begin{equation}
        \I_k = \paraANN{k} (\fJ, \dots, \fJ),    
    \end{equation}
    %
    let $\mathbb{J} \in \bN^2$ satisfy $\mathbb{J} = (\I_\dm, \I_{\abs{A}})$.
    %
    Next, observe that \cref{lem:parallelizations_of_anns_same_depth} ensures for all $k \in \N$, $x \in \R^k$ that $\cD (\I_k) = (k, k \fd, k) \in \N^3$, $\cL(\I_k) = 2$, $\cR_\activation (\I_k) \in C(\R^k, \R^k)$, and $\bigl( \cR_\activation (\I_k) \bigr)(x) = x$.
    %
    Throughout the remainder of this proof let $\Lambda_n^{\theta, a }, \Phi_n^\theta, \Xi_n^\theta \in \bN$, $\theta \in \Theta$, $n \in \N_0$, $a \in A$, satisfy for all $\theta \in \Theta$, $n \in \N$, $a \in A$ that
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_def_base_case_ANN} 
            \Lambda_0^{\theta, a} &= \left( \begin{pmatrix}
                0 & 0 & \cdots & 0
            \end{pmatrix}, 0 \right) \in \R^{1 \times \dm} \times \R^1, \qquad \Phi_0^\theta = \paraANN{\abs{A}} ( (\Lambda_0^{\theta, a})_{a \in A} ) \bullet \fT_{\dm, \abs{A}},\\
            %
            \Xi_0^\theta &= \left( 0, 0 \right) \in \R^{({\abs{A}} + \dm) \times \dm} \times \R^{\abs{A} + \dm},
        \end{split}\\
        \phantom{a} \nonumber \\
        %
        % 
        %
        \begin{split} \label{eq:mlfp_as_ann_general_Lambda}
            \Lambda_n^{\theta, a} &= \Bigg[ \BSum{l = 0}{\fJ}{n-1} \Bigg[ \scalar{\frac{1}{M^{n - l}}}{ \left( \BSum{i = 1}{\fJ}{M^{n - l}} \left( \bF \bullet \Xi_l^{(\theta, l, i)} \bullet \bX_a^{(\theta, l, i)} \right) \right)} \Bigg] \Bigg] \\
            %
            &\quad \bSum_{\,\fJ} \Bigg[ \BSum{l = 0}{\fJ}{n - 1} \Bigg[ \scalar{\frac{- \mathbbm{1}_\N (l)}{ M^{n - l} }}{ \left( \BSum{i = 1}{\fJ}{M^{n - l}} \left( \bF \bullet \Xi_{\max\{ l - 1, 0 \} }^{(\theta, -l , i)} \bullet \bX_a^{(\theta, l, i)} \right) \right) } \Bigg]  \Bigg],
        \end{split}\\
        \phantom{a} \nonumber \\
        %
        % 
        %
        \begin{split} \label{eq:mlfp_as_ann_general_Phi}
            \Phi_n^\theta &= \paraANN{\abs{A}} ( ( \Lambda_n^{\theta, a} )_{a \in A} ) \bullet \fT_{\dm, \abs{A}},
        \end{split}\\
        \phantom{a} \nonumber \\
        %
        % 
        %
        \begin{split} \label{eq:mlfp_as_ann_general_Xi}
            \Xi_n^{\theta} &= \paraLANN{2}{\mathbb{J}} \left( \I_\dm, \Phi_n^\theta \right) \bullet \fT_{\dm, 2},
            %
            %
            %
        \end{split} 
    \end{align}   
    %
    %   
    %
    let $\Psi_{n, l}^{\theta, j, a} \in \bN$, $\theta \in \Theta$, $n \in \N$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0,1\}$, $a \in A$,
    %
    satisfy for all $\theta \in \Theta$, $n \in \N$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0,1\}$, $a \in A$ that
    %
    %
    %
    \begin{equation} \label{eq:mlfp_as_ann_general_Psi}
        \Psi_{n, l}^{\theta, j, a} = \BSum{i = 1}{\fJ}{M^{n - l}} \left( \bF \bullet \Xi_{\max\{ l - j, 0 \} }^{( \theta, (-1)^jl, i )} \bullet \bX_a^{(\theta, l, i)} \right) \in \bN,
    \end{equation}
    %
    %
    %
    and let $\Gamma_n^{\theta, j, a} \in \bN$, $\theta \in \Theta$, $n \in \N$, $j \in \{0,1\}$, $a \in A$,
    %
    satisfy for all $\theta \in \Theta$, $n \in \N$, $j \in \{0,1\}$, $a \in A$ that
    %
    %
    %
    \begin{equation} \label{eq:mlfp_as_ann_general_Gamma}
        \Gamma_n^{\theta, j, a} = \BSum{l = 0}{\fJ}{n - 1} \left[ \scalar{\tfrac{ (-1)^j \mathbbm{1}_\N(l + 1 - j) }{ M^{n - l} }}{ \Psi_{n, l}^{\theta, j , a} } \right],
    \end{equation}
    %
    %
    %
    let $L^j_{l} \in \N$, $l \in \N_0 \cap [0, \infty) $, $j \in \{0,1\}$, satisfy for all $l \in \N_0 \cap [0, \infty)$, $j \in \{0,1\}$ that
    \begin{equation}
        L^j_{l} = \cL \bigl( \bF \bullet \Xi_{\max \{l - j, 0\} }^{0} \bullet \bX_\action^0 \bigr),
    \end{equation}
    %
    let $\fL_n^j \in \N$, $n \in \N$, $j \in \{0,1\}$, satisfy for all $n\in \N$, $j \in \{0,1\}$ that
    \begin{equation}
        \fL_n^j = \max_{l \in \N_0 \cap [0, n-1]} L_{l}^j,
    \end{equation}
    %
    let $\mathbb{L}_n \in \N$, $n \in \N$, satisfy for all $n \in \N$ that
    %
    \begin{equation} \label{eq:mlfp_as_ann_general_depth_nth_iterate} 
        \mathbb{L}_n = \max_{j \in \{0,1\}} \fL_n^j.
    \end{equation}
    %
    %
    %
    %
    Observe that for $\theta \in \Theta$, $n \in \N$, $a \in A$ it holds that
    \begin{equation}
        \Lambda_n^{\theta, a} = \Gamma_{n}^{\theta, 0, a} \,\bSum_{\,\fJ}\, \Gamma_n^{\theta, 1, a}.
    \end{equation}
    %
    %
    %
    %
    %
    We prove \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated,item:mlfp_as_ann_general_layer_structure,item:mlfp_as_ann_general_depth,item:mlfp_as_ann_general_width,item:mlfp_as_ann_general_size} by induction on $n \in \N_0$.
    %
    For the base case $n = 0$ note that \eqref{eq:mlfp_as_ann_general_def_base_case_ANN} ensures for all $\theta \in \Theta$, $a \in A$ that $\Lambda_0^{\theta, a} = (0, 0) \in \R^{1 \times \dm} \times \R^1$.
    %
    This establishes for all $\theta \in \Theta$, $a \in A$ that $\cD (\Lambda_0^{\theta, a}) = \cD (\Lambda_0^{0, \action}) = (\dm, 1)$.
    %
    Combining this, the fact that for all $j, k \in \N$ it holds that $\cD (\fT_{k, j}) = (k, kj)$, \eqref{eq:mlfp_as_ann_general_def_base_case_ANN}, \cref{lem:compositions_of_anns},
    %
    and \cref{lem:parallelizations_of_anns_same_depth}
    %
    proves for all $\theta \in \Theta$ that $\cD (\Phi_0^\theta) = \cD (\Phi_0^0) = (\dm, \abs{A})$.
    %
    Hence, \cref{item:mlfp_as_ann_general_layer_structure} holds for the base case $n = 0$.
    %
    Moreover, note that \eqref{eq:mlfp_as_ann_general_def_base_case_ANN} ensures for all $\theta \in \Theta$ that $\cD(\Xi_0^\theta) = \cD(\Xi_0^0) = (\dm, \dm + \abs{A})$.
    %
    Thus for all $\theta \in \Theta$, $a \in A$ it holds that
    \begin{equation}
        \cL (\Xi_0^\theta) = \cL(\Phi_0^\theta) = \cL (\Lambda_0^{\theta, a}) =  0 \cdot \bigl( \cL (\bF) + \cL (\bX_\action^0) - 1 \bigr) + 1.
    \end{equation}
    %
    This proves \cref{item:mlfp_as_ann_general_depth} for the base case $n = 0$.
    %
    The fact that for all $\theta \in \Theta$ it holds that $\cD(\Phi_0^\theta) = (\dm, \abs{A})$ implies for all $\theta \in \Theta$ that $\fnorm{ \cD(\Phi_0^\theta) } = \max \{\dm, \abs{A}\} \le \dm + \abs{A} \le c$ and $ \paramANN(\Phi_0^\theta) = \abs{A}(\dm + 1) \le c^2 \le 2c^2$.
    %
    This establishes \cref{item:mlfp_as_ann_general_width,item:mlfp_as_ann_general_size} for the base case $n = 0$.
    %
    Furthermore, note that \eqref{eq:mlfp_as_ann_general_def_base_case_ANN} implies for all $\theta \in \Theta$, $x \in \R^\dm$, $a \in A$ that $\cR_\activation (\Lambda_0^{\theta, a}) \in C(\R^\dm, \R)$ and $\bigl( \cR_\activation(\Lambda_0^{\theta, a}) \bigr)(x) = 0$.
    %
    This,
    %
    \eqref{eq:mlfp_as_ann_general_def_base_case_ANN},
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{lem:parallelizations_of_anns_same_depth},
    %
    and the fact that for all $\theta \in \Theta$, $x \in \R^\dm$, $a \in A$ it holds that $ \bigl( \varmlfp_0^{\theta}(x) \bigr)(a) = 0$
    %
    demonstrate for all $\theta \in \Theta$, $x \in \R^\dm$ that $\cR_\activation (\Phi_0^\theta) \in C (\R^\dm, \R^{|A|})$ and
    \begin{align}
        \begin{split}
            \bigl(\cR_\activation (\Phi_0^\theta) \bigr)(x) &= \bigl(  \cR_\activation( \paraANN{\abs{A}}((\Lambda_0^{\theta, a})_{a \in A}) \bullet \fT_{\dm, \abs{A}} )  \bigr)(x) = \bigl( \cR_\activation ( \paraANN{\abs{A}}((\Lambda_0^{\theta, a})_{a \in A}) ) \bigr)\begin{pmatrix}
                x \\x \\ \vdots \\ x
            \end{pmatrix}\\
            %
            &= \Bigl( \bigl( \cR_\activation (\Lambda_0^{\theta, a}) \bigr)(x) \Bigr)_{a \in A} = 0 = \varmlfp_0^\theta(x).
        \end{split}
    \end{align}
    Hence \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated} hold true for the base case $n = 0$.
    %
    Thus \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated,item:mlfp_as_ann_general_layer_structure,item:mlfp_as_ann_general_depth,item:mlfp_as_ann_general_width,item:mlfp_as_ann_general_size} hold for the base case $n = 0$.
    %
    %
    %
    %
    %
    For the induction step $\N_0 \ni (n - 1) \induct n \in \N$ let $n \in \N$ and assume that \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated,item:mlfp_as_ann_general_layer_structure,item:mlfp_as_ann_general_depth,item:mlfp_as_ann_general_width,item:mlfp_as_ann_general_size} hold for all $l \in \N_0 \cap [0, n - 1]$.
    %
    First, note that \eqref{eq:mlfp_as_ann_general_Xi},
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities},
    %
    and the induction hypothesis imply for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $x \in \R^\dm$ that
    %
    %
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Xi_realization_evaluated} 
            \bigl( \cR_\activation (\Xi_l^\theta)\bigr) (x) &= \bigl( \cR_\activation ( \paraLANN{2, \mathbb{J}} ( \I_\dm, \Phi_l^\theta ) \bullet \fT_{\dm, 2} ) \bigr)(x) = \bigl( \cR_\activation (\paraLANN{2, \mathbb{J}} ( \I_\dm, \Phi_l^\theta ) ) \circ \cR_\activation (\fT_{\dm, 2}) \bigr) (x)\\
            %
            %
            %
            &= \bigl(\cR_\activation (\paraLANN{2, \mathbb{J}} ( \I_\dm, \Phi_l^\theta ) )\bigr)(x, x) = \begin{pmatrix}
                \bigl( \cR_\activation (\I_\dm) \bigr)(x) \\ \bigl( \cR_\activation (\Phi_l^\theta) \bigr)(x)
            \end{pmatrix} = \begin{pmatrix}
                x \\ \varmlfp_l^\theta(x)
            \end{pmatrix} \in \R^{\dm + \abs{A}}.
        \end{split}
    \end{align}
    %
    %
    %
    This and \cref{lem:compositions_of_anns} demonstrate for all $\theta, \vartheta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $x \in \R^\dm$, $a \in A$ that 
    %
    %
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_summands_realization_evaluated}
            \bigl( \cR_\activation (\bF \bullet \Xi_l^\vartheta \bullet \bX_a^\theta) \bigr)(x) &= \bigl( \cR_\activation(\bF) \circ \cR_\activation(\Xi_l^\vartheta) \bigr) \bigl( \bigl( \cR_\activation(\bX_a^\theta) \bigr)(x) \bigr)\\
            %
            %
            %
            &= \bigl( \cR_\activation (\bF) \bigr) \Bigl( \bigl( \cR_\activation(\bX_a^\theta) \bigr)(x) , \varmlfp_l^\vartheta \bigl( \bigl( \cR_\activation(\bX_a^\theta) \bigr)(x) \bigr)  \Bigr).
        \end{split}
    \end{align}
    %
    %
    %
    Moreover, observe that \eqref{eq:mlfp_as_ann_general_Xi} and the induction hypothesis
    %
    establish for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n -1]$ that $\cD (\Xi_l^\theta) = \cD(\Xi_l^0) $.
    %
    Combining this,
    %
    \cref{lem:compositions_of_anns},
    %
    and the assumption that for all $\theta \in \Theta$, $a \in A$ it holds that $\cD (\bX_a^\theta) = \cD (\bX_\action^0)$
    %
    proves for all $\theta, \vartheta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $a \in A$ that 
    %
    \begin{equation} 
        \cD (\bF \bullet \Xi_{\max\{l - j, 0\}}^\vartheta \bullet \bX_a^\theta) = \cD ( \bF \bullet \Xi_{\max \{l - j, 0\}}^0 \bullet \bX_\action^0 ). 
    \end{equation}
    %
    This implies for all $\theta, \vartheta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $a \in A$ that 
    %
    %
    %
    \begin{equation}
        \cL \bigl( \bF \bullet \Xi_{\max\{ l - j, 0 \}}^\vartheta \bullet \bX_a^\theta \bigr) = \cL \bigl(\bF \bullet \Xi_{\max \{l - j, 0\}}^0 \bullet \bX_\action^0 \bigr) = L_{l}^j.
    \end{equation}
    %
    %
    %
    This,
    %
    \cref{lem:linear_combination_anns_different_length} (applied for every $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $a \in A$ with
    \begin{align}
        \begin{split}
            &u \with 1, \qquad v \with M^{n - l}, \qquad \fJ \with \fJ, \qquad (h_k)_{k \in \Z \cap [u, v]} \with (1)_{i \in \N \cap [1, M^{n - l}]},\\
            &L \with L^j_{l}, \qquad \activation \with \activation, \qquad \Psi \with \Psi_{n, l}^{\theta, j, a},\\
            &(\Phi_k)_{k \in \Z \cap [u, v]} \with (\bF \bullet \Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bullet \bX_a^{(\theta, l, i)})_{i \in \N \cap [1, M^{n - l}]}
        \end{split}
    \end{align}
    in the notation of \cref{lem:linear_combination_anns_different_length}),
    %
    and \cref{item:certain_extensions_of_anns_item_extension_to_same_length} in \cref{lem:certain_extensions_of_anns} yield for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $x \in \R^\dm$, $a \in A$ that
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Psi_layer_structure}
            &\cD (\Psi_{n, l}^{\theta, j, a})\\
            %
            %
            %
            &= \pr[\bigg]{\dm, \SmallSum{i = 1}{M^{n - l}} \dimANNlevel_1 (\longerANN{L^j_{l}, \fJ} (\bF \bullet \Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bullet \bX_a^{(\theta, l, i)}) ), \SmallSum{i = 1}{M^{n - l}} \dimANNlevel_2  (\longerANN{L^j_{l}, \fJ} (\bF \bullet \Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bullet \bX_a^{(\theta, l, i)}) ), \dots\\
            %
            %
            %
            &\quad\dots,\SmallSum{i = 1}{M^{n - l}} \dimANNlevel_{L_{l}^j - 1} (\longerANN{L^j_{l}, \fJ} (\bF \bullet \Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bullet \bX_a^{(\theta, l, i)}) ), 1} \\
            %
            %
            %
            &= \pr[\bigg]{\dm, M^{n - l} \dimANNlevel_1 (\bF \bullet \Xi^0_{\max\{l - j, 0\}} \bullet \bX_\action^0 ),  M^{n - l} \dimANNlevel_2 (\bF \bullet \Xi^0_{\max\{l - j, 0\}} \bullet \bX_\action^0 ), \dots\\
            %
            &\quad\dots,  M^{n - l} \dimANNlevel_{L^j_{l} - 1} (\bF \bullet \Xi^0_{\max\{l - j, 0\}} \bullet \bX_\action^0 ), 1} \in \N^{L^j_{l} + 1}
        \end{split}
    \end{align}
    %
    and
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Psi_realization_evaluated}
            \bigl(\cR_\activation(\Psi_{n, l}^{\theta, j, a})\bigr)(x) &= \sum_{i = 1}^{M^{n - l}} \Bigl( \cR_\activation  \bigl( \bF \bullet \Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bullet \bX_a^{(\theta, l, i)}  \bigr) \Bigr)(x)\\
            %
            %
            %
            &= \sum_{i = 1}^{M^{n - l}} \Bigl( \cR_\activation (\bF) \Bigr) \Bigl( \bigl( \cR_\activation (\bX_a^{(\theta, l, i)}) \bigr)(x) , \varmlfp_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)} \bigl(  \bigl( \cR_\activation (\bX_a^{(\theta, l, i)}) \bigr)(x)  \bigr)  \Bigr).
        \end{split}
    \end{align}
    %
    %
    %
    Furthermore, observe that \eqref{eq:mlfp_as_ann_general_Psi_layer_structure} and \cref{lem:scalar_multiplications_of_anns} assure for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $a \in A$ that
    \begin{equation}
        \cD \Bigl( \scalar{\tfrac{(-1)^j\mathbbm{1}_{\N}(l + 1 - j)}{M^{n - l}}}{\Psi_{n, l}^{\theta, j, a}} \Bigr) = \cD (\Psi_{n, l}^{\theta, j, a}) = \cD (\Psi_{n, l}^{0, j, \action}).
    \end{equation}
    %
    Hence, it holds for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$, $j \in \{0, 1\}$, $a \in A$ that $\cL (\Psi_{n, l}^{\Theta, j, a}) = \cL (\Psi_{n, l}^{0, j, \action}) = L^j_{l}$. This ensures for all $\theta \in \Theta$, $a \in A$, $j \in \{0, 1\}$ that $\max_{l \in \N_0 \cap [0, n - 1] } \cL(\Psi_{n, l}^{\theta, j, a}) = \max_{l \in \N_0 \cap [0, n - 1]} L_{l}^j = \fL_n^j $.
    %
    Moreover, note that this,
    %
    \eqref{eq:mlfp_as_ann_general_Gamma},
    %
    and \cref{lem:linear_combination_anns_different_length} (applied for every $\theta \in \Theta$, $j \in \{0, 1\}$, $a \in A$ with
    \begin{align}
        \begin{split}
            &u \with 0, \qquad v \with n - 1, \qquad \fJ \with \fJ, \qquad (h_k)_{k \in \Z \cap [u, v]} \with \Bigl( \tfrac{(-1)^j \mathbbm{1}_{\N}(l + 1 - j)}{M^{n - l}} \Bigr)_{l \in \N_0 \cap [0, n - 1]}, \\
            %
            %
            %
            &L \with \fL_n^j, \qquad \activation \with \activation, \qquad \Psi \with \Gamma_n^{\theta, j , a},\qquad (\Phi_k)_{k \in \Z \cap [u, v]} \with ( \Phi_{n, l}^{\theta, j, a} )_{l \in \N_0 \cap [0, n - 1]}
        \end{split}
    \end{align}
    in the notation of \cref{lem:linear_combination_anns_different_length}) establish for all $\theta \in \Theta$, $j \in \{0 , 1\}$, $x \in \R^\dm$, $a \in A$ that
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Gamma_layer_structure}
            \cD ( \Gamma_n^{\theta, j, a} ) &=  \pr*{\dm, \SmallSum{l = 0}{n - 1} \dimANNlevel_1( \longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{\theta, j, a})  ), \SmallSum{l = 0}{n - 1} \dimANNlevel_2( \longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{\theta, j, a}) ), \dots, \SmallSum{l = 0}{n - 1} \dimANNlevel_{\fL_n^j - 1}(\longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{\theta, l, a}) ), 1} \\
            %
            %
            %
            &= \pr*{d, \SmallSum{l = 0}{n - 1} \dimANNlevel_1( \longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{0, j, \action}) ), \SmallSum{l = 0}{n - 1} \dimANNlevel_2( \longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{0, j, \action}) ), \dots, \SmallSum{l = 0}{n - 1} \dimANNlevel_{\fL_n^j - 1}( \longerANN{\fL_n^j, \fJ} (\Psi_{n, l}^{0, j, \action}) ), 1} \\
            %
            %
            %
            &= \cD (\Gamma_n^{0, j, \action}) \in \N^{\fL_n^j + 1}
        \end{split}
    \end{align}
    %
    %
    and 
    %
    %
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Gamma_realization_evaluated}
            \pr*{\cR_\activation (\Gamma_n^{\theta, j, a})} (x) &= \sum_{l = 0}^{n - 1} \tfrac{(-1)^j\mathbbm{1}_{\N}(l + 1 - j)}{M^{n - l}} \pr[\big]{\cR_\activation (\Psi_{n, l}^{\theta, j, a})} (x)\\
            %
            %
            %
            &= \sum_{l = 0}^{n - 1} \tfrac{(-1)^j\mathbbm{1}_{\N}(l + 1 - j)}{M^{n - l}} \sum_{i = 1}^{M^{n - l}}  \pr*{\cR_\activation (\bF) \circ \cR_\activation (\Xi_{\max\{l - j, 0\}}^{(\theta, (-1)^jl, i)}) \circ \cR_\activation (\bX_a^{(\theta, l, i)})} (x).
            %
            %
            %
        \end{split}
    \end{align}
    %
    %
    %
    Note that \eqref{eq:mlfp_as_ann_general_Gamma_layer_structure} implies for all $\theta \in \Theta$, $a \in A$ that
    \begin{equation}
        \max\{ \cL(\Gamma_n^{\theta, 0, a}), \cL(\Gamma_n^{\theta, 1, a}) \} = \max\{ \cL (\Gamma_n^{0, 0, \action}), \cL (\Gamma_n^{0, 1, \action}) \} = \max\{ \fL_n^0, \fL_n^1 \} = \mathbb{L}_n.
    \end{equation}
    %
    %
    %
    Combining this, \eqref{eq:mlfp_as_ann_general_Gamma}, \eqref{eq:mlfp_as_ann_general_Xi_realization_evaluated}, \eqref{eq:mlfp_as_ann_general_summands_realization_evaluated}, \eqref{eq:mlfp_as_ann_general_Gamma_layer_structure}, \eqref{eq:mlfp_as_ann_general_Gamma_realization_evaluated}, and \cref{lem:linear_combination_anns_different_length} (applied for every $\theta \in \Theta$, $a \in A$ with $u \with 1$, $v \with 2$, $\fJ \with \fJ$, $h_1 \with 1$, $h_2 \with 1$, $L \with \mathbb{L}_n$, $\activation \with \activation$, $\Phi_1 \with \Gamma_n^{\theta, 0, a}$, $\Phi_2 \with \Gamma_n^{\theta, 1, a}$, $\Psi \with \Lambda_n^{\theta, a}$ in the notation of \cref{lem:linear_combination_anns_different_length}) proves for all $\theta \in \Theta$, $a \in A$ that
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Lambda_layer_structure}
            \cD (\Lambda_n^{\theta, a}) &= \cD ( \Gamma_n^{\theta, 0, a} \,\bSum_{\, \fJ}\, \Gamma_n^{\theta, 1, a} ) \\
            %
            %
            %
            &= \pr[\bigg]{\dm, \dimANNlevel_1 ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{\theta, 0, a} )  ) + \dimANNlevel_1 ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{\theta, 1, a}) ), \dimANNlevel_2 ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{\theta, 0, a} )  ) + \dimANNlevel_2 ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{\theta, 1, a}) ), \dots\\
            %
            %
            %
            &\quad \dots, \dimANNlevel_{\mathbb{L}_n - 1} ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{\theta, 0, a} )  ) + \dimANNlevel_{\mathbb{L}_n - 1} ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{\theta, 1, a}) ), 1} \\
            %
            %
            %
            &= \pr[\bigg]{\dm, \dimANNlevel_1 ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{0, 0, \action} )  ) + \dimANNlevel_1 ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{0, 1, \action}) ), \dimANNlevel_2 ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{0, 0, \action} )  ) + \dimANNlevel_2 ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{0, 1, \action}) ), \dots\\
            %
            %
            %
            &\quad \dots, \dimANNlevel_{\mathbb{L}_n - 1} ( \longerANN{\mathbb{L}_n, \fJ} ( \Gamma_n^{0, 0, \action} )  ) + \dimANNlevel_{\mathbb{L}_n - 1} ( \longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{0, 1, \action}) ), 1} \\
            %
            %
            %
            &= \cD (\Lambda_n^{0, \action}) \in \N^{\mathbb{L}_n + 1}.
        \end{split}
    \end{align}
    %
    %
    %
    and 
    %
    %
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Lambda_realization_evaluated}
            \bigl( \cR_\activation (\Lambda_n^{\theta, a}) \bigr)(x) &= \bigl(\cR_\activation (\Gamma_n^{\theta, 0, a}) \bigr)(x) + \bigl(\cR_\activation (\Gamma_n^{\theta, 1, a})\bigr)(x) \\
            %
            %
            %
            &= \bigg[\SmallSum{l = 0}{n - 1} \tfrac{1}{M^{n - l}} \bigl(\cR_\activation (\Psi_{n, l}^{\theta, 0, a})\bigr)(x) \bigg] + \bigg[ \SmallSum{l = 0}{n - 1} \tfrac{-\mathbbm{1}_{\N}(l)}{M^{n- l}} \bigl( \cR_\activation (\Psi_{n, \max\{l - 1, 0\}}^{\theta, 1, a}) \bigr)(x) \bigg]\\
            %
            %
            %
            &= \sum_{l = 0}^{n - 1} \tfrac{1}{M^{n - l}} \sum_{i = 1}^{M^{n - l}}\Bigl( \cR_\activation(\bF) \circ \cR_\activation (\Xi_l^{(\theta, l, i)}) \circ \cR_\activation(\bX_a^{(\theta, l, i)}) \Bigr) (x) \\
            %
            %
            %
            &\quad- \sum_{l = 0}^{n - 1} \tfrac{\mathbbm{1}_{\N}(l)}{M^{n - l}} \sum_{i = 1}^{M^{n - l}} \bigl( \cR_\activation (\bF) \circ \cR_\activation (\Xi_{\max\{ l - 1, 0\}}^{(\theta, -l, i)}) \circ \cR_\activation( \bX_a^{(\theta, l, i)}) \bigr) (x)\\
            %
            %
            %
            &= \bigl(\varmlfp_n^{\theta}(x)\bigr)(a).
        \end{split}
    \end{align}
    %
    %
    %
    This,
    %
    \eqref{eq:mlfp_as_ann_general_Lambda_layer_structure},
    %
    \eqref{eq:mlfp_as_ann_general_Phi},
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{lem:parallelizations_of_anns_same_depth}
    %
    demonstrate for all $\theta \in \Theta$, $x \in \R^\dm$ that
    %
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Phi_layer_structure}
            \cD (\Phi_n^\theta) &= \cD (\paraANN{\abs{A}} (( \Lambda_n^{\theta, a}  )_{a \in A}) \bullet \fT_{\dm, \abs{A}} ) \\
            %
            %
            %
            &= \Bigl( \dm, \SmallSum{a \in A}{} \dimANNlevel_1 (\Lambda_n^{\theta, a}), \SmallSum{a \in A}{} \dimANNlevel_2 (\Lambda_n^{\theta, a}), \dots, \SmallSum{a \in A}{} \dimANNlevel_{\mathbb{L}_n - 1} (\Lambda_n^{\theta, a}), \SmallSum{a \in A}{} \dimANNlevel_{\mathbb{L}_n} (\Lambda_n^{\theta, a}) \Bigr) \\
            %
            %
            %
            &= \Bigl( \dm, \abs{A} \dimANNlevel_1(\Lambda_n^{0, \action}), \abs{A}  \dimANNlevel_1(\Lambda_n^{0, \action}), \dots, \abs{A} \dimANNlevel_{\mathbb{L}_n - 1}(\Lambda_n^{0, \action}), \abs{A} \Bigr) \in \N^{\mathbb{L}_n + 1}
        \end{split}
    \end{align}
    %
    %
    %
    and
    %
    %
    %
    \begin{align}
        \begin{split}
            \bigl( \cR_\activation (\Phi_n^\theta) \bigr)(x) &= \bigl( \cR_\activation (\paraANN{\abs{A}} (( \Lambda_n^{\theta, a}  )_{a \in A}) \bullet \fT_{\dm, \abs{A}} ) \bigr)(x) = \Bigl(\cR_\activation \bigl(\paraANN{\abs{A}} (( \Lambda_n^{\theta, a}  )_{a \in A})  \bigr)\Bigr) \begin{pmatrix}
                x \\ x \\ \vdots \\ x
            \end{pmatrix} \\
            %
            %
            %
            %
            &= \Bigl( \bigl( \cR_\activation (\Lambda_n^{\theta, a}) \bigr)(x) \Bigr)_{a \in A} = \Bigl( \bigl(\varmlfp_n^\theta (x)\bigr)(a) \Bigr)_{a \in A} = \varmlfp_n^\theta (x) \in \R^{|A|}.
        \end{split}
    \end{align}
    %
    %
    %
    This and induction prove \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated,item:mlfp_as_ann_general_layer_structure}.
    %
    %
    %
    %
    %
    Moreover, note that \eqref{eq:mlfp_as_ann_general_def_base_case_ANN},
    %
    \eqref{eq:mlfp_as_ann_general_Xi},
    %
    the fact that for all $j, k \in \N$ it holds that $\cL(\fT_{k, j}) = 1$,
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{item:certain_extensions_of_anns_item_extension_to_same_length} in \cref{lem:certain_extensions_of_anns},
    %
    \cref{def:parallelizations_of_anns_with_different_layer_structure},
    %
    \cref{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities},
    %
    and the induction hypothesis yield for all $\theta \in \Theta$, $l \in \N \cap [1, n - 1]$, that
    \begin{equation}
        \cL (\Xi_0^\theta) = \cL (\Xi_0^0) = 1
    \end{equation}
    and
    \begin{align}
        \begin{split}
            \cL (\Xi_l^\theta) &= \cL (\Xi_l^0) = \cL \bigl( \paraLANN{2}{\mathbb{J}} (\I_\dm, \Phi_l^0) \bullet \fT_{\dm, 2} \bigr) = \cL \bigl( \paraLANN{2}{\mathbb{J}} (\I_\dm, \Phi_l^0) \bigr)\\
            %
            %
            %
            &= \cL \bigl( \paraANN{2} ( \longerANN{ \max\{ \cL(\I_\dm), \cL(\Phi_l^0) \}, \I_\dm }(\I_\dm), \longerANN{ \max\{\cL(\I_\dm), \cL (\Phi_l^0)\}, \I_{\abs{A}} } (\Phi_l^0) ) \bigr) \\
            %
            %
            %
            &= \max\{ \cL (\I_\dm), \cL(\Phi_l^0) \} = \max \{2, \cL (\Phi_l^0)\} \\
            %
            %
            %
            &\le \max\{2, l (\cL(\bF) + \cL(\bX_\action^0) - 1) + 1\} = l \bigl( \cL (\bF) + \cL (\bX_\action^0) - 1 \bigr) + 1.
        \end{split}
    \end{align}
    %
    This ensures for all $\theta \in \Theta$, $l \in \N_0 \cap [0, n - 1]$ that 
    %
    \begin{equation}
        \cL (\Xi_l^\theta) = \cL (\Xi_l^0) \le l \bigl( \cL(\bF) + \cL(\bX_\action^0) - 1 \bigr) + 1.
    \end{equation}
    %
    This, \eqref{eq:mlfp_as_ann_general_depth_nth_iterate}, \eqref{eq:mlfp_as_ann_general_Phi_layer_structure}, and \cref{lem:compositions_of_anns} establish for all $\theta \in \Theta$ that 
    %
    \begin{align}
        \begin{split}
            \cL (\Phi_n^\theta) &= \mathbb{L}_n\\
            %
            %
            %
            &= \max_{j \in \{0,1\}} \fL_n^j \\ 
            %
            %
            %
            &= \max_{ \substack{l \in \{0, 1, \dots, n- 1\},\\ j \in \{0,1\}} } \cL ( \bF \bullet \Xi_{\max\{l - j, 0\}}^0 \bullet \bX_\action^0 ) \\
            %
            %
            %
            &= \max_{ \substack{l \in \{0, 1, \dots, n- 1\},\\ j \in \{0,1\}} } \big[ \cL (\bF) + \cL (\bX_\action^0) + \cL (\Xi_{ \max \{l - j, 0\}}^0) - 2 \big] \\
            %
            %
            %
            &\le \max_{ \substack{l \in \{0, 1, \dots, n- 1\},\\ j \in \{0,1\}} } \big[ \cL (\bF) + \cL (\bX_\action^0) - 2 + \max\{ l - j, 0 \} \bigl( \cL (\bF) + \cL (\bX_\action^0) - 1 \bigr) + 1 \big] \\
            %
            %
            %
            &= \cL (\bF) + \cL (\bX_\action^0) - 2 + (n - 1)\bigl( \cL (\bF) + \cL (\bX_\action^0) - 1 \bigr) + 1\\
            %
            %
            %
            &\le n \bigl( \cL(\bF) + \cL (\bX_\action^0) - 1 \bigr) + 1.
        \end{split}
    \end{align}
    This and induction prove \cref{item:mlfp_as_ann_general_depth}.
    %
    Next, observe that \eqref{eq:mlfp_as_ann_general_Psi_layer_structure},
    %
    \eqref{eq:mlfp_as_ann_general_Gamma_layer_structure},
    %
    \eqref{eq:mlfp_as_ann_general_Lambda_layer_structure},
    %
    and \cref{item:extensions_of_anns_involving_identities_item_extension_by_identity} in \cref{lem:extensions_of_anns_involving_identities}
    %
    demonstrate for all $\theta \in \Theta$, $a \in A$ that
    \begin{align}
        \begin{split} \label{eq:mlfp_as_ann_general_Lambda_width}
            \fnorm{ \cD (\Lambda_n^{\theta, a}) } &= \fnorm{ \cD (\Lambda_n^{0, \action})} \le \fnorm{ \cD (\longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{0, 0, \action}) ) } + \fnorm{ \cD (\longerANN{\mathbb{L}_n, \fJ} (\Gamma_n^{0, 1, \action}) ) } \\
            %
            %
            %
            % 
            %
            &\le \max\big\{ \fnorm{ \cD (\fJ) }, \fnorm{ \cD(\Gamma_n^{0,0,\action})}\big\} + \max\big\{\fnorm{ \cD (\fJ) }, \fnorm{ \cD(\Gamma_n^{0,1,\action}) }\big\} \\
            %
            %
            %
            % 
            %
            &\le \max\! \bigg\{\! \fd, \SmallSum{l = 0}{n - 1} \fnorm{ \cD (\longerANN{\fL_n^0, \fJ} ( \Psi_{n, l}^{0,0,\action} )) } \!\bigg\} + \max \! \bigg\{ \! \fd, \SmallSum{l = 0}{n - 1} \fnorm{ \cD( \longerANN{ \fL_n^1, \fJ } ( \Psi_{n, l}^{0, 1, \action} ) )  }\! \bigg\} \\
            %
            %
            %
            %  
            %
            &\le \max\! \bigg\{\! \fd, \SmallSum{l = 0}{n - 1} \max\!\big\{ \fd, \fnorm{ \cD (\Psi_{n, l}^{0,0,\action}) } \big\} \! \bigg\} + \max \! \bigg\{\! \fd, \SmallSum{l = 0}{n - 1} \max\!\big\{ \fd, \fnorm{ \cD (\Psi_{n, l}^{0,1,\action}) } \big\}  \!\bigg\} \\
            %
            %
            %
            %
            %
            &\le \SmallSum{l = 0}{n - 1} \max \big\{ \fd, \fnorm{ \cD (\Psi_{n, l}^{0,0,\action}) } \big\} + \SmallSum{l = 0}{n - 1} \max \big\{ \fd, \fnorm{ \cD (\Psi_{n, l}^{0,1,\action}) } \big\} \\
            %
            %
            %
            % 
            %
            &\le \SmallSum{l = 0}{n - 1} \max\big\{ \fd, M^{n - l} \max \big\{ \dm, \fnorm{ \cD( \bF \bullet \Xi_l^0 \bullet \bX_\action^0 ) } \big\} \big\} \\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} \max \big\{ \fd, M^{n - l} \max \big\{ \dm, \fnorm{ \cD( \bF \bullet \Xi_{\max\{l - 1, 0\}}^0 \bullet \bX_\action^0 ) } \big\} \big\} \\
            %
            %
            %
            % 
            %
            &\le \SmallSum{l = 0}{n - 1} M^{n - l} \max \big\{ \fd, \fnorm{ \cD (\bF \bullet \Xi_l^0 \bullet \bX_\action^0)  } \big\}\\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} M^{n - l} \max \big\{ \fd, \fnorm{ \cD (\bF \bullet \Xi_{ \max\{l - 1, 0\} }^0 \bullet \bX_\action^0)  } \big\}\\
            %
            %
            %
            %
            %
            &\le \SmallSum{l = 0}{n - 1} M^{n - l} \max \big\{ \fd, \fnorm{ \cD (\bF) }, \fnorm{\cD(\bX_\action^0)}, \fnorm{\cD( \Xi_l^0) } \big\}\\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} M^{n - l} \max \big\{ \fd, \fnorm{ \cD (\bF) }, \fnorm{\cD(\bX_\action^0)}, \fnorm{ \cD(\Xi_{ \max\{ l - 1, 0 \} }^0) } \big\}.
        \end{split}
    \end{align}
    %
    %
    %
    Furthermore, note that the fact that for all $j, k \in \N$ it holds that $\cD (\fT_{k, j}) = (k, jk)$,
    %
    \eqref{eq:mlfp_as_ann_general_def_base_case_ANN},
    %
    \eqref{eq:mlfp_as_ann_general_Xi},
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{lem:parallelizations_of_anns_same_depth},
    %
    and \cref{def:parallelizations_of_anns_with_different_layer_structure} ensure for all $l \in \N \cap [1, n - 1]$ that $\fnorm{\cD (\Xi_0^0)} = \dm + \abs{A} \le \fd\dm + \fd \abs{A} + \fnorm{\cD(\Phi_0^0)}$ and
    \begin{align}
        \begin{split}
            \fnorm{ \cD ( \Xi_l^0 )} &= \fnorm{ \cD ( \paraLANN{2}{ \mathbb{J}}(\I_\dm, \Phi_l^0 ) \bullet \fT_{\dm, 2} ) }\\
            %
            %
            %
            %
            &\le \max \cu*{2\dm, \fnorm{ \cD\pr{\paraLANN{2}{\mathbb{J}} (\I_\dm, \Phi_l^0)} }} \\
            %
            %
            %
            %
            &\le \max \cu*{2\dm, \fnorm[\big]{ \cD\pr{\longerANN{\max\{ \cL(\I_\dm), \cL(\Phi_l^0) \}, \I_\dm  } (\I_\dm)} } + \fnorm[\big]{ \cD\pr{\longerANN{ \max\{\cL(\I_\dm), \cL(\Phi_l^0)\}, \I_{\abs{A}} }(\Phi_l^0)} }}  \\
            %
            %
            %
            &\le \max \cu*{2\dm, \fd \dm +  \max \cu*{\fd \abs{A}, \fnorm{\cD (\Phi_l^0)}} } \\
            %
            %
            %
            %
            &= \fd \dm+ \max \cu*{ \fd \abs{A}, \fnorm{\cD(\Phi_l^0)}} \le \fd \dm + \fd \abs{A} + \fnorm{\cD(\Phi_l^0)}.
        \end{split}
    \end{align}
    This implies for all $l \in \N_0 \cap [0, n - 1]$ that $\fnorm{ \cD (\Xi_l^0)} \le \fd \dm + \fd |A| + \fnorm{ \cD(\Phi_l^0)}$.
    %
    Combining this,
    %
    \eqref{eq:mlfp_as_ann_general_Lambda_width},
    %
    the assumption that $M \ge 2$,
    %
    and the induction hypothesis yields that
    \begin{align}
        \begin{split}
            \fnorm{ \cD (\Lambda_n^{0, \action}) } &\le \SmallSum{l = 0}{n - 1} M^{n - l} \max\big\{ \fd, \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fnorm{ \cD (\Xi_l^0)} \big\}\\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} M^{n - l} \max\big\{ \fd, \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fnorm{ \cD (\Xi_{\max\{l - 1, 0\}}^0)} \big\} \\
            %
            %
            %
            &\le \SmallSum{l = 0}{n - 1} M^{n - l} \max\big\{ \fd, \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fd \dm + \fd |A| + \fnorm{\cD(\Phi_l^0)} \big\}\\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} M^{n - l} \max\big\{ \fd, \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fd \dm + \fd |A| + \fnorm{\cD(\Phi_{\max\{ l - 1, 0 \}}^0)} \big\} \\
            %
            %
            %
            %
            &\le \SmallSum{l = 0}{n - 1} M^{n - l} \big[ \max\big\{ \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fd \dm + \fd |A| \big\} + \fnorm{\cD(\Phi_l^0)} \big] \\
            %
            &\quad+ \SmallSum{l = 0}{n - 1} M^{n - l} \big[ \max\big\{ \fnorm{\cD (\bF)}, \fnorm{ \cD (\bX_\action^0)}, \fd \dm + \fd |A| \big\} + \fnorm{\cD(\Phi_{\max\{ l - 1, 0 \}}^0)} \big] \\
            %
            %
            %
            &= c \bigg[\SmallSum{l = 0}{n - 1} M^{n - l}\bigg] + \bigg[ \SmallSum{l = 0}{n - 1} M^{n - l} \big[ \fnorm{ \cD (\Phi_l^0)} + \fnorm{ \cD (\Phi_{\max\{ l - 1, 0 \}}^0)} \big]  \bigg]\\
            %
            %
            %
            %
            &\le c \Bigg[ \bigg[ \SmallSum{l = 0}{n - 1} M^{n - l} \bigg] + \bigg[ \SmallSum{ l = 0 }{n - 1} M^{n - l} (4|A|M)^l \bigg] + \bigg[\SmallSum{l = 0}{n - 1} M^{n - l} (4|A|M)^{\max\{l - 1, 0\}}\bigg] \Bigg]\\
            %
            %
            %
            &= c \Bigg[ M \tfrac{M^n - 1}{M - 1} + M^n \bigg[ \SmallSum{l = 0}{n - 1} (4|A|)^l \bigg] + M^n + M^{n - 1} \bigg[ \SmallSum{l = 1}{n - 1} (4|A|)^{l - 1} \bigg] \Bigg] \\
            %
            %
            %
            &\le c \bigg[ 3M^n + M^n \tfrac{(4|A|)^n - 1}{4|A| - 1} + M^{n - 1} \tfrac{(4|A|)^{n - 1} - 1}{4|A| - 1}\bigg]\\
            %
            %
            %
            &= c M^n \bigg[ 3 + \tfrac{(4|A|)^n - 1}{4|A| - 1} + \tfrac{1}{M} \tfrac{(4|A|)^{n - 1} - 1}{4|A| - 1} \bigg] \\
            %
            %
            %
            &\le c M^n \bigg[ \tfrac{(4|A|)^n}{4|A| - 1} + \tfrac{(4|A|)^{n - 1}}{4|A| - 1} + \tfrac{3(4|A| - 1) - 2}{4|A| - 1}\bigg]\\
            %
            %
            %
            &= c(4|A|M)^n \bigg[ \tfrac{1}{4|A| - 1} + \tfrac{1}{4|A|(4|A| - 1)} + \tfrac{3(4|A| - 1) - 2}{ (4|A|)^n (4|A| - 1)}\bigg]\\
            %
            %
            %
            &\le c(4|A|M)^n \bigg[ \tfrac{4|A| + 1}{4|A|(4|A| - 1)} + \tfrac{3(4|A| - 1) - 2}{4|A|(4|A| - 1)} \bigg] \\
            %
            %
            %
            &= c(4|A|M)^n \bigg[ \tfrac{4(4|A| - 1)}{4|A|(4|A| - 1)} \bigg] = c(4|A|M)^n \tfrac{1}{|A|}.
        \end{split}
    \end{align} 
    Combining this and \eqref{eq:mlfp_as_ann_general_Phi} demonstrates that
    \begin{equation}
        \fnorm{ \cD (\Phi_n^0)} \le |A| \fnorm{\cD (\Lambda_n^{0, \action})} \le c (4|A|M)^n.
    \end{equation}
    This and induction prove \cref{item:mlfp_as_ann_general_width}. This, \cref{item:mlfp_as_ann_general_depth}, and the fact that for all $L \in \N$, $\zeta \in \bN$, $l_0, l_1, \dots, l_L \in \N$ with $\cD (\zeta) = (l_0, l_1, \dots, l_L) \in \N^{L + 1}$ it holds that $\paramANN(\zeta) = \sum_{k = 1}^{L} l_k(l_{k - 1} + 1)$ establish that
    \begin{align}
        \begin{split}
            \paramANN(\Phi_n^0) &\le \SmallSum{k = 1}{\cL(\Phi_n^0)} \fnorm{\cD (\Phi_n^0)} \bigl( \fnorm{ \cD (\Phi_n^0)} + 1 \bigr) \le 2\cL(\Phi_n^0) \fnorm{ \cD (\Phi_n^0) }^2\\
            %
            %
            %
            &\le 2 \big[ n \bigl( \cL(\bF) + \cL(\bX_\action^0) - 1 \bigr) + 1 \big] c^2 (4|A|M)^{2n}.
        \end{split}
    \end{align}  
    This and induction prove \cref{item:mlfp_as_ann_general_size}. Hence, \cref{item:mlfp_as_ann_general_realization,item:mlfp_as_ann_general_realization_evaluated,item:mlfp_as_ann_general_layer_structure,item:mlfp_as_ann_general_depth,item:mlfp_as_ann_general_width,item:mlfp_as_ann_general_size} hold true. The proof of \cref{lem:mlfp_as_ann_general} is thus complete.
\end{mproof}



