\subsection{ANN approximations for functional fixed-point equations with general activation functions}
\label{subsec:general_fp_equation}



\cfclear
\begin{theo} \label{thm:main_simple}
    Let $\Theta = \cup_{n \in \N} \Z^n$, let $A$ be a nonempty finite set,
    %
    let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space,
    %
    let $\genConst \in [1, \infty)$, 
    %
    for every $\dm \in \N$ let $ \lambda_\dm, \eta_\dm, K_\dm, L_\dm \in \pr{0,\infty}$,
    %
    for every $\dm \in \N$, $\eps \in \err$ let $\lipFANN_{\dm, \eps} \in \pr{0,\infty}$,
    %
    assume $\sup_{\dm \in \N} \lambda_\dm L_\dm < 1$, $\sup_{\dm \in \N} \eta_\dm L_\dm < 1$, $\sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps} < 1$,
    %
    for every $\dm \in \N$ let $\w_\dm \colon \R^\dm \to \pr{0, \infty}$ be measurable,
    %
    for every $\dm \in \N$, $x \in \pr{x_1, \dots, x_\dm} \in \R^\dm$ let $\fnorm{x} \in \R$ satisfy $\fnorm{x} = \max_{i \in \cu{ 1,\dots, \dm}} \abs{x_i}$,
    %
    for every $\dm \in \N$ let $f_\dm \colon \R^\dm \times \R^{\abs{A}} \to \R$ be measurable,
    %
    for every $\dm \in \N$ let $\tker_\dm^{\pr{a}} \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $a \in A$, be stochastic kernels,
    %
    let $\action \in A$, 
    %
    let $\ol{\omega} \in \Omega$,
    %
    %
    %
    %
    let $\activation \in C(\R, \R)$,
    %
    let $\fJ \in \bN$ satisfy $\cR_\activation(\fJ) = \idfunc_\R$ and $\cL(\fJ) = 2$,
    %
    let $(\bF_{\dm, \eps})_{(\dm, \eps) \in \N \times \err} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \N$ that $\cR_\activation(\bF_{\dm, \eps}) \in C(\R^{\dm + \abs{A}}, \R)$,
    %
    let $\bX^{\theta, a}_{\dm, \eps} \colon \Omega \to \bN$, $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $a \in A$, satisfy for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $a \in A$, $\omega \in \Omega$ that $\cD (\bX_{\dm, \eps}^{\theta, a}(\omega)) = \cD (\bX_{\dm, \eps}^{0, \action}(\ol{\omega}))$ and $\cR_\activation( \bX_{\dm, \eps}^{0, \action}(\omega) ) \in C(\R^\dm, \R^\dm)$,
    %
    for every $\dm \in \N$, $\eps \in \err$ let $\tkerANN_{\dm, \eps}^{\pr{a}} \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $a \in A$, satisfy for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$, $Y \in \Borel(\R^\dm)$ that $ \tkerANN_{\dm, \eps}^{\pr{a}}(x, Y) = \mathbb{P} \br[\big]{ \pr[\big]{ \cR_\activation (\bX_{\dm, \eps}^{\theta, a}  ) }(x) \in Y }$,
    %
    for every $\dm \in \N$, $\eps \in \err$ let $(\mathcal{F}^\theta_{\dm, \eps})_{\theta \in \Theta}$ be independent sub-$\sigma$-algebras of $\mathcal{F}$,
    %
    assume for all $\dm \in \N$, $\eps \in \err$ that $\pr{\cR_{\activation} \pr{\bX^{\theta, a}_{\dm, \eps}}}_{a \in A} \colon \R^\dm \times \Omega \to \pr{\R^\dm}^{\abs{A}}$, $\theta \in \Theta$, are i.i.d.\ random fields,
    %
    assume for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$ that $\pr{\cR_{\activation} \pr{\bX^{\theta, a}_{\dm, \eps}}}_{a \in A}$ is $(\Borel(\R^\dm) \otimes \mathcal{F}^\theta_{\dm, \eps}) / \Borel((\R^\dm)^{\abs{A}})$-measurable,
    %
    %
    assume for all $\dm \in \N$, $\eps \in \err$ that $\max \{ \lambda_\dm, K_\dm \} \le \genConst \dm^\genConst$ and
    \begin{align} \label{eq:main_simple_poly_growth_assumption_ANN}
        \max\cu[\big]{ \cL (\bF_{\dm, \eps}), \cL(\bX_{\dm, \eps}^{0, \action}(\ol{\omega})), \fnorm{\cD (\bF_{\dm, \eps}) }, \fnorm{ \cD (\bX_{\dm, \eps}^{0, \action}(\ol{\omega})) } } \le \genConst \dm^{\genConst}\eps^{-\genConst},
    \end{align}
    %
    %
    %
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $x,y \in \R^\dm$, $r, s \in \R^{\abs{A}}$, $a \in A$ that 
    \begin{align}
        \begin{split} \label{eq:main_simple_approximation_assumption}
            &\abs[\big]{ \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,r) -  f_\dm (x,r) } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)}, \qquad \wdist_\dm\pr[\big]{ \tkerANN_{\dm, \eps}^{\pr{a}}(x, \cdot), \tker_\dm^{\pr{a}}(x, \cdot) } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)},
        \end{split} \\
        %
        \begin{split} \label{eq:main_simple_lipschitz}
            & \abs*{ f_\dm (x,r) - f_\dm(x,s) } \le L_\dm \max_{b \in A} \abs*{ r(b) - s(b) }, \qquad \abs*{f_\dm(x, r) - f_\dm(y,r)} \le K_\dm \norm{ x - y}, \\
            %
            %
            &\abs*{ \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,r) - \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,s) } \le \lipFANN_{\dm, \eps} \max_{b \in A} \abs*{ r(b) - s(b) },\quad \text{and} \\
            %
            %
            &\wdist_\dm \pr[\big]{ \tker_{\dm}^{\pr{a}}(x, \cdot), \tker_{\dm}^{\pr{a}}(y, \cdot) } \le \eta_\dm \norm{x - y},
        \end{split}
    \end{align}
    %
    %
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $a \in A$ that
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_first_moment_kernels}
            \sup_{x \in \R^\dm} \abs{\w_\dm\pr{x}}^{-1} \int_{\R^\dm} \norm{y} \tker_\dm^{\pr{a}}\pr{x, \dxx y} < \infty \qquad \text{and} \qquad \sup_{x \in \R^\dm} \abs{\w_\dm \pr{x}}^{-1 } \int_{\R^\dm} \norm{y} \tkerANN_{\dm, \eps}^{\pr{a}} \pr{x, \dxx y} < \infty,
        \end{split}
    \end{equation} 
    %
    %
    %
    %
    assume for all $\dm \in \N$, $x \in \R^\dm$, $\eps \in \err$, $a \in A$ that 
    \begin{align}
        \begin{split} \label{eq:main_simple_regularity_perturbed_inputs}
            &\pr*{ \int_{\R^\dm} \abs{\w_\dm(y)}^2 \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y) }^{\!\!\nicefrac{1}{2}} \le \lambda_\dm \abs{ \w_\dm(x) }, \\
            %
            &\pr*{ \int_{\R^\dm} \abs*{ \pr[\big]{ \cR_\activation(\bF_{\dm, \eps}) } (y, 0) }^2 \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y)    }^{\!\!\nicefrac{1}{2}} \le \genConst \dm^\genConst \abs{\w_\dm(x)},
        \end{split} \\
        %
        \begin{split} \label{eq:main_simple_regularity_target_inputs}
            &\int_{\R^\dm} \abs{ \w_\dm (y) } \tker_\dm^{\pr{a}}(x, \dxx y) \le \lambda_\dm \abs{\w_\dm (x)}, \quad \text{and} \quad \sup_{\substack{z \in \R^\dm,\\ b \in A}} \abs{\w_\dm(z)}^{-1} \!\! \int_{\R^\dm} \abs{ f_\dm (y, 0) } \tker_\dm^{\pr{b}}(z, \dxx y) < \infty.
        \end{split}
    \end{align}
    %
    Then there exists $c \in \R$ such that for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr[]{ \int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu (\dxx x) }^{\nicefrac{1}{2}} \le \genConst \dm^\genConst$ it holds that
    \begin{enumerate}[label=(\roman *)]
        \item \label{item:main_simple_ex_uniq_sol} there exists a unique measurable $u \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that 
        %
        $\sup_{(z, b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(u(z))(b)} < \infty$,
        %
        $\int_{\R^\dm} \abs{f_\dm(y, u(y))} \tker_\dm^{\pr{a}}(x, \dxx y) < \infty$, and
        %
        \begin{equation}
            \pr*{ u (x) } \pr{a} = \int_{\R^\dm} f_\dm \pr{ y, u(y) } \tker^{\pr{a}}_\dm(x, \dxx y) 
        \end{equation}
        and
        \item \label{item:main_simple_ex_ann} there exists $\Psi \in \bN$ which satisfies that $\cH \pr{ \Psi } > 0$, $\paramANN(\Psi) \le c \dm^c \eps^{-c}$, $\cR_\activation(\Psi) \in C(\R^\dm, \R^{\abs{A}})$, and
        %
        \begin{equation} \label{eq:main_simple_existence_approximating_ann}
            \pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ (u(x))(a) - \pr*{\pr[\big]{\cR_\activation(\Psi)}(x)}(a) }^2 \mu(\dxx x) }^{\!\!\nicefrac{1}{2}} \le \eps
        \end{equation}
    \end{enumerate}
    \cfout.
\end{theo}

\begin{mproof}{\cref{thm:main_simple}}
    %
    %
    Throughout this proof let $\fd \in \N$ satisfy $\cD (\fJ) = (1, \fd, 1)$,
    %
    let $\fK \in \R$ satisfy $\fK = \max\cu{\fc, \fd\pr{1 + \abs{A}}}$,
    %
    let $M \in \N \cap [2, \infty)$ satisfy
    \begin{equation} \label{eq:main_simple_def_M}
        M > \pr*{\frac{  1 + \pr{\sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps}}(2\abs{A} - 1) }{ 1 - \pr{ \sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps} } }}^2,
    \end{equation}
    %
    let $\alpha_{\dm, \eps}, \gamma_{\dm, \eps} \in [0, \infty)$, $\dm \in \N$, $\eps \in \err$, satisfy for all $\dm \in \N$, $\eps \in \err$ that
    \begin{align}
        \begin{split} \label{eq:main_simple_def_alpha_gamma_dm_eps}
            \alpha_{\dm, \eps} &= \tfrac{\lambda_\dm \lipFANN_{\dm, \eps} (1 + |A|M^{\nicefrac{-1}{2}}) + M^{\nicefrac{-1}{2}} + \sqrt{ \big( \lambda_\dm \lipFANN_{\dm, \eps} (1 + |A|M^{\nicefrac{-1}{2}}) + M^{\nicefrac{-1}{2}} \big)^2 + 4M^{\nicefrac{-1}{2}} \lambda_\dm \lipFANN_{\dm, \eps} (|A| - 1)}}{2} \qquad \text{and} \\
            %
            \gamma_{\dm, \eps} &= \tfrac{3}{2} \max\Big\{ \tfrac{\genConst}{1 - \lambda_\dm \lipFANN_{\dm, \eps}}, \tfrac{ \abs{A} \genConst}{\abs{A} \lambda_\dm \lipFANN_{\dm, \eps} + 1} \Big\},
        \end{split}
    \end{align}
    %
    let $\mlfppower, \mlfpconst \in \br{0, \infty}$ satisfy $\mlfppower = \sup_{(\dm, \eps) \in \N \times \err} \alpha_{\dm, \eps}$ and $\mlfpconst = \sup_{(\dm, \eps) \in \N \times \err} \gamma_{\dm, \eps}$,
    %
    let $\scrn \colon \err \to \N \cup \{+\infty\}$ satisfy for all $\eps \in \err$ that $\scrn(\eps) = \min( \{ n \in \N : \mlfpconst \mlfppower^n \le \eps\} \cup \{+ \infty\} )$.\ %
    %
    First, observe that the assumption that $\sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps} < 1$
    %
    and \eqref{eq:main_simple_def_M} 
    %
    ensure that $\mlfppower \in [M^{-\nicefrac{1}{2}}, 1)$.
    %
    Next, note that the assumption that $\sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps} < 1$
    %
    and the assumption that $\genConst \in [1, \infty)$ imply that $\mlfpconst \in [\nicefrac{3}{2}, \infty)$.
    %
    This and the fact that $\mlfppower \in \pr{0,1}$ show for all $\eps \in \err$ that $\scrn(\eps) \in \N$.
    %
    Furthermore, let $\mlfp_{\dm, \eps, n}^\theta \colon \R^\dm \times \Omega \to \R^{\abs{A}}$, $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $n \in \N_0$ satisfy for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $n \in \N_0$, $x \in \R^\dm$, $a \in A$ that 
    \begin{align}
        \begin{split}
            &\pr*{\mlfp_{\dm, \eps, n}^\theta(x)}(a)\\
            %
            &= \SmallSum{l = 0}{ n -1} \tfrac{1}{M^{n- l}} \br[\bigg]{ \SmallSum{i = 1}{M^{n - l}} \br[\Big]{ \pr[\Big]{ \cR_\activation(\bF_{\dm, \eps}) } \pr[\Big]{  \pr[\big]{ \cR_\activation ( \bX_{\dm, \eps}^{(\theta, l, i), a} ) }(x)  , \mlfp_{\dm, \eps, l}^{(\theta, l, i)} \pr[\big]{ \pr[\big]{ \cR_\activation ( \bX_{\dm, \eps}^{(\theta, l, i), a} ) }(x) } }  \\
            %
            &\quad- \mathbbm{1}_\N(l) \pr[\Big]{ \cR_\activation(\bF_{\dm, \eps}) } \pr[\Big]{  \pr[\big]{ \cR_\activation ( \bX_{\dm, \eps}^{(\theta, l, i), a} ) }(x)  , \mlfp_{\dm, \eps, \max\{l - 1, 0\}}^{(\theta, -l, i)} \pr[\big]{ \pr[\big]{ \cR_\activation ( \bX_{\dm, \eps}^{(\theta, l, i), a} ) }(x) } } }  }. 
        \end{split}
    \end{align}
    %
    %
