    %
    the assumption that for all $\dm \in \N$ it holds that $\lambda_\dm L_\dm < 1$,
    %
    the assumption that for all $\dm \in \N$ it holds that $\sup_{(x,a) \in \R^\dm \times A} \abs{\w_\dm(x)}^{-1} \!\! \int_{\R^\dm} \abs{ f_\dm (y, 0) } \tker_\dm^{\pr{a}}(x, \dxx y) < \infty$,
    %
    the assumption that for all $\dm \in \N$, $x \in \R^\dm$, $a \in A$ it holds that $\int_{\R^\dm} \abs{ \w_\dm (y) } \tker_\dm^{\pr{a}}(x, \dxx y) \le \lambda_\dm \abs{\w_\dm (x)}$,
    %
    and \cite[Lemma~2.2]{beck2023nonlinctrl} (applied for every $\dm \in \N$ with $c\with \lambda_\dm$, $L \with L_\dm$, $(\X, \mathcal{X}) \with (\R^\dm, \Borel(\R^\dm))$, $A \with A$, $(\tker_a)_{a \in A} \with (\tker_\dm^{\pr{a}})_{a \in A}$, $f \with f_\dm$, $\w \with \br{\R^\dm \ni x \mapsto \br{A \ni a \mapsto \w_\dm(x) \in \pr{0,\infty}} \in \pr{0,\infty}^{\abs{A}}}$ in the notation of \cite[Lemma~2.2]{beck2023nonlinctrl})
    %
    yield that for every $\dm \in \N$ there exists a unique measurable $u_\dm \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that $\sup_{(z,b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(u_\dm(z))(b)} < \infty$, $\int_{\R^\dm} \abs{ f_\dm \pr{y, u_\dm(y)} } \tker_\dm^{\pr{a}}(x, \dxx y) < \infty$, and 
    \begin{equation} \label{eq:main_simple_existence_exact_solution}
