    \end{equation}
    %
    This proves \cref{item:main_simple_ex_uniq_sol}.
    %
    Next, observe that
    %
    the assumptions that for all $\dm \in \N$, $\eps \in \err$ it holds that $\lambda_\dm \lipFANN_{\dm, \eps} < 1$,
    %
    the assumptions that for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$ it holds that $\pr[\big]{ \int_{\R^\dm} \abs{\w_\dm(y)}^2 \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y) }^{\nicefrac{1}{2}} \le \lambda_\dm \abs{ \w_\dm(x) }$ and
    %
    $\pr[\big]{ \int_{\R^\dm} \abs*{ \pr[\big]{ \cR_\activation(\bF_{\dm, \eps}) } (y, 0) }^2 \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y)    }^{\nicefrac{1}{2}} \le \genConst \dm^\genConst \abs{\w_\dm(x)}$,
    %
