    %
    imply that for every $\dm \in \N$, $\eps \in \err$ there exists a unique measurable $v_{\dm, \eps} \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that $\sup_{(z,b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(v_{\dm, \eps}(z))(b)} < \infty$, $\int_{\R^\dm} \abs*{ \pr{\cR_\activation (\bF_{\dm, \eps})} \pr{y, v_{\dm, \eps}(y)} } \tkerANN^{\pr{a}}_{\dm, \eps}(x, \dxx y) < \infty$, and
    %
    \begin{equation} \label{eq:main_simple_existence_perturbed_solution_1}
        (v_{\dm, \eps}(x))(a) = \int_{\R^\dm} \pr{\cR_\activation (\bF_{\dm, \eps})} \pr{y, v_{\dm, \eps}(y)} \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y).
    \end{equation}
    %
    This and 
    %
    the assumption that for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$, $Y \in \Borel(\R^\dm)$ it holds that $ \tkerANN_{\dm, \eps}^{\pr{a}}(x, Y) = \mathbb{P} \br[\big]{ \pr[\big]{ \cR_\activation (\bX_{\dm, \eps}^{\theta, a}  ) }(x) \in Y }$
    %
    ensure for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$ that 
    \begin{align}
        \begin{split} \label{eq:main_simple_existence_perturbed_solution_2}
            (v_{\dm, \eps}(x))(a) &= \int_{\R^\dm} \pr{\cR_\activation (\bF_{\dm, \eps})} \pr{y, v_{\dm, \eps}(y)} \tkerANN_{\dm, \eps}^{\pr{a}}(x, \dxx y) \\
            %
            %
            %
            &= \E \br*{ \pr[\big]{\cR_\activation(\bF_{\dm, \eps})} \pr*{ \pr*{\cR_\activation(\bX^{0,a}_{\dm, \eps})}(x) , v_{\dm, \eps}\pr*{\pr*{\cR_\activation(\bX^{0,a}_{\dm, \eps})}(x)} } }.
        \end{split}
    \end{align}
    %
    Moreover, observe that the triangle inequality demonstrates for all $\dm, n \in \N$, $\eps \in \err$, $x \in \R^\dm$ that
    %
    \begin{align}
        \begin{split}
            &\pr[\Big]{\E \br[\Big]{ \max_{a \in A} \abs*{ (u_\dm(x))(a) - \pr*{ \mlfp_{\dm, \eps, n}^{0}(x) }(a) }^2  }}^{\!\!\nicefrac{1}{2}} \\
            %
