    $\pr{\varmlfp_n^\theta}_{\pr{\theta, n} \in \Theta \times \N_0} \with \pr{\mlfp_{\dm, \eps, n}^{\theta} \pr{\cdot, \omega}}_{\pr{\theta, n} \in \Theta \times \N_0}$
    %
    in the notation of \cref{lem:mlfp_as_ann_general}) establishes that for all $\dm \in \N$, $\eps \in \err$, $\omega \in \Omega$ there exists $\Phi_{\dm, \eps, n}^\theta\pr{\omega} \in \N$, $\theta \in \Theta$, $n \in \N_0$ such that 
    %
    \begin{enumerate}[label = (\Roman *)] 
        \item \label{item:main_simple_mlfp_as_ann_realization} it holds for all $\theta \in \Theta$, $n \in \N_0$ that $ \cR_\activation \pr{ \Phi_{\dm, \eps, n}^\theta \pr{\omega} } \in C\pr{\R^\dm, \R^{\abs{A}}}$,
        %
        \item \label{item:main_simple_mlfp_as_ann_realization_evaluated} it holds for all $\theta \in \Theta$, $n \in \N_0$, $x \in \R^\dm$ that $\pr{ \cR_{\activation}\pr{\Phi_{\dm, \eps, n}^\theta \pr{\omega}} } \pr{x} = \mlfp_{\dm, \eps, n}^\theta \pr{x, \omega}$,
        %
        \item \label{item:main_simple_mlfp_as_ann_architecture} it holds for all $\theta \in \Theta$, $n \in \N_0$ that $\cD \pr{\Phi_{\dm, \eps, n}^\theta \pr{\omega}} = \cD \pr{\Phi_{\dm, \eps, n}^0 \pr{\omega}}$,
        %
        \item \label{item:main_simple_mlfp_as_ann_depth} it holds for all $\theta \in \Theta$, $n \in \N_0$ that $\cL\pr{ \Phi_{\dm, \eps, n}^\theta \pr{\omega} } \le n \pr*{\cL \pr{\bF_{\dm, \eps}} + \cL \pr{\bX_{\dm, \eps}^{0, \action}\pr{\omega}} - 1} + 1$,
        %
        \item \label{item:main_simple_mlfp_as_ann_width} it holds for all $\theta \in \Theta$, $n \in \N_0$ that 
        \begin{equation}\label{eq:main_simple_mlfp_as_ann_width}
            \fnorm[\big]{\cD \pr[\big]{ \Phi_{\dm, \eps, n}^\theta \pr{\omega} } } \le 2 \max \cu[\big]{ \fnorm{\cD \pr{ \bF_{\dm, \eps} }}, \fnorm{ \cD\pr{ \bX_{\dm, \eps}^{0, \action} \pr{\omega} } }, \fd d + \fd \abs{A} } \pr{4 \abs{A} M}^{2n},
        \end{equation}
        %
        and
        %
        \item \label{item:main_simple_mlfp_as_ann_size} it holds for all $\theta \in \Theta$, $n \in \N_0$ that 
        \begin{equation}
            \begin{split}
                \paramANN \pr{ \Phi_{\dm, \eps, n}^{\theta} \pr{\omega}} &\le 2 \pr[\big]{ n \pr{ \cL \pr{\bF_{\dm, \eps}} + \cL \pr{ \bX_{\dm, \eps}^{0, \action} \pr{\omega} } - 1} + 1}\\
                %
                &\quad\cdot \pr[\big]{2 \max \cu[\big]{ \fnorm{\cD \pr{ \bF_{\dm, \eps} }}, \fnorm{ \cD\pr{ \bX_{\dm, \eps}^{0, \action} \pr{\omega} } }, \fd d + \fd \abs{A} }}^2 \pr{4\abs{A} M}^{2 n}.                
            \end{split}
        \end{equation}
    \end{enumerate}
    %
    For every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ let $\Psi_{\dm, \eps, \mu} \in \bN$ satisfy that
    \begin{equation} \label{eq:main_simple_definition_Psi}
        \Psi_{\dm, \eps, \mu} = \Phi^0_{\dm, \delta_{\dm, \eps}, \scrn\pr{\delta_{\dm, \eps}}} \pr{\omega_{\dm, \eps, \mu}}.
    \end{equation}
    %
    Combining this,
    %
    \cref{eq:main_simple_error_of_realization_of_mlfp},
    %
    and \cref{item:main_simple_mlfp_as_ann_realization,item:main_simple_mlfp_as_ann_realization_evaluated}
    %
    demonstrates for every $\dm \in \N$, $\eps \in \err$, $y \in \R^\dm$, $b \in A$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$
    %
    that $\cR_\activation \pr{ \Psi_{\dm, \eps, \mu}} \in C\pr{\R^\dm, \R^{\abs{A}}}$, $\pr*{\pr[\big]{\cR_\activation \pr{ \Psi_{\dm, \eps, \mu} } }\pr{y}}\pr{b} = \pr[\big]{\mlfp_{\dm, \delta_{\dm, \eps}, \scrn\pr{\delta_{\dm, \eps}}}^0\pr{y, \omega_{\dm, \eps, \mu}}}\pr{b}$, and
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_error_Psi}
            &\pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ \pr{u_\dm\pr{x}}\pr{a} - \pr*{\pr[\big]{\cR_\activation \pr{ \Psi_{\dm, \eps, \mu} } }\pr{x}}\pr{a} }^2 \mu\pr{\dxx x} }^{\!\!\nicefrac{1}{2}} \\
            %
            &\le \pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ \pr{u_\dm \pr{x}}\pr{a} - \pr*{\mlfp_{\dm, \delta_{\dm, \eps}, \scrn\pr{\delta_{\dm, \eps}}} \pr{x, \omega_{\dm, \eps, \mu}} }\pr{a} }^2 \mu\pr{\dxx x} }^{\!\!\nicefrac{1}{2}} \le \eps. 
        \end{split}
    \end{equation}
    %
    This establishes \cref{eq:main_simple_existence_approximating_ann}.
    %
    Furthermore, note that \cref{eq:main_simple_definition_Psi},
    %
    \cref{item:main_simple_mlfp_as_ann_size},
    %
    the fact that for all $\eps \in \err$ it holds that $\scrn \pr{\eps} \in \N$,
    %
    and the assumption that for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $a \in A$, $\omega \in \Omega$ it holds that $\cD\pr{ \bX_{\dm, \eps}^{\theta, a}\pr{\omega} } = \cD\pr{\bX_{\dm, \eps}^{0, \action} \pr{\ol{\omega}}}$
    %
    yield that for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ it holds that
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_effort_base_estimate}
            \paramANN \pr{\Psi_{\dm, \eps, \mu}} &\le 2 \pr[\big]{ \scrn \pr{\delta_{\dm, \eps}} \pr{ \cL \pr{\bF_{\dm, \delta_{\dm, \eps}}} + \cL \pr{ \bX_{\dm, \delta_{\dm, \eps}}^{0, \action} \pr{\ol{\omega}} } - 1} + 1}\\
            %
            &\quad\cdot \pr[\big]{2 \max \cu[\big]{ \fnorm{\cD \pr{ \bF_{\dm, \delta_{\dm, \eps}} }}, \fnorm{ \cD\pr{ \bX_{\dm, \delta_{\dm, \eps}}^{0, \action} \pr{\ol{\omega}} } }, \fd d + \fd \abs{A} }}^2 \pr{4\abs{A} M}^{2 \scrn \pr{\delta_{\dm, \eps}}}\\
            %
            &\le 8 \pr[\big]{ \max \cu[\big]{ \fnorm{\cD \pr{ \bF_{\dm, \delta_{\dm, \eps}} }}, \fnorm{ \cD\pr{ \bX_{\dm, \delta_{\dm, \eps}}^{0, \action} \pr{\ol{\omega}} } }, \fd d + \fd \abs{A} } }^2  \\
            %
            &\quad \cdot \pr[\big]{\cL \pr{\bF_{\dm, \delta_{\dm, \eps}}} + \cL \pr{ \bX_{\dm, \delta_{\dm, \eps}}^{0, \action} \pr{\ol{\omega}} }} \scrn \pr{\delta_{\dm, \eps}} \pr{4\abs{A} M}^{2 \scrn \pr{\delta_{\dm, \eps}}}.
        \end{split}
    \end{equation}
    Next, observe that for all $\dm \in \N$ it holds that $\fd \dm + \fd \abs{A} \le \pr{\fd + \fd\abs{A}} \dm \le \fK \dm$.
    %
    This, 
    %
    the assumption that $\max\cu{\genConst, \fd} \ge 1$,
    %
    the assumption that $A$ is nonempty,
    %
    and the assumption that for all $\dm \in \N$, $\eps \in \err$ it holds that $\max\cu[\big]{ \cL (\bF_{\dm, \eps}), \cL(\bX_{\dm, \eps}^{0, \action}(\ol{\omega})), \fnorm{\cD (\bF_{\dm, \eps}) }, \fnorm{ \cD (\bX_{\dm, \eps}^{0, \action}(\ol{\omega})) } } \le \genConst \dm^{\genConst}\eps^{-\genConst}$
    %
    assure that for all $\dm \in \N$, $\eps \in \err$ it holds that
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_width_depth_polynomial_growth}
            &\pr[\big]{\cL \pr{\bF_{\dm, \eps}}} + \cL \pr{ \bX_{\dm, \eps}^{0, \action} \pr{\ol{\omega}} } \pr[\big]{ \max \cu[\big]{ \fnorm{\cD \pr{ \bF_{\dm, \eps} }}, \fnorm{ \cD\pr{ \bX_{\dm, \eps}^{0, \action} \pr{\ol{\omega}} } }, \fd d + \fd \abs{A} } }^2 \\
            %
            &\le 2\genConst \dm^\genConst \eps^{-\genConst} \pr{ \fK \dm^\genConst \eps^{-\genConst} }^2 \le 2\fK^3 \dm^{3\genConst} \eps^{-3\genConst}.
        \end{split}
    \end{equation}
    %
    %
    Moreover, note that \cite[Lemma~3.15]{beck2024overcoming} (applied with $m \with 1$,
    %
    $\alpha \with \mlfppower$,
    %
    $\beta \with (4\abs{A}M)^2$,
    %
    $\kappa_1 \with \mlfpconst$,
    %
    $\kappa_2 \with 1$,
    %
    $ (c_n)_{n \in \N} \with \pr[\big]{((4\abs{A}M)^2)^n}_{n \in \N}$,
    %
    $(e_n)_{n \in \N} \with (\mlfpconst \mlfppower^n)_{n \in \N}$,
    %
    $N \with \scrn$ in the notation of \cite[Lemma~3.15]{beck2024overcoming})
    %
    and the fact that $\gamma \in [\nicefrac{3}{2}, \infty)$
    %
    yield
    %
    for all $\eps \in \err$ that
    %
    \begin{equation} \label{eq:main_simple_effort_power_of_M}
        \begin{split}    
            \pr*{ (4 \abs{A} M)^2 }^{\scrn( \eps) } &\le (4 \abs{A} M)^2 \max\Big\{ 1, \mlfpconst^{\frac{2 \ln( 4 \abs{A} M )}{\ln( \nicefrac{1}{\mlfppower})}} \Big\} \eps^{- \frac{2 \ln( 4 \abs{A} M )}{\ln( \nicefrac{1}{\mlfppower})}}\\
            %
            &= (4 \abs{A} M)^2 \mlfpconst^{\frac{2 \ln( 4 \abs{A} M )}{\ln( \nicefrac{1}{\mlfppower})}} \eps^{- \frac{2 \ln( 4 \abs{A} M )}{\ln( \nicefrac{1}{\mlfppower})}}.
        \end{split}
    \end{equation}
    %
    %
    %
    Furthermore,
    %
    observe that the fact that for all $\eps \in \err$ it holds that $\scrn(\eps) = \min\{ n \in \N : \mlfpconst \mlfppower^n \le \eps \}$ implies for all $\eps \in \err$ with $\scrn(\eps) \in \N \cap [2, \infty)$ that $\mlfpconst \mlfppower^{\scrn(\eps) - 1} > \eps$.
    %
    Hence, it holds for all $\eps \in \err$ with $\scrn(\eps) \in \N \cap [2, \infty)$ that $\scrn(\eps) < \frac{\ln( \eps^{-1} ) + \ln( \mlfpconst )}{\ln( \nicefrac{1}{\mlfppower})} + 1$.
    %
    This,
    %
    the fact that $\mlfppower \in \pr{0,1}$,
    %
    and the fact that $\mlfpconst \in [\nicefrac{3}{2}, \infty)$
    %
    establish that for all $\eps \in \err$ it holds that 
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_iterate_number_poly_bound}
            \scrn\pr{\eps} \le \pr*{\frac{\ln\pr{\nicefrac{1}{\mlfppower}} + \ln \pr{\mlfpconst} + 1}{\ln \pr{ \nicefrac{1}{\mlfppower}}}} \eps^{-1}.
        \end{split}
    \end{equation}
    %
    Combining this,
    %
    \eqref{eq:main_simple_effort_base_estimate},
    %
    \eqref{eq:main_simple_width_depth_polynomial_growth},
    %
    and \eqref{eq:main_simple_effort_power_of_M}
    %
    ensures for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ that
    %
    \begin{equation}
        \begin{split} \label{eq:main_simple_effort_intermediate_estimate}
            \paramANN\pr{\Psi_{\dm, \eps, \mu}} &\le 16 \fK^3\dm^{3\genConst}\delta_{\dm, \eps}^{-3\genConst} \pr*{\frac{\ln\pr{\nicefrac{1}{\mlfppower}} + \ln \pr{\mlfpconst} + 1}{\ln \pr{ \nicefrac{1}{\mlfppower}}}} \delta_{\dm, \eps}^{-1} \pr{4\abs{A}M}^2 \gamma^{\tfrac{2 \ln \pr{4\abs{A}M}}{\ln \pr{\nicefrac{1}{\alpha}}}} \delta_{\dm, \eps}^{- \tfrac{2 \ln \pr{ 4 \abs{A} M}}{\ln \pr{\nicefrac{1}{\alpha}}}} \\
            %
            &= 256 \fK^3 (\abs{A}M)^2 \gamma^{\tfrac{2 \ln \pr{4\abs{A}M}}{\ln \pr{\nicefrac{1}{\alpha}}}} \pr*{\frac{\ln\pr{\nicefrac{1}{\mlfppower}} + \ln \pr{\mlfpconst} + 1}{\ln \pr{ \nicefrac{1}{\mlfppower}}}} \dm^{3\genConst} \delta_{\dm, \eps}^{- \pr*{1 + 3\genConst + \tfrac{2 \ln \pr{ 4\abs{A} M }}{\ln \pr{\nicefrac{1}{\alpha}}}}}.
        \end{split}
    \end{equation}
    %
    Moreover, observe the assumption that $\sup_{\dm \in \N} \lambda_{\dm} L_\dm < 1$,
    %
    the assumption that $\sup_{\dm \in \N} \eta_\dm L_\dm < 1$,
    %
    and \cref{eq:main_simple_definition_delta_dm_eps}
    %
    establish for all $\dm \in \N$, $\eps \in \err$ that
    %
    \begin{equation}
        \begin{split}
            \delta_{\dm, \eps}^{-1} \le \tfrac{3\genConst^3}{\pr{1 - \sup_{u \in \N}\lambda_u L_u} \pr{1 - \sup_{u \in \N} \eta_u L_u}} \dm^{3\genConst} \eps^{-1}.
        \end{split}
    \end{equation}
    %
    Combining this with \eqref{eq:main_simple_effort_intermediate_estimate} demonstrates for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ that
    %
    \begin{equation}
        \begin{split}
            \paramANN\pr{\Psi_{\dm, \eps, \mu}} &\le 256 \fK^3 \pr{\abs{A}M}^2 \gamma^{\tfrac{2 \ln \pr{4\abs{A}M}}{\ln \pr{\nicefrac{1}{\alpha}}}} \pr*{\frac{\ln\pr{\nicefrac{1}{\mlfppower}} + \ln \pr{\mlfpconst} + 1}{\ln \pr{ \nicefrac{1}{\mlfppower}}}} \\
            %
            &\quad\cdot \pr*{\tfrac{3\genConst^3}{\pr{1 - \sup_{u \in \N}\lambda_u L_u} \pr{1 - \sup_{u \in \N} \eta_u L_u}}}^{\pr*{1 + 3\genConst + \tfrac{2 \ln \pr{ 4\abs{A} M }}{\ln \pr{\nicefrac{1}{\alpha}}}}} \dm^{3\genConst + 3\genConst \pr*{1 + 3\genConst + \tfrac{2 \ln \pr{ 4\abs{A} M }}{\ln \pr{\nicefrac{1}{\alpha}}}}} \\
            %
            &\quad \cdot \eps^{-\pr*{1 + 3\genConst + \tfrac{2 \ln \pr{ 4\abs{A} M }}{\ln \pr{\nicefrac{1}{\alpha}}}}}.
        \end{split}
    \end{equation}
    %
    This proves \cref{item:main_simple_ex_ann}.
    %
    The proof of \cref{thm:main_simple} is thus complete.
\end{mproof}


\subsection{ANN approximations for functional fixed-point equations with specific activation functions and one-step transitions}
\label{subsec:activation_transition}

\cfclear
\begin{lemma}
    \label{lem:properties_wdist}
    \cfconsiderloaded{lem:properties_wdist}
    Let $\dm, m \in \N$,
    %
    let $\eta \in [0, \infty)$,
    %
    let $(\Omega, \cF, \mathbb{P})$ be a probability space,
    %
    let $\xi \colon \Omega \to \R^m$ be measurable,
    %
    let $\ft_i \colon \R^\dm \times \R^m \to \R^\dm$, $i \in \cu{1,2}$, be measurable,
    %
    assume that for all $x, y \in \R^\dm$, $p \in \R^m$ it holds that $\norm{\ft_1(x, p) - \ft_1(y, p)} \le \eta \norm{x - y}$,
    %
    let $\kappa_i \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $i \in \cu{1,2}$, satisfy for all $i \in \cu{1,2}$, $x \in \R^\dm$, $B \in \Borel(\R^\dm)$ that $\kappa_i\pr{x, B} = \mathbb{P}\br{\ft_i\pr{x, \xi} \in B}$,
    %
    and assume for all $i \in \cu{1,2}$, $x \in \R^\dm$ that $\E \br{\norm{\ft_i\pr{x, \xi}}} < \infty$.
    %
    Then 
    \begin{enumerate}[label = (\roman*)]
        \item \label{item:properties_wdist_error} it holds for all $x \in \R^\dm$ that
        \begin{equation}
            \wdist_\dm \pr{\kappa_1(x, \cdot), \kappa_2(x, \cdot)} \le \int_{\R^m} \norm{\ft_1 (x, p) - \ft_2(x,p)} \pr{\mathbb{P} \circ \xi^{-1}}\pr{\dxx p}
        \end{equation}
        and
        \item \label{item:properties_wdist_lipschitz} it holds for all $x, y \in \R^\dm$ that
        \begin{equation}
            \wdist_\dm \pr{ \kappa_1(x, \cdot), \kappa_1(y, \cdot) } \le \eta \norm{x - y}
        \end{equation}
    \end{enumerate}
    \cfout .
\end{lemma}

\begin{mproof}{\cref{lem:properties_wdist}}
    Let $X_i \colon \R^\dm \times \Omega \to \R^\dm$, $i \in \cu{1,2}$, satisfy for all $i \in \cu{1,2}$, $x \in \R^\dm$ that $X_i^x = \ft_i\pr{x, \xi}$.
    %
    Note that the assumption that for all $x \in \R^\dm$, $i \in \cu{1,2}$ it holds that $\E \br{ \norm{ \ft_i\pr{x, \xi}}} < \infty$ ensures for all $i \in \cu{1,2}$, $x \in \R^\dm$ that $\kappa_i \pr{x, \cdot} \in \meas_\dm$.
    %
    Observe that for all $i \in \cu{1,2}$, $x \in \R^\dm$, it holds that $X^x_i \sim \kappa_i(x, \cdot)$.
    %
    Furthermore, it holds for all $x \in \R^\dm$ that $\mathbb{P} \circ (X_1^x, X_2^x)^{-1} \in \coup_\dm \pr{\kappa_1\pr{x, \cdot}, \kappa_2\pr{x, \cdot}}$.
    %
    This demonstrates for all $x \in \R^\dm$ that
    %
    \begin{equation}
        \begin{split}
            \wdist_\dm \pr{\kappa_1(x, \cdot), \kappa_2(x, \cdot)} &= \inf_{\gamma \in \coup_\dm \pr{ \kappa_1(x, \cdot), \kappa_2(x, \cdot) }} \int_{\R^\dm \times \R^\dm} \norm{\bfx - \bfy} \gamma\pr{\dxx \pr{\bfx, \bfy}} \\
            %
            &\le \int_{\R^\dm \times \R^\dm} \norm{\bfx - \bfy} \pr*{\mathbb{P} \circ (X_1^x, X_2^x)^{-1}} \pr{ \dxx (\bfx, \bfy)} \\
            %
            &= \int_{\Omega} \norm*{ X^x_1(\omega) - X^x_2(\omega)} \mathbb{P}\br{\dxx \omega} \\
            %
            &= \int_{\Omega} \norm*{ \ft_1(x, \xi(\omega)) - \ft_2(x, \xi(\omega)) } \mathbb{P}\br{\dxx \omega}\\
            %
            &= \int_{\R^m} \norm*{\ft_1(x, p) - \ft_2(x, p)} \pr*{\mathbb{P} \circ \xi^{-1}} \pr{\dxx p}.
        \end{split}
    \end{equation}
    %
    This proves \cref{item:properties_wdist_error}.
    %
    Moreover, it holds for all $x, y \in \R^\dm$ that $\mathbb{P} \circ (X_1^x, X_1^y)^{-1} \in \coup_\dm\pr{ \kappa_1(x, \cdot), \kappa_1(y, \cdot)}$.
    %
    Combining this with the assumption that for all $x, y \in \R^\dm$, $p \in \R^m$ it holds that $\norm{\ft_1(x,p) - \ft_1(y, p)} \le \eta \norm{x-y}$
    %
    yields for all $x, y \in \R^\dm$ that
    %
    \begin{equation}
        \begin{split}
            \wdist_\dm \pr{ \kappa_1(x, \cdot), \kappa_1(y, \cdot) } &= \inf_{\gamma \in \coup_\dm \pr{ \kappa_1(x, \cdot), \kappa_1(y, \cdot) }} \int_{\R^\dm \times \R^\dm} \norm{\bfx - \bfy} \gamma\pr{\dxx \pr{\bfx, \bfy}} \\
            %
            &\le \int_{\R^m} \norm*{\ft_1(x, p) - \ft_1(y, p)} \pr*{\mathbb{P} \circ \xi^{-1}} \pr{\dxx p} \\
            %
            &\le \eta \norm{x - y}.
        \end{split}
    \end{equation} 
    %
    This proves \cref{item:properties_wdist_lipschitz}.
    %
    The proof of \cref{lem:properties_wdist} is thus complete.
\end{mproof}


\cfclear
\begin{corollary}
    \label{cor:activation_transition}
    %
    \cfconsiderloaded{cor:activation_transition}
    %
    Let $A$ be a nonempty finite set,
    %
    let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space,
    %
    let $\genConst \in [1, \infty)$, 
    %
    let $\nu \in \cu{0,1}$,
    %
    let $\beta \in [0, \infty) \backslash \cu{1}$,
    %
    for every $\dm \in \N$ let $ \lambda_\dm, \eta_\dm, K_\dm, L_\dm \in \pr{0,\infty}$,
    %
    for every $\dm \in \N$, $\eps \in \err$ let $\lipFANN_{\dm, \eps} \in \pr{0,\infty}$,
    %
    assume $\sup_{\dm \in \N} \lambda_\dm L_\dm < 1$, $\sup_{\dm \in \N} \eta_\dm L_\dm < 1$, $\sup_{(\dm, \eps) \in \N \times \err} \lambda_\dm \lipFANN_{\dm, \eps} < 1$,
    %
    for every $\dm \in \N$ let $\w_\dm \colon \R^\dm \to \pr{0, \infty}$ be measurable,
    %
    for every $\dm \in \N$, $x \in \pr{x_1, \dots, x_\dm} \in \R^\dm$ let $\fnorm{x} \in \R$ satisfy $\fnorm{x} = \max_{i \in \cu{1,\dots, \dm}} \abs{x_i}$,
    %
    for every $\dm \in \N$ let $f_\dm \colon \R^\dm \times \R^{\abs{A}} \to \R$ be measurable,
    %
    for every $\dm \in \N$, $a \in A$ let $t^{\pr{a}}_\dm \colon \R^{2\dm} \to \R^\dm$ be measurable,
    %
    for every $\dm \in \N$ let $\xi_\dm \colon \Omega \to \R^\dm$ be measurable,
    %
    let $\action \in A$, 
    %
    %
    %
    let $\activation \colon \R \to \R$ satisfy for all $x \in \R$ that $\activation(x) = \nu \max\cu{x, \beta x} + \pr{1 - \nu} \ln\pr{1 + \exp(x)}$,
    %
    let $(\bF_{\dm, \eps})_{(\dm, \eps) \in \N \times \err} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \N$ that $\cR_\activation(\bF_{\dm, \eps}) \in C(\R^{\dm + \abs{A}}, \R)$,
    %
    let $(\ft_{\dm, \eps}^{\pr{a}})_{(\dm, \eps, a) \in \N \times \err \times A} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \err$, $a \in A$ that $\cD\pr{ \ft_{\dm, \eps}^{\pr{a}}} = \cD \pr{ \ft_{\dm, \eps}^{\pr{\action}}}$ and $\cR_\activation\pr{\ft_{\dm, \eps}^{\pr{a}}} \in C(\R^{2\dm}, \R^\dm)$,
    %
    assume for all $\dm \in \N$, $\eps \in \err$ that $\max\cu{\lambda_\dm, K_\dm} \le \genConst \dm^\genConst$ and
    %
    \begin{equation}
        \begin{split}
            \max\cu*{\cL\pr{ \bF_{\dm, \eps} }, \cL\pr{ \ft_{\dm, \eps}^{\pr{\action}} }, \fnorm[\big]{\cD\pr{ \bF_{\dm, \eps} }}, \fnorm[\big]{ \cD\pr{ \ft_{\dm, \eps}^{\pr{\action}} } } } \le \genConst \dm^\genConst \eps^{- \genConst},
        \end{split}
    \end{equation}
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $x,y, p \in \R^\dm$, $r, s \in \R^{\abs{A}}$, $a \in A$ that 
    \begin{align}
        \begin{split} \label{eq:activation_transition_approximation_assumption}
            &\abs[\big]{ \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,r) -  f_\dm (x,r) } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)},\\
            %
            &\norm[\big]{ \pr[\big]{\cR_\activation \pr{\ft_{\dm, \eps}^{\pr{a}}}} \pr{x, p} - t_\dm^{\pr{a}}\pr{x, p} } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)},
        \end{split} \\
        %
        \begin{split} \label{eq:activation_transition_lipschitz}
            & \abs*{ f_\dm (x,r) - f_\dm(x,s) } \le L_\dm \max_{b \in A} \abs*{ r(b) - s(b) }, \qquad \abs*{f_\dm(x, r) - f_\dm(y,r)} \le K_\dm \norm{ x - y}, \\
            %
            %
            &\abs*{ \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,r) - \pr[\big]{ \cR_\activation (\bF_{\dm, \eps}) }(x,s) } \le \lipFANN_{\dm, \eps} \max_{b \in A} \abs*{ r(b) - s(b) },\quad \text{and} \\
            %
            %
            &\norm[\big]{ t_\dm^{\pr{a}}\pr{ x, p } - t_\dm^{\pr{a}}\pr{ y, p }  }  \le \eta_\dm \norm{x - y},
        \end{split}
    \end{align}
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $a \in A$ that
    \begin{equation}
        \begin{split}
            \sup_{x \in \R^\dm} \abs{\w_\dm\pr{x}}^{-1} \E \br[\big]{ \norm{t_\dm^{\pr{a}} \pr{x, \xi_\dm}} } < \infty \quad \text{ and } \quad \sup_{x \in \R^\dm } \abs{\w_\dm\pr{x}}^{-1} \E \br[\big]{ \norm[\big]{ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} } } \pr{x, \xi_\dm} }  } < \infty,
        \end{split}
    \end{equation}
    %
    assume for all $\dm \in \N$, $x \in \R^\dm$, $\eps \in \err$, $a \in A$ that
    \begin{align}
        \begin{split}
            &\pr*{ \E\br*{ \abs*{ \w_\dm \pr*{ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}}} } \pr{x, \xi_\dm} } }^2 } }^{\!\!\nicefrac{1}{2}} \le \lambda_\dm \abs{\w_\dm\pr{x}}, \\
            %
            &\pr*{ \E \br*{ \abs*{ \pr[\big]{ \cR_\activation \pr{\bF_{\dm, \eps}} } \pr[\big]{ \pr[\big]{ \cR_\activation \pr{\ft_{\dm, \eps}^{\pr{a}}  } } \pr{x, \xi_\dm} , 0  }  }^2 } }^{\!\!\nicefrac{1}{2}} \le \genConst \dm^\genConst \abs{\w_\dm\pr{x}},
        \end{split}\\
        %
        \begin{split}
            & \E \br[\Big]{ \abs[\big]{ \w_\dm \pr[\big]{ t_\dm^{\pr{a}}(x, \xi_\dm) } } } \le \lambda_\dm \abs{\w_\dm\pr{x}}, \quad \text{ and } \quad \sup_{\substack{y \in \R^\dm \\ b \in A}} \abs{\w_\dm\pr{y}}^{-1} \E \br[\Big]{ \abs[\big]{ f_\dm \pr{ t_\dm^{\pr{b}} \pr{y, \xi_\dm} , 0 } } } < \infty.
        \end{split}
    \end{align}
    %
    Then there exists $c \in \R$ such that for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ it holds that
    %
    \begin{enumerate}[label = (\roman*)]
        \item \label{item:activation_transition_ex_uniq_sol} there exists a unique measurable $u \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that 
        %
        $\sup_{(z, b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(u(z))(b)} < \infty$,
        %
        $\E \br[\Big]{ \abs[\big]{ f_\dm \pr[\big]{ t_\dm^{\pr{a}} \pr{x, \xi_\dm}, u \pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } } } } < \infty$, and
        \begin{equation}
            \begin{split}
               \pr{u\pr{x}}\pr{a} = \E \br*{ f_\dm \pr[\big]{ t_\dm^{\pr{a}} \pr{x, \xi_\dm}, u \pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } } }
            \end{split}
        \end{equation}
        %
        and

        \item \label{item:activation_transition_ex_ann} there exists $\Psi \in \bN$ which satisfies $\cH \pr{\Psi} > 0$, $\paramANN(\Psi) \le c \dm^c \eps^{-c}$, $\cR_\activation(\Psi) \in C(\R^\dm, \R^{\abs{A}})$, and
        %
        \begin{equation} \label{eq:activation_transition_existence_approximating_ann}
            \pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ (u(x))(a) - \pr[]{\pr[]{\cR_\activation(\Psi)}(x)}(a) }^2 \mu(\dxx x) }^{\!\!\nicefrac{1}{2}} \le \eps
        \end{equation}
    \end{enumerate}
    \cfout.
\end{corollary}

\begin{mproof}{\cref{cor:activation_transition}}
    Throughout this proof let $\Theta = \cup_{n \in \N} \Z^n$,
    %
    for every $\dm \in \N$ let $\xi_\dm^\theta \colon \Omega \to \R^\dm$, $\theta \in \Theta$, be i.i.d. random variables,
