    and \cref{lem:compositions_of_anns} ensure for all $\theta \in \Theta$, $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$, $\omega \in \Omega$ that
    %
    $\cD \pr{ \ft_{\dm, \eps}^{\pr{a}} \bullet \Xi_{\dm}^\theta \pr{\omega} } = \cD \pr{ \ft_{\dm, \eps}^{\pr{\action}} \bullet \Xi_\dm^0\pr{\ol{\omega}} }$,
    %
    $\cL \pr{ \ft_{\dm, \eps}^{\pr{\action}} \bullet \Xi_\dm^0\pr{\ol{\omega}} } = \cL \pr{ \ft_{\dm, \eps}^{\pr{\action}} } + \cL \pr{ \Xi_{\dm}^{0} \pr{\ol{\omega}} } - 1 = \cL \pr{ \ft_{\dm, \eps}^{\pr{\action}} } $,
    %
    $\fnorm{ \cD \pr{ \ft_{\dm, \eps}^{\pr{\action}} \bullet \Xi_\dm^0\pr{\ol{\omega}}} } \le \max \cu{ \fnorm{ \cD\pr{ \ft_{\dm, \eps}^{\action} } }, \fnorm{\cD \pr{ \Xi_\dm^0\pr{ \ol{\omega} } }} } = \fnorm{ \cD\pr{ \ft_{\dm, \eps}^{\pr{\action}} } }$,
    %
    $ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{\action}} \bullet \Xi_\dm^0 \pr{\ol{\omega}} } \in C\pr{\R^\dm, \R^\dm} $, and
    %
    $ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} \bullet \Xi_{\dm}^\theta \pr{\omega} } } \pr{x} = \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} } } \pr{ x, \xi_\dm^\theta \pr{\omega} } $.
