    %
    Next, note that the assumption that for all $\dm \in \N$ it holds that $\xi_\dm^\theta$, $\theta \in \Theta$, are i.i.d.\ random variables assures that for all $\dm \in \N$, $\eps \in \err$ it holds that $ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} \bullet \Xi_\dm^\theta } }_{a \in A} $, $\theta \in \Theta$, are i.i.d.\ random fields.  
    %
    Throughout the remainder of this proof let $\tker^{\pr{a}}_\dm \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $\dm \in \N$, $a \in A$, satisfy for all $\dm \in \N$, $x \in \R^\dm$, $a \in A$, $B \in \Borel(\R^\dm)$ that $\tker_\dm^{\pr{a}}\pr{ x, B } = \mathbb{P} \br{ t_\dm^{\pr{a}} \pr{x, \xi_\dm^0} \in B }$,
    %
    let $\tkerANN_{\dm, \eps}^{\pr{a}} \colon \R^\dm \times \Borel(\R^\dm) \to \br{0,1}$, $\dm \in \N$, $\eps \in \err$, $a \in A$, satisfy for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$, $B \in \Borel\pr{\R^\dm}$ that $\tkerANN_{\dm, \eps}^{\pr{a}} \pr{x, B} = \mathbb{P} \br{ \pr[\big]{ \cR_\activation\pr{ \ft_{\dm, \eps}^{\pr{a} }}} \pr{x, \xi_\dm^0}  \in B}$.
    %
    Note that for all $\dm \in \N$, $\eps \in \err$, $a \in A$ it holds that $\tker_{\dm}^{\pr{a}}$ and $\tkerANN_{\dm, \eps}^{\pr{a}}$ are stochastic kernels.
    %
    This and \cref{lem:properties_wdist} (applied for every $\dm \in \N$, $\eps \in \err$, $a \in A$ with $\dm \with \dm$,
    %
    $m \with \dm$,
    %
    $\eta \with \eta_\dm$,
    %
    $\pr{\Omega, \cF, \mathbb{P}} \with \pr{\Omega, \cF, \mathbb{P}}$,
    %
    $\xi \with \xi_\dm^0$,
    %
    $\ft_1 \with t_\dm^{\pr{a}}$,
    %
    $\ft_2 \with \cR_\activation \pr{\ft_{\dm, \eps}^{\pr{a}}}$
    %
    in the notation of \cref{lem:properties_wdist})
    %
    establishes that for all $\dm \in \N$, $x, y \in \R^\dm$, $\eps \in \err$, $a \in A$ it holds that
    %
    $\wdist_\dm \pr{ \tker_{\dm}^{\pr{a}} \pr{x, \cdot}, \tker_{\dm}^{\pr{a}} \pr{y, \cdot} } \le \eta_\dm \norm{x - y}$ and 
    %
    \begin{equation}
        \begin{split}
            \wdist_\dm \pr{ \tker_{\dm}^{\pr{a}} \pr{x, \cdot}, \tkerANN_{\dm, \eps}^{\pr{a}} \pr{x, \cdot} } \le \int_{\R^\dm} \norm{ t_\dm^{\pr{a}} \pr{x, p} - \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} } } \pr{x, p} } \pr[\big]{ \mathbb{P} \circ \pr{\xi_\dm^0}^{-1} } \pr{\dxx p}.
