    Combining this 
    %
    with   
    %
    \cref{thm:main_simple} (applied with
    %
    \begin{align}
        &\Theta \with \Theta, \quad A \with A, \quad \pr{\Omega, \cF, \mathbb{P}} \with \pr{\Omega, \cF, \mathbb{P}}, \quad \genConst \with \genConst, \quad \pr{ \lambda_\dm, \eta_\dm, K_\dm, L_\dm }_{\dm \in \N} \with \pr{ \lambda_\dm, \eta_\dm, K_\dm, L_\dm }_{\dm \in \N}  \nonumber\\
        %
        &\pr{\lipFANN_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err} \with \pr{\lipFANN_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err}, \quad \pr{\w_\dm}_{\dm \in \N} \with \pr{\w_\dm}_{\dm \in \N}, \quad \pr{f_\dm}_{\dm \in \N} \with \pr{f_\dm}_{\dm \in \N}, \nonumber \\
        %
