        %
        &\pr{ \bX_{\dm, \eps}^{ \theta, a } }_{ \pr{ \theta, \dm, \eps, a } \in \Theta \times \N \times \err \times A } \with \pr{ \ft_{\dm, \eps}^{\pr{a}} \bullet \Xi_\dm^\theta }_{ \pr{ \theta, \dm, \eps, a } \in \Theta \times \N \times \err \times A }, \nonumber \\
        %
        &\pr{ \mathcal{F}_{\dm, \eps}^\theta }_{\pr{\theta, \dm, \eps} \in \Theta \times \N \times \err} \with \pr{ \F_{\dm}^\theta }_{\pr{ \theta, \dm, \eps } \in \Theta \times \N \times \err} 
