    let $(\bG_{\dm, \eps})_{(\dm, \eps) \in \N \times \err} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \N$ that $\cR_\activation(\bG_{\dm, \eps}) \in C(\R^{\dm}, \R^{\abs{A}})$,
    %
    let $(\ft_{\dm, \eps}^{\pr{a}})_{(\dm, \eps, a) \in \N \times \err \times A} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \err$, $a \in A$ that $\cD\pr{ \ft_{\dm, \eps}^{\pr{a}}} = \cD \pr{ \ft_{\dm, \eps}^{\pr{\action}}}$ and $\cR_\activation\pr{\ft_{\dm, \eps}^{\pr{a}}} \in C(\R^{2\dm}, \R^\dm)$,
    %
    assume for all $\dm \in \N$, $\eps \in \err$ that 
    %
    \begin{equation}
        \begin{split}
            \max\cu*{\cL\pr{ \bG_{\dm, \eps} }, \cL\pr{ \ft_{\dm, \eps}^{\pr{\action}} }, \fnorm[\big]{\cD\pr{ \bG_{\dm, \eps} }}, \fnorm[\big]{ \cD\pr{ \ft_{\dm, \eps}^{\pr{\action}} } } } \le \genConst \dm^\genConst \eps^{- \genConst},
        \end{split}
    \end{equation}
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $x,y, p \in \R^\dm$, $a \in A$ that 
    \begin{align}
        \begin{split} \label{eq:bellman_approximation_assumption}
            &\abs[\big]{ \pr[\big]{\pr[\big]{ \cR_\activation (\bG_{\dm, \eps}) }(x)}\pr{a} -  \pr{g_\dm (x)}\pr{a} } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)},\\
            %
            &\norm[\big]{ \pr[\big]{\cR_\activation \pr{\ft_{\dm, \eps}^{\pr{a}}}} \pr{x, p} - t_\dm^{\pr{a}}\pr{x, p} } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)},
        \end{split} \\
        %
        \begin{split} \label{eq:bellman_lipschitz}
            & \abs*{ \pr{g_\dm \pr{x}} \pr{a} - \pr{g_\dm\pr{y}}\pr{a}} \le K \norm{ x - y}, \quad \text{and} \\
            %
            %
            %
            &\norm[\big]{ t_\dm^{\pr{a}}\pr{ x, p } - t_\dm^{\pr{a}}\pr{ y, p }  }  \le \eta \norm{x - y},
        \end{split}
    \end{align}
    %
    assume for all $\dm \in \N$, $\eps \in \err$, $a \in A$ that
    \begin{equation}
        \begin{split}
            \sup_{x \in \R^\dm} \abs{\w_\dm\pr{x}}^{-1} \E \br[\big]{ \norm{t_\dm^{\pr{a}} \pr{x, \xi_\dm}} } < \infty \quad \text{ and } \quad \sup_{x \in \R^\dm } \abs{\w_\dm\pr{x}}^{-1} \E \br[\big]{ \norm[\big]{ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}} } } \pr{x, \xi_\dm} }  } < \infty,
        \end{split}
    \end{equation}
    %
    assume for all $\dm \in \N$, $x \in \R^\dm$, $\eps \in \err$, $a \in A$ that
    \begin{align}
        \begin{split}
            &\pr*{ \E\br*{ \abs*{ \w_\dm \pr*{ \pr[\big]{ \cR_\activation \pr{ \ft_{\dm, \eps}^{\pr{a}}} } \pr{x, \xi_\dm} } }^2 } }^{\!\!\nicefrac{1}{2}} \le \lambda \abs{\w_\dm\pr{x}}, \\
            %
            &\pr*{ \E \br*{ \max_{b \in A} \abs*{ \pr[\Big]{\pr[\big]{ \cR_\activation \pr{\bG_{\dm, \eps}} } \pr[\big]{ \pr[\big]{ \cR_\activation \pr{\ft_{\dm, \eps}^{\pr{a}}  } } \pr{x, \xi_\dm} }} \pr{b}  }^2 } }^{\!\!\nicefrac{1}{2}} \le \genConst \dm^\genConst \abs{\w_\dm\pr{x}}, 
        \end{split}\\
        %
        \begin{split}
            & \E \br[\Big]{ \abs[\big]{ \w_\dm \pr[\big]{ t_\dm^{\pr{a}}(x, \xi_\dm) } } } \le \lambda \abs{\w_\dm\pr{x}}, \quad \text{ and } \quad \sup_{\substack{y \in \R^\dm \\ b \in A}} \abs{\w_\dm\pr{y}}^{-1} \abs{ \pr{g_\dm\pr{y}} \pr{b}} < \infty.
        \end{split}
    \end{align}
    %
    %
    Then there exists $c \in \R$ such that for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ it holds that
    %
    \begin{enumerate}[label = (\roman*)]
        \item \label{item:bellman_ex_uniq_sol} there exists a unique measurable $\qfunc \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that 
        %
        $\sup_{(z, b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(\qfunc(z))(b)} < \infty$,
        %
        $\E \br[\Big]{ \max_{b \in A} \abs[\big]{ \pr{ \qfunc \pr{ t_{\dm}^{\pr{a}}\pr{x, \xi_\dm} } } \pr{b} }  } < \infty$, and
        \begin{equation}
            \begin{split}
                \pr{\qfunc\pr{x}}\pr{a} = \pr{g_\dm(x)}\pr{a} + L \E \br*{ \max_{b \in A}  \pr{ \qfunc \pr{ t_{\dm}^{\pr{a}}\pr{x, \xi_\dm} } } \pr{b} }
            \end{split}
        \end{equation}
        and

        \item \label{item:bellman_ex_ann} there exists $\bQ \in \bN$ which satisfies $\cH \pr{\bQ} > 0$, $\paramANN (\bQ) \le c \dm^c \eps^{-c}$, $\cR_\activation (\bQ) \in C( \R^\dm, \R^{\abs{A}})$, and
        \begin{equation} \label{eq:bellman_approximating_ann}
            \pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ (\qfunc(x))(a) - \pr*{ \pr*{ \cR_\activation(\bQ) }(x) }(a) }^2 \mu(\dxx x) }^{\!\!\nicefrac{1}{2}} \le \eps
        \end{equation}
    \end{enumerate}
    \cfout.
\end{corollary}

\begin{mproof}{\cref{cor:bellman}}
    Throughout this proof let $\genConstVar = \max\cu{L, 2\abs{A} + 1} \genConst$, let $\bI, \fJ \in \bN$ satisfy
    %
    \begin{align}
        \bI &= \pr*{ \pr*{ \begin{pmatrix}
                1 \\ - 1
            \end{pmatrix}, \begin{pmatrix}
                0 \\ 0
            \end{pmatrix} }, \pr[\Big]{ \begin{pmatrix}
                1 & -1
            \end{pmatrix}, 0 }} \in \pr{\R^{2\times 1} \times \R^2} \times \pr{\R^{1 \times 2} \times \R^1} \qquad \text{and}\\
        %
        \fJ &= (1 + \beta)^{-1} \circledast \bI
    \end{align}
    %
    let $\I_k \in \bN$, $k \in \N$, satisfy for all $k \in \N$ that $\I_k = \paraANN{k}(\fJ, \fJ, \dots, \fJ)$,
    %
    for every $\dm \in \N$ let $f_\dm \colon \R^\dm \times \R^{|A|} \to \R$ satisfy for all $x \in \R^\dm$, $r\in \R^{|A|}$ that $f_\dm (x, r) = L \max_{a \in A} \{ ( g_\dm(x) )(a) + r(a) \}$.
    %
    %
    Observe that \cite[Lemma~3.5]{ackermann2023deep} ensures for all $x \in \R$ that $\cD\pr{\fJ} = \pr{1,2,1} \in \N^3$ and $\pr{ \cR_\activation \pr{\fJ} }\pr{x} = x$.
    %
    This and \cref{lem:parallelizations_of_anns_same_depth} imply for all $k \in \N$, $ x \in \R^k $ that $\cD \pr{\I_k} = \pr{k, 2k, k} \in \N^3$ and $\pr{\cR_\activation \pr{\I_k} } \pr{x} = x$.
    %
    %      
    %
    Next, note that \cref{lem:max_of_finite_set_leaky} ensures that there exists $\bM \in \bN$ such that for all $x = (x_1, x_2, \dots, x_{|A|}) \in \R^{|A|}$ it holds that $\cR_\activation(\bM) \in C(\R^{|A|}, \R)$, $ \big( \cR_\activation (\bM)  \big)(x) = \max_{i \in [1, |A|] \cap \N} x_i$, $\cL(\bM) = \ceil{\log_2(|A|)} + 1$, and $\fnorm{ \cD (\bM) } \le 2|A|$.
    %
    Throughout the remainder of this proof let $(\bF_{\dm, \eps})_{(\dm, \eps) \in \N \times \err} \subseteq \bN$ satisfy for all $\dm \in \N$, $\eps \in \err$ that
    %
    \begin{equation} \label{eq:bellman_def_nonlin_net}
        \bF_{\dm, \eps} = L \circledast \pr[\big]{\bM \bullet \fS_{|A|, 2} \bullet \paraLANN{2}{\pr{\I_{\abs{A}}, \I_{\abs{A}}}} \pr[\big]{ \bG_{\dm, \eps}, \I_{|A|}} } .
    \end{equation}
    %
    Next, observe that
    %
    the assumption that $A$ is nonempty,
    % 
    the assumption that for all $\dm \in \N$, $\eps \in \err$ it holds that $ \max\cu{ \cL \pr{ \bG_{\dm, \eps} }, \fnorm{\cD \pr{ \bG_{\dm, \eps} }}} \le \genConst \dm^\genConst \eps^{-\genConst} $,
    %
    the assumption that for all $r = (r(a))_{a \in A} \in \R^{\abs{A}}$ it holds that $\pr[\big]{ \cR_\activation (\bM) }(r) = \max_{a \in A} r(a)$,
    %
    the fact that for all $k \in \N$ it holds that $\cD (\I_k) = (k , 2 k, k)$,
    %
    the fact that for all $n \in \N$ it holds that $\ceil{\log_2(n)} + 1 \le n$,
    %
    \cref{lem:compositions_of_anns},
    %
    \cref{lem:extensions_of_anns_involving_identities},
    %
    \cref{cor:parallelizations_of_anns_with_different_layer_structure_realization_involving_identities}, and
    %
    \cref{lem:scalar_multiplications_of_anns} 
    %
    assure for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $r = (r(a))_{a \in A} \in \R^{\abs{A}}$ that
    %
    \begin{align}
        \begin{split} \label{eq:bellman_nonlin_architecture}
            \cI (\bF_{\dm, \eps}) &= \cI \pr[\big]{ \paraLANN{2}{\pr{\I_{\abs{A}}, \I_{\abs{A}}}} \pr[\big]{ \bG_{\dm, \eps}, \I_{|A|}}  } = \dm + |A|,\\
            %
            \cO (\bF_{\dm, \eps}) &= \cO (\bM) = 1, \qquad \cR_\activation (\bF_{\dm, \eps}) \in C(\R^{\dm + |A|}, \R),\\
            %
            \cL(\bF_{\dm, \eps}) &= \cL(\bM) + \cL\pr{ \fS_{\abs{A}, 2} } + \cL\pr{ \paraLANN{2}{\pr{\I_{\abs{A}}, \I_{\abs{A}}}} \pr[\big]{ \bG_{\dm, \eps}, \I_{|A|}} } - 2\\ 
            %
            &\le \ceil{ \log_2(\abs{A}) } + 1 + \max\cu{ \cL\pr{ \bG_{\dm, \eps} }, \cL \pr{ \I_{\abs{A}}} } - 1 \le \abs{A} + \cL(\bG_{\dm, \eps}) + 1 \\
            %
            &\le \pr{\abs{A} + 2} \genConst \dm^\genConst \eps^{-\genConst} \le \pr{2\abs{A} + 1} \genConst \dm^\genConst \eps^{-\genConst} \le \genConstVar \dm^\genConstVar \eps^{-\genConstVar},\\
            %
            \fnorm{\cD(\bF_{\dm, \eps})} &\le \max \cu[\big]{ \fnorm{\cD(\bM)}, \fnorm{\cD (\fS_{\abs{A}, 2})}, \fnorm{ \cD \pr{ \paraLANN{2}{\pr{\I_{\abs{A}}, \I_{\abs{A}}}} \pr{ \bG_{\dm, \eps}, \I_{|A|}} } } } \\
            %
            &\le \max \cu[\big]{ \fnorm{\cD(\bM)},  2\abs{A}, 2\abs{A} + \fnorm{\cD(\bG_{\dm, \eps})} }  \\
            %
            &= 2\abs{A} + \fnorm{\cD(\bG_{\dm, \eps})} \le \pr{2\abs{A} + 1} \genConst \dm^\genConst \eps^{-\genConst} \le \genConstVar \dm^\genConstVar \eps^{- \genConstVar}, \qquad \qquad \text{and} 
        \end{split} \\
        %
        \begin{split} \label{eq:bellman_nonlin_realization} 
            \pr*{\cR_\activation (\bF_{\dm, \eps})}(x,r) &= L \pr*{ \pr[\big]{\cR_\activation (\bM) \circ \cR_\activation (\fS_{|A|, 2}) \circ \cR_\activation \pr[\big]{ \paraLANN{2}{\pr{\I_{\abs{A}}, \I_{\abs{A}}}} \pr{ \bG_{\dm, \eps}, \I_{|A|}} }} (x, r) } \\
            %
            %
            %
            &= L \pr[\bigg]{ \pr[\big]{\cR_\activation (\bM) \circ \cR_\activation(\fS_{\dm, \eps}) } \begin{pmatrix}
                \pr[\big]{\cR_\activation(\bG_{\dm, \eps})} (x) \\r
            \end{pmatrix} } \\
            %
            %
            %
            &= L \pr[\big]{\pr[\big]{\cR_\activation(\bM)}  \pr[\big]{(\cR_\activation (\bG_{\dm, \eps}))(x) + r} }  \\
            %
            %
            %
            &= L \max_{a \in A}  \cu[\big]{  \pr[\big]{\pr[\big]{ \cR_\activation(\bG_{\dm, \eps})}(x)}(a) + r(a) }.
        \end{split}
    \end{align}
    %
    Next, observe that for all $\dm \in \N$, $x \in \R^\dm$, $r,s \in \R^{\abs{A}}$, $\eps \in \err$ it holds that $\abs{ f_\dm\pr{x, r} - f_\dm \pr{x, s} } \le L \max_{a \in A} \abs{r\pr{a} - s\pr{a}}$ and $\abs{ \pr{ \cR_\activation \pr{\bF_{\dm, \eps}} } \pr{x, r} - \pr{ \cR_\activation \pr{\bF_{\dm, \eps}} } \pr{x, s} } \le L \max_{a \in A} \abs{ r\pr{a} - s\pr{a} }$.
    %
    Moreover, note that the assumption that for all $\dm \in \N$, $x,y\in \R^\dm$, $a \in A$ it holds that $\abs{ \pr{g_\dm\pr{x}}\pr{a} - \pr{g_\dm\pr{y}}\pr{a} } \le K \norm{x - y}$
    %
    implies for all $\dm \in \N$, $x,y \in \R^\dm$, $r\in \R^{\abs{A}}$ that
    %
    \begin{equation}
        \begin{split} \label{eq:bellman_nonlin_lipschitz_1st_arg}
            \abs{ f_\dm \pr{x,r} - f_\dm \pr{y, r} } \le L \max_{a \in A} \abs{ \pr{g_\dm \pr{x}}\pr{a} - \pr{g_\dm \pr{y}}\pr{a} } \le K L \norm{x - y}.
        \end{split}
    \end{equation}
    %
    In addition, observe that the assumption that for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$ it holds that
    $\abs[\big]{ \pr[\big]{\pr[\big]{ \cR_\activation (\bG_{\dm, \eps}) }(x)}\pr{a} -  \pr{g_\dm (x)}\pr{a} } \le \eps \genConst \dm^{\genConst} \abs{\w_\dm(x)}$
    %
    establishes for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $r \in \R^\dm$ that
    %
    \begin{equation}
        \begin{split}
            \abs[\big]{ \pr{ \cR_\activation \pr{\bF_{\dm, \eps}} } \pr{x, r} - f_\dm \pr{x, r} } &\le L \max_{a \in A} \abs[\big]{ \pr[\big]{ \pr{\cR_\activation \pr{\bG_{\dm, \eps}}} \pr{x} } \pr{a} - \pr{ g_\dm\pr{x} }\pr{a}  }\\
            %
            &\le \eps \genConst L \dm^\genConst \abs{\w_\dm \pr{x}} \le \eps \genConstVar \dm^\genConstVar \abs{\w_\dm\pr{x}}.
        \end{split}
    \end{equation} 
    %
    %
    This
    %
    and \cref{cor:activation_transition} (applied with
    \begin{equation}
        \begin{split}
            &A \with A, \quad \pr{\Omega, \mathcal{F}, \mathbb{P}} \with \pr{\Omega, \mathcal{F}, \mathbb{P}}, \quad \genConst \with \genConstVar, \quad \nu \with 1, \quad \beta \with \beta, \\
            %
            &\pr{\lambda_\dm, \eta_\dm, K_\dm, L_\dm}_{\dm \in \N} \with (\lambda, \eta, KL, L)_{\dm \in \N}, \quad \pr{\lipFANN_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err} \with \pr{ L}_{\pr{\dm, \eps} \in \N \times \err}, \\
            %
            &\pr{\w_\dm}_{\dm \in \N} \with \pr{\w_\dm}_{\dm \in \N}, \quad \pr{f_\dm}_{\dm \in \N} \with \pr{f_\dm}_{\dm \in \N}, \\
            %
            &\pr{ t_\dm^{\pr{a}} }_{\pr{\dm, a } \in \N \times A} \with \pr{ t_\dm^{\pr{a}} }_{\pr{\dm, a } \in \N \times A}, \quad \pr{\xi_\dm}_{\dm \in \N} \with \pr{\xi_\dm}_{\dm \in \N}, \quad \action \with \action, \quad \activation \with \activation, \\
            %
            &\pr{\bF_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err} \with \pr{\bF_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err}, \quad (\ft_{\dm, \eps}^{\pr{a}})_{(\dm, \eps, a) \in \N \times \err \times A} \with (\ft_{\dm, \eps}^{\pr{a}})_{(\dm, \eps, a) \in \N \times \err \times A}
        \end{split}
    \end{equation}
    %
    in the notation of \cref{cor:activation_transition})
    %
    demonstrate that there exists $c \in \R$ such that for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ it holds that
    %
    \begin{enumerate}[label = (\Roman*)]
        \item \label{item:bellman_item_I_cor_activation_transition} there exists a unique measurable $u_\dm \colon \R^\dm \to \R^{\abs{A}}$ which satisfies for all $x \in \R^\dm$, $a \in A$ that 
        %
        $\sup_{(z, b) \in \R^\dm \times A} \abs{\w_\dm(z)}^{-1} \abs{(u_\dm(z))(b)} < \infty$,
        %
        \begin{equation}
            \E \br[\Big]{  \max_{b \in A} \abs[\big]{ \pr[\big]{ g_\dm\pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } }\pr{b} + \pr[\big]{u_\dm \pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} }} \pr{b} } } < \infty,
        \end{equation}
        %
        and
        %
        \begin{equation}
            \pr{u_\dm\pr{x}}\pr{a} = L \E \br[\Big]{ \max_{b \in A} \pr[\Big]{ \pr[\big]{ g_\dm\pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } }\pr{b} + \pr[\big]{u_\dm \pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} }} \pr{b} } } 
        \end{equation}
        and

        \item \label{item:bellman_item_II_cor_activation_transition} there exists $\Psi_{\dm, \eps, \mu} \in \bN$ which satisfies $ \cH\pr{\Psi_{\dm, \eps, \mu}} > 0$, $\paramANN(\Psi_{\dm, \eps, \mu}) \le c \dm^c \eps^{-c}$, $\cR_\activation(\Psi_{\dm, \eps, \mu}) \in C(\R^\dm, \R^{\abs{A}})$, and
        %
        \begin{equation} \label{eq:bellman_approximating_ann_cor_activation_transition}
            \pr*{ \int_{\R^\dm} \max_{a \in A} \abs*{ (u_\dm(x))(a) - \pr*{\pr[\big]{\cR_\activation(\Psi_{\dm, \eps, \mu})}(x)}(a) }^2 \mu(\dxx x) }^{\!\!\nicefrac{1}{2}} \le \eps.
        \end{equation}
    \end{enumerate}
    %
    Throughout the remainder of this proof let $\qfunc_\dm \colon \R^\dm \to \R^{\abs{A}}$, $\dm \in \N$, satisfy for all $\dm \in \N$, $x \in \R^\dm$, $a \in A$ that $\pr{\qfunc_\dm \pr{x}}\pr{a} = \pr{g_\dm\pr{x}}\pr{a} + \pr{u_\dm\pr{x}}\pr{x}$,
    %
    let $\pr{\delta_{\dm, \eps}}_{\pr{\dm, \eps} \in \N \times \err} \subseteq \R$ satisfy for all $\dm \in \N$, $\eps \in \err$ that $\delta_{\dm, \eps} = \eps \pr{1 + \genConst^2 \dm^{2\genConst}}^{-1}$,
    %
    let $\fK = \max\cu{2\abs{A}, \genConst, c}$,
    %
    and for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ let $\bQ_{\dm, \eps, \mu} \in \bN$
    satisfy that $\bQ_{\dm, \eps, \mu} = \bG_{\dm, \delta_{\dm, \eps}} \,\bSum_{\, \I_{|A|}}\, \Psi_{\dm, \delta_{\dm, \eps}, \mu}$.
    %
    Observe that for all $\dm \in \N$, $\eps \in \err$ it holds that $\delta_{\dm, \eps} \in (0,1]$.
    %
    Moreover, it follows from 
    %
    the assumption that for all $\dm \in \N$ it holds that $g_\dm$ is measurable,
    %
    the assumption that for all $\dm \in \N$ it holds that $\sup_{(x, a) \in \R^\dm \times A} \abs{\w_\dm(x)}^{-1} \abs{(g_\dm(x))(a)} < \infty$,
    %
    and \cref{item:bellman_item_I_cor_activation_transition} that for all $\dm \in \N$, $x \in \R^\dm$, $a \in A$ it holds that 
    %
    $\qfunc_\dm$ is measurable,
    %
    $\sup_{\pr{y,b} \in \R^\dm \times A} \abs{\w_\dm\pr{y}}^{-1} \abs{\pr{\qfunc_\dm\pr{y}}\pr{b}} < \infty$,
    %
    $\E \br[\Big]{ \max_{b \in A} \abs[\big]{ \pr{ \qfunc_\dm \pr{ t_{\dm}^{\pr{a}}\pr{x, \xi_\dm} } } \pr{b} }  } < \infty$, and
    %
    \begin{equation}
        \begin{split}
            \pr{\qfunc_\dm\pr{x}}\pr{a} &= \pr{g_\dm\pr{x}}\pr{a} + \pr{u_\dm\pr{x}}\pr{x} \\
            %
            &= \pr{g_\dm\pr{x}}\pr{a} + L \E \br[\Big]{ \max_{b \in A} \cu[\big]{ \pr[\big]{ g_\dm\pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } }\pr{b} + \pr[\big]{u_\dm \pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} }} \pr{b} } } \\
            %
            &= \pr{g_\dm\pr{x}}\pr{a} + L \E \br[\Big]{ \max_{b \in A} \cu[\big]{ \pr[\big]{ \qfunc_\dm\pr{ t_\dm^{\pr{a}} \pr{x, \xi_\dm} } }\pr{b} } }.
        \end{split}
    \end{equation}
    %
    This proves \cref{item:bellman_ex_uniq_sol}.
    %
    %
    Furthermore, note that
    %
    \cref{lem:linear_combination_anns_different_length}
    %
    establishes for every $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ that
    %
    $ \cI(\bQ_{\dm, \eps, \mu}) = \cI ( \bG_{\dm, \delta_{\dm, \eps}}) = \dm$, $\cO(\bQ_{\dm, \eps, \mu}) = \cO(\bG_{\dm, \delta_{\dm, \eps}}) = \abs{A}$, $\cR_\activation (\bQ_{\dm, \eps, \mu}) \in C(\R^\dm, \R^{\abs{A}})$, and $\pr*{ \cR_\activation (\bQ_{\dm, \eps, \mu})} (x) = \pr*{ \cR_\activation(\bG_{\dm, \delta_{\dm, \eps}}) }(x) + \pr*{ \cR_\activation(\Psi_{\dm, \delta_{\dm, \eps}, \mu}) }(x) \in \R^{\abs{A}}$.
    %
    This,
    %
    the assumption that for all $\dm \in \N$, $\eps \in \err$, $x \in \R^\dm$, $a \in A$ it holds that $\abs{ (g_\dm(x))(a) - \pr*{\pr*{ \cR_\activation(\bG_{\dm, \eps}) }(x)}(a) } \le \eps \genConst \dm^\genConst \abs{\w_\dm(x)}$,
    %
    the triangle inequality,
    %
    and \cref{item:bellman_item_II_cor_activation_transition}
    %
    yield for every $\dm \in \N$, $\eps \in \err$ and every probability measure $\mu \colon \Borel\pr{\R^\dm} \to \br{0,1}$ with $\pr{\int_{\R^\dm} \abs{\w_\dm(x)}^2 \mu( \dxx x)}^{\nicefrac{1}{2}} \le \genConst d^\genConst$ that
    %
    %
    %
    \begin{align}
        &\pr*{\int_{\R^\dm} \max_{a \in A} \abs*{ (\qfunc_\dm(x))(a) -  \pr[\big]{ \pr*{ \cR_\activation (\bQ_{\dm, \eps, \mu}) }(x) }(a) }^2   \mu (\dxx x)}^{\!\!\nicefrac{1}{2}} \nonumber \\
            %
        &= \pr[\bigg]{ \int_{\R^\dm} \!\!  \max_{a \in A} \abs[\big]{ (g_\dm(x))(a) -  \pr*{\pr*{\cR_\activation(\bG_{\dm, \delta_{\dm, \eps}})}(x)}(a) + (u_\dm(x))(a) - \pr*{\pr*{\cR_\activation(\Psi_{\dm, \delta_{\dm, \eps}, \mu})}(x)}(a) }^2  \mu(\dxx x)\! }^{\!\!\nicefrac{1}{2}} \nonumber\\
