\begin{algorithm}[H]
	\setcounter{algorithm}{0}
	\caption{Forward Projection to First Local Quadrant}
	{}\label{alg:ForwardProjection}
	\textbf{Inputs:}
	$\left(x_{0}, y_{0}\right) \gets{}$ start position \\
	\hspace*{11mm} $\left(x_{f}^{l}, y_{f}^{l}, \theta_{f}^{l}\right) \gets{}$ local final configuration \\
	\textbf{Output: } $p_{m}^{l} = (x_{m}^{l}, y_{m}^{l}, \theta_{m}^{l}) \gets{}$ local mirrored configuration
	\begin{algorithmic}[1]
		\Procedure{ForwardProjectToQ1}{Inputs}
		\State$dx = x_{f}^{l}-x_{0}$, $dy = y_{f}^{l}-y_{0}$
		\If{$dx > 0 \land{} dy > 0$} \Comment{Quadrant $Q_{1}$}
		\State$p_{m}^{l} \gets{} p_{f}^{l}$
		\ElsIf{$dx \leq{} 0 \land{} dy \geq{} 0$} \Comment{Quadrant $Q_{2}$}
		\State$x_{m}^{l} \gets{} 2 \cdot x_{0}-x_{f}^{l}$
		\State$\theta_{m}^{l} \gets{} 2 \pi-\theta_{f}^{l}$
		\ElsIf{$dx \leq{} 0 \land{} dy \leq{} 0 $} \Comment{Quadrant $Q_{3}$}
		\State$x_{m}^{l} \gets{} 2 \cdot x_{0}-x_{f}^{l}$
		\State$y_{m}^{l} \gets{} 2 \cdot y_{0}-y_{f}^{l}$
		\ElsIf{$dx > 0 \land{} dy < 0 $} \Comment{Quadrant $Q_{4}$}
		\State$y_{m}^{l} \gets{} 2 \cdot y_{0}-y_{f}^{l}$
		\State$\theta_{m}^{l} \gets{} 2 \pi-\theta_{f}^{l}$
		\EndIf{}
		\State\textbf{return} $p_{m}^{l}$
		\EndProcedure{}
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
	\setcounter{algorithm}{2}
	\caption{Is In Set B}\label{alg:booleanset}
	\small{}
	\textbf{Inputs:}
	$p_{0}^{l} = (x_{0}^{l}, y_{0}^{l}, \theta_{0}^{l}) \gets{}$ local start configuration \\
	\hspace*{11mm} $p_{m}^{l} = (x_{m}^{l}, y_{m}^{l}, \theta_{m}^{l}) \gets{}$ final mirrored configuration \\
	\hspace*{11mm} $r \gets{}$ minimum turning radius \\
	\textbf{Output: } $\text{Boolean} \gets{}$ true if path is in set B, false otherwise
	\begin{algorithmic}[1]
		\Procedure{IsInSetB}{Inputs}
		\State$c_{0_{R_{x}}} \gets{} x_{0}^{l} + r\cos\left(\theta_{0}^{l}-\frac{\pi}{2}\right)$
		\State$c_{0_{R_{y}}} \gets{} y_{0}^{l} + r\sin\left(\theta_{0}^{l}-\frac{\pi}{2}\right)$
		\State$c_{0_{L_{x}}} \gets{} x_{0}^{l}-r\cos\left(\theta_{0}^{l}-\frac{\pi}{2}\right)$
		\State$c_{0_{L_{y}}} \gets{} y_{0}^{l}-r\sin\left(\theta_{0}^{l}-\frac{\pi}{2}\right)$
		\State$c_{m_{R_{x}}} \gets{} x_{m}^{l} + r\cos\left(\theta_{m}^{l}-\frac{\pi}{2}\right)$
		\State$c_{m_{R_{y}}} \gets{} y_{m}^{l} + r\sin\left(\theta_{m}^{l}-\frac{\pi}{2}\right)$
		\State$c_{m_{L_{x}}} \gets{} x_{m}^{l}-r\cos\left(\theta_{m}^{l}-\frac{\pi}{2}\right)$
		\State$c_{m_{L_{y}}} \gets{} y_{m}^{l}-r\sin\left(\theta_{m}^{l}-\frac{\pi}{2}\right)$
		\State$\mathcal{K} \gets{} 2r\sqrt{2}$
		\State~$LL \gets{} \twonorm{c_{0_{L}}-c_{m_{L}}}$, $LR \gets{}\twonorm{c_{0_{L}}-c_{m_{R}}}$
		\State~$RL \gets{} \twonorm{c_{0_{R}}-c_{m_{L}}}$, $RR \gets{}\twonorm{c_{0_{R}}-c_{m_{R}}}$
		\State~$\mathcal{P}_{1} \gets{} (RR \leq{} \mathcal{K}) \land{} (LL \leq{} \mathcal{K}) \land{} (LR \leq{} 2r)$
		\State~$\mathcal{P}_{2} \gets{} (RR \leq{} \mathcal{K}) \land{} (LL \leq{} \mathcal{K}) \land{} (RL \leq{} 2r)$
		\State~$\mathcal{P}_{3} \gets{} (LR \leq{} 2r) \land{} (LL \leq{} \mathcal{K}) \land{} (RL \leq{} 2r)$
		\State\textbf{return} $\left(\mathcal{P}_{1} \lor{} \mathcal{P}_{2} \lor{} \mathcal{P}_{3}\right)$
		\EndProcedure{}
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
	\setcounter{algorithm}{3}
	\caption{Get Local Mirrored Optimal Path}
	{}\label{alg:main_partition}
	\textbf{Inputs:}
	$p_{0}^{l} \gets{}$ local start configuration \\
	\hspace*{11mm} $p_{f}^{l} \gets{}$ local mirrored configuration \\
	\textbf{Output: } $P_{m}^{l} \gets{}$ optimal local path
	\begin{algorithmic}[1]
		\Procedure{GetOptimalPath}{Inputs}
		\If{\Call{IsInSetB}{$p_{0}^{l}$, $p_{f}^{l}$}}
		\State~$P_{m}^{l} \gets{}$ \Call{SetBPartitions}{$p_{0}^{l}$, $p_{f}^{l}$}
		\Else{}
		\State~$P_{m}^{l} \gets{}$ \Call{SetAPartitions}{$p_{0}^{l}$, $p_{f}^{l}$}
		\EndIf{}
		\State\textbf{return} $P_{m}^{l}$
		\EndProcedure{}
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
	\setcounter{algorithm}{1}
	\caption{Backward Projection to Original Quadrant}
	{}\label{alg:BackwardProjection}
	\textbf{Inputs:}
	$P_{m}^{L} \equiv{} \mathcal{T}_{m}^{1\times5}$, $\mathcal{D}_{m}^{1\times5}$, $\mathcal{L}_{m}^{1\times5}$, $Q$ \\
	\textbf{Output: } $P_{f}^{L} \equiv{} \mathcal{T}_{f}^{1\times5}$, $\mathcal{D}_{f}^{1\times5}$, $\mathcal{L}_{f}^{1\times5}$
	\begin{algorithmic}[1]
		\Procedure{BackwardProjectFromQ1}{Inputs}
		\If{$Q == 1$}
