\title{Quantum Error Correction Exploiting Degeneracy to Approach the Hashing Bound}
\author{
\IEEEauthorblockN{Kenta Kasai}
\IEEEauthorblockA{\\Institution of Science Tokyo\\
%Tokyo, Japan
Email: kenta@ict.eng.isct.ac.jp}
