\subsection{Construction of $\HH_X$ and $\HH_Z$}
\label{101943_12Jun25}
%----------------------------------------
The following requirement on $\fU$ and $\gU$ is used to ensure that the resulting matrices $\HH_X$ and $\HH_Z$ are orthogonal \cite{komoto2024quantumerrorcorrectionnear}.
\begin{yosei}\label{yosei:orthogonal}
We require that the following commutativity condition holds:
\begin{align}
  g_{\ell-j} \, f_{k-\ell} = f_{k-\ell} \, g_{\ell-j} \quad \text{for all } \ell \in [L/2],\ j,k \in [J]. \label{162154_15Feb25}
\end{align}
 Here, the indices of $f$ and $g$ are understood modulo $L/2$. 
\end{yosei}
This condition~\eqref{162154_15Feb25} is equivalently expressed by any of the following three statements.  
\begin{align}
& f_{\ell - j} \, g_{k - \ell} = g_{k - \ell} \, f_{\ell - j} \quad \text{for all } \ell \in [L/2],\ j, k \in [J], \label{192555_14Jun25}\\
& \text{$f_\ell$ commutes with $g_{- \ell + j}$ for all $\ell \in [L/2]$ and $j \in \{0,\pm 1,\ldots,\pm (J-1)\}$,} \label{191912_14Jun25}\\
 & \text{$g_\ell$ commutes with $f_{- \ell + j}$ for all $\ell \in [L/2]$ and $j \in \{0,\pm 1,\ldots,\pm (J-1)\}$.}
% & \text{$f_\ell$ commutes with $g_{-(J - 1) - \ell + j}$ for all $\ell \in [L/2]$ and $j \in [2J - 1]$,} \\
% & \text{$g_\ell$ commutes with $f_{-(J - 1) - \ell + j}$ for all $\ell \in [L/2]$ and $j \in [2J - 1]$.}
\end{align}


This commutativity condition guarantees that each pair of corresponding blocks in $\HH_X$ and $\HH_Z$ ensures the orthogonality.
