\subsection{Construction of $H_X$ and $H_Z$}
\label{092546_7Jun25}
%- - - - - - - - - - - - - - - - - - - - 
In this section, we construct orthogonal $\Fb_2$-valued matrices $H_X$ and $H_Z$ of size $m \times n$ from the orthogonal $\Fb_q$-valued matrices $H_\Gamma$ and $H_\Delta$ of size $M \times N$ obtained in the previous section, where $n = eN$ and $m = eM$. This construction follows the method used in \cite{6017122} and \cite{komoto2024quantumerrorcorrectionnear}. 
The matrices $H_X$ and $H_Z$ are constructed from $H_\Gamma$ and $H_\Delta$ as follows. The theoretical justification and proofs, which were omitted in \cite{6017122} and \cite{komoto2024quantumerrorcorrectionnear}, are provided in the appendices.


The companion matrix $A(\gamma)\in \Fb_2^{e\times e}$  for $\gamma \in \Fb_q$ are defined in Appendices~\ref{234926_5Apr25}. Using the mapping $A$, we construct the binary parity-check matrices $(H_X, H_Z)$ as follows:
\begin{align}
    H_X &= \bigl(A(\gamma_{i,j})\bigr), \quad
    H_Z = \bigl(A(\delta_{i,j})^\top\bigr).
\end{align}
From the properties of the companion matrix, it can be verified that $(H_X, H_Z)$ are orthogonal:
\begin{align}
    H_X H_Z^{\top} = O. \label{224009_19May25}
\end{align}
A proof of~\eqref{224009_19May25} is provided in Appendix~\ref{164912_4Jun25}.

We denote by $C_\Gamma$ and $C_\Delta$ the $\Fb_q$-linear spaces defined as the null spaces of the matrices $H_\Gamma$ and $H_\Delta$, respectively:
\begin{align}
    C_\Gamma &= \{\xiU \in \Fb_q^N \mid H_\Gamma \xiU = 0\},\quad     C_\Delta = \{\xiU \in \Fb_q^N \mid H_\Delta \xiU = 0\}.
\end{align}
Likewise, we denote by $C_X$ and $C_Z$ the $\Fb_2$-linear spaces defined as the null spaces of the binary matrices $H_X$ and $H_Z$, respectively:
\begin{align}
    C_X &= \{\xU \in \Fb_2^n \mid H_X \xU = 0\}, \quad    C_Z = \{\xU \in \Fb_2^n \mid H_Z \xU = 0\}.
\end{align}
The following theorem shows that the codes $C_\Gamma$ and $C_\Delta$, originally defined over $\Fb_q$, can be equivalently represented as binary codes $C_X$ and $C_Z$ via the transformations $\vU$ and $\wU$, respectively. 
The definitions of the mappings $\vU(\cdot)$ and $\wU(\cdot)$ are provided in Appendices~\ref{234926_5Apr25} and~\ref{234956_5Apr25}.
\begin{teiri}\label{thm:binary_mapping}
Let $\xiU = (\xi_0,\ldots,\xi_{N-1})$ be a vector over $\Fb_q$. Then the following statements hold:
\begin{enumerate}
 \item $\bigl(\vU(\xi_0),\ldots,\vU(\xi_{N-1})\bigr) \in C_X$ if and only if $\xiU \in C_\Gamma$.
 \item $\bigl(\wU(\xi_0),\ldots,\wU(\xi_{N-1})\bigr) \in C_Z$ if and only if $\xiU \in C_\Delta$.
\end{enumerate}
\end{teiri}
\begin{proof}
From Appendix~\ref{234926_5Apr25} and Appendix~\ref{234956_5Apr25}, we obtain the following identities for any vector $\xiU=(\xi_0,\ldots,\xi_{N-1})\in\Fb_q^N$:
\begin{align}
\sum_j(H_X)_{ij} \vU(\xi_j) &= \sum_j A(\gamma_{ij}) \vU(\xi_j) = \sum_j \vU(\gamma_{ij} \xi_j) = \vU\left(\sum_j \gamma_{ij} \xi_j\right), \\
\sum_j(H_Z)_{ij} \wU(\xi_j) &= \sum_j A(\delta_{ij})^\T \wU(\xi_j) = \sum_j \wU(\delta_{ij} \xi_j) = \wU\left(\sum_j \delta_{ij} \xi_j\right).
\end{align}
These equalities show that applying $H_X$ to the bit-level expansion $\bigl(\vU(\xi_0), \ldots, \vU(\xi_{N-1})\bigr)$ is equivalent to applying $H_\Gamma$ to $\xiU$ over $\Fb_q$ and then mapping the result via $\vU$.  
Therefore, $\bigl(\vU(\xi_0), \ldots, \vU(\xi_{N-1})\bigr)$ belongs to $C_X$ if and only if $\xiU \in C_\Gamma$.  
The second statement is proved in the same way.
\end{proof}

This correspondence allows us to identify $(C_X, C_Z)$ with $(C_\Gamma, C_\Delta)$.  
For example, we write
\begin{align}
C_X = C_\Gamma, \quad C_Z = C_\Delta.  
\end{align}
In particular, the orthogonality condition $C_X^\perp \subset C_Z$ is equivalent to $C_\Gamma^\perp \subset C_\Delta$.  

The binary CSS code defined by $(C_X, C_Z)$ is used for quantum error correction.  
As explained in Section~\ref{sec:171047_25May25}, the decoder does not directly use the binary matrices $H_X$ and $H_Z$ as the binary matrices that define the Tanner graphs for BP decoding.  
Instead, it uses a partitioned form of $H_X$ and $H_Z$ divided into $e$-bit blocks, or equivalently, the corresponding nonbinary matrices $H_\Gamma$ and $H_\Delta$.  
Accordingly, when we refer to the girth of $C_X$ or $C_Z$, we mean the girth of $H_\Gamma$ or $H_\Delta$, respectively; that is, the girth of $\HH_X$ or $\HH_Z$.  


\label{003230_3Jun25}
The minimum distance $d$ is defined as follows, where $w_H(\cdot)$ denotes the Hamming weight of a binary vector:  
\begin{align}
d_X &= \min_{\xU \in C_X \setminus C_Z^\perp}  w_H(\xU) \\
&= \min_{\xiU \in C_\Gamma \setminus C_\Delta^\perp}  w_H\bigl(\vU(\xi_0),\vU(\xi_1),\ldots,\vU(\xi_{N-1})\bigr), \label{def:d_X} \\
d_Z &= \min_{\zU \in C_Z \setminus C_X^\perp} w_H(\zU) \\
&= \min_{\zetaU \in C_\Delta \setminus C_\Gamma^\perp} w_H\bigl(\wU(\zeta_0),\wU(\zeta_1),\ldots,\wU(\zeta_{N-1})\bigr), \label{def:d_Z} \\
d &= \min\{d_X, d_Z\}.
\end{align}
