\subsection{Impact of UTCBCs on Minimum Distance}\label{231534_3Jun25}
%----------------------------------------
Following common conventions in the literature on LDPC codes, we identify the Tanner graph $\Gt$ corresponding to the matrix $H_\Gamma$ with $H_\Gamma$ itself. Accordingly, columns correspond to variable nodes, rows to check nodes, and submatrices to subgraphs, allowing us to treat these elements interchangeably. For example, the Tanner graph associated with a submatrix $S$ of $H_\Gamma$ is also denoted by $S$. Similarly, a subgraph of $H_\Gamma$ is denoted by $\Gt'$, and the corresponding submatrix is also referred to as $\Gt'$.

Let us consider a Tanner cycle $\Ct$ of length $2L$ contained in $H_\Gamma$.
Let $(H_\Gamma)_\Ct$ denote the submatrix of $H_\Gamma$ obtained by zeroing out all columns not involved in the cycle $\Ct$.  
Similarly, let $\xiU_\Ct$ denote the vector obtained from $\xiU \in \Fb_q^N$ by zeroing out all coordinates not corresponding to columns in $\Ct$.
We define the subcode associated with the cycle $\Ct$ as
\begin{align}
 N(\Ct;H_\Gamma) \defeq \left\{ \xiU_\Ct \in \Fb_q^N\mid (H_\Gamma)_\Ct \, \xiU_\Ct = \zeroU,\ \xiU \in \Fb_q^N \right\}.
 \label{042010_2Jun25}
\end{align}
The set $N(\Ct;H_\Gamma)$ is a subcode of $C_\Gamma$, supported only on the positions involved in the cycle $\Ct$.  
It captures the contribution of the cycle $\Ct$ to the code $C_\Gamma$ by isolating codewords whose nonzero positions lie solely within $\Ct$.
Theorem~\ref{192838_2Jun25} shows that $N(\Ct;H_\Gamma)$ is contained in $C_\Delta^\perp \subset C_\Gamma$, and therefore such codewords do not affect the minimum distance $d_X$ (see~\eqref{def:d_X}).


\begin{teiri}\label{192838_2Jun25}
Let $\Ct$ be a Tanner cycle in the UTCBC $\uU(k)$ in $H_\Gamma$ for $k = 0,1$, which is orthogonal to the row vector $\hU_{kr}^\top$, in the sense that
\begin{align}
 (H_\Gamma)_\Ct \, \hU_{kr} = \zeroU. \label{144858_5Jun25}
\end{align}
Here, $\hU_{kr}^\top$ denotes the $r$-th row of $H_\Delta^{(k)}$.
Then, the associated subcode $N(\Ct;H_\Gamma)$ is a one-dimensional subspace over $\Fb_q$ given by
\begin{align}
N(\Ct;H_\Gamma) = \{ \xi \hU_{kr} \mid \xi \in \Fb_q \},\label{145346_5Jun25}
\end{align}
where $\xi$ is a scalar in $\Fb_q$.
Moreover, $N(\Ct;H_\Gamma)$ is a subspace of $C_\Delta^\perp \subset C_\Gamma$.
A similar statement holds when $H_\Delta$ is considered in place of $H_\Gamma$, i.e., when the roles of $X$ and $Z$ are interchanged.
\end{teiri}
\begin{proof}
We first observe that $\supp(\hU_{kr}) = \supp(\Ct)$.  
By Theorem~\ref{053905_28Apr25}, the cycle $\Ct$ is square-shaped and can be arranged into an upper-triangular form except for one row. Therefore, its rank is at least $L - 1$.  
Since the column weight is $J = 2$, the rank of the submatrix $(H_\Gamma)_\Ct$ coincides with that of the cycle $\Ct$.  
From~\eqref{144858_5Jun25}, a nonzero solution $\hU_{kr}$ exists in the kernel of $(H_\Gamma)_\Ct$, implying that its rank is at most $L - 1$.
Hence, the rank of $(H_\Gamma)_\Ct$ is exactly $L - 1$, and this proves~\eqref{145346_5Jun25}.
Since $\hU_{kr}^\top$ is a row of the parity-check matrix $H_\Delta$, it follows that $N(\Ct;H_\Gamma)$ is a subspace of $C_\Delta^\perp$.
\end{proof}


