\subsection{Joint Belief Propagation Decoding over Finite Field}\label{sec:143825_6Jun25}
%----------------------------------------
In the concluding part of Section~\ref{sec:171047_25May25}, we will propose a post-processing technique for the joint BP algorithm.  
For the sake of a concise formulation, this section describes a joint BP algorithm over a finite field, which is equivalent to the one over binary vectors defined in Section~\ref{subsec:205908_25May25}.

For $x_j, z_j \in \Fb_2^e$, we define \(\xi_j, \zeta_j \in \Fb_q\) such that  
\begin{align}
 \vU(\xi_j) = x_j \tAND \wU(\zeta_j) = z_j, \label{031931_14May25}
\end{align}
respectively. Similarly, we define \(\sigma_i, \tau_i \in \Fb_q\) such that \(\vU(\sigma_i) = \sU_i\) and \(\wU(\tau_i) = \tU_i\). Then, by Theorems~\ref{013653_26Mar25} and~\ref{wU_linear_relation_theorem} in the Appendices, we obtain the following equivalences:
\begin{align}
\left.
\begin{aligned}
H_\Delta\, \xiU &= \sigmaU 
\quad &&\Longleftrightarrow \quad 
H_Z\, \xU = \sU, \\
H_\Gamma\, \zetaU &= \tauU 
\quad &&\Longleftrightarrow \quad 
H_X\, \zU = \tU
\end{aligned}
\right\}.
\label{eq:binary_nonbinary_equiv}
\end{align}


Using the equivalence in \eqref{eq:binary_nonbinary_equiv}, the decoding constraint \eqref{align_p(x,z|s,t)} in terms of binary variables \(\xU, \zU\) can be equivalently rewritten using $\Fb_q$-valued variables \(\xiU, \zetaU \in \Fb_q^N\) as follows:
\begin{align}
 p(\xU,\zU|\sU,\tU)&\propto \I\bigl[H_Z\xU=\sU\bigr]\I\bigl[H_X\zU=\tU\bigr]p(\xU,\zU)
 \\ &= \I\bigl[H_\Delta\xiU=\sigmaU\bigr]\I\bigl[H_\Gamma\zetaU=\tauU\bigr]p(\xiU,\zetaU)
 \\&=
 \Bigl(\prod_{i\in[M]} \I\bigl[\sum_{j\in[N]}\delta_{ij}\xi_j=\sigma_i\bigr] \Bigr)
 \Bigl(\prod_{i\in[M]} \I\bigl[\sum_{j\in[N]}\gamma_{ij}\zeta_j=\tau_i\bigr] \Bigr)\label{022413_12May25}
 \Bigl(\prod_{j\in[N]} p\left(\xi_j, \zeta_j\right) \Bigr)
 \\&\defeq p(\xiU,\zetaU|\sigmaU,\tauU).
  \label{233428_11May25}
\end{align}
Here, the pairwise prior $p\left(\xi_j, \zeta_j\right)$ is defined as $p\left(\xi_j, \zeta_j\right)\defeq p(x_j, z_j)$ for a pair $(x_j, z_j)$ satisfying the mapping condition described in~\eqref{031931_14May25}.

The joint BP algorithm that marginalizes the posterior probability \(p(\xiU,\zetaU|\sigmaU,\tauU)\) is an algorithm that updates the following eight types of messages:
\begin{align}
& \mu^{(\ell),X}_{ij}(\xi_j),  \nu^{(\ell),X}_{ji}(\xi_j), \lambda^{(\ell),X}_j(\xi_j),  \kappa^{(\ell),X}_j(\xi_j), 
\\&\mu^{(\ell),Z}_{ij}(\zeta_j),\nu^{(\ell),Z}_{ji}(\zeta_j), \lambda^{(\ell),Z}_j(\zeta_j),\kappa^{(\ell),Z}_j(\zeta_j),
\end{align}
at the iteration round $\ell=0,1,\ldots$. 
These messages are probability vectors of length~$q$. 
Note that although we use Greek letters to denote these messages, they represent probability distributions and not elements of the finite field.
The following messages are initialized to the uniform distribution over $\xi_j, \zeta_j\in \Fb_q$, respectively:
\begin{align}
& \lambda_j^{(0),X}(\xi_j) = 1/q, \\
& \lambda_j^{(0),Z}(\zeta_j) = 1/q,\\
& \nu_{ij}^{(0),X}(\xi_j) = 1/q, \\
& \nu_{ij}^{(0),Z}(\zeta_j) = 1/q.
\end{align}

Each message is updated at each iteration round $\ell = 0, 1, 2, \ldots$ using the following update equations.
After each update, the messages are normalized to ensure they form probability distributions.
\begin{align}
 \kappa_{j}^{(\ell),X}(\xi_j)&=\sum_{\zeta_j}p(\xi_j,\zeta_j)\lambda_j^{(\ell),Z}(\zeta_j)\label{013318_27May25},
\\ \kappa_{j}^{(\ell),Z}(\zeta_j)&=\sum_{\xi_j}p(\xi_j,\zeta_j)\lambda_j^{(\ell),X}(\xi_j)\label{013321_27May25},
\\\mu^{(\ell),X}_{ji}(\xi_j)&=\kappa^{(\ell),X}_j(\xi_j)\prod_{i'\in \partial_Z(j)\setminus i}\nu_{i'j}^{(\ell),X}(\xi_j),\label{noise_X}
\\\mu^{(\ell),Z}_{ji}(\zeta_j)&=\kappa^{(\ell),Z}_j(\zeta_j)\prod_{i'\in \partial_X(j)\setminus i}\nu_{i'j}^{(\ell),Z}(\zeta_j),\label{noise_Z}
\\  \nu_{ij}^{(\ell+1),X}(\xi_j) &=\sum_{(\xi_{j'}):{j'\in \partial_Z(i)}\setminus j}
    \I\Bigl[\sum_{j'\in \partial_Z(i)}\delta_{ij'}\xi_{j'}=\sigma_i\Bigr]
    \prod_{j'\in \partial_Z(i)\setminus j}\mu_{j'i}^{(\ell),X}(\xi_{j'}),\label{parity_check_X}
\\  \nu_{ij}^{(\ell+1),Z}(\zeta_j)&=\sum_{(\zeta_{j'}):{j'\in \partial_X(i)}\setminus j}
    \I\Bigl[\sum_{j'\in \partial_X(i)}\gamma_{ij'}\zeta_{j'}=\tau_i\Bigr]
    \prod_{j'\in \partial_X(i)\setminus j}\mu_{j'i}^{(\ell),Z}(\zeta_{j'}),\label{parity_check_Z}
\\ \lambda_{j}^{(\ell+1),X}(\xi_j)&=\prod_{i\in \partial_Z(j)}\nu_{ij}^{(\ell+1),X}(\xi_j), 
\\ \lambda_{j}^{(\ell+1),Z}(\zeta_j)&=\prod_{i\in \partial_X(j)}\nu_{ij}^{(\ell+1),Z}(\zeta_j),
\end{align}
where $\partial_X(i)\subset[N]$ and $\partial_Z(i)\subset[N]$ are the set of column index $j$ such that $\gamma_{ij}\neq 0$ and $\delta_{ij}\neq 0$, respectively.
Similarly,  $\partial_X(j)\subset[M]$ and $\partial_Z(j)\subset[M]$ are the set of row index $i$ such that $\gamma_{ij}\neq 0$ and $\delta_{ij}\neq 0$, respectively.
It holds that 
$\#\partial_X(i)=\#\partial_Z(i)=L$ and 
$\#\partial_X(j)=\#\partial_Z(j)=J$.
The outer summation in \eqref{parity_check_X} is taken over all vectors $(\xi_{j'})$ of length $L - 1$,  
where $j' \in \partial_Z(i) \setminus \{j\}$ and each component $\xi_{j'}$ ranges over $\Fb_q$.  
In this summation, the variable $\xi_j$ is fixed, and the sum is taken over all other variables involved in the parity check at node $i$.
The interpretation of the summation in \eqref{parity_check_Z} is analogous, with $\zeta_j$ fixed and the summation taken over all $\zeta_{j'}$ for $j' \in \partial_X(i) \setminus \{j\}$.

We define the estimated noise at iteration $\ell$ as
\begin{align}
  &  \xiH_j^{(\ell)} \defeq \argmax_{\xi_j}     \kappa^{(\ell),X}_j(\xi_j)  \prod_{i \in \partial_Z(j)} \nu_{ij}^{(\ell),X}(\xi_j), \quad
\\&  \zetaH_j^{(\ell)} \defeq \argmax_{\zeta_j} \kappa^{(\ell),Z}_j(\zeta_j)\prod_{i \in \partial_X(j)} \nu_{ij}^{(\ell),Z}(\zeta_j).
\end{align}
% The corresponding syndromes of the estimated noise vectors $\xiUH^{(\ell)}$ and $\zetaUH^{(\ell)}$ are written as
% \begin{align}
% &    H_\Delta \xiUH^{(\ell)} =: \sigmaUH^{(\ell)}, \quad
% \\&    H_\Gamma \zetaUH^{(\ell)} =: \tauUH^{(\ell)}.
% \end{align}
At each iteration $\ell$, we check whether these estimated syndromes match the true syndromes $\sigmaU$ and $\tauU$.
If both conditions $H_\Delta \xiUH^{(\ell)} = \sigmaU$ and $H_\Gamma \zetaUH^{(\ell)} = \tauU$ are satisfied, then $\xiUH^{(\ell)}$ and $\zetaUH^{(\ell)}$ are accepted as the estimated noise, and the algorithm terminates.
If either condition is not satisfied, the decoding continues.

The messages \eqref{parity_check_X} and \eqref{parity_check_Z} can be computed using FFT \cite{DaveyMacKayGFq}, requiring \(O(Lq\log q)\) operations per message. 
On the other hand the computation for messages \eqref{013318_27May25} and \eqref{013321_27May25} require \(O(q^2)\) operations per message.  
Other messages computation require only $O(Jq)$ operations per message. 
Moreover, since the message updates at each node do not share memory, they can be computed in parallel across all nodes.  
As performance improves with increasing \(P\), and assuming \(q\) is fixed, the overall computational complexity is proportional to the number of physical qubits \(n = ePL\).  
In the experiments conducted in this paper, we set \(q = 2^e\) with \(e = 8\).

