\section{Companion Matrix Representation over Finite Fields}\label{234926_5Apr25}
%----------------------------------------
This section introduces the companion matrix representation of finite field elements over $\mathbb{F}_{2^e}$. We begin by reviewing the vector representation of field elements via the mapping $\vU$, and then define the companion matrix $A(\alpha)$ associated with a primitive element $\alpha$. The main result is that multiplication in $\mathbb{F}_{2^e}$ can be translated into matrix-vector multiplication over $\mathbb{F}_2$, providing a linear-algebraic framework that is crucial for decoding operations in quantum LDPC codes. Several theorems are presented to formalize the algebraic properties of these representations, including linearity, multiplicativity, and the equivalence between field equations and their matrix representations.


Let $q = 2^e$. It is well-known that elements of the finite field $\mathbb{F}_q$ can be commonly represented either as binary vectors of length $e$ or as polynomials of degree less than $e$ with binary coefficients.
Let $\alpha \in \mathbb{F}_q$ be a primitive element. Any element $\gamma \in \mathbb{F}_q$ can be uniquely written in the form 
\begin{align}
 \gamma = \sum_{j=0}^{e-1} g_j \alpha^j.
\end{align} 
We define the mapping $\vU : \mathbb{F}_q \to \mathbb{F}_2^e$ by
\[
\vU(\gamma) := (g_0, g_1, \ldots, g_{e-1})^{\top} \in \mathbb{F}_2^e.
\]

\begin{example}\label{ex:023559_22Mar25}
For $e=8$, using the primitive polynomial $x^8 + x^4 + x^3 + x^2 + 1$ over $\mathbb{F}_2$, we have:
\begin{align}
 \begin{array}{ll}
 \vU(0) &= (00000000)^\top, \\
 \vU(1) &= (10000000)^\top, \\
 \vU(\alpha) &= (01000000)^\top, \\
 \vU(\alpha^{e-1}) &= (00000001)^\top, \\
 \vU(\alpha^{e}) &= (10110000)^\top, \\
 \end{array}
\end{align}
\end{example}

\begin{teiri}
The map $\vU$ defines an isomorphism of vector spaces over $\mathbb{F}_2$, and also a group isomorphism under addition:
\[
\vU(\gamma_1 + \gamma_2) = \vU(\gamma_1) + \vU(\gamma_2), \quad \forall \gamma_1, \gamma_2 \in \mathbb{F}_q.
\]
\end{teiri}

\begin{proof}
Let $\gamma_1, \gamma_2 \in \mathbb{F}_q$. Since $\mathbb{F}_q = \mathbb{F}_{2^e}$ is an $\mathbb{F}_2$-vector space with basis $\{1, \alpha, \ldots, \alpha^{e-1}\}$, each $\gamma_i$ has a unique representation
\[
\gamma_1 = \sum_{j=0}^{e-1} g_j^{(1)} \alpha^j, \quad
\gamma_2 = \sum_{j=0}^{e-1} g_j^{(2)} \alpha^j \quad (g_j^{(i)} \in \mathbb{F}_2).
\]
Thus,
\[
\gamma_1 + \gamma_2 = \sum_{j=0}^{e-1} ( g_j^{(1)} + g_j^{(2)} ) \alpha^j.
\]
Hence,
\[
\vU(\gamma_1 + \gamma_2) = ( g_0^{(1)} + g_0^{(2)}, \ldots, g_{e-1}^{(1)} + g_{e-1}^{(2)} )^{\top}
= \vU(\gamma_1) + \vU(\gamma_2).
\]
Therefore, $\vU$ is a homomorphism with respect to addition, and it is a linear isomorphism over $\mathbb{F}_2$, as it extracts coefficients from a linear combination and both $\mathbb{F}_q$ and $\mathbb{F}_2^e$ have the same dimension.
\end{proof}


They can also be naturally represented using $e \times e$ binary matrices.
\begin{df}
Let $a(x) = a_0 + a_1 x + \cdots + a_e x^e$ with $a_0 = a_e = 1$ be the primitive polynomial of $\alpha \in \mathbb{F}_q$. The {\itshape companion matrix} $A(\alpha)$ \cite{macwilliams77} is defined as:
\begin{align}
    A(\alpha) &\defeq
\bigl(\vU(\alpha^1),\vU(\alpha^2),\ldots,\vU(\alpha^{e})\bigr)\label{153337_11May25}
\\&=
    \begin{pmatrix}
        0 & 0 & 0 & 0 & a_0 \\
        1 & 0 & 0 & 0 & a_1 \\
        0 & 1 & 0 & 0 & a_2 \\
        \vdots & \vdots & \ddots & \vdots & \vdots \\
        0 & 0 & 0 & 1 & a_{e-1}
    \end{pmatrix}.\label{031734_22Mar25}
\end{align}
We define the mapping \(A: \Fb_q \to \Fb_2^{e \times e}\) by
\begin{align}
    A(0) &\defeq O, \\
    A(\alpha^l) &\defeq A(\alpha)^l, \quad \text{for } l = 0, \ldots, q-2.
\end{align}
\end{df}

The mapping \(A: \mathbb{F}_q \to \mathbb{F}_2^{e \times e}\) introduced above has important algebraic properties. Specifically, it preserves the algebraic structure of the finite field $\mathbb{F}_q$, as demonstrated in the following theorem.
\begin{teiri}\label{163515_22Mar25}
As shown in \cite{macwilliams77}, the map $A$ is injective, and its image $A(\mathbb{F}_q)$ forms a field isomorphic to $\mathbb{F}_q$. The map satisfies the following properties for all $\gamma_1, \gamma_2, \delta \in \mathbb{F}_q$: multiplicativity, commutativity, and additivity:
\begin{align}
&     A(\gamma_1 \gamma_2) = A(\gamma_1)A(\gamma_2) = A(\gamma_2)A(\gamma_1), \label{044508_22Mar25}\\
&     A(\gamma)\vU(\delta) = \vU(\gamma\delta), \label{044514_22Mar25}\\
&     A(\gamma_1 + \gamma_2) = A(\gamma_1) + A(\gamma_2). \label{044517_22Mar25}
\end{align}
\end{teiri}

\begin{proof}
The case for the zero element is trivial, so we assume that $\gamma_1, \gamma_2, \delta \in \mathbb{F}_q^\times$.
Let $\eU^{(i)}$ denote the standard basis vector of $\mathbb{F}_2^e$ whose $i$th component is 1 and the others are 0. By the definition of $\vU$, we have $\vU(\alpha^i) = \eU^{(i)}$. Furthermore, by the definition of the companion matrix $A(\alpha)$, its action on $\eU^{(i)}$ corresponds to the $i$th column of $A(\alpha)$. Hence, we have
\begin{align}
  A(\alpha)\vU(\alpha^i) = \vU(\alpha^{i+1}) \quad \text{for all } i \in [e]. \label{025939_22Mar25}
\end{align}
Let $\gamma_1 = \alpha^i$ and $\gamma_2 = \alpha^j$. Then, since $A(\alpha^k) = A(\alpha)^k$ for all $k \in \mathbb{Z}$, we have
\[
A(\gamma_1) A(\gamma_2) = A(\alpha)^i A(\alpha)^j = A(\alpha)^{i+j} = A(\alpha^{i+j}) = A(\gamma_1 \gamma_2),
\]
which establishes both multiplicativity and commutativity.
To prove \eqref{044514_22Mar25}, suppose $\gamma = \alpha^j$ and $\delta = \alpha^i$. Then,
\[
A(\gamma)\vU(\delta) = A(\alpha^j)\vU(\alpha^i) = A(\alpha)^j \vU(\alpha^i) = \vU(\alpha^{i+j}) = \vU(\gamma \delta),
\]
where we used \eqref{025939_22Mar25} repeatedly.
To prove \eqref{044517_22Mar25}, note that for any $\delta \in \mathbb{F}_q$, we compute:
\[
(A(\gamma_1) + A(\gamma_2))\vU(\delta)
= A(\gamma_1)\vU(\delta) + A(\gamma_2)\vU(\delta)
= \vU(\gamma_1 \delta) + \vU(\gamma_2 \delta)
= \vU((\gamma_1 + \gamma_2)\delta)
= A(\gamma_1 + \gamma_2)\vU(\delta).
\]
Since $\vU$ is injective, the equality
\[
A(\gamma_1 + \gamma_2) = A(\gamma_1) + A(\gamma_2)
\]
follows.
\end{proof}


The matrix representation $A(\gamma)$ not only captures the algebraic operations in $\mathbb{F}_q$, but also provides a useful tool for performing field multiplication and addition in terms of binary vector and matrix operations. In particular, the mapping $A$ allows us to translate scalar equations over $\mathbb{F}_q$ into linear-algebraic expressions over $\mathbb{F}_2$ via the map $\vU$.

The following theorem illustrates a basic but important connection between the vector representation $\vU(\alpha^i)$ and the matrix representation $A(\alpha^i)$.
\begin{teiri}
The vector $\vU(\alpha^i)$ agrees with the leftmost column of $A(\alpha^i)$.
\end{teiri}
\begin{proof}
From the multiplication property,
\[
A(\gamma_1)\vU(\gamma_2) = \vU(\gamma_1 \gamma_2).
\]
Let $\gamma_1 = \alpha^i$ and $\gamma_2 = 1 = \alpha^0$. Then
\[
A(\alpha^i)\vU(1) = \vU(\alpha^i).
\]
Since $\vU(1) = (1, 0, \ldots, 0)^{\top}$, this implies that $\vU(\alpha^i)$ agrees with the first column of $A(\alpha^i)$, which completes the proof.
\end{proof}

The next theorem provides an equivalence between scalar linear combinations over $\mathbb{F}_q$ and their binary vector representations using matrix multiplication. This property will be useful when solving equations or decoding in vectorized form.
\begin{teiri}\label{013653_26Mar25}
The following equivalence holds for any \(\delta_j, \xi_j, \sigma \in \Fb_q\):
\begin{align}
\sum_j \delta_j \xi_j = \sigma 
\quad \text{ if and only if }\quad 
\sum_j A(\delta_j)\, \vU(\xi_j) = \vU(\sigma).
\end{align}
\end{teiri}

\begin{proof}
Using the additivity of \(\vU\) and the multiplicative property \(A(\gamma)\vU(\delta) = \vU(\gamma \delta)\) from \eqref{044514_22Mar25}, we compute:
\begin{align}
\sum_j A(\delta_j)\, \vU(\xi_j) 
&= \sum_j \vU(\delta_j \xi_j) \notag\\
&= \vU\Bigl(\sum_j \delta_j \xi_j\Bigr). \notag
\end{align}
Therefore, the identity \(\sum_j A(\delta_j)\, \vU(\xi_j) = \vU(\sigma)\) holds  
if and only if \(\vU\left(\sum_j \delta_j \xi_j\right) = \vU(\sigma)\).  
Since \(\vU\) is injective, this is equivalent to \(\sum_j \delta_j \xi_j = \sigma\).
\end{proof}

