\section{Proof for \texorpdfstring{$\eqref{015905_13Feb25}$ and $\eqref{095733_27May25}$}{(24)}}\label{224018_19May25}
%----------------------------------------
In this appendix, we show that if the orthogonality condition \eqref{212247_11Feb25}:
\begin{align}
H_\Gamma (H_\Delta)^\top = O 
\end{align}
holds, then the congruence relations \eqref{015905_13Feb25} and \eqref{095733_27May25}:
\begin{align}
\left(
\begin{array}{c|c|c|c}
-\HH_Z^{(\Lrm)} & \HH_Z^{(\Rrm)} & \HH_Z^{(\Lrm)} & -\HH_Z^{(\Rrm)}
\end{array}
\right)
 \log \gammaU &= \zeroU \pmod{q - 1}, \\
\left(
\begin{array}{c|c|c|c}
-\HH_X^{(\Lrm)} & \HH_X^{(\Rrm)} & \HH_X^{(\Lrm)} & -\HH_X^{(\Rrm)}
\end{array}
\right)
 \log \deltaU &= \zeroU \pmod{q - 1} 
\end{align}
necessarily follow.

Let $\deltaU_{jr}^\top$ denote the $r$-th row of $H_\Delta^{(j)}$, where $H_\Delta^{(j)}$ is the $j$-th row block of $H_\Delta$. 
