% Subsection: Block coordinate descent methods
\subsection{Block coordinate descent methods}
\label{Subsec:BCD}
Block coordinate descent methods are important instances of subspace correction methods for convex optimization.
We discuss how randomized block coordinate descent methods~\cite{LX:2015,Nesterov:2012,RT:2014} can be interpreted within the framework of the randomized subspace correction method; see also~\cite[Section~3.3]{JPX:2025} and~\cite[Section~6.4]{Park:2020} for related discussions.

We begin by presenting the standard setting for block coordinate descent methods~\cite{LX:2015,RT:2014}.  
Assume that the space \( V \) is given by the direct sum of subspaces \( V_j \), \( j \in [J] \):
\begin{equation*}
    V = \bigoplus_{j=1}^J V_j,
\end{equation*}
so that each \( v \in V \) can be represented in block form as~\cite[Proposition~1]{RT:2016}
\begin{equation}
\label{block}
    v = (v_1, v_2, \dots, v_J),
    \quad v_j \in V_j.
\end{equation}


In the composite optimization problem~\eqref{model}, we assume that \( F \) is block smooth.
That is, there exist positive constants \( L_j \), \( j \in [J] \), such that
\begin{equation}
\label{F_RBCD}
    F(v + w_j) \leq F(v) + ( F'(v), w_j ) + \frac{L_j}{2} \| w_j \|^2,
    \quad v \in V,\ w_j \in V_j.
\end{equation}
In addition, we assume that the functional \( G \) is block separable, meaning it admits the decomposition
\begin{equation}
\label{G_RBCD}
    G(v) = \sum_{j=1}^J G^j(v_j),
    \quad v \in V,
\end{equation}
for some functionals \( G^j \colon V_j \to \overline{\mathbb{R}} \).

In the local problem~\eqref{local_inexact}, for each \( j \in [J] \), we set
\begin{equation}
\label{local_RBCD}
\begin{aligned}
F_j(w_j; v) &= F(v) + ( F'(v), w_j ) + \frac{L_j}{2} \| w_j \|^2, \\
G_j(w_j; v) &= G ( v + w_j),
\end{aligned}
\quad w_j \in V_j,\ v \in V.
\end{equation}
Then, it is readily seen that the local problem~\eqref{local_inexact} computes the increment of a single proximal descent step with step size \( 1 / L_j \) applied to the \( j \)th block coordinate; see \cref{Ex:local_inexact}.
Consequently, \cref{Alg:RSC} reduces to the randomized block coordinate descent method considered in~\cite{LX:2015,RT:2014}.

Next, we demonstrate that our convergence theory recovers the results established in~\cite{RT:2014} for the randomized block coordinate descent method.
It is straightforward to verify that \cref{Ass:local} holds with $\omega = 1$, based on~\eqref{F_RBCD},~\eqref{G_RBCD}, and~\eqref{local_RBCD}.
Moreover, using~\eqref{G_RBCD}, we obtain (cf.~\cite[Section~6.4]{Park:2020})
\begin{equation*}
    \sum_{j=1}^J G_j(w_j; v) = G(v + w) + (J - 1) G(v),
    \quad v,w \in V.
\end{equation*}
From~\eqref{F_RBCD} and~\eqref{local_RBCD}, we have
\begin{equation*}
    \sum_{j=1}^J d_j(w_j; v) \leq \frac{1}{2} \| w \|_L^2,
    \quad v, w \in V,
\end{equation*}
where the norm \( \| \cdot \|_L \) is defined by
\begin{equation*}
    \| v \|_L = \left( \sum_{j=1}^J L_j \| v_j \|^2 \right)^{\frac{1}{2}},
    \quad v \in V.
\end{equation*}
That is, \cref{Ass:stable} holds with the \( \| \cdot \|_L \)-norm, \( q = 2 \), and \( C_K = 1 \) for any bounded convex subset \( K \subset V \).
Consequently, by \cref{Thm:conv}, the randomized block coordinate descent method satisfies
\begin{equation*}
    \mathbb{E}[E(u^{(n)})] - E(u) \leq \frac{2 J R_0^2}{n + 2 J R_0^2 / ( E(u^{(0)}) - E(u) )},
    \quad n \geq 0,
\end{equation*}
provided that \( E(u^{(0)}) - E(u) \) is sufficiently small. Otherwise, the method exhibits linear convergence.
Here, \( R_0 \) is defined by~\eqref{K_0} with respect to the \( \| \cdot \|_L \)-norm.
This result is consistent with~\cite[Theorem~5]{RT:2014} and~\cite[Equation~(16)]{LX:2015}.

Now suppose further that \( F \) and \( G \) are \( \mu_F \)- and \( \mu_G \)-strongly convex with respect to the \( \| \cdot \|_L \)-norm, respectively, for some \( \mu_F, \mu_G \geq 0 \) with \( \mu_F + \mu_G > 0 \).
In this case, \cref{Thm:conv_strong} implies the following linear convergence rate:
\begin{equation*}
    \mathbb{E}[E(u^{(n)})] - E(u) \leq \left(1 - \frac{1}{J} \frac{\mu_F + \mu_G}{1 + \mu_G}\right)^n (E(u^{(0)}) - E(u)),
    \quad n \geq 0,
\end{equation*}
which agrees with~\cite[Theorem~7]{RT:2014}.


