% Subsection: Operator splitting
\subsection{Operator splitting methods}
\label{Subsec:OS}
By utilizing the duality between subspace correction and operator splitting methods developed in~\cite{JPX:2025}, we can derive a randomized operator splitting method from the randomized subspace correction method.

As a model problem for operator splitting methods, we consider the following optimization problem involving the sum of multiple convex functionals:
\begin{equation}
\label{model_OS}
    \min_{v \in V} \left\{ F(v) + \sum_{j=1}^J G_j (B_j v) \right\},
\end{equation}
where \( V \) and each \( W_j \), \( j \in [J] \), are Hilbert spaces, \( B_j \colon V \to W_j \) are continuous linear operators, and \( F \colon V \to \mathbb{R} \) and \( G_j \colon W_j \to \overline{\mathbb{R}} \) are proper, convex, and lower semicontinuous functionals.
For simplicity, we assume that \( F \) is strongly convex and smooth so that \( F' \) is invertible~\cite{BC:2011}.

A randomized Peaceman--Rachford-type splitting method for solving~\eqref{model_OS} is presented in \cref{Alg:OS}.
At each iteration of \cref{Alg:OS}, an index \( j \in [J] \) is selected at random, and an optimization problem involving only the functional \( G_j \) is solved.
Recall that $d$ denotes the Bregman divergence associated with $F$.

% Algorithm: Randomized Peaceman--Rachford splitting algorithm
\begin{algorithm}
\caption{Randomized Peaceman--Rachford splitting algorithm for~\eqref{model_OS}}
\begin{algorithmic}[]
\label{Alg:OS}
\STATE Choose $u^{(0)} \in V$ and $v_1^{(0)},\dots,v_J^{(0)} \in V$.
\FOR{$n=0,1,2,\dots$}
    \STATE Sample $j \in [J]$ from the uniform distribution on $[J]$.
    \STATE $\displaystyle
        u^{(n+1)} = \operatornamewithlimits{\arg\min}_{v \in V} \left\{ d (v - u^{(n)}; u^{(n)}) + (v_j^{(n)}, v) + G_j (B_j v) \right\}
        $
    \STATE $\displaystyle
        v_i^{(n+1)} = \begin{cases}
            v_i^{(n)} + F' (u^{(n+1)}) - F'(u^{(n)}), & \quad \text{ if } i = j, \\
            v_i^{(n)}, & \quad \text{ if } i \neq j,
        \end{cases}
        \quad i \in [J]
        $
\ENDFOR
\end{algorithmic}
\end{algorithm}

As summarized in \cref{Thm:OS}, and similar to~\cite[Theorem~5.4]{JPX:2025}, we can deduce that \cref{Alg:OS} is a \textit{dualization} of the randomized subspace correction method applied to the following dual problem:
\begin{equation}
\label{model_OS_dual}
\min_{(p_j)_{j=1}^J \in \bigoplus_{j=1}^J W_j} \left\{ F^* \left( - \sum_{j=1}^J B_j^* p_j \right) + \sum_{j=1}^J G_j^* (p_j) \right\},
\end{equation}
where \( F^* \colon V \to \mathbb{R} \) and \( G_j^* \colon W_j \to \overline{\mathbb{R}} \) denote the Legendre--Fenchel conjugates of \( F \) and \( G_j \), respectively, and \( B_j^* \) denotes the adjoint of \( B_j \).
Note that~\eqref{model_OS_dual} is an instance of~\eqref{model} in which the nonsmooth part is block separable~(cf.~\eqref{G_RBCD}).

% Theorem: Dualization relation between RPR and RSC
\begin{theorem}
\label{Thm:OS}
Let $\{ u^{(n)} \}$, $\{ (v_j^{(n)})_{j=1}^J \}$, and $\{ (p_j^{(n)} )_{j=1}^J \}$ be the sequences generated by the randomized Peaceman--Rachford splitting algorithm for solving~\eqref{model_OS}~(\cref{Alg:OS}) and the randomized subspace correction method with exact local problems for solving~\eqref{model_OS_dual}.
If
\begin{equation*}
u^{(0)} = (F^*)' \left( - \sum_{j=1}^J B_j^* p_j^{(0)} \right), \quad
v_j^{(0)} = - B_j^* p_j^{(0)},
\quad j \in [J],
\end{equation*}
then we have
\begin{equation*}
u^{(n)} \stackrel{\text{a.s.}}{=} (F^*)' \left( - \sum_{j=1}^J B_j^* p_j^{(n)} \right), \quad
v_j^{(n)} \stackrel{\text{a.s.}}{=} - B_j^* p_j^{(n)},
\quad j \in [J],\ n \geq 1.
\end{equation*}
\end{theorem}
