\KeywordTok{function} \FunctionTok{assign}\NormalTok{(parord)}
\NormalTok{    sigma }\OperatorTok{=} \FunctionTok{CFTP\_linear\_extensions}\NormalTok{(}\FloatTok{10}\NormalTok{, parord)}
\NormalTok{    output }\OperatorTok{=} \FunctionTok{zeros}\NormalTok{(}\DataTypeTok{Int}\NormalTok{, }\FloatTok{8}\NormalTok{)}

    \ControlFlowTok{if}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{1}\NormalTok{, }\FloatTok{2}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{1}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{1}\NormalTok{, }\FloatTok{2}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{2}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{1}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{2}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{3}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{4}\NormalTok{, }\FloatTok{1}\NormalTok{, }\FloatTok{2}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{4}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{2}\NormalTok{, }\FloatTok{1}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{5}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{2}\NormalTok{, }\FloatTok{1}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{6}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{2}\NormalTok{, }\FloatTok{4}\NormalTok{, }\FloatTok{1}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{7}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{elseif}\NormalTok{ sigma }\OperatorTok{==}\NormalTok{ [}\FloatTok{4}\NormalTok{, }\FloatTok{2}\NormalTok{, }\FloatTok{1}\NormalTok{, }\FloatTok{3}\NormalTok{, }\FloatTok{5}\NormalTok{]}
\NormalTok{        output[}\FloatTok{8}\NormalTok{] }\OperatorTok{=} \FloatTok{1}
    \ControlFlowTok{end}

    \ControlFlowTok{return}\NormalTok{ output}
\KeywordTok{end}
