%     Let $\overrightarrow{G}$ be an oriented graph and $G$ be its underlying graph. If $\Delta(G) \leq 4$, then $\csp{G} = 1$.
% \end{theorem}

\begin{restatable}{theorem}{Tmaxdegree}\label{T:maxdegree}
    Let $\overrightarrow{G}$ be an oriented graph and $G$ be its underlying graph. If $\Delta(G) \leq 4$, then $\csp{G} = 1$.
\end{restatable}

