Putting this all together, we summarize the unbiased low-rank approximation procedure in Algorithm \ref{fig1} below. An illustration of the algorithm applied to grayscale images (treated as real-valued matrices) is shown in Figures \ref{fig:cats} and \ref{fig:triangles}. The runtime of the algorithm is dominated by the cost of computing the singular value decomposition of the matrix $P$ at the beginning.

\begin{algorithm}
\caption{Unbiased Low-Rank Approximation with Minimum Distortion}
\label{fig1}
\begin{algorithmic}[1]
\item {\bf given} matrix $P\in\mathbb{C}^{n\times m}$, rank constraint $r$
\item {\bf compute SVD} $P=U\Lambda V^*$, $\Lambda = \mathsf{diag}(d_1,\ldots,d_N,0,\ldots,0)$
\For{k'=0,\ldots,N-1}
\If {$(r-k')d_{k'+1} < \sum_{i=k'+1}^N d_i$} \State $k\leftarrow k'$
\State break
\EndIf
\EndFor
\item $S\leftarrow\mathsf{unif}[0,1]$
\item $I\leftarrow \{\}$
\item $\mathsf{length} \leftarrow 0$
\item $C \leftarrow \frac{r-k}{\sum_{i=k+1}^Nd_i}$
\For{i=k+1,\ldots,N}
\State $\mathsf{length} \leftarrow \mathsf{length} + Cd_i$
\If {$\mathsf{length} \geq S$}
\State $I\leftarrow I \cup \{i\}$
\State $S \leftarrow S+1$
\EndIf
\EndFor
\item $Q'=\mathsf{diag}(Q'_1,\ldots,Q'_N,0,\ldots,0)$ where $
Q_i' = \begin{cases} d_i & \; , \; i=1,\ldots,k \\ c = \frac{1}{C} = \frac{\sum_{j=k+1}^N d_j}{r-k} & \; , \; i\in I \\ 0 & \; , \; \mathsf{otherwise} \end{cases}
$
\item {\bf return} $Q = UQ'V^*$
\end{algorithmic}
\end{algorithm}

\section{Matching Lower Bound}
In this section, we show that the lower bound from the supplementary material in \cite{benzing2019optimal} matches the expected error achieved by Algorithm \ref{fig1}. This shows that Algorithm \ref{fig1} produces unbiased low-rank approximations that are optimal in the sense that they minimize \eqref{eq:frob}.

For any fixed matrix $B$, we have
\begin{align}
\mathbb{E}\|Q'-\Lambda\|_F^2 & = \mathbb{E}\|Q'-(\Lambda-B)\|_F^2 - \|B\|_F^2 \label{eq:step1}\\
& \geq \min_{X\in\mathbb{C}^{n\times m}, \, \mathsf{rank}(X)\leq r} \|X-(\Lambda-B)\|_F^2 - \|B\|_F^2 \label{eq:step2} \; .
\end{align}
Equation \eqref{eq:step1} follows by the unbiasedness of $Q'$ so that $\mathbb{E}[B^*(Q'-\Lambda)] = 0$. In equation \eqref{eq:step2}, we lower bound the expected error by the smallest error that can be achieved, with any fixed low-rank matrix $X$, between $\Lambda-B$ and $X$. In particular, we pick $B$ so that
\begin{equation} \label{eq:defineB}
\Lambda - B = \mathsf{diag}(d_1,\ldots,d_k,\underbrace{c,\ldots,c}_{N-k},0,\ldots,0)
\end{equation}
where $c$ is defined as in \eqref{eq:sparsecomps}.

A key property that is needed is that $d_k \geq c$ so that the diagonal elements in \eqref{eq:defineB} are non-increasing. This follows because by definition the index $k$ is heavy, so
$$ (r-(k-1))d_k \geq \sum_{j=k}^Nd_j \implies d_k \geq \frac{\sum_{j=k+1}^Nd_j}{r-k} = c\; .$$
Using this property and the Eckart-Young-Mirsky Theorem, it is clear that the expression in \eqref{eq:step2} is minimized exactly by the first $r$ diagonal components of \eqref{eq:defineB}. Furthermore, if $Q'$ is defined as in \eqref{eq:sparsecomps}, then the error in \eqref{eq:step1} is the same as in \eqref{eq:step2} for \emph{every} realization of $Q'$. Therefore, for our choice of $Q'$, the inequality in \eqref{eq:step2} is actually equality, and we exactly match the minimum possible expected error.

