\begin{mathbox}
    \label{box:contextual_chain_rule}
    \textbf{Contextual chain rule.} If
    \begin{enumerate}
\item\label{item:fd1}
    $x_1 \to x_2 \to \dots \to x_{n-1} \to x_n,$
\item\label{item:fd2}
$\fd{c_1}{ x_n},\fd{c_2}{ x_n}, \dots ,\fd{c_{n-1}}{x_n}$,
\item\label{item:c1} $x_1c_1x_n$,
    \item\label{item:c2} $x_1c_1x_2,c_1x_2c_2,x_2c_2x_3,\dots ,x_{n-2}c_{n-2}x_{n-1},$\\
    $c_{n-2}x_{n-1}c_{n-1},x_{n-1}c_{n-1}x_n$, and
    \item\label{item:c3} $c_1c_2x_n, c_2c_3x_n, \dots ,c_{n-2}c_{n-1}x_n$,
\end{enumerate}
then $\fd{x_1}{ x_n}$.
\end{mathbox}


