\subsection{Craig Interpolation}
\jonni{More steamlined discussion on CI}

Next, we focus on answering the question whether the axiomatisations of functional dependence introduced in the paper enjoy Craig interpolation.
A deductive system $\vdash$ has Craig interpolation, if for every set of formulae $\Sigma\cup \{\varphi\}$ such that
\[
    \Sigma \vdash \varphi
\]
there exists a formula $\psi$ such that $\Vars(\psi)\subseteq \Vars(\Sigma)\cap \Vars(\varphi)$ and
\[
    \Sigma \vdash \psi \vdash \varphi.
\]
Here, we focus on the setting, where $\Sigma$, $\psi$, and $\phi$ are FDs.
We start with the classical Armstrong's axioms.
\begin{theorem}
Armstrong's axioms have Craig Interpolation.
\end{theorem}
\begin{proof}
Let $\Sigma$ be a collection of FDs and $X$ and $Y$ sets of variables such that $\Sigma \vdash \fd{X}{Y}$. We next construct an interpolant $\psi$ such that $\Sigma \vdash \psi \vdash \fd{X}{Y}$ step by step.

Initialise $\psi=\fd{X}{Y}$.
If $x$ is a variable that does  not occur in $\Sigma$, but it occurs in $X$, then set $\psi= \fd{X\setminus \{x\}}{Y\setminus\{x\}}$.

\jonni{Define the algorithm computing the closure of $X$ with $\Sigma$.}
\cite{BeeriB79}


If $x$ is a variable that does  not occur in $\Sigma$, but it occurs in $Y$ but not in $X$ we have a contradiction.

Repetitive application of the above rewriting rule terminates and produces the required interpolant. Correctness is proven via the closure algorithm and some citation that the closure algorithm works as intended.

\end{proof}

\begin{definition}
We write $\vdash_{\textrm{CA}}$ to denote the restriction of Armstrong's axioms to uni-context rules (i.e., assumptions and consequents are assumed to be included in the same context).  
\end{definition}

\begin{proposition}[This should be proved quite early]\label{prop:unicontextcomp}
    If $\Sigma\cup\{\varphi\}$ is a set of FDs with variables in $V$, then
    \[
    \Sigma \cup\{\fd{V}{V} \} \vdash \varphi \text{ if and only if } \Sigma \vdash_{\textrm{CA}} \varphi ,
    \]
\end{proposition}
\begin{proof}
Easy, once the axiomatisation is finalised.
\end{proof}

\begin{proposition}\label{prop:unicontextCI}
Let $\vdash$ be an axiomatisation of FDs extending $\vdash_{\textrm{CA}}$ that has Craig Interpolation. If $\Sigma$ is a set of FDs with variables in $V$, then
\[
\Sigma \cup\{\fd{V}{V} \} \vdash \fd{X}{Y} \text{ if and only if } \Sigma \vdash_{\textrm{CA}} \fd{X}{Y}.
\]
\end{proposition}
\begin{proof}
Craig interpolation gives an interpolant using variables $V\cap (X\cup Y)$. The claim then follows from Proposition \ref{prop:unicontextcomp}.
\end{proof}

\jonni{Cycle and chain rule trivially satisfy Craig interpolation, since there the consequent is always the interpolant.}

\begin{definition}[Strong context specific CI]
A deductive system $\vdash$ has strong context specific Craig interpolation, if for every set of formulae $\Sigma\cup \{\varphi\}$ such that
\[
    \Sigma \vdash \varphi
\]
there exists a sequence $\Sigma_1, \dots, \Sigma_n$ of uni-context subsets of $\Sigma$ and a sequence of formulae  $\psi_1,\dots, \psi_n$ s.t.
\begin{enumerate}
\item $\Vars(\psi_i)\subseteq \Vars(\Sigma_i)\cap \Vars(\varphi)$, for every $i\leq n$,
\item $\Sigma_i \vdash \psi_i$, for every $i\leq n$, and $\{\psi_1,\dots, \psi_n\} \vdash \varphi$.
\end{enumerate}
\end{definition}

\begin{definition}[Context specific CI]
A deductive system $\vdash$ has context specific Craig interpolation, if for every set of formulae $\Sigma\cup \{\varphi\}$ such that
\[
    \Sigma \vdash \varphi
\]
there exists a sequence $\Sigma_1, \dots, \Sigma_n$ of uni-context subsets of $\Sigma$ and a sequence of formulae  $\psi_1,\dots, \psi_n$ s.t.
\begin{enumerate}
\item $\Vars(\psi_i)\subseteq \Vars(\Sigma_i)\cap \Vars(\varphi)$, for every $i\leq n$, and
\item $\Sigma \vdash \{\psi_1,\dots, \psi_n\} \vdash \varphi$.
\end{enumerate}
\end{definition}

\begin{example}
If we omit the dummy dependencies, and write the context-set $C$ directly to $\vdash^C$, we obtain that the chain rule breaks context specific Craig Interpolation.

Let $\Sigma$ contain all the non-dummy assumptions of the context sensitive chain rule, for $n=3$, and let $C$ be the smallest context-set that includes all the contexts encoded by the assumptions of the rule. By applying the chain rule, we obtain $\Sigma \vdash^C \fd{x_1}{x_3}$.

For the sake of contradiction, assume there exists a sequence $\Sigma_1, \dots, \Sigma_n$ of uni-context subsets of $\Sigma$ and a set of formulae  $\Delta = \{\psi_1,\dots, \psi_n\}$ such that $\Vars(\psi_i)\subseteq \Vars(\Sigma_i)\cap \Vars(\varphi)$, for every $i\leq n$,  and $\Sigma \vdash^C \{\psi_1,\dots, \psi_n\} \vdash^C \varphi$.
Note that the sets of the form $\Vars(\Sigma_i)\cap \Vars(\varphi)$ are exactly $\{x_1\}$ and $\{x_3\}$.
It follows that the $\psi_i$s come from the set
\[
\Delta_0 = \{\fd{x_1}{x_1}, \fd{\emptyset}{x_1}, \fd{x_3}{x_3}, \fd{\emptyset}{x_3}\}.
\]
Now, $\Delta' \vdash^C \fd{x_1}{x_3}$, for $\Delta'\subseteq \Delta_0$, if and only if $\fd{\emptyset}{x_3} \in \Delta'$.
However, Example (\textcolor{red}{needs to be done}) shows that $\Sigma \not \vdash^C \fd{\emptyset}{x_3}$. Hence $\Delta$ cannot be an interpolant.
\end{example}

\begin{proposition}
The contextual axiomatisation $\vdash$ does not have a strong context specific Craig Interpolation.
\end{proposition}
\begin{proof}
Let $\Sigma = \{ \fd{x_1}{x_2}, \fd{x_2}{x_3}, \fd{x_3}{x_1}\} \}$. By applying of the cycle rule, we obtain
\(
\Sigma \vdash \fd{x_1}{x_3}.
\)
For the sake of contradiction, assume there exists a sequence $\Sigma_1, \dots, \Sigma_n$ of uni-context subsets of $\Sigma$ and a sequence of formulae  $\psi_1,\dots, \psi_n$ such that $\Vars(\psi_i)\subseteq \Vars(\Sigma_i)\cap \Vars(\varphi)$, for every $i\leq n$, $\Sigma_i \vdash \psi_i$, for every $i\leq n$, and $\{\psi_1,\dots, \psi_n\} \vdash \varphi$.
Note that the uni-context subsets of $\Sigma$ are exactly
\[
\{\Sigma_1 = \{\fd{x_1}{x_2}\}, \Sigma_2 = \{\fd{x_2}{x_3}\}, \Sigma_3 = \{\fd{x_3}{x_1}\}\}.
\]
By Proposition \ref{prop:unicontextcomp}, it follows that the $\psi_i$s come from the set 
\[
\Delta = \{\fd{x_1}{x_1}, \fd{x_3}{x_1}, \fd{x_3}{x_3}\}.
\]
By Proposition \ref{prop:unicontextcomp}, it also follows that $\Delta \not\vdash \fd{x_1}{x_3}$, from which the claim follows.
\end{proof}
In fact, one can use the ideas of the previous proposition to obtain the following stronger result:
\begin{proposition}
Let $\vdash$ be an axiomatisation of FDs extending $\vdash_{\textrm{CA}}$ that has strong context specific Craig Interpolation and $\Sigma$ be a set of FDs, then
\[
\Sigma \vdash \fd{X}{Y} \text{ if and only if } \Sigma \vdash_{\textrm{CA}} \fd{X}{Y}.
\]
\end{proposition}
\begin{proof}
The direction from right-to-left is immediate and the converse follows readily using Proposition \ref{prop:unicontextCI}.
Assume $\Sigma \vdash \fd{X}{Y}$, and let $\Sigma_1, \dots, \Sigma_n$ be uni-context subsets of $\Sigma$ and $\psi_1,\dots, \psi_n$ be a sequence of formulae that are obtained due to strong context specific Craig Interpolation. Hence, we have that $\Vars(\psi_i)\subseteq \Vars(\Sigma_i)\cap \Vars(\varphi)$ and  $\Sigma_i \vdash \psi_i$, for every $i\leq n$, and $\{\psi_1,\dots, \psi_n\} \vdash \fd{X}{Y}$.
By Proposition \ref{prop:unicontextcomp}, we obtain that $\Sigma_i \vdash_{\textrm{CA}} \psi_i$, for every $i\leq n$, and that $\{\psi_1,\dots, \psi_n\} \vdash_{\textrm{CA}} \fd{X}{Y}$. Hence $\Sigma \vdash_{\textrm{CA}} \fd{X}{Y}$ readily follows.
\end{proof}

\subsection{Contextual team semantics}
A \emph{semiring} is a tuple $K=(K,+,\cdot,0,1)$, where $+$ and $\cdot$ are binary operations on $K$, $(K,+,0)$ is a commutative monoid with identity element $0$, $(K,\cdot ,1)$ is a monoid with identity element $1$, $\cdot$ left and right distributes over $+$, and $x \cdot 0 =0= 0\cdot x$ for all $x \in K$.
 $K$ is called \emph{commutative} if $(K,\cdot ,1)$ is a commutative monoid.
 That is, semirings are rings which need not have additive inverses.


