\subsection{Line of action estimation}
\begin{algorithm}
\caption{Line of action estimation}\label{euclid}
    \begin{algorithmic}[1]
    \Procedure{LOA}{$skeleton, mesh, axis, samples$}

    \State $tendon\gets []$
    \State $KDTrees\gets \{\}$
    \For{$bone\in skeleton$}
    \State $KDTrees[bone.name] \gets kdTree(bone)$
    \EndFor

    \State $contours\gets slice(mesh, axis, samples)$
    \State $centroids\gets [] $
    \For{$c\in contours$}
    \State $centroids.append(c.centroid())$
    \EndFor

    \State $addedSites \gets []$

    \For{$c\in centroids$}
    \State $geom \gets getClosestGeom(KDTrees, c)$
    \State $d \gets distance(c, addedSites.last)$

    \State $conds \gets False$
    \State $cond$ {\bf or} $addedSites.empty()$
    \State $cond$ {\bf or} $c.last$
    \State $cond$ {\bf or} $d \geq maxDist$
    \State $cond$ {\bf or} ($newBody$ {\bf and} $d \geq minDist$)
    \If{$cond$}
        \State $tendon.addSite(c)$
        \If{$wrapping$}
            \State $tendon.addWrapping()$
        \EndIf
    \EndIf

    \EndFor

    \State \textbf{return} $tendon$
    \EndProcedure
    \end{algorithmic}

    \label{line of action}
\end{algorithm}

