 \end{figure} 



The optimization problem for estimating the CFO is expressed as, \vspace{-9mm}

\begin{equation}\label{eq: optimization CFO}
\begin{split}
      \hat{\omega}_{CFO} &= \arg\max_{\omega_i} \Bigg[\sum_{\tau} y(\tau)e^{j \frac{\omega_i}{f_s}\tau}x_{pss}(t-\tau)   \Bigg],
\end{split}
\end{equation} where $x_{pss}$ is the primary synchronization signal, the first OFDM symbol in SSB and $f_s$ is the sampling frequency.
For obtaining time offset to the SSB, Schmidl \& Cox approach \cite{Schmidl1997} is used. Hence, the following optimization problem (\ref{eq: optimization TO}) is solved numerically where $\mathcal{P}(t)$ and $\mathcal{R}(t)$ are represented as (\ref{eq: TO-P}) and (\ref{eq: TO-R}), where $\hat{L}$ is one-half of the number of samples in one OFDM symbol. \vspace{-4mm}

\begin{equation}\label{eq: optimization TO}
\begin{split}
      \hat{T}_{off} &= \arg\max_{t} \, M(t)=\frac{|\mathcal{P}(t)|^2}{\mathcal{R}(t)^2} ,
\end{split}
\end{equation}

\vspace{-8mm}

\begin{equation}\label{eq: TO-P}
\begin{split}
      \mathcal{P}(t)=\sum_{n=0}^{\hat{L}-1} y^*(t+n)y(t+n+\hat{L})  ,
\end{split}
\end{equation}
 \vspace{-9mm}

\begin{equation}\label{eq: TO-R}
\begin{split}
      \mathcal{R}(t)=\sum_{n=0}^{\hat{L}-1}|y(t+n+\hat{L})|^2 
\end{split}
\end{equation}
